// Original bilingual survey lessons. Each module is an introduction, not a complete
// laboratory course, examination qualification, or expert-reviewed textbook.
import { readFileSync } from 'node:fs';
import {calculationZh} from './science-calculations-zh.mjs';
const catalogue = JSON.parse(readFileSync(new URL('../blueprint/curriculum.json', import.meta.url), 'utf8'));
const b = (en, zh) => ({ en, zh });
export const lessons = [];
export const outlines = {};
export const titles = {};
const sources = {
 P: [{title:'OpenStax · University Physics, Volume 1',url:'https://openstax.org/details/books/university-physics-volume-1'},{title:'OpenStax · University Physics, Volume 2',url:'https://openstax.org/details/books/university-physics-volume-2'},{title:'OpenStax · University Physics, Volume 3',url:'https://openstax.org/details/books/university-physics-volume-3'}],
 C: [{title:'OpenStax · Chemistry 2e',url:'https://openstax.org/details/books/chemistry-2e'}],
 B: [{title:'OpenStax · Biology 2e',url:'https://openstax.org/details/books/biology-2e'}]
};
function course(id, foundationEn, foundationZh, connectionEn, connectionZh, prerequisites, rows, extraSources=[]) {
 const c=catalogue.courses.find(x=>x.id===id);
 if (!c || rows.length!==6) throw Error(`Expected six modules for ${id}`);
 rows.forEach((r,i)=>{
  const [zh, termsEn, termsZh, theoryEn, theoryZh, exampleEn, exampleZh, qEn, qZh, answer, calculation, pitfallEn, pitfallZh, correctEn, correctZh, incorrectEn, incorrectZh] = r;
  const m=c.modules[i], lid=`module.${m.id}`, terms=termsEn.split('|').map((x,k)=>b(x,termsZh.split('|')[k]));
  titles[m.id]=b(m.title.en,zh);
  outlines[m.id]={concepts:terms,check:b(qEn,qZh)};
  const right=i%2===0?'a':'b';
  lessons.push({id:lid,courseId:id,moduleId:m.id,title:titles[m.id],summary:b(theoryEn.split('. ')[0]+'.',theoryZh.split('。')[0]+'。'),prerequisites:i?[`module.${c.modules[i-1].id}`]:prerequisites,minutes:25,visual:null,
   contentStatus:'original-module-survey-review-pending',coverage:'introductory-survey',
   objectives:[b(`Describe ${terms[0].en} and its relationship to ${terms[1].en}.`,`说明${terms[0].zh}与${terms[1].zh}之间的联系。`),b(`Explain ${terms[2].en} and identify the conditions behind the example.`,`解释${terms[2].zh}，并指出例子所依赖的条件。`)],
   sections:[
    {type:'concept',title:b('Foundation and meaning','基础与含义'),body:b(foundationEn,foundationZh)},
    {type:'concept',title:b(termsEn.replaceAll('|',' · '),termsZh.replaceAll('|',' · ')),body:b(theoryEn,theoryZh)},
    {type:'example',title:b('Work through a concrete case','分析具体例子'),body:b(exampleEn,exampleZh)},
    {type:'pitfall',title:b('Conditions and common errors','成立条件与常见误区'),body:b(pitfallEn,pitfallZh)}
   ],
   exercises:[{id:`${lid}.1`,type:'numeric',prompt:b(qEn,qZh),answer,tolerance:answer===0?1e-10:Math.abs(answer)*1e-6,hints:[b('Identify the quantities and relation in the worked example, then substitute the stated values.','先找出例题中的量与关系，再代入题目给定数值。')],explanation:b(calculation,calculationZh(calculation))},
   {id:`${lid}.2`,type:'choice',prompt:b('Which statement follows from the model and its conditions?','哪项陈述符合模型及其适用条件？'),options:(right==='a'?[[correctEn,correctZh],[incorrectEn,incorrectZh]]:[[incorrectEn,incorrectZh],[correctEn,correctZh]]).map((o,j)=>({id:j?'b':'a',text:b(...o)})),answer:right,hints:[b('Check the distinction explained under conditions and common errors.','检查“成立条件与常见误区”中所说明的区别。')],explanation:b(`${correctEn} ${pitfallEn}`,`${correctZh}${pitfallZh}`)}],sources:[...sources[id[0]],...extraSources]
  });
  if (expansions[m.id]) expand(m.id, expansions[m.id].en, expansions[m.id].zh);
 });
}

// Compact authored records retain module-specific explanations and checks; the shared
// course foundation is intentionally repeated so a directly opened lesson is readable.
function compact(id, zhNames, foundation, foundationZh, prerequisites, rows, extraSources=[]) {
 course(id,foundation,foundationZh,
 'Before applying the relation to a new situation, draw the system boundary and identify what is measured, what is inferred and what is assumed constant. Change one parameter and predict the direction of the result before calculating. This separates understanding of a model from memorizing one numerical answer. This introductory survey establishes the named ideas; extended derivations, laboratory competence and comprehensive examination preparation require further study and review.',
 '把关系应用于新情境前，先确定系统边界，区分测量量、推断量以及假定不变的量。改变一个参数，先预测结果的变化方向，再计算。这能区分理解模型与记忆数值答案。本入门概览建立所列核心概念；完整推导、实验操作和全面考试训练仍需进一步学习与审核。',prerequisites,
 rows.map((r,i)=>{const [te,tz,en,zh,ex,exzh,q,qzh,a,calc,yes,yeszh,no,nozh]=r;return [zhNames[i],te,tz,en,zh,ex,exzh,q,qzh,a,calc,`${yes} Common misconception: “${no}”`,`${yeszh}常见误解：“${nozh}”`,yes,yeszh,no,nozh];}),extraSources);
}
const scientificFoundation={
 P:b('A physical model starts with a clearly specified system and measurable quantities. Write down the reference frame, units, boundary conditions and idealizations before using an equation. A scalar has magnitude; a vector also has direction. A rate describes change per unit time, while an accumulated quantity adds contributions over an interval. Conservation laws compare the same defined system at different times and require accounting for transfers across its boundary. An equation is a relationship between quantities, so both sides must have the same dimensions. Dimensional agreement is necessary but cannot prove a model. Check a simple limiting case and compare a prediction with independent evidence before trusting an extrapolation.', '物理模型始于明确的系统与可测量的量。使用方程前，写出参考系、单位、边界条件和理想化假设。标量只有大小，矢量还具有方向。变化率描述单位时间内的改变，累积量则把区间内的贡献相加。守恒定律比较同一定义系统的不同时刻，必须计入穿过边界的转移。方程两侧必须具有相同量纲，但量纲一致并不能证明模型。应检查简单极限，并用独立证据检验预测，然后才谨慎推广。'),
 C:b('Chemistry connects observable properties with the identities, arrangements and interactions of particles. An atom has a positively charged nucleus and electrons; a molecule is a bonded collection of atoms. A mole counts entities, and concentration compares an amount with a stated volume. Begin by identifying the species, phases, temperature and system boundary. Conservation of atoms and electric charge constrains every balanced reaction. A reaction equation describes stoichiometric change but does not by itself specify a mechanism or speed. Equilibrium concerns competing forward and reverse processes; kinetics concerns how fast change occurs. Laboratory numbers also depend on sampling, calibration and uncertainty, which must be considered when comparing a model with a measurement.', '化学把宏观性质与粒子的种类、排列及相互作用联系起来。原子具有带正电的原子核和电子；分子是相互成键的原子集合。摩尔计数粒子，浓度把物质的量与指定体积联系起来。先识别物种、相态、温度和系统边界。所有配平反应都受到原子和电荷守恒约束。反应方程式说明计量变化，却不能单独确定机理或速率。平衡关注正逆过程竞争，动力学关注变化快慢。实验数值还取决于取样、校准与不确定度，比较模型与测量时必须考虑这些因素。'),
 B:b('Biology explains living systems through interacting structures, chemical processes and inherited information. A cell is a bounded chemical system that exchanges matter and energy with its environment. Genes influence molecular products, but traits also depend on regulation, development and environmental conditions. Organisms vary, so a biological claim often concerns a distribution or tendency rather than an exceptionless rule. Identify the level of explanation: molecule, cell, tissue, organism, population or ecosystem. Distinguish a directly observed result from an inferred mechanism. A controlled comparison changes one proposed cause while accounting for other differences. Repeated observations, appropriate controls and alternative explanations matter more than whether a diagram looks persuasive.', '生物学通过相互作用的结构、化学过程和遗传信息解释生命。细胞是有边界的化学系统，与环境交换物质和能量。基因影响分子产物，但性状还取决于调控、发育与环境。生物具有变异，因此许多结论描述分布或趋势，而非毫无例外的规则。应明确解释层次：分子、细胞、组织、个体、种群或生态系统。区分直接观察的结果与推断的机制。对照比较改变一个待检验原因，同时考虑其他差异。重复观察、适当对照与替代解释，比图示是否直观更重要。')
};
function survey(id, pre, rows, extras=[]) {
 const f=scientificFoundation[id[0]];
 compact(id,rows.map(r=>r[0]),f.en,f.zh,pre,rows.map(r=>{
  const [name,terms,termsZh,en,zh,ex,exzh,q,qzh,a,calc,yes,yeszh,no,nozh]=r;
  return [terms,termsZh,en,zh,ex,exzh,q,qzh,a,calc,yes,yeszh,no,nozh];
 }),extras);
}
function units(id, pre, rows, extras=[]) {
 survey(id,pre,rows.map(r=>{
  const [name,te,tz,en,zh,q,qzh,a,calc,yes,yeszh,no,nozh]=r;
  return [name,te,tz,en,zh,`${q}\n\n${calc}`,`${qzh}\n\n${calculationZh(calc)}`,q,qzh,a,calc,yes,yeszh,no,nozh];
 }),extras);
}

// Substantive topic expansions are intentionally separate from repeated study-method
// guidance. Validation must count these original topic paragraphs, not boilerplate.
const expansions = {};
// Keep authored sentence order while giving long prose a readable rhythm.
const sentenceSegmenters={en:new Intl.Segmenter('en',{granularity:'sentence'}),zh:new Intl.Segmenter('zh',{granularity:'sentence'})};
function paragraphs(value,language){
 if(value.includes('\n\n'))return value;
 const sentences=[...sentenceSegmenters[language].segment(value)].map(x=>x.segment.trim());
 const groups=[];for(let i=0;i<sentences.length;i+=3)groups.push(sentences.slice(i,i+3).join(language==='zh'?'':' '));
 return groups.join('\n\n');
}
function expand(moduleId,en,zh){
 expansions[moduleId]=b(en,zh);
 const lesson=lessons.find(x=>x.moduleId===moduleId);
 if(!lesson) return; // Course record can appear later in this authored source file.
 lesson.sections[0]={type:'concept',title:b('How the ideas fit together','理解概念之间的联系'),body:b(paragraphs(en,'en'),paragraphs(zh,'zh'))};
 lesson.topicTeachingWords=(en.match(/\b[\w]+\b/g)||[]).length;
}

expand('P14.01','Statistical mechanics distinguishes a microscopic specification from a macroscopic description. A microstate records the detailed state permitted by the chosen classical or quantum model, while a macrostate groups states sharing quantities such as energy, volume or magnetization. Multiplicity counts how many microstates satisfy those constraints when discrete counting is appropriate. If accessible microstates are equally likely, Boltzmann entropy is kB lnΩ, so independent multiplicities multiply while their entropies add. The logarithm is essential to this additivity. A large multiplicity makes a macrostate overwhelmingly probable in many-particle systems, explaining why reproducible thermodynamic behavior can emerge from microscopic variability. Equal probability is an assumption tied to an ensemble and dynamics, not permission to assign equal likelihood to arbitrary macrostates. Classical continuous phase space requires a measure and normalization rather than naively counting infinitely many points. Coarse graining determines which microscopic distinctions are ignored, and entropy should be interpreted with the specified description in mind. A system can have many particles yet few accessible configurations under strong constraints. Relate entropy changes to changes in accessible states and energy distribution instead of relying only on the vague image of increasing messiness.','统计力学分微观规格与宏观描述。微观态记录选经典量子模型允许的细节，宏观态按能量、体积、磁化等分组。离散适用时简并度计约束下态数，等可能时 S=kB lnΩ，独立态数相乘熵相加，对数使广延相加。多粒子中大简并宏态压倒性概率，解释微变中可重复热行为。等概率依系综动力学，不是任意宏态均等。经典连续相空间需测度归一，不能数无限点。粗粒化决定忽略何差，熵须配描述。强约束下粒多仍可能可及构型少。应联系可及态和能分布，不只用变乱模糊图像。');
expand('P14.02','An ensemble is a probability model for systems prepared under specified macroscopic constraints. A microcanonical ensemble fixes energy, volume and particle number in the ideal isolated description. A canonical ensemble allows energy exchange with a thermal reservoir while fixing temperature, volume and particle number. A grand-canonical description also permits particle exchange and introduces chemical potential. In the canonical ensemble, each state carries a Boltzmann weight exp(−βE), where β = 1/(kBT). The partition function sums weights and normalizes probabilities, including degeneracy when several states share an energy. Average energy is a weighted average, not simply the most probable state’s energy. Derivatives of the partition function connect microscopic energies to macroscopic free energy, heat capacity and fluctuations. A chosen ensemble must match the physical exchanges allowed by the boundary. Different ensembles often agree for large ordinary systems under suitable conditions, but finite systems or special interactions can reveal differences. An additive energy reference changes the partition function by a factor while leaving normalized probabilities consistently related. Keep the state count, statistical weight and probability distinct; forgetting normalization is a common source of incorrect averages.','系综是指定宏约束的概率模型。微正则固定能体积粒数，正则允许与热库换能但固定温体积粒数，巨正则还换粒子并引化学势。正则权重 exp(−βE)，β=1/(kBT)，Z 求和归一，同能简并也计。平均能是加权平均，不只是最可能态能，Z 导数连自由能、热容和涨落。系综须匹配边界可交换量，大普通系统适当条件常等价，有限或特殊作用可有差。整体能量参考平移使 Z 乘因子，归一概率一致不变。应分态数、权重与概率，漏归一常致错平均。');
expand('P14.03','The classical ideal gas provides a bridge between molecular motion and thermodynamic quantities. At equilibrium, the velocity components follow distributions determined by temperature and particle mass, giving the Maxwell speed distribution after accounting for the number of velocity directions at each speed. The most probable speed, mean speed and root-mean-square speed are different statistics. Equipartition assigns an average kBT/2 to each independent quadratic contribution to energy when classical assumptions are valid. Translational motion therefore gives 3kBT/2 per particle in three dimensions, while rotational or vibrational contributions depend on which degrees of freedom are accessible. Quantum level spacing can freeze out modes at low temperature, invalidating a naive classical heat-capacity count. Collisions establish equilibrium and transport properties; the mean free path characterizes distance between collisions in a simplified kinetic model. Pressure comes from momentum transfer, while diffusion and viscosity involve transport through molecular motion. An ideal-gas equation of state does not alone determine every relaxation rate, because collision details matter. Specify equilibrium, dilution and classical limits before using a distribution or equipartition formula, and do not imagine that every molecule permanently carries the mean energy.','经典理想气桥接分子与热量。平衡速度分量分布依温度质量，计每速率方向数后成麦克斯韦速率分布。最概然、平均、方均根不同。经典条件能均分使每独立二次能项均 kBT/2，三维平动每粒3kBT/2，转振贡献依可及自由度。低温量子间隔可冻结模式，朴素经典热容计数失效。碰撞建立平衡及输运，简动理论平均自由程描述碰间距。压强源动量传递，扩散黏性源分子输运。状态方程不单定每松弛速率，碰撞细节重要。用分布均分前明平衡、稀薄和经典限，不能想每分子永久带平均能。');
expand('P14.04','Quantum statistics becomes important when identical particles cannot be treated as individually distinguishable occupants of separate classical trajectories. Fermions have antisymmetric many-particle states and obey exclusion, allowing at most one identical fermion in each complete one-particle state. Bosons have symmetric states and can share a state without that exclusion restriction. Fermi–Dirac and Bose–Einstein occupation distributions incorporate these differences together with temperature and chemical potential. At low occupation per available state, both approach the classical dilute limit, explaining why many gases can be treated approximately with Maxwell–Boltzmann statistics. A fermion system can have a filled set of low-energy states even near zero temperature, with the Fermi energy marking an important scale. Bosons can show collective occupation phenomena under appropriate conditions, but particle interactions and dimensionality affect real behavior. Spin labels count as part of a state, so two electrons with opposite spins can occupy the same spatial orbital without violating exclusion. Quantum statistics is not simply an extra repulsive or attractive force between particles; it arises from exchange symmetry and combines with actual interactions. Distinguish a single-state occupation from a spatial density, since many distinct states can overlap in the same region.','量子统计在相同粒子不能当各自可辨经典轨迹时重要。费米多体反对称，每完整单粒子态至多一个；玻色对称，可共享无此排除。费米—狄拉克与玻色—爱因斯坦分布结合温度化学势。每可用态低占时两者趋经典稀薄，解释许多气体可麦克斯韦—玻尔兹曼近似。费米近零温仍可填低能态，费米能给尺度。玻色适当条件可集体占据，但真实行为依作用和维度。自旋属态标签，两反自旋电子可同空间轨道。统计不是额外排斥吸引力，而源交换对称并与真作用合并。态占据不同于空间密度，多不同态可在同区域重叠。');
expand('P14.05','A solid combines ordered or disordered atomic structure with collective motion and electronic states. In a crystalline approximation, atoms oscillate around equilibrium positions and their coupled vibrations can be decomposed into normal modes. Quantizing those modes gives phonons, useful quasiparticles that describe vibrational energy and momentum-like crystal properties rather than new fundamental atoms. Phonon populations contribute to heat capacity and thermal transport. Electrons experience a periodic potential that organizes allowed energies into bands, with possible gaps where no extended state of the simple model exists. Whether a band is filled, partially filled or separated from accessible empty states helps distinguish metallic, semiconducting and insulating behavior. Temperature, impurities and defects can change carrier populations and scattering. A band gap alone does not determine every conductivity measurement, because mobility and interactions also matter. The independent-electron band model can fail in strongly correlated materials, and disordered materials need additional descriptions. Crystal momentum is related to lattice translation symmetry and should not be identified blindly with free-particle mechanical momentum. Connect an observed property to the relevant lattice, carrier and scattering mechanisms rather than treating the word solid as one uniform physical model.','固体结合原子结构、集体运动和电子态。晶近似原子绕平衡振，耦合分解简正模，量子化为声子，是描述振动能与晶体动量样性质的准粒子，不是新基本原子。声子布居贡献热容输热。周期势使电子允许能成带，可能带隙无简单模型延展态。填满、半填或隔空带帮助区金属半导体绝缘。温度、杂质缺陷改载流和散射，带隙不独定电导，还需迁移率作用。强关联可使独立电子能带失效，无序另需描述。晶体动量关联平移对称，不能盲等自由机械动量。解释性质须连晶格、载流和散射，不把“固体”当统一模型。');
expand('P14.06','A phase is a macroscopically distinct form of organization characterized by properties such as density, symmetry or long-range order. A phase transition changes that organization as a control variable such as temperature, pressure or field is varied. An order parameter is a quantity chosen to distinguish phases, for example magnetization in a simple magnetic model. First-order transitions can involve discontinuous changes and latent heat, while continuous transitions can show growing fluctuations and no latent heat in the ideal classification. Near a critical point, correlations between distant regions may become important, so independent-particle reasoning fails. A correlation length describes the spatial scale over which fluctuations are related, and its growth can make details at many scales relevant. Universality refers to shared critical behavior among different systems with appropriate common symmetry and dimensional features, not identical microscopic mechanisms. Finite samples round sharp ideal transitions, and hysteresis can reflect metastability and nucleation barriers rather than equilibrium alone. A lattice-spin model is useful for isolating collective effects but is not a literal complete picture of every magnetic material. Compare order parameters, fluctuations and response functions to identify the transition rather than relying on one dramatic-looking snapshot.','相是以密度、对称或长程有序等区分的宏组织，温压场变时转组织为相变。序参量选来区相，如简单磁模型磁化。一级可不连续并有潜热，连续理想分类可涨落增而无潜热。临界附近远区关联重要，独立粒子失效；关联长度描述涨落联系空间尺度，增长使多尺度相关。普适指适当共同对称维度系统共享临界行为，不是微观机理同。有限样品圆化理想尖转，滞后可反映亚稳与成核，不只平衡。格点自旋隔离集体现象有用，却不是每磁材料完整真像。应比较序参量、涨落和响应识别转变，不靠单张戏剧快照。');

expand('P13.01','An Olympiad estimate begins by identifying the dominant physical scales rather than immediately seeking an exact formula. List quantities that can influence the result and their dimensions, then construct combinations with the required units. Dimensional analysis can restrict a relation but cannot determine every dimensionless factor or distinguish all possible functional dependencies. Similarity arguments compare systems whose shapes or dimensionless parameters are held fixed. Doubling every length multiplies area by four and volume by eight, so strength, weight and heat loss need not scale together. An order-of-magnitude estimate uses explicit approximate values and aims to distinguish scales, not to manufacture unjustified significant digits. Limiting cases test a proposed result when a parameter vanishes, becomes very large or makes the geometry symmetric. If a predicted force stays nonzero after its source is removed, the model or algebra is likely wrong. A balance of competing effects can identify a crossover scale even without solving the full dynamics. State which neglected effect could become important beyond that scale. Good estimation includes a plausible range and sensitivity to uncertain inputs rather than one confident-looking rounded number.','竞赛估算先找主导尺度而非立刻精确式。列可能影响量及量纲，构目标单位组合；量纲约束却不能定全部无量纲因子和函数依赖。相似比较保持形状或无量纲参数，长度全加倍则面积四倍体积八倍，强度重力散热不必同缩。数量级估明确近似值，目的是分尺度，不制造有效位。极限检参数零、大或对称，源撤仍有预测力常示错误。平衡竞争效应可不解完整动力学先找交叉尺度，说明超后何忽略项重要。好估算给合理范围和输入敏感，而非一个看似自信的圆数。');
expand('P13.02','Coupled mechanics problems combine force laws with kinematic constraints, so neither part can be solved in isolation. First choose bodies or a whole system and draw only the forces acting on that choice. Internal tensions may cancel in a whole-system momentum equation but remain important in an individual-body equation. An inextensible rope gives a length relation; differentiating it relates velocities and accelerations, with factors determined by moving pulleys or changing geometry. A rolling condition links translation and rotation only while no slipping occurs. Check whether the required friction lies within the available static-friction range. Contact can also be lost when a solved normal force would need to become negative. Energy methods can bypass internal forces when the relevant constraints do no work, but a moving support or dissipative contact can transfer energy. Momentum conservation requires negligible external impulse over the chosen interval, which may hold during a short collision even when it fails over longer motion. Divide the motion into stages when constraints change, preserving the correct state information at each transition. An elegant single equation is not valid if it silently spans incompatible contact or friction regimes.','耦合力学须力律和运动约束并用。先选物体或系统，只画作用其上的力。内张力可在整体动量式抵消，单体仍重要。不可伸绳给长度关系，微分得速度加速度比例，系数由动滑轮或几何决定。滚动约束只在不滑成立，需检所需摩擦不超静限；支持力算负意味着可失接触。约束不做功时能量可绕内力，但动支架或耗散接触可传能。动量守恒需所选区间外冲量可忽略，短碰撞可能成立而长程不行。约束变化应分阶段，正确传状态。跨不相容接触摩擦区的一条漂亮式不有效。');
expand('P13.03','A field–circuit–thermal problem requires several models joined by shared variables. Electrical current can produce Joule heating, heating can change resistance, and that resistance change can alter current under the source constraint. Begin by deciding whether the source maintains voltage, current or a more realistic load-dependent terminal relation. Write electrical power consistently and place it into a thermal balance containing heat capacity and heat loss. A steady temperature means net heating is zero, not that no electrical energy flows. If a magnetic or electric field changes mechanical motion, the motion may in turn change emf, capacitance or flux, creating another feedback loop. Conservation of total energy helps connect these descriptions and detect double counting. Linearize around a steady state only when deviations are small, and examine whether a small temperature rise increases or decreases net heating to assess stability. Several mathematical steady solutions can exist, but not all need be stable or physically reachable. Identify timescales before deciding whether electrical variables can be treated as instantaneous relative to thermal ones. A clear solution states each coupling relation and the assumptions under which it remains valid.','场电热题由共享变量接几模型。电流焦耳热改电阻，电阻再改源约束下电流。先定恒压、恒流或真实负载端压。电功率纳入含热容散热的热平衡，稳温是净热零，不是无电能流。场改机械运动，运动再改电动势、电容或磁通，形成反馈。总能守恒连接描述并防双计。只小偏离才线性化，温升使净热增减决定稳定。多个数学稳态未必都稳定可达。先比时间尺度再把电变量视为相对热即时。清晰解应列耦合关系和有效假设。');
expand('P13.04','Problems connecting optics and modern physics often require switching carefully between propagation and detection models. Ray optics can locate an image when geometric assumptions hold, while wave optics determines interference, diffraction and resolution. A detector may then respond to discrete photon absorption, relating energy flow to photon count through E = hf. The photon energy is set by frequency, whereas intensity changes the number arriving per time for a fixed frequency. Quantum efficiency and background counts affect recorded detections, so measured counts are not automatically the total incident photon number. In a photoelectric problem, compare photon energy with the work function before assigning kinetic energy to emitted electrons. A diffraction grating can separate wavelengths, and that wavelength information can constrain atomic energy-level differences. Keep vacuum wavelength, wavelength in a medium and frequency distinct. A limiting-case check can reveal an invalid approximation, such as using small-angle fringe spacing at a very large angle. Combining models is legitimate when their domains overlap and the interface quantities are defined; it is not legitimate to mix a classical continuous-energy assumption with a quantum threshold while ignoring the inconsistency.','光学现代连接题须谨慎切传播与探测模型。射线在几何条件下定位像，波模型定干涉衍射分辨，探测离散吸光子以 E=hf 连能流计数。光子能由频率定，固定频率增强度增每时到达数。量子效率与背景使实测不等总入射数。光电先比 hf 与逸出功再赋电子动能。光栅分波长可约束原子能差，须分真空波长、介质波长和频率。大角套小角条纹等可由极限抓错。模型范围重叠且接口量明确时可组合，不能一边假连续能一边用量子阈却忽略冲突。');
expand('P13.05','An experimental data challenge asks which physical conclusions are supported by a finite noisy dataset. Identify the measured variables and units before fitting, and distinguish directly measured quantities from quantities derived using the model being tested. If a graph’s axis already contains a theoretical transformation, a straight line may be partly built into the analysis, so inspect the original data and assumptions. Use uncertainties to judge whether residual patterns are meaningful. A systematic offset, a scale error and random scatter produce different signatures and require different remedies. Compare competing models through predictions that differ within the available measurement range rather than only through the number of adjustable parameters. When estimating a parameter from a slope, propagate calibration and axis uncertainties rather than using only the fitting software’s internal error. Outlier removal requires an explicit defensible rule or documented measurement failure, not mere inconvenience. A result consistent with a theory does not uniquely prove every assumption, especially when an alternative predicts nearly the same curve. State the strongest supported claim, the main unresolved uncertainty and the next measurement that would most improve discrimination.','实验数据挑战问有限噪声支持何结论。拟合前识变量单位，区分直测与用待检模型导出的量。轴含理论变换时，直线可能部分内建，需看原数据假设。用不确定判断残差模式意义，零偏、比例错和随机散不同签名补救。应比较现范围内预测差，而非只数参数。斜率估参数需传播校准和双轴不确定，不只软件内误。删异常需明规则或已知失败，不能嫌不便。与理论相容不唯一证明全部假设，尤当替代理论近同曲。应述最强支持主张、主要未解与最能区分的下一测量。');
expand('P13.06','Timed physics work benefits from a staged strategy that preserves reasoning under pressure. First identify the system, requested quantity and applicable regime, then select the governing laws before committing to algebra. Mark assumptions such as negligible friction, small angle, quasistatic change or nonrelativistic speed because later subparts may deliberately violate them. Separate independent subproblems and carry unresolved earlier results symbolically when possible. A diagram with signs and reference directions prevents repeated ambiguity in vector calculations. Estimate scale and limiting behavior before evaluating numbers, then check dimensions after each major transformation. In an experimental component, reserve time for setup checks, raw-data recording and uncertainty rather than spending the whole interval collecting more points. Partial credit in a learning setting should reflect a valid model and derivation even when one arithmetic step fails, so write enough intermediate reasoning to locate errors. After the session, classify mistakes into concept gaps, model selection, algebra, units, graph interpretation and time allocation. Re-solving the identical problem from memory is weaker evidence than applying the same principle to a changed constraint or unfamiliar geometry. Use those transfer problems to decide which route node needs further study.','限时物理需分阶段保推理。先识系统、目标和适用区，再选规律后代数。标无摩擦、小角、准静态、低速等假设，后题可能故意破坏。分独立子题，前结果未解可符号携带。图上标正负参考防矢量反复歧义，数算前估尺度极限，重大变换后检量纲。实验预留装置检查、原始记录和不确定，不全耗多取点。学习评分应识别有效模型推导，即使一步算错，所以写足中间可定位。事后分概念、选模、代数、单位、读图和时间错。背同题重做弱于换约束或陌生几何迁移，用后者判断下一路由节点。');

expand('P12.01','An instrument converts a physical quantity into an indication through a response that must be understood. Resolution is the smallest change the display or scale can distinguish, while calibration compares indications with reference values to estimate offsets, scale factors or nonlinear response. A digital display with many digits can still be biased, unstable or poorly calibrated. Accuracy concerns agreement with an appropriate reference, whereas precision concerns repeatability under stated conditions. A zero check detects one kind of offset but does not establish the entire scale. Calibrating at several points across the working range can reveal gain error or curvature that a single reference misses. The instrument can also affect the measured system: a thermometer exchanges heat, a voltmeter draws some current and a mechanical probe can deform a surface. Response time matters when the quantity changes during measurement. Record the instrument, range, calibration relation and relevant environmental conditions rather than copying only the final number. Correct known systematic effects where justified and retain uncertainty in the correction. The aim is a traceable measurement model connecting the indication to the quantity, not an unsupported claim that a more expensive device must be correct.','仪器经响应把物理量变示值。分辨率是可区分最小变化，校准与参考比以估零偏、比例或非线性。多位数字仍可有偏、不稳或未校。准确关注参考一致，精密关注指定条件重复。查零仅检一种偏移，不建全量程；多点校准可见单点漏的增益曲率。仪器还扰被测：温计换热，电表取流，探针变形表面。变时测量响应时间重要。应记录仪器、量程、校准和环境，不只抄数。已知系统效应可合理修正并保修正不确定。目标是从示值到量的可追溯模型，不是贵仪器必正确。');
expand('P12.02','Every measurement is an estimate accompanied by uncertainty arising from the instrument, procedure, environment and sampling. Repeated readings can estimate random variation, but a shared calibration bias may remain invisible in their spread. The arithmetic mean summarizes repeated values, and under suitable independence and stability assumptions its statistical uncertainty can shrink as more readings are averaged. That reduction does not apply unchanged to correlated drift or a common systematic effect. Standard deviation describes variation among readings; uncertainty of the mean describes uncertainty in an estimated average and is a different quantity. When combining measured quantities, propagate their uncertainties through the measurement equation, considering correlations when inputs share a source. Linear approximations work when uncertainties are sufficiently small and the model is locally smooth; strongly nonlinear cases may need another method. Significant digits communicate reporting precision but are not a full uncertainty analysis. Compare two results using their uncertainties and covariance rather than declaring disagreement whenever their printed numbers differ. State whether a reported interval is a standard uncertainty, expanded interval or another convention, because identical plus–minus notation can otherwise hide different meanings.','测量是带仪器、方法、环境及抽样不确定的估计。重复可估随机变异，但共同校准偏在分散中不可见。适当独立稳定假设下，多读数平均可缩统计不确定，却不直接适于相关漂移或共同系统效应。标准差描述读数变异，均值不确定描述平均估计，两者不同。组合测量须经方程传播误差，同源输入需相关。小不确定且局部平滑可线性近似，强非线性另需方法。有效数字传报告精度，不是完整不确定分析。比结果应考虑不确定及协方差，而非印数不同就不一致。加减区间须说明标准、扩展或其他约定，否则相同符号可藏不同含义。');
expand('P12.03','A mechanics experiment tests a relation between motion and controlled conditions rather than merely reproducing a familiar number. For a pendulum, the small-angle model predicts T = 2π√(L/g), where L is the distance from pivot to the bob’s centre of mass under the point-mass approximation. Timing many complete oscillations reduces the relative contribution of start–stop reaction time, but damping, changing amplitude and support motion can introduce other effects. Varying length and plotting T² against L tests both proportionality and possible intercept problems. A friction experiment should distinguish static threshold from kinetic sliding and specify how normal force is measured. A cart experiment must consider track inclination, pulley inertia, sensor calibration and whether acceleration is actually constant. Choose a range large enough to discriminate models but within the apparatus’s reliable behavior. Record raw position or timing data when possible so alternative analyses remain available. Check the expected units and limiting behavior before fitting. Agreement with one predicted value supports only that comparison; testing a scaling law across conditions provides stronger evidence for the model and can expose a systematic offset.','力学实验检运动与受控条件关系，不只是复现熟数。小角摆 T=2π√(L/g)，点质近似 L 为支点到球质心。多完整振动计时减启停相对误差，但阻尼、变幅和支架动带来其他效应。变 L 画 T²-L 可检正比及截距问题。摩擦实验需分静阈和滑动，说明 N 测法；小车需考虑轨道斜、滑轮惯量、传感校准和是否真恒加速。范围要足以区分模型又在装置可靠区。尽可能保原位置时间，让替代分析可行。拟合前检单位极限。单值吻合只支持该比，多条件缩放更强且能显系统偏。');
expand('P12.04','Electrical and optical experiments require a model of both the target system and the measuring apparatus. An ammeter belongs in series with the branch whose current is measured, while a voltmeter compares the potentials of two nodes. Their finite internal impedances can modify the circuit, particularly when the measured component has a comparable impedance. Lead resistance, contact resistance and source internal resistance may matter when seeking precision. For time-dependent signals, bandwidth and sampling rate constrain which features can be resolved, and aliasing can create misleading apparent frequencies. In optics, align the source, lens and detector axes, define the criterion for a focused image and measure distances from the appropriate reference planes. A finite aperture, thick lens or off-axis ray can violate a simple thin-lens approximation. Parallax and screen-position uncertainty affect distance estimates. Use repeated measurements or a fitted relationship across several object positions rather than trusting one visually judged focus. Check whether changing an instrument range, probe or aperture changes the result, since that can reveal measurement loading or model limitations. Report the configuration explicitly so the observed behavior can be reproduced.','电光实验需同时建目标和仪器模型。电流表串所测支路，电压表比两节点，有限内阻在与组件阻抗相近时改电路。导线、接触和源内阻可影响精度。时变信号带宽采样约束细节，混叠可造假频。光学需对源镜探测轴，定义清晰成像判据，并从适当参考面量距。有限孔、厚镜或离轴可违薄镜近似，视差和屏位不确定影响距离。宜多物距重复或拟合，而非一次目测对焦。改量程、探头或孔径若改结果，可揭负载和模型限制。配置应明报以便复现。');
expand('P12.05','Fitting estimates model parameters by comparing predicted and observed data, but the result is meaningful only relative to a measurement and error model. A least-squares line is appropriate under particular assumptions about which variable contains uncertainty and how residuals are distributed. If both axes have important errors or points share correlated drift, ordinary unweighted fitting may be inadequate. A residual is the observed value minus the fitted prediction. Random-looking residuals of an appropriate scale are consistent with the model, while curvature, time trends or changing spread suggest missing structure or unsuitable weighting. A high coefficient of determination does not prove causation or justify extrapolation far beyond the data. Parameter uncertainty also depends on the range and distribution of measurements, so many nearly identical points may constrain a slope poorly. A nonzero intercept can indicate a real offset, background or model failure rather than something to delete automatically. Compare alternative physically motivated models and inspect whether added parameters improve prediction rather than merely fitting noise. Preserve raw data and document exclusions so another analysis can test the same claims.','拟合以预测观察比较估参数，意义依测量误差模型。最小二乘直线适用于误差在哪轴及残差分布等特定假设；双轴大误差或共同漂移时普通无权可能不足。残差为观测减预测，适当尺度随机状与模型相容，曲率、时间趋势或变散度提示漏结构或权重不适。高决定系数不证明因果也不保证远外推。参数不确定依范围分布，许多近同点可能很差地约束斜率。非零截距可能真偏移背景或失模，不能自动删。比较物理动机替代，检查加参数是否改善预测而非追噪。保原数据及排除记录，让他人检同主张。');
expand('P12.06','Experimental design begins with a question whose competing answers lead to measurably different predictions. Specify the dependent quantity, controlled variables, deliberately changed variable and conditions under which the model should hold. A control measurement can reveal background or apparatus effects, while randomizing run order can reduce confusion between a treatment change and time drift. Replication should address the source of variation of interest rather than repeatedly reading an unchanged display and calling it independent evidence. Plan the measurement range and expected uncertainty before collecting data so the apparatus can discriminate the predicted effect. Record procedures and deviations as they occur. In a report, separate observations, data processing, model assumptions and interpretation, and show how the uncertainty supports the final claim. A defense of the experiment should explain why the chosen design tests the hypothesis and what alternative explanation remains possible. Unexpected results are information about the model or method, not automatically bad data to discard. State the limits of validity and propose a follow-up that would resolve the largest remaining ambiguity. Reproducible records and honest scope make a modest experiment more convincing than an elaborate setup with undocumented corrections.','实验设计始于竞争答案能给可测不同预测的问题。明确因变量、控制量、主动改变量及模型成立条件。对照揭背景装置效应，随机运行序减处理与时间漂移混淆。重复应针对目标变异源，不是反复读未变显示就称独立证据。采前规划范围和预期不确定，确保能分辨效应，实时记程序及偏离。报告分观察、处理、假设和解释，说明不确定如何支持主张。答辩解释设计为何检假说、还剩何替代。意外结果是模型方法信息，不自动坏数据应删。明确适用限并提解决最大歧义的后续。可复现记录及诚实范围，比复杂装置加无文档修正更有说服力。');

expand('P11.01','Special relativity begins with two connected principles: the laws of physics take the same form in all inertial frames, and light in vacuum has the same speed c for inertial observers regardless of source motion. These statements require revising the classical assumption that all observers share one universal time. An event is a definite occurrence specified by space and time coordinates in a frame. To compare distant events, observers need a synchronization convention implemented with signals whose travel time is accounted for. Two separated events judged simultaneous in one frame need not be simultaneous in another moving frame. This does not mean observers disagree about whether a signal can causally connect events; the spacetime structure preserves the relevant causal ordering. An inertial frame moves without acceleration, so applying the simple formulas to changing motion requires care. Low-speed predictions approach Galilean mechanics, explaining why everyday velocity addition often works well. A light-clock thought experiment can motivate time dilation, but every comparison must specify which clock’s elapsed time and which pair of events are being compared. Avoid treating relativistic effects as optical illusions caused only by delayed images; they concern corrected spacetime measurements.','狭义相对论以惯性系物理规律同形及真空光速 c 与源运动无关为基础，迫使修正所有人共享绝对时间。事件是确定时空发生，远事件比较需计信号传播的同步约定。一系异地同时在另一运动系未必同时，但不表示观察者对能否信号因果连接任意分歧，时空结构保相关因果序。惯性系无加速，变速套简单式需谨慎。低速趋伽利略，解释日常速度相加有效。光钟思想实验可启发时间膨胀，但须指哪钟及哪对事件。相对效应不是仅由图像延迟的光学错觉，而是校正后时空测量。');
expand('P11.02','Lorentz transformations relate the coordinates of the same event in inertial frames moving uniformly relative to each other. For relative motion along x, the transformation mixes x and t through the factor γ = 1/√(1 − v²/c²). The proper time between two events on one clock’s worldline is the time read by that clock; another frame can assign a longer coordinate interval for those same events. Length contraction concerns the separation of an object’s endpoints measured simultaneously in the measuring frame. Because simultaneity differs between frames, one must not compare two endpoint events chosen simultaneously in a different frame and call that the same length measurement. The spacetime interval is invariant even though separate space and time intervals change. Relativistic velocity addition preserves the speed limit for signals and massive objects under the appropriate assumptions, replacing simple addition near c. Reciprocal time-dilation statements are consistent when the event pairs and synchronization conventions are kept straight. Situations involving reunion and acceleration require comparing entire worldlines rather than only repeating a symmetric slogan. Always draw or label the events before substituting into a formula.','洛伦兹变换把同一事件在相对匀速惯性系的坐标联系，沿 x 运动时 x,t 经 γ=1/√(1−v²/c²) 混合。同钟世界线两事件固有时由该钟读，另一系可给更长坐标间隔。长度收缩测两端须在测量系同时，由于同时性异，不能把另一系同时选的两端事件当同长度测量。时空间隔不变而空间时间各变。相对速度合成在近 c 替简单加法，保持信号及有质量物条件下速度限。互相时间膨胀在事件对同步说清时一致。重聚加速需比完整世界线，不是重复对称口号。代公式前始终画或标事件。');
expand('P11.03','Relativistic energy and momentum replace the separate classical formulas with quantities that transform consistently between inertial frames. For a particle of invariant mass m, total energy is γmc² and momentum is γmv. At rest the energy is mc², while kinetic energy is the total minus that rest value. Expanding at low speed recovers approximately mv²/2, so classical kinetic energy is a limiting expression rather than an unrelated rule. The invariant relation E² − p²c² = m²c⁴ applies across frames. A massless particle has E = pc and can carry momentum despite having zero rest mass. Conservation of total energy and momentum must include radiation, internal energy and all participating bodies. The invariant mass of a composite system can change when its internal energy changes, even if the rest masses of its constituent particles remain the same. Massive particles require unbounded energy to approach c in this ideal formula and cannot be accelerated through the limit by a finite energy input. Distinguish invariant mass from older frame-dependent terminology, and use consistent units when comparing energies, momenta and masses.','相对论能量动量以跨惯性系一致量替经典式，有不变质量 m 时 E=γmc²、p=γmv。静能 mc²，动能为总减静；低速展开恢复 mv²/2，经典是极限非无关规则。不变量 E²−p²c²=m²c⁴，无质量粒子 E=pc，零静质量仍携动量。总守恒须包括辐射、内能及全部物体。复合系统内能变可使整体不变质量变，即使组分静质量未变。有质量粒子趋 c 所需能无界，有限输入不能穿越。应分不变质量与旧依系术语，能量动量质量单位需一致。');
expand('P11.04','General relativity extends the description of gravity beyond a force acting in a fixed background spacetime. The equivalence principle states that, within a sufficiently small freely falling region, nongravitational experiments can resemble those in a gravity-free inertial frame. The qualification small is essential: tidal effects, meaning differences in gravitational acceleration across a region, cannot generally be removed by one frame choice and reveal curvature. Freely falling bodies follow spacetime paths called geodesics, while mass-energy and stress influence the geometry through field equations. Clocks at different gravitational potentials can accumulate different elapsed times, and light paths can bend in a gravitational field. In weak, slowly varying fields and at low speeds, predictions reduce approximately to Newtonian gravity. This correspondence is a check on the theory’s useful limit. Curved spacetime is not simply a rubber sheet embedded in ordinary space; that picture can illustrate one aspect while misleading about time and dimensionality. Observational tests include orbital effects, gravitational redshift, lensing and gravitational waves. Distinguish the full theory from weak-field approximation formulas, and avoid treating a conceptual overview as sufficient to solve arbitrary curved-spacetime problems.','广义相对论超越固定时空中的引力力。等效原理说足够小自由落区内非引力实验类似无引力惯性系，“足够小”关键：跨区引力加速度差即潮汐，不能通常靠一换系消除，揭曲率。自由落体沿测地线，质能应力经场方程影响几何。不同引力势钟可积不同时间，光路可弯。弱缓变场低速近牛顿，这是极限检验。弯时空不只是嵌普通空间的橡皮膜，该图只示一面且可误导时间维度。轨道、红移、透镜和引力波提供检验。须分全理论与弱场公式，概念概览不足解任意曲时空问题。');
expand('P11.05','A star’s structure reflects a balance among gravity, pressure, energy generation and energy transport. Hydrostatic equilibrium means that an inward gravitational tendency is balanced by an outward pressure gradient, not that all parts of the star have equal pressure. Temperature, density and composition determine which nuclear reactions occur and how efficiently radiation or convection carries energy outward. During the main sequence, core hydrogen fusion is the dominant energy source in the usual model, but the fusion route depends strongly on mass and temperature. A more massive star has more fuel yet often consumes it much faster because its luminosity is much greater, so greater mass does not imply longer life. As core composition changes, the structure readjusts and later burning stages or compact remnants become possible. White dwarfs, neutron stars and black holes arise in different evolutionary channels with important mass-loss and binary-interaction complications. A Hertzsprung–Russell diagram compares luminosity with temperature or related observables; position is not a direct chronological clock for every individual star. Infer stellar properties by combining spectra, brightness, distance and models, keeping observational estimates separate from assumptions about interior structure.','恒星结构反映引力、压强、产能和输运平衡。流体静力是向内引力由向外压强梯度平衡，不是各处等压。温密组成决定核反应及辐射对流效率。通常主序核心氢聚变主供能，具体途径强依质量温度。大质量燃料更多但光度大消耗更快，因此不意味着寿命长。核心组成变化使结构调整，出现后续燃烧和致密遗迹。白矮、中子星和黑洞由不同通道产生，质量损失及双星作用复杂。赫罗图比光度与温度等量，不是每星直接年龄钟。须综合光谱、亮度、距离和模型推性质，分观测估计与内部假设。');
expand('P11.06','Cosmology uses observations to test models of the universe’s large-scale evolution. In an expanding spacetime, light emitted earlier can arrive with a longer wavelength, giving cosmological redshift. This is related to the scale-factor change and should not always be interpreted as an ordinary local Doppler velocity, especially at large redshift. For nearby galaxies, recession and distance approximately follow a linear Hubble relation, but peculiar motions and distance-measurement uncertainties complicate individual cases. The cosmic microwave background provides a nearly thermal relic radiation field with small anisotropies that constrain early conditions and later evolution. Primordial light-element abundances, galaxy distributions and supernova distance measurements provide additional independent tests. Model parameters are inferred jointly, so one observation rarely fixes every component of the model. Dark matter and dark energy are names for distinct inferred contributions with different evidence and effects, not interchangeable substances directly photographed by a telescope. Expansion does not mean every bound system expands at the same rate; local gravitational or electromagnetic binding can dominate. Separate measured redshifts and brightnesses from the model-dependent distances and histories inferred from them.','宇宙学用观察检大尺度演化模型。膨胀时空使早发光到达波长更长，红移联系尺度因子，不应尤其大红移都当普通局部多普勒速度。近星系速度距离近哈勃线性，但本动及距离误差影响个例。微波背景为近热遗留辐射，小各向异性约束早期及后演；原初轻元素、星系分布和超新星距离另给独立检验。参数联合推断，一观察少能定全部。暗物质暗能是证据作用不同的推断贡献，不是可互换或望远镜直接拍的物。膨胀不意味每束缚系统同速胀，局部引力电磁束缚可主导。须分实测红移亮度与依模型推距离历史。');

expand('P10.01','Quantum physics was motivated by observations that classical models could not explain together. Thermal radiation spectra, atomic line spectra and the photoelectric effect revealed that energy exchange cannot always be treated as continuously adjustable. In the photoelectric effect, a photon with energy hf must supply the material’s work function before an emitted electron can carry kinetic energy; increasing intensity below the appropriate threshold does not simply give each photon more energy. Electron diffraction and interference show wave-like behavior for matter, with de Broglie wavelength h/p. These experiments do not mean that an electron is literally a small classical ball that sometimes turns into a water-like wave. The quantum description predicts probabilities for outcomes using amplitudes whose interference matters. Localization of a detection event and an extended interference pattern can both occur in the same experimental framework. Which features are observed depends on the preparation and measurement arrangement. Classical mechanics and wave optics remain useful limits when quantum discreteness or coherence is not resolved. Begin each example by identifying the measured quantity, such as energy threshold, wavelength or detection count, rather than invoking wave–particle duality as a slogan without a calculation.','量子起因是经典模型无法同时解释的观察。热辐射、原子线谱与光电显示能量交换不总连续。光电中 hf 先付逸出功，余为电子动能，低阈下增强度不直接增加每光子能。电子衍射干涉显示物质波行为，德布罗意 λ=h/p；这不意味电子是小球偶尔变水波。量子用可干涉振幅预测结果概率，局域探测事件与展开干涉图可在同框架并存，观察特征依制备测量。量子离散相干不显时经典力学波光仍为有效极限。每例先识别能阈、波长或计数等测量量，不能只喊波粒二象无计算。');
expand('P10.02','A quantum state is a mathematical object that encodes amplitudes for possible measurement outcomes relative to a chosen basis. Amplitudes can be complex and interfere; probabilities are squared magnitudes after proper normalization. A global phase multiplying the entire state does not change ordinary measurement probabilities, while relative phases between components can change interference. An observable is represented by a Hermitian operator, whose eigenvalues are possible outcomes in the ideal projective-measurement model. Expanding the state in its eigenbasis gives the corresponding outcome probabilities. An expectation value is a probability-weighted average over repeated identically prepared trials, not a guarantee that one trial returns that average. Operators for incompatible observables need not commute, and uncertainty relations constrain spreads in a state rather than merely describing poor instruments. After an ideal measurement, the state update depends on the outcome and the measurement model. Degenerate outcomes and general measurements need more careful treatment than the simplest one-eigenvector story. Distinguish preparation uncertainty, statistical outcome variation and experimental error. Quantum probabilities make precise testable predictions even though individual outcomes are not generally determined by a classical hidden trajectory in this introductory formulation.','量子态编码相对某基底的结果振幅。振幅可复且干涉，正确归一后模平方为概率。整态共同相位不改普通概率，分量相对相位可改干涉。厄米算符表示可观测量，理想投影测量中本征值为可能结果，在本征基展开得概率。期望值是重复同制备的加权平均，不保证单次等平均。不相容算符可不对易，不确定关系约束态内分散，不只是仪器差。理想测后更新依结果与模型，简并及一般测量需比单本征向量故事更谨慎。须分制备不确定、结果统计变化与实验误差。量子概率虽通常不由经典隐藏轨迹决定单次结果，仍给精确可检验预测。');
expand('P10.03','The time-dependent Schrödinger equation determines how a nonrelativistic wavefunction evolves under a specified Hamiltonian. For a particle in one dimension with potential V(x), the kinetic-energy operator contains a second spatial derivative, linking curvature of the wavefunction with energy. When the potential is time independent, stationary states separate into a spatial energy eigenfunction and a phase factor in time. Their probability density can remain time independent even though the state’s phase evolves. Boundary conditions and normalization determine which solutions are physical. An infinite square well forces the wavefunction to vanish at its walls, producing discrete standing-wave patterns and energies proportional to n². A finite well permits penetration outside the classically allowed region and has a different spectrum. Bound states are normalizable and localized in the relevant sense; scattering states require a different normalization framework. The probability density |ψ|² is not the wavefunction itself, and a negative or complex amplitude is not a negative probability. Superpositions of different energy states can produce time-dependent densities. Check continuity and appropriate derivative conditions at potential boundaries rather than matching only a sketch of the oscillations.','含时薛定谔式决定指定哈密顿下非相对论波函数演化。一维势 V(x) 中动能算符含空间二阶导，连接曲率与能量。定常势允许分离空间能量本征函数和时间相位，虽相位演化，概率密度可不变。边界与归一决定物理解。无限方阱墙处 ψ 零，产生离散驻波和 n² 能；有限阱允许经典禁区渗入，谱不同。束缚态可归一并局域，散射态需不同归一框架。|ψ|² 才是密度，负或复振幅不是负概率。不同能量叠加可使密度时变。边界应检查连续及适当导数条件，不只画振荡草图。');
expand('P10.04','The quantum harmonic oscillator models a quadratic potential near a stable minimum and is important far beyond literal springs. Its allowed energies are (n + 1/2)ℏω, so the ground state retains zero-point energy rather than sitting motionless at the potential minimum. The uncertainty principle provides intuition: confining position too sharply would increase momentum spread and kinetic energy. Raising and lowering operators organize the evenly spaced spectrum, while wavefunctions have increasing numbers of nodes for higher states. The harmonic approximation fails when the potential’s neglected higher-order terms become important. Tunneling concerns a different feature of wave mechanics: a wavefunction can extend through a finite classically forbidden barrier and yield transmission even when particle energy is below the barrier height. Transmission depends strongly on barrier width, height and particle mass, often approximately exponentially in an appropriate regime. This does not violate energy conservation for a static barrier; transmitted particles retain the same total energy. A nonzero probability inside a barrier is not a classical trajectory with negative kinetic energy. Compare the quantum result with the classical turning-point prediction to identify precisely what the wave description adds.','量子谐振子模拟稳定极小附近二次势，远不限弹簧。能级 (n+1/2)ℏω，基态保零点能，不是静止势底；位置太束缚会增动量分散与动能，可作不确定直觉。升降算符组织等间距谱，高态节点增，势高阶重要时谐近似失效。隧穿是另一波特征：有限禁势垒内波函数延伸，能低于垒仍可透射。概率强依宽、高、质量，适当区间常指数。静势垒中不违能量守恒，透射总能相同；垒内非零概率不是负动能经典轨迹。应与经典转向点比较，明确波描述新增何预测。');
expand('P10.05','Quantum angular momentum is described by operators whose components do not all have simultaneously definite values. For orbital angular momentum, a state can have definite L² and one chosen component Lz, with eigenvalues ℏ²l(l+1) and mℏ respectively. The integer m ranges from −l to +l, giving 2l + 1 component states for a fixed l. These labels describe measurement properties, not a tiny arrow following a known classical orientation at every instant. In hydrogen, the Coulomb attraction between electron and nucleus is central, allowing radial and angular structure to be separated. Bound orbitals are labeled by quantum numbers and have characteristic probability distributions and nodes. In the simplest nonrelativistic hydrogen model, energy depends primarily on principal quantum number, while additional interactions produce finer splitting. An orbital image displays probability density or amplitude contours under a chosen convention; it is not a photograph of an electron’s path. Spectral transitions depend on energy differences and selection rules, so not every pair of levels connects with equal strength. Distinguish orbital angular momentum from intrinsic spin, which adds another degree of freedom rather than another spatial orbit.','量子角动量分量不能全同时定值。轨道态可同时有定 L² 与选定 Lz，本征值 ℏ²l(l+1)、mℏ，m 从−l到+l，共2l+1。这是测量性质标签，不是小箭头每时有已知经典方向。氢的核电子库仑为中心势，可分径向角结构。束缚轨道由量子数标，有概率分布与节点；最简非相对论氢能主要依主量子数，其他作用产生精细分裂。轨道图是选约定的密度或振幅等值，不是电子路径照片。谱跃迁依能差和选择定则，不是任意两态同强连接。轨道角动量与内禀自旋不同，后者添自由度而非空间新轨道。');
expand('P10.06','Spin is intrinsic angular momentum with quantum properties that cannot be modeled fully as a tiny rigid sphere physically rotating. A spin-one-half system has two outcomes for a chosen component, while measurements along different axes correspond to different bases. Combining spins and orbital angular momenta produces larger state spaces and coupled total angular momentum. Approximation methods become necessary when a Hamiltonian cannot be solved exactly. Perturbation theory treats a sufficiently small additional interaction around a known solution, while variational methods use trial states to constrain energies under appropriate conditions. Their validity depends on assumptions and convergence, not simply on obtaining a number. For identical particles, exchanging labels cannot create a physically distinguishable situation. Fermionic states are antisymmetric under exchange and lead to Pauli exclusion of identical fermions from the same complete one-particle state; bosonic states are symmetric and permit multiple occupation. Electron shells, atomic structure and material behavior depend on these statistics. “Same state” includes all relevant quantum labels, so two electrons can share a spatial orbital when their spin states differ. Many-particle interactions and correlations require more than independently filling isolated-particle levels, making this a starting framework rather than a complete many-body solution.','自旋是不能完全视为小刚球转动的内禀角动量。自旋半沿选轴两结果，不同轴是不同基。自旋与轨道组合产生更大态空间和总角动量。不可精确解时需近似，微扰绕已知解处理足够小附加作用，变分用试态在条件下约束能量；有效依假设收敛，不是有数就有效。相同粒子交换标签不能造物理可区分状态，费米态反对称导致泡利排同完整单粒子态，玻色态对称允许多占。电子层、原子和材料依这些统计。“同态”含所有量子标签，因此自旋不同的两电子可同空间轨道。多粒子相互作用关联不只是独立填能级，此处是起点而非完整多体解。');

expand('P09.01','Electrostatic boundary-value problems determine a potential throughout a region from charge density and conditions on its boundary. The electric field is E = −∇V, so Gauss’s law becomes Poisson’s equation ∇²V = −ρ/ε0 in vacuum. In a charge-free region it reduces to Laplace’s equation, which still permits a nonzero field imposed by boundary charges elsewhere. A Dirichlet condition specifies potential, while a Neumann condition specifies its normal derivative and hence related field information. Suitable complete boundary data establish uniqueness up to relevant constant freedoms, which makes methods such as image charges powerful: a constructed solution is valid if it satisfies the differential equation and the actual boundary conditions in the physical region. The fictitious image charges are mathematical devices, not additional real charges placed inside the region. Separation of variables can exploit rectangular, cylindrical or spherical geometry, with coefficients fixed by boundary matching. Conducting surfaces are equipotentials in electrostatic equilibrium, but their surface charge density need not be uniform. Verify the solution’s boundary values, singularities and large-distance behavior rather than accepting a formula solely because it resembles a familiar Coulomb expression.','静电边值题由区域电荷密度及边界条件确定全域势。E=−∇V 使高斯式化泊松 ∇²V=−ρ/ε0；无电荷域为拉普拉斯，但外部边界电荷仍可使场非零。狄利克雷指定势，诺伊曼指定法向导数及相关场。适当完整边值保证相应常数自由度外唯一，因此像电荷法构造只要在物理域满足方程和真实边界即有效；像电荷是数学装置，不是域内新增真实电荷。分离变量可利用直角柱球几何，系数由匹配决定。静电导体等势但面电荷未必均匀。须检边值、奇点和远场，不因像熟悉库仑式就接受。');
expand('P09.02','A multipole expansion organizes the distant field of a localized charge distribution by how rapidly terms decrease with distance. The monopole term depends on total charge. If that vanishes, a dipole term may dominate and depends on the separation of positive and negative charge, followed by quadrupole and higher structure. The expansion is useful only when the observation distance is large compared with the source’s characteristic size. A neutral distribution can therefore create a substantial nonzero field near it and a dipole field far away. In matter, polarization P describes electric dipole moment per unit volume after an appropriate averaging. Spatial variation and surface termination of polarization lead to bound-charge descriptions. The displacement field D groups the vacuum electric-field contribution with polarization so a macroscopic Gauss law can be written in terms of free charge. This grouping does not remove the microscopic charges or guarantee a simple linear material law. A linear isotropic dielectric approximation relates P to E through a susceptibility, while anisotropy, nonlinearity and frequency dependence require extensions. Keep free charge, bound charge, total field and auxiliary fields conceptually distinct when applying boundary conditions.','多极展开按随距衰减快慢组织局域源远场。单极依总电荷，若零则偶极可主导，反映正负分离，之后四极高阶。只有观察距远大源尺寸才有效，中性分布近处可强非零，远处可偶极场。物质极化 P 是适当平均的单位体积偶极矩，空间变化和表面终止可用束缚电荷描述。位移场 D 把真空场项与极化合并，使宏观高斯用自由电荷写；此分组不删除微观电荷，也不保证线性材料。线性各向同性以极化率连 P/E，各向异性、非线性和频依需扩展。边界计算须分自由、束缚、总场和辅助场。');
expand('P09.03','Magnetostatics studies time-independent magnetic fields produced by steady currents and magnetized matter. The field has zero divergence in the standard theory, meaning that magnetic flux entering a closed surface equals flux leaving it. Introducing a vector potential A with B = ∇×A satisfies this condition automatically. The potential is not unique: adding the gradient of a suitable scalar function leaves its curl, and therefore B, unchanged. This gauge freedom reflects redundancy in the representation rather than uncertainty in the measurable field. A gauge condition can simplify the differential equations for A, but physical predictions must remain independent of that choice. For localized currents, far-field behavior often begins with a magnetic dipole term. Magnetic materials can be described by magnetization and corresponding bound-current models after coarse graining. Boundary conditions distinguish normal and tangential field components and depend on currents at an interface. Do not infer that zero enclosed current forces zero local B; Ampere’s law constrains a circulation, not every point individually. Choose a potential representation that respects geometry, and verify the resulting field rather than interpreting individual components of A as directly measurable forces.','静磁研究稳流和磁化物产生的定常场。标准理论 B 散度零，闭面入出通量等。引入 A 使 B=∇×A 自动满足，A 不唯一：加适当标量梯度不改旋度/B。规范自由是表示冗余，不是实测场不确定。选规范可简化 A 方程，物理预测应不依选择。局域电流远场常从磁偶极起。磁材料粗粒化后可用磁化和束缚流模型。界面边界分法向切向，依表面电流。包围流零不迫局部 B 零，安培只约束环量。选势须尊几何并检最终场，不能把 A 各分量直接当实测力。');
expand('P09.04','Maxwell’s equations can be written in integral form, describing fluxes and circulations over finite regions, or differential form, describing local spatial derivatives. Gauss’s electric law links divergence of E to charge density; Gauss’s magnetic law gives zero divergence of B. Faraday’s law links curl of E to the negative time derivative of B, while the Ampere–Maxwell law links curl of B to current density and the time derivative of E in vacuum. Taking the divergence of the latter and combining with Gauss’s law yields charge continuity, showing why displacement current is required. Boundary conditions follow by applying integral laws to thin pillboxes and small loops crossing an interface. Normal electric-field jumps relate to surface charge, while tangential magnetic-field jumps relate to surface current in the appropriate formulation. Material media require constitutive relations in addition to the field equations; the equations alone do not specify how every substance polarizes or conducts. Initial conditions and sources are also necessary for a unique time-dependent solution. Treat integral and differential versions as complementary statements of the same local conservation and coupling principles, not separate unrelated laws.','麦克斯韦积分形式描述有限区域通量环量，微分形式描述局部导数。电高斯连 E 散度与电荷，磁高斯令 B 散度零；法拉第连 E 旋度与负 B 时间导，真空安培—麦克斯韦连 B 旋度与电流及 E 时间导。对后式取散度结合高斯得连续性，说明位移流必要。薄药盒和跨界小回路给边界，法向 E 跳与面电荷相关，适当形式切向磁场跳与面流相关。介质还需本构，场方程不单定所有物质极化导电。唯一时变解也需初值和源。积分微分是同一局部守恒耦合的互补表述，不是无关定律。');
expand('P09.05','Electromagnetic fields store and transport energy in addition to exerting forces on matter. In vacuum the energy density is ε0E²/2 + B²/(2μ0), while the Poynting vector E×B/μ0 gives local energy-flow density. Poynting’s theorem balances changes in field energy, energy flowing through a boundary and work done on charges. This helps explain why circuit energy is not simply carried inside a wire by slowly drifting electrons; the surrounding electromagnetic field participates in transfer. Fields also carry momentum, so absorption or reflection of radiation produces force. A perfectly reflecting surface reverses the normal photon momentum and can experience twice the pressure of a perfectly absorbing surface for the same normally incident ideal beam. The Maxwell stress tensor is a compact way to express electromagnetic momentum flow and forces across surfaces, but each component must be interpreted with the chosen geometry. In matter, separating field and material momentum can require careful conventions; the total conservation statement remains the essential check. Use a well-defined surface and include sources, receivers and mechanical supports when accounting for energy and momentum.','电磁场除施力还储运能。真空能密度 ε0E²/2+B²/(2μ0)，坡印廷 E×B/μ0 给局部能流。坡印廷定理平衡场能变、穿界能与对电荷做功，解释电路能并非只由慢漂电子在导线内搬，周围场参与。场也携动量，吸收反射辐射施力；理想正入射同光束，完美反射反转法向动量，压力可为吸收两倍。麦克斯韦应力张量紧凑表达动量流及面力，各分量需配几何解释。介质中分场与物质动量可能需谨慎约定，总守恒是关键。核算须明确定义面，包含源、接收者和机械支撑。');
expand('P09.06','Radiation is the part of an electromagnetic disturbance that carries energy outward over large distances rather than remaining tied to a static near field. Accelerating charges and time-dependent current distributions can radiate, with angular patterns determined by source geometry and motion. Field changes reach an observer after a finite travel time, so a retarded description uses the source state at an earlier time rather than its simultaneous position. A dipole approximation is useful when the source size is small compared with wavelength; larger sources require additional structure and interference. Waveguides confine fields through boundaries, producing transverse mode patterns rather than arbitrary free-space plane waves. In a hollow conducting guide, many modes have a cutoff frequency below which they do not carry propagating power down the guide in the ideal model. Phase velocity and group velocity can differ, and a phase velocity above c does not imply faster-than-light transmission of information. Losses, imperfect conductors and coupling determine real performance. Antennas and waveguides therefore require matching source, geometry, wavelength and boundary conditions. Distinguish near-field coupling from far-field radiation before applying a simple inverse-square intensity model.','辐射是把能量远送而非束缚静近场的扰动部分。加速电荷和时变电流可辐射，角图由源几何运动定。场变有限时间到观察者，推迟描述用较早源态，不是同时位置。源远小波长时偶极近似有用，大源需高阶和干涉。波导边界约束出横模，非任意自由平面波；空心导体许多模式有截止，低于截止理想模型不沿导传播功率。相速群速可不同，相速超 c 不代表信息超光。损耗、非理想导体和耦合决定实性能，天线波导需匹配源、几何、波长和边界。套简单平方反比强度前须分近场耦合与远场辐射。');

expand('P08.01','A mechanical configuration is the collection of positions needed to specify a system at one instant. Cartesian coordinates are convenient but can include redundant variables when motion is constrained. A rigid pendulum bob moving in a plane has two Cartesian coordinates but one fixed-length relation, leaving one independent positional degree of freedom. Its angle is a generalized coordinate that automatically respects the constraint. Generalized coordinates may be lengths, angles or other parameters, and their associated generalized forces have corresponding units. A holonomic constraint can be written as a relation among coordinates and possibly time; some velocity constraints cannot be reduced to this form and need additional treatment. Constraints may be time independent or externally driven, changing the energy accounting. Choose coordinates that describe the allowed configurations without singularities in the region of interest. Then express kinetic and potential energy in those variables rather than assuming the Cartesian kinetic-energy form remains unchanged. Constraint forces can disappear from the reduced equations when they do no virtual work along allowed variations, but this is an assumption to verify. Counting equations without checking independence can overestimate the number of constraints or leave hidden degrees of freedom.','构型是某时刻确定系统所需位置集合，笛卡尔坐标方便却在约束下冗余。平面刚摆球有两坐标和固定长关系，因此一个独立位置自由度，可用角自动满足约束。广义坐标可长度、角或其他参数，广义力单位相应变化。完整约束可写坐标及可能时间关系，某些速度约束不能化成此式，需额外处理。约束可定常或外驱，影响能量。选坐标应描述允许构型且在研究区无奇点，再以其表达动势能，不能保留笛卡尔动能形式不变。约束力若对允许虚位移不做虚功，可在约化方程消失，但须验证。只数方程而不查独立性，会错计约束或藏自由度。');
expand('P08.02','A variational principle compares entire nearby paths rather than only the force at one instant. For ordinary conservative mechanics, the action is the time integral of the Lagrangian L = T − V between fixed endpoint times. Consider small changes of the path that vanish at the endpoints. Hamilton’s principle states that the first-order change in action vanishes for the physical path. This is stationarity, not a guarantee of a global minimum; different intervals or systems can produce minima, maxima or saddle-like behavior. By integrating the term involving the variation of velocity by parts, the endpoint contribution vanishes and the remaining coefficient of each arbitrary coordinate variation gives the Euler–Lagrange equation. The principle therefore reproduces local equations of motion without assuming that a particle consciously evaluates possible futures. A trial-path approximation can reduce a difficult problem to a few parameters, but its quality depends on the chosen family. Boundary conditions are essential: changing which quantities are fixed changes the allowed variations and possibly the appropriate action terms. Keep action units distinct from energy, since integrating energy over time produces joule seconds.','变分原理比较整条邻近路径而非仅瞬时力。普通保守力学作用量是固定端时之间 L = T − V 的时间积分。考虑端点为零的小路径变化，哈密顿原理说物理路径的一阶作用量变化零，是驻值而非保证全局最小；不同系统区间可极小、极大或鞍。速度变分项分部积分后端点项消失，任意坐标变分系数给欧拉—拉格朗日式。因此得到局部运动方程，不意味着粒子有意识评估未来。试探路径把问题化少参数，但质量依所选族。边界条件关键，改变固定量会改允许变分及适当边界项。作用量单位是能量乘时间 J·s，不是能量。');
expand('P08.03','The Lagrangian method derives motion from a scalar function expressed in suitable generalized coordinates. For a system with ordinary conservative forces, use L(q,qdot,t) = T − V and form one Euler–Lagrange equation per independent coordinate. Compute partial derivatives while holding the other arguments fixed, then take the total time derivative of the momentum-like term ∂L/∂qdot. A simple spring gives m xddot + kx = 0, showing that the method agrees with Newton’s force equation. In curvilinear coordinates, kinetic energy contains coordinate-dependent factors, which automatically generate terms associated with the changing geometry. A coordinate absent from L is cyclic, and its conjugate momentum is conserved under the stated conditions. This connects symmetry with conservation more directly than solving every force component separately. Nonconservative forces such as friction can enter through generalized-force terms; they should not be disguised as an ordinary potential unless that representation is justified. Explicit time dependence may indicate external driving and can spoil energy conservation. The method’s advantage is systematic handling of coupled coordinates and constraints, not a promise that every resulting differential equation has a simple closed-form solution.','拉格朗日法从适当广义坐标中的标量函数导运动。普通保守系统取 L(q,qdot,t)=T−V，每独立坐标一个欧拉—拉格朗日式。偏导时其他自变量固定，再对动量样项 ∂L/∂qdot 取全时间导数。弹簧得 m xddot + kx=0，与牛顿一致。曲线坐标动能含坐标因子，自动生成几何变化项。L 中不出现的循环坐标，其共轭动量在条件下守恒，直接联系对称守恒。摩擦等非保守力应通过广义力项，不能未经证明装成普通势。显含时常示外驱，可能破坏能量守恒。优势是系统处理耦合约束，不保证所得微分式都有简单闭式解。');
expand('P08.04','A central force points along the line from a fixed centre to the particle and depends only on radial separation in the usual conservative model. Its torque about that centre is zero, so angular momentum is conserved and nonradial motion remains in a fixed plane. In polar coordinates, the conserved angular momentum relates angular speed to radius, producing the equal-areas property. The radial motion can be viewed as one-dimensional motion in an effective potential consisting of the physical potential plus an angular-momentum barrier L²/(2mr²). This extra term is a consequence of eliminating angular motion, not a new fundamental interaction. Turning points occur where radial kinetic energy vanishes, and a circular orbit corresponds to a stationary point of the effective potential. Stability requires examining the local curvature: a minimum supports small radial oscillations, while a maximum is unstable. Bound and unbound trajectories depend on total energy and the potential’s large-distance behavior. The inverse-square gravitational potential gives familiar conic-section orbits, but other central potentials need not close into ellipses. Check which quantities remain constant when comparing orbits rather than varying radius while silently holding incompatible energy and angular momentum conditions.','中心力沿固定力心到粒子连线，常见保守模型只依半径。对心力矩零，角动量守恒，非径向运动限固定平面。极坐标守恒联系角速与半径，给等面积性质。消去角运动后，径向可视一维有效势：物理势加 L²/(2mr²) 角动量屏障；这不是新基本作用。径向动能零为转向点，有效势驻点对应圆轨道，局部曲率最小稳定小振、最大不稳。有界无界依总能和远处势形。平方反比引力给圆锥轨道，其他中心势未必闭椭圆。比较轨道须查保持哪些量，不可改半径却暗持互不相容能量角动量条件。');
expand('P08.05','Hamiltonian mechanics describes motion in phase space, where positions and conjugate momenta are independent state coordinates. Begin with p = ∂L/∂qdot and, when the relation can be inverted, replace velocities by momenta through the Legendre transform H = Σpqdot − L. Hamilton’s equations then give qdot = ∂H/∂p and pdot = −∂H/∂q. For a particle with ordinary quadratic kinetic energy and a time-independent potential, H equals total mechanical energy, but this identity is not automatic for every coordinate choice or velocity-dependent interaction. Canonical momentum can also differ from mechanical momentum, notably for a charged particle in electromagnetic potentials. A phase-space point includes enough position and momentum information to determine a trajectory under suitable smoothness and uniqueness conditions. Conserved quantities constrain that trajectory to lower-dimensional regions, while canonical transformations preserve the form of the equations. The Hamiltonian framework provides a bridge to statistical mechanics and quantum theory, but those theories add new assumptions rather than simply renaming classical variables. Check units and the chosen conjugate pairs before differentiating, and distinguish a partial derivative in phase space from a derivative taken along the actual time-evolving trajectory.','哈密顿力学在位置和共轭动量独立的相空间描述。先 p=∂L/∂qdot，关系可逆时勒让德变换 H=Σpqdot−L 换速度为动量，得 qdot=∂H/∂p、pdot=−∂H/∂q。普通二次动能、定常势粒子 H 等机械总能，但非每种坐标或速度作用都自动如此。带电粒子电磁势中正则动量可不同机械动量。合适光滑唯一条件下，相空间点有足够位置动量决定轨迹，守恒约束低维区域，正则变换保方程形式。框架连接统计和量子，但后者添新假设，不是只改名。求导前查单位共轭对，并区分相空间偏导与实际轨迹时间导数。');
expand('P08.06','Near a stable equilibrium, expand the potential in small coordinate displacements. The constant term does not affect forces, the linear term vanishes at equilibrium, and the quadratic term defines a stiffness matrix. Together with the kinetic-energy mass matrix, it gives an eigenvalue problem for normal-mode frequencies and relative displacement patterns. Positive squared frequencies indicate oscillatory stability within the linearized model; a negative squared frequency signals an unstable direction. Zero modes can reflect a symmetry or require higher-order analysis. Linear superposition allows general small motion to be assembled from modes, but larger amplitudes retain cubic and higher terms that can shift frequencies and couple modes. Nonlinear dynamics can include multiple equilibria, bifurcations, resonance changes and chaotic behavior. Chaos means sensitive dependence on initial conditions in a deterministic system, not absence of governing equations. A numerical trajectory alone should be checked for timestep and energy errors before being called chaotic. The small-oscillation approximation is local in both displacement and model assumptions, so validate it by estimating neglected terms or comparing amplitude-dependent results. Distinguish a genuinely unstable equilibrium from a stable system driven strongly by an external periodic force.','稳定平衡附近展开势：常项不影响力，平衡处线项零，二次项定刚度矩阵，与动能质量矩阵给频率和相对位移的本征问题。平方频率正在线性模型为振荡稳定，负为不稳方向，零可能对称或需高阶。小运动可模式叠加，大幅保留三次高项会移频耦模。非线性可多平衡、分岔、共振改变和混沌；混沌是确定系统初值敏感，不是无方程。数值轨迹称混沌前应检查步长和能量误差。小振近似对位移和假设都局部，需估忽略项或比较振幅效应。应分真正不稳平衡与稳定系统被外周期强驱。');

expand('P07.01','A wave is a propagating disturbance or field pattern, not necessarily a stream of material traveling with the pattern. In a transverse mechanical wave, particle displacement is perpendicular to propagation; in a longitudinal wave it is parallel. Wavelength is the spatial distance between equivalent phases, period is the time for one cycle at a fixed position and frequency is the reciprocal of period. For a periodic traveling wave, speed equals frequency times wavelength. A sinusoidal expression separates amplitude, spatial phase and temporal phase, helping distinguish particle motion from movement of a crest. In a linear medium, superposition means overlapping displacements add algebraically with their signs. Constructive and destructive interference depend on relative phase, but energy accounting involves the complete field and its transport rather than simply declaring energy destroyed at a node. Real media can be dispersive, meaning different frequencies propagate at different phase speeds; a wave packet’s envelope can then move differently from an individual crest. Boundaries can reflect and transmit waves, with phase changes depending on boundary conditions. Always identify what physical quantity oscillates and what sets the propagation speed in the chosen model.','波是传播扰动或场模式，不必是物质随模式流。横机械波位移垂直传播，纵波平行。波长为空间同相点距，周期为定点一循环时间，频率为倒数，周期行波 v = fλ。正弦式分振幅、空间和时间相位，帮助分质点运动与波峰移动。线性介质叠加是带符号位移相加，相长相消依相对相位，但能量需完整场及输运核算，不能说波节把能量毁掉。色散使不同频率相速不同，波包包络速度可不同波峰。边界反射透射的相变依边界条件。始终明确振荡物理量及何因素设波速。');
expand('P07.02','Standing waves arise when traveling waves of suitable frequency and amplitude propagate in opposite directions and interfere. Nodes have zero displacement amplitude in the ideal pattern, while antinodes have maximum amplitude; the pattern does not translate like a traveling crest. Boundary conditions select allowed modes. A string fixed at both ends must have displacement nodes at those ends, producing wavelengths 2L/n and harmonic frequencies nv/(2L) when wave speed is frequency-independent. An air column has different displacement and pressure boundary conditions: a displacement antinode corresponds to a pressure node, so the two diagrams must not be confused. Sound in ordinary air is a longitudinal pressure and density disturbance, while the air particles oscillate locally. Pitch is associated with frequency, loudness depends on several perceptual and physical factors, and intensity is power per area. A decibel scale expresses a logarithmic ratio relative to a stated reference, not a linear amount of sound. Resonance can amplify a driven mode, but damping and coupling determine the actual amplitude. Real instruments include end corrections, multiple modes and material effects beyond the simplest ideal string or tube.','驻波由合适频幅的反向行波干涉产生。理想波节位移振幅零，波腹最大，图样不随波峰平移。边界选模式，两端固定弦端点位移节，允许 λ = 2L/n；无色散时频率 nv/(2L)。空气柱的位移和压强边界不同，位移腹对应压强节，不能混图。普通空气声是纵向压强密度扰动，空气质点局部振荡。音高关联频率，响度依多物理知觉因素，声强为功率/面积。分贝是相对指定参考的对数比，不是线性声量。共振可放大驱动模式，但阻尼耦合定真实幅。真实乐器还含端修正、多模式和材料效应。');
expand('P07.03','Reflection and refraction follow from how waves satisfy conditions at an interface. Draw the normal perpendicular to the surface before measuring any angle. The reflected angle equals the incident angle for a smooth stationary interface in the simple ray model. Refraction changes direction when propagation speed changes, with n1sinθ1 = n2sinθ2. The refractive index n = c/v describes phase speed relative to vacuum and can depend on wavelength, producing dispersion. Frequency remains the same across a stationary boundary, while speed and wavelength change together. Traveling from higher to lower refractive index can reach a critical angle where the refracted ray would be parallel to the surface. Above that angle, the ray model predicts total internal reflection, although an evanescent field extends a short distance beyond the boundary. This is not possible for incidence from lower to higher index in the same simple setting. Surface roughness scatters light into multiple directions rather than invalidating energy conservation. Ray optics assumes structures large compared with wavelength, so very narrow apertures or fine features require wave analysis. Check direction qualitatively before calculating: entry into a higher index bends the ray toward the normal.','反射折射来自界面波条件。先画法线再量角，光滑静止界面简单射线反射角等入射角。速度变化可折向，满足 n1sinθ1 = n2sinθ2。n = c/v 是相速比且可依波长产生色散。静界面频率不变，速度波长一起变。高 n 到低 n 达临界时折射平行面，超过后射线模型全反射，但边界外仍有短距倏逝场；反向低到高无此条件。粗面向多方向散射，不违能量守恒。射线近似需结构远大于波长，窄孔细结构需波分析。计算前先定性检：入高 n 朝法线弯。');
expand('P07.04','A lens changes wavefront direction through refraction and can form an image by bringing rays together or making them appear to diverge from a point. In the thin-lens approximation, thickness is small compared with the relevant distances and paraxial rays make small angles with the axis. With a consistent sign convention, the object distance, image distance and focal length obey 1/f = 1/u + 1/v. A real image occurs where rays actually converge and can be projected onto a screen; a virtual image is found by backward extensions of diverging rays and cannot be caught on a screen at that apparent location. Transverse magnification relates image and object heights and carries an orientation sign. A converging lens can make either real or virtual images depending on object position, while a diverging lens’s behavior also depends on whether the incident object is real or virtual. Optical instruments combine elements, apertures and detectors, so magnification alone does not determine useful detail. Aberrations, diffraction and alignment limit performance. Trace a few representative rays and check the algebraic image location against the geometry rather than applying a formula without a drawing.','透镜折射波前，使光线会聚或看似从一点发散成像。薄透镜假设厚度相对距离小、近轴角小，一致符号下 1/f = 1/u + 1/v。实像是实际会聚，可投屏；虚像是发散线反延长交点，不能在该表观位置接屏。横向放大率含正倒符号。会聚镜依物距可实可虚，发散镜也依入射物是实是虚。仪器组合元件、孔径和探测器，放大倍数不单定可用细节，像差、衍射和对准限制性能。应画代表光线并用几何复核代数像位，而非无图套式。');
expand('P07.05','Interference compares the phase of waves that reach the same point through different paths. For equal-frequency coherent sources, a path difference of an integer wavelength gives constructive interference when their initial phases agree, while an odd half-wavelength gives destructive interference for equal amplitudes. Coherence means that the relative phase remains sufficiently stable over the observation; merely having the same approximate colour is not enough for a stable pattern. Young’s double-slit geometry converts path differences into a spatial fringe pattern under suitable far-field and small-angle approximations. Diffraction is the spreading and interference associated with a finite aperture or obstacle. A narrower slit produces a broader central angular maximum, revealing a tradeoff between spatial confinement and directional concentration. The double-slit pattern can be modulated by each slit’s own diffraction envelope, so not every predicted interference maximum has equal intensity. Interference redistributes energy rather than destroying it globally. Instrument resolution is limited partly by diffraction from its aperture, even if lenses are perfectly manufactured. Always state whether a calculation uses exact geometry, a far-field approximation or a small-angle approximation, because those assumptions set its useful range.','干涉比较不同路径到同点的相位。等频相干源初相同，整数波长程差相长，等幅时奇数半波长相消。相干要求观察期间相对相位足够稳定，仅颜色近同不够。杨氏双缝在远场小角等近似下把程差变空间条纹。衍射是有限孔或障碍相关扩散干涉，缝越窄中央角峰越宽，体现空间局限与方向集中权衡。双缝图可被单缝包络调制，因此干涉峰不都等强。干涉重分能量而非全球毁能。即使透镜完美，孔径衍射也限制分辨。应说明精确几何、远场或小角近似，假设决定范围。');
expand('P07.06','Polarization describes the direction and time dependence of transverse electric-field oscillation. Linearly polarized light oscillates along a fixed transverse direction, while circular and elliptical polarization involve changing direction with a phase relation between components. An ideal linear polarizer transmits the component along its axis. For an already linearly polarized beam, transmitted intensity follows Malus’s law I = I0cos²θ, because field amplitude is projected and intensity is proportional to its square. Unpolarized light requires averaging over fluctuating orientations, so the same input interpretation must not be assumed without checking. Polarization supports the transverse nature of electromagnetic waves and is used in imaging, displays and material analysis. It does not describe ordinary longitudinal sound in air in the same way. Classical wave optics explains propagation, interference and diffraction, but energy exchange in photoelectric and photon-counting experiments requires quantization. A photon description and a wave description are not mutually exclusive stories chosen arbitrarily; each captures aspects of one physical theory in an appropriate limit. State what an experiment measures before claiming that it proves light is only a particle or only a wave.','偏振描述横向电场方向及随时变化。线偏沿固定横向，圆椭圆偏振由两分量相位关系使方向变化。理想线偏器透其轴分量；已线偏输入满足 I = I0cos²θ，因为场幅投影而强度与平方成正比。非偏光需对波动取向平均，不能不查输入就套同解释。偏振支持电磁横波，用于成像、显示和材料；空气普通纵声不以同样方式偏振。经典波解释传播干涉衍射，光电和计数能量交换需量子。光子与波并非随意二选互斥故事，而是同理论适当极限的不同方面。宣称“仅粒”或“仅波”前须说明实验实际测什么。');

expand('P06.01','The magnetic part of the Lorentz force on a point charge is qv × B. Its direction is perpendicular to both velocity and magnetic field, with the sign of q reversing the right-hand-rule direction. The magnitude is |q|vB sinθ, so a stationary charge or motion parallel to the field has no magnetic force from that field. Because the force is perpendicular to instantaneous velocity, it does no work on the point charge and does not directly change its speed. In a uniform field, perpendicular motion can therefore be circular, with magnetic force supplying the required centripetal acceleration. A parallel velocity component remains unchanged in the simple model, producing a helical path when combined with circular motion. The radius mvperpendicular/(|q|B) depends on momentum and field strength, while the nonrelativistic angular frequency |q|B/m is independent of speed. Electric fields, collisions or relativistic speeds require extensions. A current-carrying wire also experiences force because its moving charges transfer momentum to the material. Do not confuse magnetic field direction with particle travel direction, and check the charge sign before drawing curvature.','点电荷洛伦兹磁力为 qv × B，垂直速度和磁场，q 正负反转右手方向，大小 |q|vB sinθ。因此静止或平行运动不受该磁力。力垂直瞬时速度，不对点电荷做功，不直接改速率。均匀场中垂直运动可成圆，磁力供向心加速度；简单模型平行分速不变，与圆运动合成螺旋。半径 mv垂直/(|q|B) 依动量和场，非相对论角频率 |q|B/m 与速率无关。有电场、碰撞或相对论速度需扩展。载流导线也受力，因为运动电荷向材料传动量。不能混场方向与粒子方向，画弯曲前检电荷符号。');
expand('P06.02','Steady electric currents create magnetic fields whose geometry follows the current distribution. The Biot–Savart law adds vector contributions from current elements, each depending on orientation and distance. For an ideal infinitely long straight wire, symmetry gives circular field lines and magnitude μ0I/(2πr) in vacuum. A finite wire near its ends does not satisfy that ideal expression exactly. A current loop produces an axial field and resembles a magnetic dipole far away; many turns arranged as a long solenoid can produce an approximately uniform interior field with reduced exterior field. Ampere’s circuital law relates the circulation of B around a closed path to enclosed steady current. It is always a relation in its applicable magnetostatic setting, but it becomes an easy algebraic tool only when symmetry determines the field direction and constancy along the chosen loop. Enclosing zero net current does not imply zero magnetic field at every point. Magnetic materials modify the relationship through magnetization, so a vacuum formula may need a material model. Use the right-hand rule consistently and distinguish a chosen mathematical integration loop from a physical wire.','稳恒电流产生随分布决定几何的磁场。毕奥—萨伐尔定律矢量叠加电流元贡献，依取向与距离。真空无限长直线由对称给圆场线和 μ0I/(2πr)，有限导线端部不严格满足。电流环在轴上有场、远处似偶极，长螺线管多匝可给近均匀内场和较小外场。安培环路联系 B 环量与包围稳流，在适用静磁条件总成立，但只有对称已确定方向和沿路径恒定性时才化简单代数。包围净流零不意味着处处零场。磁性材料通过磁化改变关系，真空式可能需材料模型。右手规则须一致，并区分数学积分回路与实体导线。');
expand('P06.03','Magnetic flux measures the field component passing through an oriented surface. For a uniform field and flat area, Φ = BA cosθ with θ measured from the surface normal, not from the surface itself. Reversing the chosen normal reverses the signed flux. Faraday’s law relates induced electromotive force around a closed loop to the negative time derivative of magnetic flux through it; a coil with N similar turns uses the flux linkage NΦ. Flux can change because field strength changes, the loop area changes, the loop rotates or the loop moves through a nonuniform region. Thus a constant magnetic field can still produce induction in a moving circuit. Electromotive force is work per unit charge around the loop, not necessarily an electrostatic potential difference defined independently of path. In a moving conductor, magnetic forces on charges contribute to the motional-emf description, while a changing field can create a circulating electric field even without a conductor present. Keep the loop orientation and flux sign consistent before applying the minus sign. A flux change predicts emf; current additionally depends on whether a conducting path exists and on its impedance.','磁通量测穿过定向面的场分量。均匀场平面 Φ = BA cosθ，θ 从法线而非平面量；反法线则通量反号。法拉第定律把闭路感应电动势与穿面磁通负变化率联系，多匝用 NΦ 磁通链。场强、面积、朝向或穿非均匀区移动都可改通量，因此恒 B 仍可在运动电路感应。电动势是绕回路单位电荷功，不一定是与路径无关静电势差。动导体中电荷磁力构成动生描述，时变场则无导体也可产生环形电场。负号前应统一回路朝向与通量符号。通量变化预示电动势，电流还取决于闭合导电路及阻抗。');
expand('P06.04','Lenz’s law determines the sign of induction by stating that the induced response opposes the change in magnetic flux that produces it. It does not say that the induced field always opposes the existing external field. If an upward flux is increasing, the induced field tends downward; if that upward flux is decreasing, the induced field tends upward to resist the decrease. Use a right-hand rule to connect the required induced-field direction with current circulation. The opposition is consistent with energy conservation. Pulling a conducting loop from a field can require mechanical work because the induced current produces a force opposing the motion; the work can become thermal energy in the resistance. If the induced effect instead amplified the original motion without an energy source, the model would predict unphysical self-generated energy. Eddy currents are distributed induced currents in bulk conductors and can produce braking or heating. Their strength depends on conductivity, geometry and time variation, not just magnetic-field magnitude. Distinguish an open circuit, which can have an induced emf without sustained loop current, from a closed conducting path. Always identify precisely which flux change is being opposed.','楞次定律说感应响应反抗导致它的磁通变化，不是总反抗已有外场。向上通量增加，感应趋向下；向上通量减少，感应趋向上以抵减。用右手把所需场方向连到电流环向。反抗符合守恒：把导电环拉出磁场时，感应流力阻运动，机械功可变电阻热；若无能量源却放大原运动，会预测自生能。涡流是块导体中的分布感应电流，可制动发热，强度依电导、几何及时间变化，不只 B 大小。开路可有感应电动势却无持续环流，应与闭路分。必须准确指出反抗的是哪种磁通变化。');
expand('P06.05','An inductor links circuit current with magnetic flux, and a changing current produces a self-induced emf that opposes the change. For a linear ideal inductor, the magnitude relation is v = L di/dt with a consistent passive sign convention; a constant current can have zero inductor voltage even while magnetic energy remains stored. The stored energy is LI²/2. Connecting resistance and inductance creates an exponential current transient with a characteristic L/R timescale. In sinusoidal steady state, inductive reactance grows with angular frequency as ωL, while capacitive reactance decreases as 1/(ωC). Voltage and current may be out of phase, so average power is not generally the product of their peak values. Root-mean-square values and the phase factor provide the appropriate resistive power comparison. An RLC circuit can resonate when inductive and capacitive effects balance, with resistance limiting the response. Real inductors also have winding resistance, parasitic capacitance and possible magnetic-core losses. Keep transient behavior distinct from sinusoidal steady-state analysis, and do not replace every time-dependent relation with a simple DC resistance formula.','电感联系电流与磁通，变流自感反抗变化。线性理想元件按一致被动符号 v = L di/dt，恒流可电压零而磁能仍存，储能 LI²/2。RL 产生时间尺度 L/R 的指数暂态。正弦稳态感抗 ωL 随频增，容抗 1/(ωC) 随频减。电压电流可不同相，平均功率不一般等峰值乘积，需有效值和相位因子。RLC 在感容平衡时可共振，电阻限制响应。真实电感还含线阻、寄生容和芯损。须区分暂态与正弦稳态，不能把所有时间关系换为直流电阻公式。');
expand('P06.06','Maxwell’s equations unify electric and magnetic phenomena through four linked statements. Electric charge is a source of electric flux; closed surfaces have no net magnetic flux in the standard theory; changing magnetic flux produces electric circulation; and conduction current together with changing electric flux produces magnetic circulation. The displacement-current term is essential for consistency with charge conservation, including the region between charging capacitor plates where no conduction current crosses the gap. In vacuum these coupled equations admit waves whose electric and magnetic fields sustain each other while propagating at c = 1/√(μ0ε0). For a plane wave, the fields are transverse to propagation and mutually perpendicular, with linked magnitudes. Electromagnetic waves carry energy and momentum, so they can transfer power and exert pressure without a material medium. Radio, visible light and other bands differ in frequency, not in being fundamentally unrelated kinds of wave. Material response changes propagation speed, absorption and dispersion. The wave model explains many propagation effects, while quantized interactions require additional quantum ideas. Treat the overview as a connected set of laws, not four isolated formulas to memorize without their source and flux meanings.','麦克斯韦四关系统一电磁：电荷源出电通量，标准理论闭面磁通零，变磁通生电环量，传导电流和变电通量生磁环量。位移电流对电荷守恒一致性必要，包括充电电容间隙无传导流区。真空耦合式允许 c = 1/√(μ0ε0) 的波，电磁场相互维持传播。平面波场横向且彼此垂直，大小相联系。电磁波携能量动量，可无介质传功施压。无线电、可见等频段频率不同而非根本无关波。材料响应改变波速、吸收和色散。波模型解释传播，量子化相互作用需量子思想。应把四式看成源、通量和环量的连接规律，而非四条孤立死记式。');

expand('P05.01','Electric charge is a conserved property with positive and negative signs. In ordinary matter, protons and electrons carry opposite elementary charges, while an object’s net charge reflects an imbalance rather than creation of charge from nothing. Charging by contact transfers charge, and induction redistributes charges in response to another charged object. Conductors permit mobile charges to rearrange readily, whereas insulators restrict that motion on the relevant timescale. Coulomb’s law gives the force between stationary point charges in vacuum as k|q1q2|/r², directed along the line joining them. Like signs repel and opposite signs attract. Extended objects can sometimes be treated as point charges by symmetry or distance, but not merely because their total charge is known. For several sources, add forces as vectors, preserving direction; adding magnitudes alone fails when forces oppose or meet at angles. The surrounding material can change the effective interaction and may require a field description including polarization. Check limiting behavior: doubling distance quarters the force, while doubling one charge doubles it. Newton’s third-law forces act on different charged bodies and do not cancel on one body’s force diagram.','电荷有正负并守恒。普通物质质子电子带相反元电荷，物体净电荷反映不平衡而非凭空产生。接触带电转移电荷，感应使电荷随外带电体重排。导体电荷易移动，绝缘体在相关时间限制移动。真空静止点电荷库仑力 k|q1q2|/r² 沿连线，同斥异吸。扩展物体仅在对称或远距等条件可点化，不能只知总电荷就点化。多源力按矢量叠加，反向或夹角时不能只加大小。介质可改作用，需含极化的场描述。检极限：距离加倍力四分之一，一电荷加倍力加倍。第三定律对力作用不同物体，不在单物体受力图抵消。');
expand('P05.02','An electric field assigns to each position the force that a sufficiently small positive test charge would experience per unit charge. The test charge is imagined small enough not to appreciably disturb the source distribution. Because force has direction, electric field is a vector; field lines are a visualization whose tangent indicates direction and whose spacing convention suggests strength. Electric potential is instead potential energy per charge relative to a chosen reference. Only potential differences affect electrostatic energy changes, so adding the same constant everywhere does not change the field. In one dimension E = −dV/dx, and in multiple dimensions the field is the negative gradient of potential. Moving a positive charge toward lower potential lowers its potential energy, while a negative charge reverses that energy relation. Equipotential surfaces are perpendicular to electrostatic field lines where the field is nonzero. Zero potential at a point does not imply zero field there, and zero field at a point does not require the potential value to be zero. For several sources, potentials add as scalars, which can simplify calculations compared with direct vector-field addition.','电场给每位置足够小正试探电荷单位电量所受力，试探电荷须小到不显著扰源。力有方向，场是矢量；场线切向示方向，疏密约定示强度。电势则为相对参考的单位电荷势能，只有势差影响静电能变，全处加同常数不改场。一维 E = −dV/dx，多维为负梯度。正电荷向低势移动势能降低，负电荷相反。非零静电场处等势面与场线垂直。一点零势不代表零场，一点零场也不要求零势。多源电势按标量加，常比直接矢量场合成简便。');
expand('P05.03','In a conductor at electrostatic equilibrium, mobile charges have rearranged until the internal electric field vanishes. The conductor is then at one potential, and excess charge resides on its surface in the ideal electrostatic model. This statement does not apply unchanged inside a conductor carrying a resistive steady current. Surface charge distribution depends on geometry and nearby objects, with stronger fields often occurring near sharp curvature. A capacitor stores separated charge on conductors; capacitance is the ratio of charge magnitude to potential difference for a specified linear arrangement. For parallel plates with negligible edge effects, C = εA/d, showing the roles of area, separation and material permittivity. A dielectric polarizes rather than freely conducting all charge, reducing the field for a fixed free charge and increasing capacitance. Whether voltage or charge stays fixed during insertion depends on whether the capacitor remains connected to a source. Stored energy can be written Q²/(2C), CV²/2 or QV/2 under the ideal linear model. Track the energy exchange with a battery or mechanical agent before interpreting a change in capacitor energy as an isolated gain or loss.','静电平衡导体中，自由电荷重排到内部场为零，导体等势，理想模型多余电荷在表面。这不直接适用于流稳恒电阻电流的导体内部。表面分布依几何和邻物，尖曲率附近场常更强。电容器在导体分离电荷，给定线性结构电容为电荷绝对量/势差。忽略边缘的平行板 C = εA/d，体现面积、间距和介电性。电介质极化而非让电荷全自由流动，固定自由电荷时减场增电容。插介质时电压或电荷何者固定，取决于是否接电源。理想线性储能可写 Q²/(2C)、CV²/2 或 QV/2。解释能量增减前须计电池或机械作用的能量交换。');
expand('P05.04','Electric current is the rate at which net charge crosses a chosen surface. Conventional current follows the direction positive charge would move, which is opposite to electron drift in a typical metal. Charge carriers drift slowly compared with the propagation of the electromagnetic change that establishes a circuit response. Resistance relates voltage and current for a specified component and conditions. An ohmic resistor has an approximately linear current–voltage relation over its operating range; diodes, lamps and many other devices do not have one constant resistance over all conditions. For a uniform conductor, resistance depends on resistivity, length and cross-sectional area. Resistivity itself depends on material and often temperature. Electrical power transferred to a component is VI with a consistent sign convention; for an ideal resistor it is dissipated as thermal energy and equals I²R or V²/R. These equivalent expressions must use the voltage and current for that same resistor. Compare fixed-voltage and fixed-current conditions carefully: increasing resistance lowers power in the former but raises it in the latter. A circuit’s total energy accounting includes sources and all receiving components, not only the most visible resistor.','电流是净电荷穿过面的速率，约定方向为正电荷运动方向，金属中通常与电子漂移反向。载流子漂移比建立电路响应的电磁变化传播慢。电阻在给定条件联系电压电流，欧姆元件在工作范围近线性，二极管灯泡等不在所有条件恒阻。均匀导体电阻依电阻率、长度和截面，电阻率依材料且常依温度。一致符号下功率 VI，理想电阻转热为 I²R 或 V²/R，须用同一电阻电压电流。恒压增阻降功率，恒流增阻升功率，必须区分。全电路能量包括电源和所有接收组件，不只最显眼电阻。');
expand('P05.05','Kirchhoff’s junction rule is charge conservation for a circuit node under conditions where net charge accumulation is negligible. Assign current directions first; a negative solved value simply means the actual direction is opposite to the chosen arrow. The loop rule accounts for energy changes around a closed lumped-circuit path, with signs set consistently for source rises and resistor drops. A changing magnetic flux may require an induced-emf term rather than an unqualified zero sum of electrostatic potential differences. Series elements share the same branch current because charge has no alternative route between them. Parallel branches share their endpoint voltage but can carry different currents. Equivalent resistance simplifies the external current–voltage behavior of a resistive network, but it does not preserve every internal current or power without further calculation. Real sources can be modeled with internal resistance, causing terminal voltage to differ from the ideal emf under load. A voltmeter’s finite resistance and an ammeter’s nonzero resistance can alter the network. After solving, verify junction balances, loop signs and total power supplied versus absorbed; these independent checks catch many algebraic or wiring-model errors.','节点定律是在净积累可忽略条件下的电荷守恒。先选电流方向，负解只表示反向。回路定律核算集中电路闭路能量，电源升和电阻降须一致符号。时变磁通需感应电动势项，不能无条件说静电势差和零。串联同支电流，因为无其他路；并联同端电压，电流可不同。等效电阻简化外部伏安，却不自动保留每个内部电流功率。真实源内阻使负载下端压不同于理想电动势。电压表有限阻、电流表非零阻都可改网络。解后复核节点、回路和供耗总功率，独立检查能抓代数或接线模型错误。');
expand('P05.06','A resistor–capacitor circuit illustrates how a storage element and a dissipative element create time-dependent behavior. Capacitor voltage cannot jump instantaneously in the ideal finite-current model because Q = CV requires transferring charge. During charging through a resistor from a fixed source, the current is initially largest and decreases as capacitor voltage approaches the source voltage. The time constant τ = RC sets the exponential timescale, not an exact finishing time. After one time constant, a charging capacitor reaches about sixty-three percent of the total voltage change, while a discharging capacitor retains about thirty-seven percent of its initial voltage. Initial conditions matter: the general exponential approaches a final value from the starting value rather than always beginning at zero. Energy supplied by a source is divided between stored field energy and resistor heating. Measurements can modify τ if a probe adds significant resistance or capacitance. An oscilloscope trace must be interpreted with its sampling rate, bandwidth and grounding arrangement in mind. Compare a measured curve with both early-time slope and long-time limit before concluding that one fitted time constant fully validates the circuit model.','RC 电路展示储能与耗散元件怎样产生时间行为。理想有限电流下电容电压不能跳变，因为 Q = CV 需搬电荷。经电阻恒源充电初流最大，电容压接近源压时减小。τ = RC 是指数时间尺度，不是精确完成时间。一 τ 后充电完成约 63% 总变化，放电剩约 37%。初始条件重要，一般指数从初值趋终值，不总从零起。源供能分成场储能与电阻热。探头若添明显阻容会改 τ；示波轨迹应考虑采样率、带宽和接地。比较早斜率与晚极限后，再判断单一拟合常数是否足够验证模型。');

expand('P04.01','Temperature is an operational measure of thermal state, established by comparing systems that can exchange energy as heat. The zeroth law states that if two systems are separately in thermal equilibrium with a third, they are in thermal equilibrium with each other. This makes a thermometer meaningful: after sufficient equilibration, a reproducible property of the thermometer indicates the temperature of the object. Different thermometric properties include expansion, electrical resistance and radiation, each requiring calibration and an appropriate range. Celsius and kelvin have equal interval sizes but different zeros; thermodynamic equations involving ratios or inverse temperature generally require kelvin. Temperature is not the amount of heat stored in an object. A large cool object can contain more internal energy than a small hot one, and heat names energy transferred because of a temperature difference. Thermal expansion results from temperature-dependent average particle separation or material response, not a universal constant expansion of every substance. A linear expansion coefficient is an approximation over a stated temperature interval; anisotropic materials can expand differently in different directions, and water provides familiar exceptions to simple monotonic density trends.','温度是热状态的操作量，通过能以热交换能量的系统比较建立。第零定律说两个系统若分别与第三个热平衡，则彼此热平衡，这使温度计有意义：充分平衡后，温度计可重复性质指示物温。膨胀、电阻、辐射等温标性质均需校准和适用范围。摄氏与开尔文间隔大小相同、零点不同，温度比或倒数的热力学公式一般必须用 K。温度不是物体储存热量，大冷物体内能可比小热物体多；热指温差引起的能量转移。热膨胀来自平均粒距或材料响应随温度变，不是所有物质恒定膨胀。线膨胀系数只在指定区间近似，各向异性材料不同方向可不同，水也有简单单调密度规律的例外。');
expand('P04.02','The ideal-gas model treats molecules as particles whose own volume is negligible compared with the container and whose interactions matter mainly during brief collisions. Pressure arises from momentum transfer to the walls, so more frequent or more forceful collisions raise pressure. In classical equilibrium, temperature is proportional to mean translational kinetic energy, not to every molecule having exactly the same speed. Molecules follow a distribution of speeds, and heavier particles have lower typical speeds at the same temperature. Combining microscopic reasoning with amount counting gives pV = nRT, where n is measured in moles and R must match the pressure and volume units. The equation links state variables but does not specify the path taken between states. Holding temperature fixed gives an inverse pressure–volume relation; holding volume fixed makes pressure proportional to absolute temperature. Real gases deviate when density is high or temperature is near condensation because excluded volume and attractive interactions become important. Internal energy can also include rotational and vibrational modes, so the monatomic translational model does not automatically describe every gas’s heat capacity. State the particle and energy assumptions before using its formulas.','理想气体把分子自身体积视为相对容器可忽略，相互作用主要在短碰撞。压强来自向壁传动量，碰撞更频繁或更强会增压。经典平衡下温度正比平均平动动能，不是每分子速率一样；速率有分布，同温重粒子典型速率较低。微观推理结合计数得 pV = nRT，n 用 mol，R 要匹配压强体积单位。状态方程联系变量，不指定状态间路径。恒温给压体反比，恒容给压强正比绝对温度。高密度或近冷凝时，排除体积与吸引使真实气体偏离。内能还可含转动振动，因此单原子平动模型不能自动描述所有气体热容，列式前须说明粒子和能量假设。');
expand('P04.03','The first law is energy conservation applied to a thermodynamic system. Define the boundary and sign convention before calculating: here Q is heat entering the system and W is work done by the system, so ΔU = Q − W. Internal energy U is a state function, meaning its change depends on the initial and final states. Heat and work are transfers along a process and therefore are not properties stored in the state. Two paths between the same endpoints can involve different heat and work while giving the same ΔU. Compression does negative work by the system under this convention and can raise internal energy even without heat input. For a quasistatic gas process, boundary work is the integral of external resisting pressure over volume change, with special care needed outside quasistatic conditions. Other forms of work, such as electrical work, require inclusion when present. A cyclic process returns U to its initial value, so net heat input equals net work output. The first law alone does not determine which processes can occur spontaneously; that directional restriction requires the second law.','第一定律是热力学系统的能量守恒。先定边界符号：此处 Q 入系统为正，W 系统对外做功为正，因此 ΔU = Q − W。内能是状态函数，变化只依始末；热和功是沿过程传递，不是储存在状态里的性质。相同端点不同路径可有不同热功而同 ΔU。压缩在此约定下系统做负功，即使无吸热也可增内能。准静态气体边界功可由抵抗外压对体积变化积分，非准静态需谨慎；有电功等必须计入。循环 U 回初值，净吸热等于净输出功。第一定律独自不决定自发方向，此限制需第二定律。');
expand('P04.04','A thermodynamic process is a path through states, and names such as isothermal, isobaric, isochoric and adiabatic specify different constraints. Isothermal means temperature stays constant; it does not mean no heat enters or leaves. Adiabatic means heat transfer is absent or negligible; temperature may change because work changes internal energy. Isochoric means volume is fixed, so simple pressure–volume boundary work vanishes, while isobaric means pressure is fixed. On a pressure–volume diagram, the area under a quasistatic path represents work done during expansion, and reversing the path reverses its sign. The enclosed area of a cycle represents net work with an orientation-dependent sign. For an ideal gas undergoing a reversible adiabatic process with suitable constant heat capacities, pV^γ is constant. That formula is not valid for every irreversible adiabatic event, such as unrestricted free expansion. A reversible path is an ideal limiting process that stays arbitrarily close to equilibrium and can be retraced without net changes elsewhere. Always distinguish the state equation, which holds at each modeled equilibrium state, from a process relation that requires additional assumptions about the path.','热过程是状态路径，等温、等压、等容和绝热指定不同约束。等温是温度恒定，不等于无热交换；绝热是传热无或可忽略，做功仍可改温。等容使简单 pV 边界功为零，等压则压强固定。pV 图中准静态路径下面积为膨胀功，反向变号；循环围面积是带方向的净功。理想气体可逆绝热且热容适当恒定时 pV^γ 不变，但不适用于所有不可逆绝热，如自由膨胀。可逆是无限接近平衡且可逆行不留外界净变化的理想极限。须分每个平衡态满足的状态方程，与另需路径假设的过程方程。');
expand('P04.05','Entropy is a state function that gives a quantitative direction criterion when combined with the second law. For a reversible heat transfer, dS = δQrev/T; to calculate entropy change between two states, one may choose a hypothetical reversible path even when the actual process was irreversible. The actual heat divided by temperature is not automatically equal to entropy change for an irreversible process. An isolated system’s total entropy cannot decrease, while a subsystem can decrease its entropy by exporting enough entropy to its surroundings. Heat flowing spontaneously from hot to cold raises the combined entropy because the same energy enters the colder body with a larger reciprocal-temperature factor. In microscopic terms, entropy relates to the number and probabilities of accessible states under stated constraints, which is more precise than simply calling it disorder. Entropy production measures irreversibility and limits the amount of useful work obtainable from an energy transfer. Reversible processes produce no total entropy in the ideal limit; real friction, mixing and finite-temperature heat flow produce some. The second law does not prohibit local organization, including living systems, because such systems exchange energy and entropy with their environment.','熵是状态函数，与第二定律一起给定量方向判据。可逆传热 dS = δQ可逆/T；即使实际不可逆，也可选假想可逆路径算两态熵差。不可逆过程的实际热除温度不自动等于熵变。孤立总熵不降，子系统可输出足够熵而自身降低。热自高到低流动使总熵增，因为同能进入低温体对应更大倒温因子。微观熵联系约束下可及态数和概率，比单称混乱精确。熵产衡量不可逆并限制可用功，可逆极限总熵产零，摩擦、混合、有限温差传热产生熵。第二定律不禁止生命等局部组织，因为其与环境交换能量和熵。');
expand('P04.06','A heat engine operates in a cycle, receiving heat from a hotter source, delivering some work and rejecting heat to a cooler sink. Because the working substance returns to its initial state, the first law gives W = Qhot − Qcold over a cycle. Efficiency is work output divided by heat input and cannot exceed the reversible Carnot limit 1 − Tcold/Thot for two thermal reservoirs, using absolute temperatures. A refrigerator reverses the desired transfer by consuming work to move heat from cold to hot. Its coefficient of performance compares useful cooling with work input and can exceed one without violating energy conservation. A heat pump uses the heat delivered to the warm side as its useful output. Phase changes add another energy-storage mechanism: latent heat changes phase fraction at coexistence rather than necessarily raising temperature. Heating curves therefore distinguish sensible temperature change from phase conversion, and pressure affects transition conditions. A real machine also has finite-rate losses, friction and imperfect heat exchange. Compare devices using the same boundary and useful-output definition instead of confusing engine efficiency with refrigerator performance.','热机循环从高温源吸热，部分输出功，其余向低温放热。工质回初态，第一定律给 W = Q热 − Q冷。效率为功/吸热，两个热库间不超过可逆卡诺限 1 − T冷/T热，需绝对温度。制冷机消耗功把热由冷搬热，性能系数为有用制冷量/功，可大于一而不违守恒。热泵把暖端放热作为有用输出。相变增加储能机制，潜热在共存条件下改相比例，不必升温，因此加热曲线区分显热和相变，压强影响转变条件。真实设备还有有限速率、摩擦及不完美换热损失。比较须同边界和有用输出定义，不能混热机效率与制冷性能。');

units('B10',['module.B04.06','module.B05.06','module.B07.06','module.B08.06','module.B09.06'],[
['细胞与分子证据题','Perturbation logic|Localization|Mechanistic alternatives','扰动逻辑|定位|竞争机制','Integrated cellular problems combine measurements of structure, abundance and function. A perturbation’s effect must be interpreted against controls and timing; a changed molecular marker is not automatically the direct cause of a changed phenotype.','细胞综合题结合结构、丰度与功能。扰动效应需结合对照时间解释，分子标记改变不自动是表型改变的直接原因。','Control activity is 100 units and perturbed activity 40. Find activity retained as a percentage.','对照活性 100，扰动后 40，保留百分之几？',40,'Retained = 40/100 × 100% = 40%.','A rescue can strengthen causality when it specifically restores the altered component.','特异恢复被改组分的挽救可加强因果。','Any correlated molecular change proves direct causation.','任何相关分子变化都证明直接因果。'],
['遗传与进化综合','Inheritance probabilities|Population change|Model discrimination','遗传概率|种群变化|模型区分','Genetic crosses describe transmission, while evolutionary models describe changing variant frequencies across generations. Link them through survival, reproduction and population structure, and distinguish selection from sampling fluctuation.','遗传杂交描述传递，进化模型描述跨代频率变化。通过存活、繁殖和种群结构连接二者，并区分选择与抽样波动。','Among 100 diploid individuals, 20 are AA and 40 Aa. Find frequency of A.','100 个二倍体中 AA 为 20、Aa 为 40，A 频率是多少？',0.4,'pA = (2×20 + 40)/(2×100) = 0.4.','Allele and genotype frequencies are different quantities.','等位基因频率与基因型频率不同。','The fraction of AA individuals always equals the frequency of A alleles.','AA 个体比例总等于 A 等位频率。'],
['植物与动物生理综合','Transport gradients|Feedback|Resource allocation','运输梯度|反馈|资源分配','Physiology problems connect exchange surfaces, transport networks and control loops. Identify conserved material, energy input and the variable being regulated before interpreting a graph or predicting a response.','生理题联系交换面、运输网与控制环。读图预测前，先识别守恒物料、能量输入和受调变量。','A compartment receives 8 units/min and loses 5 units/min. Find net accumulation rate.','区室每分钟流入 8 单位、流出 5，净积累率是多少？',3,'Accumulation = inflow − outflow = 8 − 5 = 3 units/min.','A steady concentration can accompany continuous balanced transport.','浓度稳定仍可持续平衡运输。','Steady state means every transport process has stopped.','稳态意味着所有运输停止。'],
['生态、行为与分类','Ecological interactions|Behavioral hypotheses|Tree interpretation','生态相互作用|行为假说|系统树解读','Ecological and behavioral explanations must fit both observations and evolutionary relationships. Distinguish a character’s function from its historical origin, and compare direct and indirect effects in interacting communities.','生态行为解释须符合观察与亲缘。区分特征当前功能与历史起源，并比较群落中的直接间接作用。','A quadrat contains 6 individuals in 2 m². Find density in individuals/m².','2 m² 样方内六个个体，密度为每平方米多少？',3,'Density = 6/2 = 3 individuals/m².','Similar ecological functions can evolve independently.','相似生态功能可独立进化。','Similar appearance always proves the closest common ancestry.','外观相似总证明最近共同祖先。'],
['图像、数据与实验设计','Scale reading|Control selection|Uncertainty','比例尺判读|对照选择|不确定度','Practical evidence tasks require reading scales, recognizing preparation limits and choosing controls that distinguish hypotheses. Count independent samples correctly and separate an observation from the inferred process that could produce it.','实践证据题需读尺度、认识制备限制，并选能区分假说的对照。正确计独立样本，区分观察与可能产生观察的过程。','An image scale bar is 10 μm and an object spans three bar lengths. Find object length in μm.','图中比例尺 10 μm，物体长为三倍尺长，实际多少 μm？',30,'Length = 3 × 10 = 30 μm.','An image’s preparation can create artifacts that need controls.','图像制备可产生需对照识别的伪影。','Every visible boundary in a prepared image is necessarily a living membrane.','制备图中的每条可见边界必是活体膜。'],
['限时综合训练','Evidence prioritization|Question decomposition|Error review','证据排序|问题分解|错误复盘','Timed biological reasoning prioritizes supplied evidence over familiar stories. Decompose a problem into variables, comparisons and predictions, then check whether the conclusion is stronger than the data justify. Review errors by concept and inference type.','限时生物推理应优先题给证据，而非熟悉故事。分解变量、比较和预测，再检查结论是否超证据。按概念与推理类型复盘。','A 100-minute set allocates 10 minutes to review and divides the rest among 6 tasks. Find minutes per task.','100 分钟预留 10 分钟复查，其余分六任务，每个多少分钟？',15,'(100 − 10)/6 = 15 min.','An explicit uncertain conclusion is preferable to an unsupported causal claim.','明示不确定结论优于无依据因果断言。','A confident answer is correct even when it contradicts the supplied data.','只要回答自信，即使与数据矛盾也正确。']]);
expand('B10.01','A cellular evidence problem often presents several assays that measure different levels of a process. Protein abundance, subcellular location, enzymatic activity and a final phenotype are not interchangeable readouts. Begin by stating what each assay directly measures and which links in the proposed mechanism remain inferred. A loss-of-function perturbation can show that a component contributes to a process, but general toxicity or developmental disruption may produce the same endpoint. A rescue that restores a specific function, a time course placing events in order and an independent perturbation with a similar result can strengthen the explanation. Overexpression can create nonphysiological interactions, so sufficiency under an artificial condition does not automatically establish the normal mechanism. If two proteins colocalize, they may occupy the same unresolved compartment without directly binding. If a transcript increases while protein does not, translation or turnover provides alternative explanations. Build a table of predicted outcomes under competing models and compare it with all supplied observations. The strongest answer identifies both the supported mechanism and the remaining ambiguity, rather than selecting one attractive panel and ignoring discordant data.','细胞证据题常有多种测不同层级的实验，蛋白量、定位、酶活与最终表型不能互换。先说各实验直接测什么，机制哪些环节仍为推断。失功能说明组件贡献，但一般毒性或发育破坏可同结果；特异挽救、事件先后时间序列和独立扰动可加强解释。过表达可造非生理作用，人工充分不自动证明正常机制。共定位可只是同一未分辨区室，不必直接结合；RNA 增而蛋白不增，可由翻译周转解释。应列表比较竞争模型对全部观察的预测。最好答案既指出支持机制也保留歧义，而非挑好看面板忽略矛盾。');
expand('B10.02','Combine inheritance and evolution by tracking the same alleles through successive biological stages. A cross predicts gamete and zygote genotype probabilities under specified segregation and linkage assumptions. Differential survival can then alter the genotype distribution observed among adults, and differential reproduction changes the contribution to the next generation. Thus an unexpected adult ratio need not mean that meiosis itself violated Mendelian segregation. Count allele copies separately from individuals and genotype classes. A rare allele can increase through selection, drift, migration or a mixture of processes, and one short time series may not distinguish them. Hardy–Weinberg expectations provide a reference for random mating and other ideal assumptions, not a claim that every natural population must exactly match. Population subdivision or assortative mating can alter genotype proportions even without changing the total allele frequency immediately. Use sample sizes and uncertainty when comparing observed frequencies. A trait associated with reproductive success may be linked to the true causal variant or correlated with environment, so causal claims require additional evidence. Explain which process acts at which stage instead of assigning every frequency change to natural selection by default.','把遗传进化连接，应追同一等位经过连续生物阶段。杂交在分离连锁假设下预测配子合子概率，差异存活可改成体分布，差异繁殖改下一代贡献。因此成体比例异常不一定是减数分离违反孟德尔。等位份数、个体和基因型应分开计。稀有等位可因选择、漂变、迁移或混合增加，短序列未必区分。哈代—温伯格是随机交配等理想参照，不要求自然群体精确符合；亚结构或选型交配可改基因型比例而总等位频率暂不变。比较须考虑样本和不确定。与繁殖成功相关性状可能只连锁真正因果变异或相关环境，需更多证据。应说明过程作用阶段，不能默认每次频率变化都自然选择。');
expand('B10.03','Integrated physiology questions often become simpler when treated as material and energy balances linked to feedback. Identify the compartment or whole organism, then list inflows, outflows, production and consumption. A constant concentration can result from large balanced fluxes, so distinguish a pool size from a transport rate. For membrane movement, determine which species can cross and whether chemical, electrical or pressure gradients drive them. In a plant, stomatal closure may conserve water while reducing carbon dioxide entry; in an animal, changing blood flow can redistribute delivery without changing every tissue’s metabolic demand equally. These are tradeoffs among coupled functions, not independent switches. A graph showing a variable returning toward baseline suggests regulation only when the response mechanism and alternatives are considered. Time delays can distinguish an immediate physical effect from a slower hormonal or transcriptional response. Use the supplied conditions rather than importing a familiar textbook result that assumes a different environment. Verify units and limiting cases, then explain the causal sequence from disturbance to sensor, effector and measured outcome. A complete answer states which quantities remain conserved and which are actively regulated.','综合生理常可化为物质能量平衡加反馈。先定区室或个体，列流入流出、生成消耗。恒浓可来自大而平衡的通量，池大小与速率不同。膜移动需识别可透物种及化学、电或压梯度。植物闭孔节水却减 CO2，动物变血流可重分配供给而不等量改变各组织需求，这是耦合权衡不是独立开关。曲线回基线只有结合机制与替代解释才支持调节。时间延迟区分即时物理与较慢激素转录作用。应使用题设条件，不套假设不同的熟悉结论。检单位极限，再说明扰动、传感、效应与结果的因果序列，指出何量守恒、何量主动调节。');
expand('B10.04','Ecology, behavior and classification questions require keeping several explanatory levels separate. A phylogenetic tree constrains ancestry, while an ecological observation describes present interactions and a behavioral experiment tests responses under particular conditions. Similar functions may arise independently, so ecological resemblance alone is weak evidence of close ancestry. Conversely, related organisms can occupy very different niches. When a predator is removed, prey may increase directly, but competition, vegetation changes or alternative predators can create indirect effects that reverse a simple expectation. A behavioral response may be learned, hormonally mediated or genetically influenced, and an adaptive interpretation needs evidence about consequences for reproduction in the relevant environment. Classifying a trait as a shared derived character requires comparison with an outgroup or an explicit ancestral-state hypothesis. Avoid reading branch order on the page as a ranking of complexity. Use experimental controls, natural comparisons and multiple lines of evidence to distinguish explanations. A strong synthesis says which observations concern history, mechanism and current function, then connects them without treating any one of those as a complete substitute for the others.','生态、行为和分类题要分解释层次。系统树约束祖先，生态观察描述现相互作用，行为实验检特定条件响应。相似功能可独立起源，因此生态相似不强证近缘，近缘也可占不同生态位。移捕食者可直接增猎物，但竞争、植被或其他捕食者的间接效应可逆转简单预期。行为可能学习、激素或遗传影响，适应解释需相关环境繁殖后果证据。判断共有衍征需外群或明示祖态假说，不能把纸上分支顺序当复杂等级。用对照、自然比较及多证据区分。好的综合应说清哪些观察关历史、机制和现功能，再连接而非以一层完全替另一层。');
expand('B10.05','Practical biological questions often test whether an image or dataset has been interpreted at the correct scale. Read the scale bar before naming a structure, and distinguish actual specimen dimensions from printed or displayed magnification. Consider section orientation: the same three-dimensional object can produce different two-dimensional profiles. Staining intensity may depend on chemistry, exposure or image processing rather than simply the amount of target material. Count independent specimens and record how fields or cells were selected; many measurements from one specimen can improve its estimate without creating many independent biological replicates. In a proposed experiment, choose controls that address the specific alternative explanation, such as background labeling, handling effects or assay failure. A positive control and a negative control answer different questions. If treatment groups were imaged with different exposure settings, raw brightness comparisons may be invalid. Combine observations with uncertainty and avoid inferring movement, causation or developmental sequence from one static image alone. The best practical answer explains what the method can establish, which artifact could mimic the result and what additional observation would discriminate them.','实践题常考是否按正确尺度解释图和数据。命名结构前读比例尺，分实际尺寸和打印放大。切面方向重要，同三维物体可有不同二维轮廓。染色强度可依化学、曝光和处理，不只是靶量。计独立样本并记录选视野细胞方式；同样本多测可改善该样本估计，却不创造更多独立生物重复。对照应针对背景标记、操作效应或测定失效等具体替代；阳性阴性回答不同问题。组间曝光不同，原亮度比较可能无效。应结合不确定，不能一张静图就推运动、因果或发育顺序。最好答案说明能建立何结论、何伪影可模拟及下一何观察可区分。');
expand('B10.06','A timed integrated set rewards disciplined interpretation more than rapid recall of isolated names. Read the requested claim carefully: identifying a pattern, calculating a probability, explaining a mechanism and designing a discriminating experiment are different tasks. Mark the independent variables, response variables, control conditions and sample sizes before interpreting a graph. Translate unfamiliar terminology into the supplied operational definition instead of assuming it matches a familiar word exactly. Solve quantitative subparts with explicit units and state probabilistic assumptions, including independence, random sampling or equilibrium when used. A later part may ask for a limitation of the same model that made an earlier calculation possible; recognizing that boundary is not a contradiction. Reserve time to test whether the conclusion exceeds the evidence, especially for claims of causation, adaptation or unique identity. When several explanations remain, choose the additional experiment that makes their predictions differ most clearly. After practice, separate factual gaps from reasoning errors such as confusing correlation with cause, technical with biological replication, or mean change with individual certainty. Use that diagnosis to select the next learning node and a fresh transfer problem.','限时综合更奖励有纪律解释而非孤立名词快背。先看要求是识模式、算概率、解释机制还是设计辨别实验。读图前标自变量、响应、对照与样本量。陌生术语按题给操作定义理解，不假定与熟词完全同义。定量部分保单位并说明独立、随机抽样或平衡等概率假设。后题可能正问前题模型的限制，认识边界不矛盾。留时间检查因果、适应或唯一身份结论是否超证据。若仍多解释，选使预测最不同的后续实验。练后区分事实缺口与推理错，如相关因果、技术生物重复、均值变化与个体确定混淆，再据此选下一节点及新迁移题。');

units('B09',['module.B03.06','math.probability','cs.arrays'],[
['显微、观察与取样','Resolution|Sampling frame|Observer bias','分辨率|抽样框|观察者偏差','Biological observation depends on what the method can reveal and which material is sampled. Resolution limits distinguishable detail, while a sampling frame defines the population to which observations can reasonably generalize.','生物观察依方法可揭示内容及所取材料。分辨率限制可区分细节，抽样框定义观察可合理推广的总体。','A sample includes 25 cells and 5 display a feature. Find observed feature proportion.','样本 25 个细胞，其中 5 个有某特征，观察比例是多少？',0.2,'p = 5/25 = 0.20.','A convenience sample may not represent the target population.','方便样本可能不代表目标总体。','Any large-looking microscope field guarantees an unbiased sample.','任何看起来大的视野都保证无偏抽样。'],
['对照与可重复性','Randomization|Independent replication|Blinding','随机化|独立重复|盲法','Controls isolate alternative explanations, randomization reduces systematic allocation differences, and independent replication estimates biological variation. Reproducibility requires transparent methods, data handling and a clear distinction between technical and biological repeats.','对照隔离替代解释，随机分配减少系统组差，独立重复估生物变异。可重复性需透明方法、数据处理，并区分技术与生物重复。','Four independent animals each contribute three technical measurements. How many independent animal units are there?','四只独立动物各测三次技术重复，独立动物单位有几个？',4,'The independent biological units are the 4 animals, not 12 readings.','Technical repeats do not automatically increase biological sample size.','技术重复不自动增加生物样本量。','Twelve readings from one specimen equal twelve independent organisms.','同一样本十二读数等于十二独立生物。'],
['生物统计与数据可视化','Distributions|Effect sizes|Uncertainty','分布|效应量|不确定度','Biological data vary, so summarize distributions and effect sizes rather than only significance labels. Visualizations should preserve units, sample structure and uncertainty; a mean alone can hide subgroups or skew.','生物数据有变异，应总结分布和效应量而非只贴显著标签。图应保单位、样本结构和不确定度，均值可掩盖亚群或偏斜。','Treatment mean is 7 and control mean 5. Find mean difference.','处理均值 7、对照 5，均值差是多少？',2,'Difference = 7 − 5 = 2 units.','Statistical significance does not by itself measure biological importance.','统计显著本身不衡量生物重要性。','A small p-value proves a large causal effect.','小 p 值证明巨大因果效应。'],
['序列比对与数据库','Alignment|Similarity versus homology|Annotation','序列比对|相似与同源|注释','Alignment proposes corresponding sequence positions using a scoring model. Similarity can support common ancestry but requires context. Database annotations combine evidence and inference and can contain errors or differing coordinate conventions.','比对按评分模型提出对应位置。相似可支持共同祖先但需情境。数据库注释兼有证据和推断，可能有错误或不同坐标约定。','Two aligned sequences match at 8 of 10 ungapped positions. Find identity percentage.','两比对序列十个无缺口位置有八个相同，一致性百分比是多少？',80,'Identity = 8/10 × 100% = 80%.','Homology denotes common ancestry, not a percentage score.','同源表示共同祖先，不是百分比分数。','A sequence is literally 80 percent homologous by definition.','按定义可以说序列有百分之八十同源。'],
['系统树与组学解释','Multiple testing|Batch effects|Phylogenetic uncertainty','多重检验|批次效应|系统树不确定性','High-dimensional datasets test many features and can reveal patterns or confounding. Correct for multiple comparisons, inspect batch effects and distinguish exploratory associations from independently validated mechanisms. Phylogenies likewise require model and support checks.','高维数据检验许多特征，可揭模式也可揭混杂。需处理多重比较、检查批次，区分探索相关与独立验证机制。系统树也需模型和支持检查。','Under 100 independent true-null tests at a 0.05 threshold, find expected false-positive count.','100 个独立真零假设检验，阈值 0.05，预期假阳性数是多少？',5,'Expected false positives = 100 × 0.05 = 5.','Batch can mimic a biological group effect when confounded with treatment.','批次与处理混杂时可伪装生物组效应。','More measured genes automatically eliminate confounding.','测更多基因会自动消除混杂。'],
['综合实验报告','Evidence chain|Reproducible analysis|Limitations','证据链|可复现分析|限制','A report connects the question, design, measurements, analysis and conclusion. Preserve raw data and explain exclusions, transformations and uncertainty. Separate observed association, model fit and causal inference.','报告连接问题、设计、测量、分析与结论。保留原始数据并说明排除、变换和不确定度，区分观察相关、模型拟合与因果推断。','A dataset has 30 records and 3 excluded by a prespecified quality rule. Find analyzed count.','数据 30 条，预定质量规则排除 3 条，分析几条？',27,'30 − 3 = 27 records.','Exclusion rules should be stated transparently and applied consistently.','排除规则应透明说明且一致应用。','Only a final graph is needed to reproduce an analysis.','只要最终图就足以复现分析。']]);
expand('B09.01','Observation is selective: an instrument, preparation and sampling plan determine which features become visible. Light microscopy distinguishes structures only above its effective resolution, while electron and fluorescence methods reveal different kinds of information with their own preparation constraints. A stain or marker must have suitable specificity; absence of labeling may reflect a technical failure rather than absence of a structure. Calibrate scale bars using the imaging setup, because digital resizing changes displayed size without changing the biological specimen. Define the sampling frame before choosing attractive images. Random or systematic sampling of fields can reduce selection bias, while repeatedly imaging the most conspicuous region can exaggerate a feature’s frequency. Cells nested within one organism or tissue sample are not necessarily independent biological replicates. Record preparation, magnification, acquisition settings and inclusion rules so another observer can evaluate the result. Blinding labels can reduce expectation-driven scoring when judgment is involved. A descriptive observation can generate a hypothesis, but showing that a structure causes a function requires additional comparisons or perturbations. Keep raw images and distinguish legitimate uniform processing from alterations that change the apparent evidence.','观察有选择性，仪器、制备和抽样决定可见特征。光镜有有效分辨限制，电镜荧光揭不同信息且各有制备约束。染色标记需特异，缺标可能技术失败而非结构不存在。比例尺须按成像系统校准，数字缩放只改显示不改样品。挑漂亮图前定义抽样框，随机或系统选视野减少偏差，反复取显眼区会夸大频率。同一个体组织的多细胞不一定是独立生物重复。记录制备、放大、采集和纳入规则，盲标签可减少期待驱动评分。描述观察能生假说，要证明结构致功能还需比较扰动。保留原图，区分合法统一处理与改变证据外观的修改。');
expand('B09.02','Experimental design aims to make alternative explanations distinguishable. A negative control establishes the baseline without the proposed active factor, while a positive control demonstrates that the system can produce the expected response when an appropriate stimulus is present. Vehicle, sham or handling controls may be needed when the procedure itself has effects. Random assignment reduces systematic pre-existing differences between groups on average, but it does not guarantee perfect balance in a small experiment. Blinding reduces the influence of expectations on treatment, measurement or analysis where feasible. Replication must occur at the level independently assigned to conditions: repeated wells from one preparation or repeated images from one animal do not automatically count as independent organisms. Technical replicates estimate measurement variability; biological replicates capture variation among independent biological units. Prespecify primary outcomes and important exclusions when possible, preserve deviations from the plan and report them. Reproducibility includes enough detail to repeat procedures and enough data and code to repeat analysis. An experiment can be repeatable yet biased if the same flawed method is repeated, so independent validation and alternative measurement methods add value.','实验设计让替代解释可区分。阴性对照给无活性因素基线，阳性对照证明系统遇合适刺激能响应。溶剂、假处理或操作对照可隔离程序本身。随机分配平均减少先存系统组差，但小实验不保证完美平衡；盲法减少期待对处理测量分析影响。重复须在独立分配条件的层级，一制备多孔或一动物多图不自动等于独立个体。技术重复估测量变异，生物重复估独立生物单位变异。尽可能预定主要结果和排除，保留并报告偏离。可复现需要足够程序细节及数据代码。相同错误方法可反复得到同样偏结果，因此独立验证与不同测量方法仍有价值。');
expand('B09.03','A biological dataset is a collection of measurements from a sampling process, not merely numbers waiting for a significance test. Begin by identifying the observational unit, variables, units and grouping structure. Plot individual observations where practical and inspect skew, outliers, missingness and possible subgroups before selecting a summary. A mean describes a centre but can hide a bimodal distribution; a median answers a different question and may be more robust to extreme values. Standard deviation describes spread among observations, while a standard error or confidence interval concerns uncertainty in an estimated quantity under a model. An effect size states the magnitude of a difference or association in interpretable units. A p-value describes compatibility with a specified null model and is not the probability that the hypothesis is true. Statistical significance does not establish causation or practical importance. Choose graphs with honest axes, clear labels and uncertainty displays that match the analysis. Paired measurements should preserve pairing, and nested designs need methods that respect dependence. Explain assumptions and sensitivity to reasonable alternatives rather than treating a software output as an automatic scientific conclusion.','生物数据来自抽样过程，不只是等显著检验的数字。先明确观察单位、变量、单位和分组，尽可能画个体值，先查偏斜、异常、缺失和亚群。均值描述中心却可掩双峰，中位数回答不同问题且对极端稳健。标准差描述观察分散，标准误或置信区间描述模型下估计不确定度。效应量以可理解单位表达差异关联大小。p 值描述与指定零模型的相容性，不是假说为真概率。显著不证明因果或实际重要。图轴应诚实、标签明确、不确定度匹配分析；配对须保配对，嵌套设计须尊重依赖。应说明假设及合理替代下敏感性，不能把软件输出当自动科学结论。');
expand('B09.04','A sequence alignment proposes which nucleotide or amino-acid positions correspond between sequences. The result depends on a scoring scheme for matches, substitutions and gaps, and on whether the goal is a global alignment of entire sequences or a local match between regions. A high-scoring alignment is evidence of similarity under that model, not automatic proof of identical function. Homology means shared ancestry and is a relationship, not a percentage; percent identity is a numerical summary of aligned matches. Orthologues arise through lineage splitting and paralogues through gene duplication, which affects how cautiously function should be transferred. Database records can contain experimentally supported annotations, computational predictions or inherited annotations of varying confidence. Record accession identifiers, database versions, sequence orientation and coordinate conventions so an analysis can be reproduced. Low-complexity regions, contamination, sequencing errors and incomplete gene models can create misleading matches. An apparent absence may reflect an incomplete assembly rather than true biological loss. Combine sequence evidence with domain organization, genomic context, expression or experiments before making a strong functional claim. A similarity search is a starting point for reasoning, not a replacement for checking evidence provenance.','序列比对提出核苷酸或氨基酸位置对应，取决于匹配替换缺口评分，以及全局或局部目标。高分只是该模型下相似证据，不自动证明同功能。同源是共同祖先关系，不是百分比；一致性才是对齐匹配数值。直系同源源自谱系分开，旁系同源源自复制，影响功能转移谨慎程度。数据库注释可来自实验证据、计算预测或继承推断，置信不同。应记录登录号、版本、方向和坐标约定以复现。低复杂、污染、测序错和不完整基因模型可误导，缺失也可能是组装不全。应结合结构域、基因组背景、表达或实验再作强功能结论。相似搜索是推理起点，不代替追查证据来源。');
expand('B09.05','Omics methods measure many molecular features at once, creating both discovery opportunities and statistical hazards. When thousands of null hypotheses are tested, some small p-values arise by chance even if each test is individually calibrated. Multiple-testing procedures control a defined error quantity, such as a family-wise rate or false-discovery rate; these are not interchangeable promises. Batch effects can arise from collection date, preparation, instrument run or processing software, and become especially dangerous when batch aligns with the biological groups of interest. Normalization adjusts selected technical differences but cannot rescue every confounded design. Exploratory clustering can reveal patterns without proving that the clusters are natural biological categories. Phylogenetic analysis likewise depends on alignment, substitution models, sampling and support assessment. Resampling support summarizes stability under a procedure, not a universal probability that a historical claim is true. Integrate high-dimensional findings with independent datasets or targeted experiments and distinguish pathway enrichment from direct measurement of pathway activity. Preserve enough metadata to test alternative explanations. A large dataset can estimate the wrong comparison very precisely if its design or labels are biased.','组学同时测许多分子，带来发现也带统计风险。数千零假设检验即使单项校准，仍会偶然出现小 p。多重检验控制指定错误量，如家族错误率或假发现率，二者不是同一承诺。批次可来自采集日、制备、仪器或软件，若与生物组重合尤其危险。归一只调部分技术差异，不能挽救所有混杂。探索聚类可显模式，却不证明自然生物类别。系统发育依比对、替换模型、取样和支持评估，重抽样支持表示特定程序下稳定性，不是历史断言的普遍真概率。高维发现需独立数据或定向实验，通路富集不等于直接测活性。保留元数据检验替代解释，大数据若设计标签偏，仍可极精确估错比较。');
expand('B09.06','A scientific report should let a reader follow the inference from question to evidence. State the biological question and the competing predictions, then describe the experimental units, treatments, controls, sampling and measurement methods. Explain how raw observations became analyzed variables, including calibration, normalization, exclusions and handling of missing values. Results should separate descriptive observations from statistical estimates, with units, sample sizes and uncertainty. Figures need labels and legends sufficient to understand what each point or band represents; a polished graphic should not conceal replication structure. The discussion connects findings to the hypothesis while considering alternative explanations, limitations and the range over which the conclusion is supported. Preserve raw data, analysis code and relevant versions so the numerical results can be reproduced. A reproducible calculation does not by itself validate the original measurement or causal interpretation, so those layers require separate evidence. Avoid inventing a mechanism simply because an association is strong. Conclude with the specific supported claim and the next discriminating test where uncertainty remains. Transparent reporting includes unexpected or null findings when they bear on the question rather than selecting only the most attractive panel.','科学报告应让读者从问题追到证据。先写生物问题和竞争预测，再述实验单位、处理、对照、取样和测量。说明原始观察如何变成分析变量，包括校准、归一、排除及缺失处理。结果分描述与统计估计，带单位、样本量和不确定度。图标图例应说明每点每带含义，不能用美图隐藏重复层级。讨论联系假说并考虑替代、限制和支持范围。保留原数据、代码和版本以复现数字；计算可复现不自动验证测量或因果，这些需分别证据。不能因相关强就编机制。结论给具体受支持断言及未解处下一辨别检验，透明报告也包括与问题相关的意外和零结果，而非只挑最漂亮面板。');

units('B08',['module.B03.04','module.B06.05'],[
['格局形成与细胞命运','Positional information|Induction|Differentiation','位置信息|诱导|分化','Developing cells acquire different states through inherited components, local signals and interactions. Positional information helps organize patterns, while differentiation stabilizes specialized functions without usually changing the entire genome sequence.','发育细胞通过继承成分、局部信号与相互作用获得不同状态。位置信息组织格局，分化稳定特化功能，通常不需改变全部基因组。','A model signal falls from 12 to 3 units across a tissue. Find the decrease.','模型信号跨组织从 12 降至 3 单位，减少多少？',9,'Decrease = 12 − 3 = 9.','Cells with similar genomes can acquire different fates through regulation.','基因组相近的细胞可因调控获得不同命运。','Every differentiated cell must lose all genes unrelated to its current function.','每个分化细胞都必须丢失与当前功能无关的全部基因。'],
['发育中的基因调控','Regulatory networks|Morphogen interpretation|State stability','调控网络|形态素解读|状态稳定','Developmental gene networks integrate signals and feedback to create spatial and temporal expression patterns. A morphogen can elicit different responses at different concentrations, but timing, receptor state and network context also matter.','发育网络整合信号反馈，形成时空表达。形态素不同浓度可引不同响应，但时间、受体状态和网络背景同样重要。','In a threshold model, gene A activates above 5 units. Signal is 8 units. By how much is threshold exceeded?','阈值模型中 A 在超过 5 单位时活化，信号为 8，超阈多少？',3,'8 − 5 = 3 units.','A threshold diagram is a model of a regulatory response, not a full molecular mechanism.','阈值图是调控响应模型，不是完整分子机制。','Morphogen concentration alone always determines fate independently of history.','形态素浓度总能不依历史独自决定命运。'],
['神经细胞与电信号','Resting potential|Ion channels|Action potentials','静息电位|离子通道|动作电位','Ion gradients and selective permeability establish membrane voltage. Voltage-dependent channels generate regenerative action potentials, followed by recovery processes. Signal propagation does not require the same sodium ions to travel the whole axon.','离子梯度与选择透过建立膜电位。电压依赖通道产生再生动作电位，随后恢复。传播不需要同一批钠离子走完整条轴突。','Membrane potential changes from −70 to +30 mV. Find the voltage change in mV.','膜电位由 −70 变 +30 mV，变化多少 mV？',100,'ΔV = 30 − (−70) = 100 mV.','Action-potential propagation is local regeneration of membrane events.','动作电位传播是膜事件逐段再生。','A neuron carries electrical messages by sending one packet of ions from soma to terminal unchanged.','神经元把同一离子包不变地从胞体送到末端传信。'],
['突触与神经回路','Synaptic transmission|Integration|Plasticity','突触传递|整合|可塑性','Synapses convert presynaptic activity into postsynaptic effects through chemical or electrical coupling. Neurons integrate inputs over space and time. Circuit function depends on connectivity, cell properties and plastic changes.','突触经化学或电耦合把突触前活动转成突触后效应，神经元在时空整合输入。回路功能依连接、细胞性质与可塑变化。','Three simultaneous model inputs contribute +3, +2 and −4 units. Find net input.','三个同时模型输入为 +3、+2、−4 单位，净输入是多少？',1,'Net = 3 + 2 − 4 = 1.','The effect of a synapse depends on receptor and postsynaptic conditions.','突触效应依受体与突触后条件。','Every synapse always causes a postsynaptic action potential.','每个突触总会引发突触后动作电位。'],
['感觉系统与行为','Sensory transduction|Neural coding|Behavioral output','感觉换能|神经编码|行为输出','Sensory receptors convert physical or chemical stimuli into cellular signals. Neural pathways transform and combine information, so perception is not a literal copy of receptor input. Behavior links sensing to action through context-dependent circuits.','感受器把物理化学刺激转为细胞信号。通路变换整合信息，知觉不是输入原样复制。行为经情境相关回路连接感知与行动。','A model receptor fires 5 spikes in 0.1 s. Find average firing rate in Hz.','模型受体 0.1 s 发五次脉冲，平均频率为多少 Hz？',50,'Rate = 5/0.1 = 50 Hz.','A firing rate is one summary of activity and omits detailed timing.','发放率只是活动摘要，省略精细时间。','Identical mean firing rates always imply identical neural information.','平均发放率相同总意味着神经信息相同。'],
['模型实验与伦理解释','Model systems|Causal perturbation|Ethical limits','模式系统|因果扰动|伦理边界','Model systems expose mechanisms under controlled conditions but differ from the target organism or behavior. Perturbations test causal roles only with specificity and controls. Ethical design weighs scientific value against welfare and minimizes unnecessary harm.','模式系统在控制条件揭示机制，但与目标生物或行为有差异。扰动只有在特异和对照支持下检验因果。伦理设计权衡价值与福利，减少不必要伤害。','An experiment has 3 conditions with 4 independent replicates each. How many independent units are included?','实验三条件各四个独立重复，共多少独立单位？',12,'3 × 4 = 12 independent units.','A model’s limitations should accompany extrapolation.','从模型推广时应同时说明限制。','A finding in one model automatically proves the same mechanism in every species.','单一模型发现自动证明所有物种同机制。']]);
expand('B08.01','Development transforms a fertilized egg or other starting structure into an organized body through division, movement, growth and differentiation. Most differentiating cells retain much of the same genome but use different regulatory programs. Cell fate describes what a cell normally becomes, while potency describes what it can become under specified conditions; those are not identical claims. Unequal inherited cytoplasmic components can bias early states, and signals from neighboring cells can induce new responses. Positional information lets cells respond differently according to location, but a gradient alone is not a complete explanation unless the sensing and response mechanisms are identified. Cells also alter their environment through adhesion, force generation and secretion, producing feedback between pattern and mechanics. Determination refers to a relatively stabilized developmental commitment, whereas differentiation produces specialized observable properties. Some states remain plastic and can change after perturbation. To infer a fate mechanism, combine lineage tracing, transplantation or controlled signaling changes with suitable controls. A final anatomical pattern is evidence of an outcome, not direct proof of the sequence of molecular decisions that produced it.','发育通过分裂、移动、生长和分化把起始结构变成有序身体。多数分化细胞保留相近基因组，却用不同调控程序。命运指通常成为何物，潜能指指定条件下能成为何物，二者不同。不均继承胞质可偏置早期状态，邻细胞信号可诱导响应。位置信息让不同位置作不同反应，但若不说明感知响应机制，梯度不是完整解释。细胞以黏附、力和分泌改环境，形成格局与力学反馈。决定指较稳定承诺，分化指专门可见性质，有些状态仍可塑。应结合谱系追踪、移植或受控信号变化及对照推断机理。最终解剖格局是结果证据，不直接证明产生它的分子决策序列。');
expand('B08.02','Developmental regulation uses interacting genes and signals to create stable but adjustable patterns. A transcription factor can activate or repress target genes, and combinations of factors give cells a context-dependent interpretation of the same extracellular signal. Positive feedback can stabilize a state once initiated, while mutual inhibition can sharpen differences between neighboring or alternative cell identities. A morphogen is a signal capable of eliciting distinct responses over a concentration range in an appropriate developmental system. Its effect can also depend on exposure duration, transport, degradation and the history of the responding cell. Boundary formation therefore cannot always be reduced to a static concentration threshold. Enhancers integrate regulatory inputs, and chromatin state can preserve accessibility or repression across divisions. Developmental timing matters: applying a signal before or after a competence window can produce different outcomes. Gene-expression maps show association with a pattern, while loss-of-function, gain-of-function and rescue experiments test causal contributions. Redundant pathways may hide an effect when one gene is removed. A useful network model makes predictions about perturbations and timing, not merely arrows connecting every gene mentioned in a diagram.','发育调控用相互作用基因和信号形成稳定而可调格局。转录因子活化或抑制靶基因，组合使同一外信号得到情境解释。正反馈稳定已启状态，相互抑制锐化邻细胞或备选身份差异。形态素在合适系统中可按浓度范围引不同响应，但效应还依暴露时间、运输、降解和细胞历史，边界不总能化成静态阈值。增强子整合输入，染色质跨分裂维持可及或抑制。能力窗口前后施信号可有不同结局。表达图显示与格局关联，功能丧失、增加及挽救检验因果，冗余路径可能遮蔽单基因去除效应。有用网络模型须预测扰动与时间，而不是把图中每基因都连箭头。');
expand('B08.03','A neuron’s membrane separates ionic solutions with different compositions. Pumps and transporters maintain gradients over time, while selective ion channels determine which ions can cross at a given moment. The resting membrane potential reflects the combined electrochemical influences and permeabilities, not a complete absence of electrical activity. A small input can depolarize or hyperpolarize the membrane. In an excitable region, reaching a threshold can open voltage-dependent channels and trigger a regenerative action potential. Subsequent channel inactivation and potassium-related currents help repolarize the membrane, while refractory behavior limits immediate re-excitation. The action potential’s local shape is relatively stereotyped under fixed conditions; stimulus strength is often represented through firing patterns rather than an arbitrarily larger spike. Propagation occurs because local currents influence adjacent membrane, which regenerates the event. Myelin changes the electrical properties and concentrates regeneration at nodes, increasing conduction efficiency and speed. Glial cells support neural function in many ways beyond passive structural filling. Distinguish the rapid channel currents of one spike from the slower transport processes that maintain the ion gradients required for repeated signaling.','神经膜隔开成分不同的离子溶液。泵和转运体长期维持梯度，选择通道决定当下能跨的离子。静息电位反映综合电化学影响与透过性，不是完全没有电活动。小输入可去极化或超极化，兴奋区达阈后电压通道可触发再生动作电位；随后失活及钾相关电流帮助复极，不应期限制即刻再激。固定条件下局部脉冲形状较定型，刺激强弱常由发放模式而非任意更大脉冲编码。局部电流影响邻膜，邻膜再生事件而传播。髓鞘改电性质并使再生集中郎飞结，提高效率速度。胶质支持功能远不止填空支架。应区分单次脉冲快通道电流与维持反复信号梯度的慢运输。');
expand('B08.04','A chemical synapse links presynaptic activity to transmitter release and a postsynaptic response. An arriving action potential can open calcium channels, and calcium entry promotes vesicle fusion at the terminal. Released transmitter binds receptors whose effects depend on their molecular type and the target cell’s ionic conditions. Some receptors directly gate channels, while others act through intracellular signaling. Excitatory and inhibitory describe effects on the likelihood of relevant activity, not a permanent moral or chemical label. Postsynaptic potentials vary in size and combine over time and across locations; dendritic geometry and active membrane properties influence that integration. Electrical synapses provide another mode of coupling through intercellular channels. Circuit behavior emerges from connection patterns together with intrinsic cell dynamics, so a wiring diagram alone is incomplete. Synapses can strengthen or weaken with activity and other signals, contributing to plasticity, learning and adaptation. Correlation between two neurons does not prove a direct connection because both may share input. Perturbing one element and measuring a predicted effect helps test a circuit model, but compensation and indirect pathways must still be considered.','化学突触把前活动连到递质释放及后响应。动作电位可开钙通道，钙进入促进末端囊泡融合，递质受体效应依分子类型与靶离子条件。有些受体直接开通道，有些经胞内信号。兴奋抑制描述对相关活动概率的影响，不是永久化学或价值标签。突触后电位大小可变，在时间空间叠加，树突几何及主动膜性质影响整合。电突触则经细胞间通道耦合。回路行为来自连接加内在动力学，接线图不完整。突触可随活动信号增强减弱，贡献可塑性学习适应。两神经元相关不证明直接连接，可能共输入；扰动并测预测效应可检验模型，仍须考虑补偿间接途径。');
expand('B08.05','Sensory systems transform selected environmental variables into neural signals through transduction. A receptor is sensitive to a range of stimuli, and its response depends on both stimulus properties and prior stimulation. Adaptation can reduce response to a sustained input while preserving sensitivity to change. Population codes distribute information across many neurons, and the timing of spikes can carry information beyond average firing rate. Receptive fields describe which stimulus features or locations influence a neuron’s response under specified conditions; they can be shaped by network interactions rather than only direct receptor input. Successive processing stages combine, compare and transform signals, so perception is an inference-like biological process rather than a pixel-perfect copy of the external world. Behavior additionally depends on internal state, past learning and available actions. A sensory experiment should separate detection, discrimination and decision criteria, since a changed response can reflect any of them. Illusions and context effects reveal properties of processing but do not imply that perception is arbitrary. Link a physical stimulus, receptor response, circuit transformation and measured behavior while acknowledging where the causal chain remains uncertain.','感觉系统经换能把选定环境变量转为神经信号。受体对某范围刺激敏感，响应依刺激及既往刺激。适应可降低持续输入响应而保留变化敏感。群体编码分布于多神经元，脉冲时间可携平均频率之外信息。感受野说明指定条件下影响响应的特征位置，可由网络塑造而非仅直接输入。后续阶段整合比较变换信号，所以知觉不是外界像素完美拷贝，而是生物推断样过程。行为还依内部状态、学习和可行动作。实验应分检测、辨别与决策标准，响应改变可反映任一。错觉和背景效应揭示处理性质，不意味着知觉任意。应连接刺激、受体、回路与行为，并承认因果链不确定处。');
expand('B08.06','A model organism or preparation is chosen because it makes a particular question experimentally accessible. Simplicity, genetic tools, optical access or a well-characterized circuit can reveal mechanisms, but the model differs from the target system in anatomy, timescale or context. An organoid, isolated cell or artificial network does not automatically reproduce the full behavior of an intact organism. Causal perturbations require specificity: changing one molecule or cell type can have indirect effects through development, compensation or general stress. Use appropriate controls, reversibility or rescue where feasible, and distinguish necessity from sufficiency. An element can be necessary for a behavior without uniquely encoding it, and artificial activation can evoke an outcome without proving that normal behavior uses the same pattern. Ethical evaluation considers scientific value, welfare, alternatives and the minimum necessary burden, with oversight appropriate to the organism and procedure. Human neural data require particular care in interpretation because group averages do not determine an individual’s thoughts or abilities. Report what was measured, what was inferred and which extrapolations remain hypotheses, rather than allowing a vivid brain image to imply unwarranted certainty.','模式生物或制备因使问题可实验而选，简单性、遗传工具、光学可达或已知回路可揭机制，但解剖、时间与背景不同。类器官、离体细胞或人工网络不自动复现完整个体行为。因果扰动需特异性，改一分子或细胞类可经发育、补偿或一般应激产生间接效应。应有对照、可逆或挽救，并分必要与充分：某元件必要不代表唯一编码，人工激活能引结果也不证明正常时用同模式。伦理评价权衡科学价值、福利、替代和最低必要负担，并按生物程序接受适当监督。人类神经数据尤其须谨慎，群体均值不决定个人思想能力。应报告测量、推断与仍是假说的推广，不能让鲜明脑图造成过度确定。');

units('B07',['module.B03.06','module.C09.02'],[
['微生物多样性与生长','Microbial groups|Growth curves|Environmental constraints','微生物类群|生长曲线|环境限制','Microbes include diverse bacteria, archaea and microbial eukaryotes with different metabolisms. Population growth depends on resources and conditions, producing lag, exponential, stationary and decline patterns in a simple closed-culture model.','微生物包括代谢多样的细菌、古菌及微型真核。种群增长依资源条件，简单封闭培养模型有延滞、指数、稳定和衰亡阶段。','A hypothetical population doubles twice from 50 cells. Find final count.','假设种群从 50 个细胞倍增两次，末数是多少？',200,'N = 50 × 2² = 200.','Microbial metabolic diversity exceeds a single oxygen-dependent growth model.','微生物代谢多样性超出单一需氧模型。','All microbes require oxygen and identical nutrients.','所有微生物都需氧和相同营养。'],
['病毒与宿主相互作用','Viral genome|Host dependence|Replication strategy','病毒基因组|宿主依赖|复制策略','Viruses package genetic material and depend on host machinery for reproduction. Attachment, entry, genome expression, assembly and release differ across virus groups. Infection outcome depends on both viral properties and host response.','病毒包装遗传物质，繁殖依宿主机器。不同类群的附着、进入、表达、装配及释放不同，感染结局同时依病毒性质与宿主响应。','An idealized model yields 20 particles per infected cell from 5 cells. Find total particles, ignoring losses.','理想模型每感染细胞产生 20 粒子，五细胞共多少，忽略损失？',100,'20 × 5 = 100 particles.','Viruses do not reproduce independently of suitable host cells.','病毒不能脱离合适宿主细胞独立繁殖。','Every virus is a small bacterial cell.','每种病毒都是小型细菌细胞。'],
['微生物生态与进化','Community interactions|Horizontal transfer|Selection','群落作用|水平转移|选择','Microbial communities exchange metabolites and compete for resources. Genes can move horizontally as well as through ancestry. Environmental changes select among existing variants and can restructure communities without implying purposeful mutation.','微生物群落交换代谢物并竞争资源，基因可水平转移也可垂直遗传。环境变化选择已有变异并重塑群落，并非有目的突变。','A community has 30 cells of type A and 70 of type B. Find A relative abundance.','群落 A 类 30、B 类 70，A 相对丰度是多少？',0.3,'pA = 30/(30+70) = 0.3.','Resistance can spread through selection and gene transfer.','抗性可经选择与基因转移传播。','Microbes consciously mutate into the exact form they need.','微生物会有意识地突变成所需形式。'],
['先天免疫','Barriers|Pattern recognition|Inflammation','屏障|模式识别|炎症','Innate defenses include physical barriers, molecular recognition and rapid cellular responses. Pattern-recognition systems detect classes of danger-associated signals; inflammation recruits and coordinates responses but can also damage tissue if dysregulated.','先天防御包括物理屏障、分子识别和快速细胞响应。模式识别检测多类危险信号，炎症募集协调反应，失调也可损伤组织。','A response recruits 40 cells and 10 leave during an interval, starting from 20. Find final count.','初始 20 细胞，区间内募集 40、离开 10，末数是多少？',50,'Nfinal = 20 + 40 − 10 = 50.','Inflammation can be protective yet harmful when excessive or misdirected.','炎症可保护，也可因过度或错向而有害。','Every inflammatory response is automatically beneficial at any intensity.','任何强度的炎症都自动有益。'],
['适应性免疫','Clonal selection|B and T cells|Memory','克隆选择|B 与 T 细胞|记忆','Adaptive immunity selects rare lymphocyte clones with suitable receptors, expands them and generates effectors and memory. B-cell antibodies and T-cell responses recognize targets through different molecular arrangements and interact with innate signals.','适应性免疫选择受体合适的稀有淋巴克隆，扩增并形成效应与记忆。B 细胞抗体和 T 细胞以不同分子方式识别目标，并与先天信号协作。','A selected clone expands by three ideal doublings from 10 cells. Find count.','某克隆从十细胞理想倍增三次，数量是多少？',80,'10 × 2³ = 80 cells.','Immune memory can change the speed and magnitude of a later response.','免疫记忆可改变再次响应的速度和幅度。','An antibody is a whole immune cell.','抗体是一整个免疫细胞。'],
['免疫实验与群体证据','Assay specificity|Immune correlates|Population comparison','测定特异性|免疫相关指标|群体比较','Immune assays measure selected molecules or cell responses, not immunity as one universal number. Population comparisons require controls for exposure, timing and confounding; an immune correlate is not automatically a complete causal mechanism.','免疫测定测特定分子或细胞响应，并非一个万能免疫数。群体比较需控制暴露、时间和混杂，免疫相关指标不自动是完整因果机制。','In a model dataset, 18 of 20 known-positive samples test positive. Find sensitivity.','模型数据中 20 份已知阳性有 18 检出，灵敏度是多少？',0.9,'Sensitivity = true positives/all actual positives = 18/20 = 0.90.','A test’s predictive value depends partly on the prevalence in the tested population.','检验预测值部分取决于受测人群的患有比例。','Sensitivity alone determines the probability that every positive result is true.','仅凭灵敏度即可确定每个阳性为真的概率。']]);
expand('B07.01','Microbiology studies organisms and biological agents that often require magnification or molecular methods to characterize, but “microbe” is not one evolutionary lineage. Bacteria and archaea are distinct prokaryotic domains, while fungi, protists and microscopic algae include eukaryotic forms. Their energy sources, carbon sources and electron acceptors vary, so oxygen use and nutritional requirements cannot be generalized from one familiar species. Binary fission is common in prokaryotes, but not every microscopic organism divides by the same process. In a simplified closed population with adequate initial resources, a lag phase reflects adjustment, an exponential phase has approximately constant per-capita growth, a stationary phase reflects balanced production and loss or limited net increase, and decline can follow deteriorating conditions. These are population patterns, not synchronized stages that every individual follows together. Optical density, direct cell counts and viable counts measure different things and can diverge. A cell-sized particle is not necessarily alive, and a viable cell need not be detected by every assay. Interpret growth data by specifying the organism, conditions, measurement and model range rather than assuming that a doubling equation remains valid indefinitely.','微生物学研究常需放大或分子方法表征的生物和因子，但“微生物”不是一个进化谱系。细菌古菌属不同原核域，真菌、原生生物和微藻含真核。能源、碳源及电子受体多样，不能从熟悉一种推广需氧和营养。原核常二分裂，但并非所有微型生物相同。简单封闭种群中，延滞反映调整，指数期人均增长近恒，稳定期净增受限或生死平衡，条件恶化可衰亡。这是群体模式，不是每个个体同步经历的阶段。光密度、直接计数与活菌数测不同量，可不一致。细胞大小粒子未必活，活细胞也非每种检测都能检出。解释增长须说明生物、条件、测量与模型范围，不能无限使用倍增式。');
expand('B07.02','Viruses contain genetic information enclosed in a protein capsid, sometimes with an additional lipid envelope. Their genomes can be DNA or RNA and differ in strand type and replication strategy. They do not possess the full independent cellular machinery needed to reproduce, so a suitable host supplies essential functions. Entry depends on interactions with host surfaces or other delivery routes, making host range a biological property rather than a universal ability to infect every cell. After entry, viral genes are expressed and copied through mechanisms appropriate to the genome type, components assemble and new particles leave or persist in association with the host. Some infections rapidly produce particles and damage cells, while others establish longer-lived states. A detected viral sequence or particle is not automatically evidence of ongoing productive infection. Host defenses, cell state and prior exposure influence outcome, and viruses themselves vary in how they interact with those responses. Distinguish the infectious particle outside a cell from the intracellular replication process. Viruses illustrate evolution and molecular dependence but should not be described as tiny bacteria, because antibacterial targets and viral reproductive mechanisms are fundamentally different.','病毒遗传信息由蛋白衣壳包裹，有些另有脂包膜；基因组可 DNA 或 RNA，链型和复制策略不同。病毒缺完整独立细胞繁殖机器，需合适宿主功能。进入依宿主表面作用或其他输送，宿主范围是具体性质，并非可感染任意细胞。进入后按基因组类型表达复制，组分装配，新粒子释放或与宿主持久相关。有些快速产粒子损细胞，另一些长期存在。检测到序列或粒子不自动证明正在生产性感染。宿主防御、细胞状态、既往暴露影响结果，病毒与防御的作用也不同。应区分胞外感染粒子与胞内复制过程，病毒虽体现进化和分子依赖，却不是小细菌，因为抗细菌靶点与病毒繁殖机制根本不同。');
expand('B07.03','Microbial ecology examines interactions among organisms and their chemical environment. One species may release a metabolite that another consumes, creating cross-feeding, while competition can limit access to carbon, nutrients or space. Communities also modify pH, oxygen availability and other conditions that feed back on their own composition. Relative abundance data describe proportions; an increase in one group’s fraction can result from decline of another without any increase in its absolute cell count. Horizontal gene transfer moves genetic material outside direct parent–offspring inheritance and can spread metabolic or resistance traits, but successful transfer and persistence depend on compatibility and selection. Evolutionary changes also arise through mutation, drift and ordinary inheritance. Environmental pressure favors variants according to their effects; it does not cause organisms to choose the precise beneficial mutation. A resistant population can expand because susceptible competitors decline, because resistance genes spread or because new variants arise and persist. Distinguish these mechanisms using time-resolved, genetic and ecological evidence. A microbiome association with a host trait is not automatically causal, since diet, environment, host physiology and reverse effects can influence both.','微生物生态研究生物与化学环境。一种释放代谢物供另一种利用形成交叉供养，竞争限制碳、营养和空间。群落也改 pH、氧等条件，反馈自身组成。相对丰度是比例，某类比例增大可只是他类减少，绝对数未增。水平转移绕过亲子遗传搬基因，可传播代谢和抗性，但成功与持久依相容和选择。突变、漂变和普通遗传也产生变化。环境压力按变异效应选择，不让生物挑精确有利突变。抗性种群扩张可因敏感竞争者减少、基因传播或新变异产生保留，应以时间、遗传和生态证据区分。微生物组与宿主性状相关不自动致因，饮食、环境、宿主生理及反向作用可共同影响。');
expand('B07.04','Innate immunity provides layered defenses that act before or alongside highly specific adaptive responses. Physical and chemical barriers reduce entry, including epithelial surfaces and local secretions. If a barrier is breached, cells can recognize conserved microbial patterns or signals of damaged tissue through pattern-recognition receptors. These receptors are inherited recognition systems rather than a newly generated receptor for every possible invader. Phagocytic cells can engulf material, complement proteins can mark or damage targets, and cytokines coordinate recruitment and activation. Inflammation changes local blood flow, permeability and cell traffic, helping deliver defenses but also producing tissue effects. The response must be regulated because excessive or misdirected activation can harm the host. Recognition of a signal does not by itself identify one unique organism, and inflammation can occur without infection. Innate signals influence adaptive activation, so the two branches are connected rather than independent backup systems. Interpret experiments by identifying the barrier, receptor, cell type and measured response. A rise in one cytokine is evidence about that signaling component, not a complete measurement of overall immune competence or the cause of a disease.','先天免疫提供分层防御，在特异适应响应前或同时作用。上皮与分泌等物理化学屏障减少进入。突破后，细胞通过模式识别受体检测保守微生物模式或组织损伤信号；这是遗传识别系统，不是为每个入侵者新造受体。吞噬细胞吞材料，补体标记或损目标，细胞因子协调募集活化。炎症改局部血流、通透和细胞交通，输送防御也产生组织影响。必须调控，因为过度错向会伤宿主。一个信号不唯一识别病原，炎症也可无感染。先天信号影响适应活化，两者相连而非独立备用。实验应明确屏障、受体、细胞与测响应；某因子升高只说明该组件，不是整体免疫能力或疾病原因的完整测量。');
expand('B07.05','Adaptive immunity uses diverse antigen receptors distributed among lymphocyte clones. A clone whose receptor recognizes a relevant target can be selected, activated and expanded when the necessary contextual signals are present. B cells can differentiate into antibody-secreting cells; antibodies bind particular molecular features and can neutralize, mark or otherwise influence targets through their structure and associated systems. T cells recognize peptide antigens presented by appropriate major-histocompatibility molecules rather than generally binding free intact antigen in the same manner as antibodies. Different T-cell subsets coordinate responses or act on target cells. Receptor specificity does not mean perfect exclusivity, since cross-reactivity is possible. Tolerance mechanisms reduce harmful responses to self, but their failure can contribute to immune pathology. After a response, some cells persist as memory populations and can alter later response speed and quality. Protection depends on the target, exposure route, tissue context and effector mechanisms, so antibody amount alone is not a universal immunity score. Adaptive and innate systems exchange signals throughout activation and resolution. A proper explanation distinguishes recognition, activation, effector action and memory rather than merging them into a single event called fighting infection.','适应性免疫将多样抗原受体分布于淋巴克隆。受体识别相关目标且情境信号适合时，克隆被选择、活化和扩增。B 可成分泌抗体细胞，抗体结合特定分子特征，通过结构及相关系统中和、标记或影响目标。T 细胞识别合适主要组织相容分子呈递的肽，而非像抗体一样通常直接结合完整游离抗原；不同亚群协调或作用靶细胞。特异并非绝对唯一，可能交叉反应。耐受降低有害自反应，失败可致免疫病理。响应后部分保留为记忆，改变后来速度和质量。保护依目标、暴露途径、组织与效应，抗体量不是万能免疫分数。先天适应在活化消退全过程交流，应区分识别、活化、效应和记忆，不能统称一个“抗感染”事件。');
expand('B07.06','An immune experiment measures a chosen proxy, such as binding antibodies, neutralization under assay conditions, cell activation or a cytokine concentration. Those proxies answer different questions and need not move together. Sensitivity is the proportion of truly positive samples detected, while specificity is the proportion of truly negative samples correctly called negative. Predictive values additionally depend on the tested population’s prevalence and the sampling design. A positive molecular or immune signal therefore requires interpretation in context rather than being a self-explanatory diagnosis. Time since exposure, age, prior immune history and assay platform can influence comparisons. Population-level evidence benefits from clearly defined outcomes, comparable groups and methods to address confounding and missing data. Random assignment can strengthen causal inference for an intervention, while observational associations require careful alternative explanations. An immune correlate predicts or accompanies an outcome but may not itself be the protective mechanism. Distinguish a laboratory response from demonstrated protection in the relevant setting, and report confidence intervals or uncertainty rather than only a point estimate. Educational datasets can illustrate these principles without substituting for individualized medical interpretation.','免疫实验测选定代理量，如结合抗体、测定条件下中和、细胞活化或细胞因子，各自问题不同，不必同步。灵敏度是真阳被检比例，特异度是真阴正确判阴比例，预测值还依受测群体比例与抽样。因此阳性分子或免疫信号需情境解释，不是自明诊断。暴露后时间、年龄、免疫史和平台影响比较。群体证据应定义结果、可比组并处理混杂缺失；随机分配加强干预因果，观察相关需认真考虑替代解释。免疫相关指标预测伴随结果，不一定本身是保护机制。区分实验室响应与相关场景证实保护，报告区间或不确定度而非仅点值。教学数据可说明原则，不替代个体医疗解释。');

units('B06',['module.B01.06','module.P01.01'],[
['动物多样性与体制','Symmetry|Tissue organization|Evolutionary relationships','对称性|组织层次|进化关系','Animal body plans differ in symmetry, tissues, cavities and development. These characters help compare lineages, but evolutionary relationships require combined evidence rather than arranging animals on a single complexity ladder.','动物体制在对称、组织、体腔和发育上不同，这些特征帮助比较谱系，但亲缘需综合证据，不能排成单一复杂度阶梯。','A bilaterally symmetric body is divided by its main symmetry plane into how many matching sides?','两侧对称身体由主要对称平面分成几个对应侧？',2,'One bilateral plane separates left and right: 2 sides.','A body-plan feature can be modified or lost in evolution.','体制特征可在进化中改变或丢失。','Every modern animal is a step toward one most advanced body plan.','每种现代动物都是通向某最高级体制的一步。'],
['稳态与反馈','Regulated variables|Negative feedback|Set-point variation','受调变量|负反馈|调节点变化','Homeostasis maintains variables within functional ranges through sensing, integration and responses. Negative feedback counteracts a deviation; positive feedback amplifies it until another process ends the loop. Regulation is dynamic rather than perfectly constant.','稳态通过感知、整合和响应将变量维持在功能范围。负反馈反抗偏离，正反馈放大偏离直至其他过程终止。调节是动态的，并非绝对恒定。','A variable rises from target 100 to 112. What is its deviation above target?','变量从目标 100 升至 112，偏高多少？',12,'Deviation = measured − target = 112 − 100 = 12.','Negative feedback can involve continuing fluctuations around a regulated range.','负反馈可伴随调节范围附近持续波动。','Homeostasis means every internal variable is perfectly constant.','稳态意味着所有内部量完全不变。'],
['运输、呼吸与营养','Exchange surfaces|Circulation|Digestion and absorption','交换表面|循环|消化与吸收','Respiratory surfaces exchange gases, circulation transports materials, and digestion converts food into absorbable forms. Exchange depends on gradients, surface area and barrier thickness, while blood flow connects distant tissues.','呼吸表面交换气体，循环运输物质，消化把食物转为可吸收形式。交换依梯度、面积与屏障厚度，血流连接远处组织。','A pump moves 70 mL per beat at 60 beats per minute. Find flow in mL/min.','泵每搏 70 mL，每分钟 60 搏，流量为多少 mL/min？',4200,'Flow = stroke volume × frequency = 70 × 60 = 4200 mL/min.','Breathing and cellular respiration are connected but different processes.','通气与细胞呼吸相联系却是不同过程。','All ATP is produced directly inside lungs.','所有 ATP 都直接在肺内产生。'],
['排泄与渗透调节','Filtration|Selective reabsorption|Water–salt balance','滤过|选择性重吸收|水盐平衡','Excretory systems remove metabolic wastes while regulating water and ions. Filtration is followed by selective reabsorption and secretion, so final excreted composition is not simply an unchanged sample of body fluid.','排泄系统去代谢废物并调节水离子。滤过后有选择重吸收与分泌，因此最终排出物不是未经改变的体液样本。','A model filters 100 units and reabsorbs 95, with no secretion. Find excreted amount.','模型滤过 100 单位，重吸收 95，无分泌，排出多少？',5,'Excreted = filtered − reabsorbed = 100 − 95 = 5.','Excretion and undigested-food elimination are different processes.','排泄与排出未消化食物是不同过程。','Kidneys merely remove all filtered substances without selection.','肾只是不加选择地排出所有滤过物。'],
['神经与内分泌系统','Electrical signals|Synaptic communication|Hormonal signaling','电信号|突触传递|激素信号','Neurons transmit electrical changes and communicate through synapses. Endocrine signals travel through body fluids and act on cells with suitable receptors. Both systems interact in feedback control across different spatial and temporal scales.','神经元传电变化并经突触交流，内分泌信号通过体液到达有适当受体的细胞，两系统在不同时间空间尺度反馈调控中相互作用。','A signal travels 2 m at 20 m/s. Find travel time in seconds.','信号以 20 m/s 传播 2 m，时间为多少秒？',0.1,'t = distance/speed = 2/20 = 0.1 s.','Hormone response depends on receptor and cellular context.','激素响应依赖受体与细胞情境。','Every hormone affects every cell equally.','每种激素对每个细胞作用相同。'],
['繁殖与整合生理','Gametes|Hormonal coordination|Physiological tradeoffs','配子|激素协调|生理权衡','Reproduction integrates gamete production, fertilization, development and physiological support. Endocrine and neural regulation connect reproductive function with nutrition, stress and internal conditions. Different animal lineages use diverse reproductive strategies.','繁殖整合配子产生、受精、发育及生理支持。内分泌和神经把繁殖与营养、胁迫及内部条件连接，不同动物谱系采用多样策略。','Two haploid gametes each contain 8 chromosomes. How many chromosomes are in the resulting diploid zygote?','两个单倍配子各含 8 条染色体，形成二倍合子共几条？',16,'8 + 8 = 16 chromosomes.','Reproductive strategies involve tradeoffs in offspring number and investment.','繁殖策略涉及后代数量与投入权衡。','All animals use the same fertilization and developmental strategy.','所有动物采用同样受精和发育策略。']]);
expand('B06.01','Animals are multicellular eukaryotes that obtain organic material from other organisms or their products, but their structures and life histories vary enormously. Comparative anatomy considers traits such as symmetry, tissue organization, segmentation, body cavities and feeding structures. Bilateral symmetry often accompanies a distinct head–tail axis and directional movement, whereas radial organization suits other ecological arrangements; there are exceptions and secondary modifications. Germ layers contribute to different tissues during development, but simplified developmental categories do not by themselves resolve every evolutionary relationship. A body cavity can provide space for organs or a hydrostatic support system, while skeletons may be internal, external or based on fluid pressure. Gas exchange, circulation and excretion must solve size- and environment-dependent problems, so small aquatic animals and large terrestrial animals can use very different designs. Phylogeny combines anatomical and molecular evidence rather than ranking organisms by resemblance to humans. Similar functions can evolve through different structures, and related structures can acquire different functions. Learn representative lineages as comparisons of mechanisms and constraints, not as an endless list of names or a ladder from inferior to superior forms.','动物是从其他生物或其产物获取有机物的多细胞真核，但结构生活史差异巨大。比较解剖看对称、组织、分节、体腔及摄食结构。两侧对称常伴头尾轴和定向运动，辐射组织适合其他生态安排，也有例外及次生改变。胚层对不同组织有贡献，但简化发育类别不能独自解决所有亲缘。体腔可给器官空间或液压支撑，骨骼可内、外或依流体压力。换气、循环和排泄需解决大小及环境问题，所以小水生与大陆生设计可很不同。系统发育综合解剖和分子证据，不按像人程度排名。同功能可由不同结构实现，同源结构可获不同功能。学习代表谱系应比较机制约束，不是无尽背名或从低等到高等阶梯。');
expand('B06.02','Homeostatic regulation maintains conditions compatible with cellular function despite changing inputs and demands. A regulated variable might be temperature, ion concentration or another internal quantity, and the acceptable range need not be one exact fixed number. Sensors detect a state, integrating processes compare information with regulatory signals, and effectors alter heat production, transport, secretion or behavior. Negative feedback means the response tends to oppose the initiating deviation. A delay or strong response can produce oscillation or overshoot, so fluctuation does not automatically indicate regulatory failure. Positive feedback reinforces a change and can be useful for a bounded event, but it usually requires an external stopping condition or depletion of the initiating stimulus. Feedforward responses anticipate a demand rather than waiting for a measured deviation. Different variables interact: conserving water may affect heat loss, and exercise simultaneously changes oxygen demand, circulation and temperature regulation. A physiological set point can vary with time or state, so a changed target should not be confused with a broken controller. Explain a feedback example by identifying the sensed variable, response direction, effectors and termination conditions rather than labeling any beneficial response homeostasis.','稳态调节在输入需求改变时维持适于细胞功能的条件。受调量可为温度、离子等，可接受范围未必一个固定点。传感器检测，整合过程比较调控信息，效应器改变产热、输运、分泌或行为。负反馈使响应反抗初始偏离；延迟或强响应可引起振荡超调，波动不自动表示失败。正反馈增强变化，可用于有边界事件，但通常需外部终止或刺激耗尽。前馈预判需求，而非等待偏差。多个变量互相影响，如节水影响散热，运动同时改变耗氧、循环和体温。调节点可随时间状态改变，目标改变不等于控制器坏。解释反馈须明确感知量、响应方向、效应器及终止条件，不能把任何有益反应都叫稳态。');
expand('B06.03','Nutrition, gas exchange and internal transport solve complementary supply problems. Digestion breaks food mechanically and chemically into forms that can cross an epithelial barrier, while absorption transfers those products into internal transport systems. Surface folds and projections increase exchange area, but a large area must also be supplied and drained effectively. Respiratory exchange depends on partial-pressure gradients and diffusion distance; ventilation renews the external medium and circulation carries gases between exchange surfaces and tissues. Oxygen-binding proteins can increase transport capacity beyond dissolved gas alone, with binding behavior influenced by local conditions. A circulatory pump establishes pressure differences that drive flow through a network, and resistance depends strongly on vessel geometry. Capillaries or other exchange regions connect bulk transport with short-distance diffusion. Breathing is movement of air or water across a respiratory surface, whereas cellular respiration is a metabolic process inside cells; neither term should replace the other. Coordinated regulation adjusts flow and ventilation to tissue demand. Compare animal systems by following the path of a nutrient or oxygen molecule from the environment to a cell, identifying each barrier, driving force and transport mechanism along the way.','营养、换气与内运输解决互补供应问题。消化机械和化学分解食物为可跨上皮形式，吸收将产物送入体内运输。褶皱突起增面积，但仍需有效供给和带走物质。呼吸交换依分压梯度与扩散距离，通气更新外介质，循环在表面与组织间运气体。氧结合蛋白使载氧能力超过单纯溶解，结合行为受局部条件影响。循环泵建立压差驱动网络流，阻力强烈依血管几何。毛细等交换区连接整体输运与短程扩散。通气是空气水跨呼吸表面运动，细胞呼吸是胞内代谢，不能互换。协调调节使流量通气适应组织需求。比较系统可追踪营养或氧从环境到细胞，逐段识别屏障、驱动力和机制。');
expand('B06.04','Metabolism produces wastes, and living in water or on land also creates challenges of maintaining water and ion balance. Excretion removes metabolic products, whereas egestion removes material that was not absorbed from food. Nitrogen-containing wastes differ in toxicity, water requirement and energetic cost, helping explain why animal groups use different dominant forms. In a nephron-like system, pressure-driven filtration transfers water and small solutes from a fluid compartment, but valuable substances would be lost if filtration were the final step. Selective reabsorption returns needed material, while secretion adds particular substances to the forming excretory fluid. Countercurrent arrangements and active transport can establish gradients that support water conservation. Hormonal regulation changes permeability or transport activity according to physiological state. Freshwater, marine and terrestrial animals face different osmotic gradients, so one universal “remove excess water” explanation is inadequate. A final urine or excretory composition reflects filtration, reabsorption, secretion and flow together. Use a material balance to distinguish those contributions, and do not infer that a substance was never filtered merely because little appears in the final output.','代谢产生废物，水陆环境还带来水盐平衡挑战。排泄去代谢产物，排遗去未被食物吸收的材料。含氮废物毒性、需水和能耗不同，解释不同动物主要形式差异。肾单位样系统中，压差滤过水及小溶质，但若止于滤过会丢失有用物。选择重吸收回收所需，分泌则把特定物加入形成的排液。逆流安排和主动运输建立梯度，帮助节水；激素按状态改变透过性与转运。淡水、海洋和陆生面对不同渗透梯度，不能一律说“排多余水”。最终组成由滤过、重吸收、分泌和流量共同决定。应物料核算区分贡献，终输出少不能推断该物从未被滤过。');
expand('B06.05','Nervous and endocrine systems coordinate activity across an animal using different but interacting communication modes. A neuron maintains ion gradients across its membrane and can generate electrical changes through regulated channel opening. Action potentials propagate along suitable membranes, and chemical synapses translate arriving electrical activity into transmitter release and a response in a target cell. The effect depends on the receptor and ion gradients, so one transmitter is not universally excitatory or inhibitory in every context. Endocrine cells release hormones into internal fluids; only cells with suitable receptors and downstream machinery respond directly. Some hormones act through membrane receptors, while others influence intracellular receptors and gene expression. Neural signals can be rapid and spatially targeted, whereas hormonal signals can reach many tissues and persist longer, but there is overlap rather than an absolute timing boundary. Feedback connects both systems, as in regulation of metabolism or stress responses. Separate signal production, transport, receptor binding and cellular response when analyzing a failure. Measuring a hormone concentration alone does not establish receptor sensitivity or the complete physiological effect.','神经与内分泌以不同而相互作用的通信方式协调动物。神经元维持跨膜离子梯度，调通道产生电变化，动作电位沿适当膜传播，化学突触把到达电活动转为递质释放和靶响应。效应取决于受体及离子梯度，因此某递质并非处处兴奋或抑制。内分泌细胞向体液放激素，只有有合适受体及下游机器者直接响应。有些激素经膜受体，另一些经胞内受体和表达。神经常快且定向，激素可广泛持久，但时间并无绝对界。反馈连接两系统，如代谢或应激调节。分析失效应分信号产生、输送、受体结合和胞内响应；只测激素浓度不能确定受体敏感性或完整生理效果。');
expand('B06.06','Sexual reproduction combines genetic material from gametes, but animals differ greatly in how gametes meet and how offspring develop. Meiosis reduces chromosome sets and contributes genetic variation; fertilization restores the diploid combination in the common life-cycle pattern. Gamete production requires coordinated cell differentiation and physiological resources. External fertilization, internal fertilization, egg laying and live bearing impose different constraints on water, protection, dispersal and parental investment. Reproductive timing can be coordinated by environmental cues and endocrine feedback, linking it to nutrition and body condition. Development after fertilization requires cell division, pattern formation and interactions between embryonic and supporting tissues; a zygote does not merely enlarge without differentiation. Investing more resources per offspring can reduce the number produced, illustrating a life-history tradeoff rather than a universally superior strategy. Reproductive function also interacts with circulation, metabolism and immune regulation, so isolated organ descriptions are incomplete. When interpreting an experiment, separate gamete number, fertilization success, embryo survival and later reproductive success because each can limit the final outcome. Avoid assuming that one familiar mammalian pattern describes all animal reproduction.','有性繁殖合并配子遗传材料，但动物配子相遇与后代发育方式差异巨大。常见生活史中，减数分裂减半染色体组并产变异，受精恢复二倍组合。配子生成需要协调分化和资源。体外体内受精、产卵胎生对水、保护、扩散及亲代投入约束不同。环境线索与内分泌反馈协调繁殖时间，联系营养和体况。受精后发育需分裂、格局形成及胚胎支持组织相互作用，合子不是不分化地只变大。每个后代投入更多可能减少数量，是生活史权衡而非万能优策略。繁殖还与循环、代谢和免疫相互作用，孤立器官描述不完整。实验应区分配子数、受精成功、胚存活与后期繁殖成功，每项都可限制结果。不能把一种熟悉哺乳类模式推广所有动物。');

units('B05',['module.B01.06','module.C01.05'],[
['植物多样性与生活史','Alternation of generations|Spores and seeds|Plant lineages','世代交替|孢子与种子|植物谱系','Plant life cycles alternate multicellular haploid and diploid stages with differing prominence across lineages. Spores begin a haploid generation, while seeds package a young sporophyte with protective and nutritional support.','植物生活史在多细胞单倍和二倍阶段间交替，各谱系主导阶段不同。孢子开启单倍世代，种子包装幼孢子体并提供保护营养。','A sporophyte has 2n = 12. How many chromosomes occur in a normal haploid spore?','孢子体 2n = 12，正常单倍孢子含几条染色体？',6,'n = 12/2 = 6.','A spore and a seed represent different structures and life-cycle stages.','孢子与种子是不同结构和生活史阶段。','All plants reproduce through flowers and seeds.','所有植物都通过花和种子繁殖。'],
['组织、生长与发育','Meristems|Dermal and vascular tissues|Growth direction','分生组织|保护与维管组织|生长方向','Meristems retain dividing cells that produce new tissues. Dermal, ground and vascular tissues perform different functions. Primary growth lengthens organs, while secondary growth in suitable plants increases girth.','分生组织保留分裂细胞形成新组织。保护、基本和维管组织分工不同。初生生长延长器官，适用植物的次生生长增加粗度。','A stem grows from 8 to 11 cm. Find length increase in cm.','茎长从 8 增至 11 cm，增长多少 cm？',3,'ΔL = 11 − 8 = 3 cm.','Plant growth involves cell division, expansion and differentiation.','植物生长涉及分裂、扩张与分化。','All mature plant cells divide at the same rate.','所有成熟植物细胞以相同速率分裂。'],
['水与矿质运输','Water potential|Xylem|Transpiration','水势|木质部|蒸腾','Water moves according to water-potential differences. Transpiration can generate tension pulling a cohesive water column through xylem. Mineral uptake involves selective membrane transport, not merely bulk water absorption.','水按水势差移动。蒸腾可产生张力，经木质部拉动内聚水柱。矿质吸收涉及选择性膜运输，并非只随水大量吸入。','Ignoring other terms, solute potential is −0.5 MPa and pressure potential +0.2 MPa. Find total water potential in MPa.','忽略其他项，溶质势 −0.5 MPa、压力势 +0.2 MPa，总水势是多少 MPa？',-0.3,'Ψ = Ψs + Ψp = −0.5 + 0.2 = −0.3 MPa.','Water moves toward lower water potential when an accessible pathway exists.','有通路时水趋向较低水势。','Water always moves toward the larger numerical solute concentration regardless of pressure.','无论压力如何，水总向溶质浓度数值更大处走。'],
['光合作用与碳分配','Light reactions|Carbon fixation|Source–sink transport','光反应|碳固定|源库运输','Light reactions generate reducing power and ATP while splitting water. Carbon fixation incorporates carbon dioxide into organic compounds. Phloem distributes assimilated carbon from sources to sinks whose roles can change over development.','光反应裂解水并生成还原力与 ATP，碳固定把 CO2 纳入有机物。韧皮部将同化碳从源运往库，角色可随发育改变。','Fixing six CO2 molecules incorporates how many carbon atoms into the combined products?','固定六个 CO2 分子，产物共纳入几个碳原子？',6,'Each CO2 has one carbon; total = 6.','Photosynthetic oxygen is released from water rather than directly from carbon dioxide.','光合作用释放的氧来自水，而非直接来自 CO2。','Plants obtain all of their carbon skeletons directly from soil minerals.','植物所有碳骨架都直接来自土壤矿物。'],
['激素与环境响应','Plant hormones|Tropisms|Signal integration','植物激素|向性|信号整合','Plant hormones coordinate growth and stress responses through concentration- and tissue-dependent effects. Tropisms involve directional growth in response to a stimulus. Light, gravity, water status and developmental signals interact.','植物激素按浓度与组织情境协调生长和胁迫响应。向性是对刺激的方向性生长，光、重力、水分和发育信号彼此作用。','One side of a shoot elongates 4 mm while the other elongates 1 mm. Find differential elongation in mm.','幼茎一侧伸长 4 mm，另一侧 1 mm，差异伸长是多少 mm？',3,'Difference = 4 − 1 = 3 mm.','The same hormone can have different effects in different tissues or concentrations.','同一激素在不同组织或浓度可有不同效应。','Every plant hormone has one identical effect in every cell.','每种植物激素在所有细胞都只有同一效应。'],
['植物实验与适应','Limiting factors|Control design|Adaptation evidence','限制因素|对照设计|适应证据','Plant experiments distinguish environmental responses from inherited differences using controlled conditions and replication. A growth change can reflect light, nutrients, water or temperature, so several covarying factors must not be attributed to one cause.','植物实验用控制条件和重复区分环境响应与遗传差异。生长变化可来自光、营养、水或温度，不能把多个共变因素全归一个原因。','A treatment mean is 15 g and control mean 12 g. Find percentage increase relative to control.','处理均值 15 g，对照 12 g，相对对照增加百分之几？',25,'Increase = (15 − 12)/12 × 100% = 25%.','A treatment effect requires comparison with an appropriate control and variation estimate.','处理效应需与合适对照及变异估计比较。','One unusually tall plant proves an inherited adaptation.','一株异常高的植物就证明遗传适应。']]);
expand('B05.01','Plant diversity is organized by evolutionary relationships and by innovations in reproduction, transport and protection from water loss. Land plants share ancestry but differ in whether they possess extensive vascular tissue, pollen, seeds or flowers. Their life cycles alternate a haploid gametophyte generation, which makes gametes by mitosis, and a diploid sporophyte generation, which makes spores by meiosis. Fertilization restores diploidy, while meiosis restores the haploid stage. The relative size and independence of these generations vary: a moss gametophyte is conspicuous, whereas the gametophytes of seed plants are highly reduced. A spore can grow without fusing with another cell, unlike a gamete. Pollen contains the male gametophyte in seed plants and permits sperm delivery without requiring free external water in the same way as many earlier lineages. A seed contains an embryo, stored resources and protective structures; fruits develop from floral tissues and help protect or disperse seeds in flowering plants. Do not arrange living groups as failed steps toward flowers: each lineage has its own adaptations and history. Compare life-cycle stages by chromosome set and function rather than visual size alone.','植物多样性由亲缘及繁殖、运输、防失水创新组织。陆生植物同源，但维管、花粉、种子和花等不同。生活史交替单倍配子体与二倍孢子体：配子体有丝分裂产配子，孢子体减数分裂产孢子，受精恢复二倍，减数恢复单倍。两世代大小独立性不同，苔藓配子体显著，种子植物配子体高度退化。孢子无需融合即可生长，配子则需融合。花粉含雄配子体，使种子植物精子输送不像许多早期谱系那样依赖外界自由水。种子含胚、储备及保护结构，果实来自花组织，帮助被子植物保护传播种子。不能把现生群体排列为通向花的失败阶梯，各自有适应和历史。比较阶段应按染色体组及功能，而非只看大小。');
expand('B05.02','Plant bodies are built from tissues whose development remains active in particular regions throughout life. Apical meristems near shoot and root tips generate primary growth, increasing length and producing new organs. In many woody plants, lateral meristems produce secondary tissues that increase diameter. Cell division supplies new cells, but expansion through water uptake and wall remodeling contributes much of organ growth. Differentiation then gives cells specialized structures and functions. Dermal tissues form protective interfaces; ground tissues contribute photosynthesis, storage or support; vascular tissues conduct water, minerals and organic solutes. Xylem and phloem are distinct tissue systems with different cell types and transport roles. Root hairs increase contact with soil, while leaves arrange light capture and gas exchange around constraints of water loss and support. Development integrates positional signals and environmental conditions, so plant form is often plastic rather than a fixed miniature plan simply enlarging. A growth measurement should distinguish cell number, cell size, organ length and biomass. Two treatments can produce equal stem length while differing greatly in tissue mass or allocation, making one-dimensional size a limited measure of overall plant performance.','植物组织在一生中特定区域持续发育。根茎尖顶端分生组织产生初生生长，增长度并形成新器官；许多木本的侧生分生组织形成次生组织增粗。分裂提供新细胞，吸水及细胞壁重塑造成的扩张也贡献大量生长，随后分化出特化结构功能。保护组织形成界面，基本组织负责光合、储存或支撑，维管组织运输水、矿质和有机溶质。木质部与韧皮部细胞及运输角色不同。根毛增加土接触，叶在失水与支撑限制下组织捕光换气。发育整合位置与环境，因此植物形态常有可塑性，并非缩小蓝图简单放大。测生长应区分细胞数、大小、器官长与生物量；等长茎可有很不同质量和分配，一维长度不是完整表现指标。');
expand('B05.03','Water transport through a plant links soil, roots, stems, leaves and the atmosphere. Water potential combines contributions such as dissolved solutes and pressure, with additional terms relevant in some situations. Water tends to move along an accessible path toward lower potential, so pressure can counteract an osmotic concentration difference. Root cell membranes regulate entry, and the endodermal barrier helps control which substances reach vascular tissue. Xylem conduits conduct water over long distances; many conducting cells are dead at maturity, leaving reinforced pathways. Evaporation from leaf surfaces lowers water potential and generates tension, while cohesion among water molecules and adhesion to conduit walls support the connected column. This cohesion–tension model does not require every segment to pump water actively. Cavitation can interrupt the column and constrain transport. Stomata regulate gas exchange and water loss through guard-cell responses, creating a tradeoff between carbon dioxide uptake and dehydration. Mineral ions require selective uptake and often active transport or symbiotic assistance. Soil concentration alone does not determine availability, because chemical form, pH, root activity and microbial interactions also influence nutrient acquisition.','植物水输运连接土壤、根、茎、叶和大气。水势合并溶质和压力等贡献，某些情形还需其他项；有通路时水流向较低势，压力可抵消渗透浓度差。根膜调控进入，内皮层屏障帮助控制到维管的物质。木质部远距导水，许多成熟输导细胞已死，留下加固通道。叶表蒸发降低水势并产生张力，水内聚和壁黏附支持连续水柱；内聚—张力模型不要求每段主动泵水。气穴可断柱并限制输运。保卫细胞控制气孔换气失水，形成 CO2 摄取与脱水权衡。矿质需选择吸收，常涉及主动运输或共生；土浓度不独定可得性，化学形态、pH、根活动和微生物也影响获取。');
expand('B05.04','Photosynthesis links light-driven electron transfer with carbon assimilation, but the two are distinct sets of reactions. In chloroplast thylakoid membranes, pigments absorb photons and reaction centres use excitation to drive electron transfer. Water supplies electrons in oxygenic photosynthesis, releasing oxygen and contributing to proton-gradient formation. Electron transport and ATP synthase generate ATP, while reducing equivalents are stored in NADPH. The Calvin cycle uses ATP and reducing power to incorporate carbon dioxide into organic intermediates and regenerate its carbon acceptor. Calling it the dark reaction can mislead because it depends on products and regulation associated with light, not a requirement to run only at night. Rubisco can also react with oxygen, initiating photorespiratory processes; C4 and CAM strategies alter carbon-concentrating arrangements and timing under particular ecological conditions. Produced carbohydrates may be used locally, stored or exported through phloem. Source tissues release assimilates and sink tissues consume or store them, and these roles can change during development. Measure photosynthetic performance by specifying light, carbon dioxide, water and temperature conditions rather than attributing every growth difference to chlorophyll amount.','光合作用连接光驱动电子转移与碳同化，但两者是不同反应组。叶绿体类囊体色素吸光，反应中心用激发驱动电子转移。产氧光合由水供电子，放氧并参与建立质子梯度；电子链和 ATP 合酶生 ATP，还原力存于 NADPH。卡尔文循环用 ATP 与还原力把 CO2 纳入有机中间体并再生受体。“暗反应”易误导，它依赖光相关产物调控，不要求只在夜间。Rubisco 也可与氧反应，启动光呼吸；C4 和 CAM 在特定生态条件下改变碳浓缩空间和时间。糖可就地用、储存或经韧皮部输出，源释放同化物，库消耗储存，角色随发育改变。测光合应明确光、CO2、水和温度，而非把所有生长差归叶绿素量。');
expand('B05.05','Plants detect environmental information and integrate it with developmental state through signaling networks. Hormones are mobile or locally acting chemical signals whose effects depend on receptor distribution, concentration, tissue identity and interactions with other pathways. Auxin can influence cell expansion, organ patterning and directional growth, but its effects differ between roots and shoots and across concentrations. Other hormone classes regulate processes such as division, dormancy, germination, senescence and stress responses; no hormone has one exclusive universal task. A tropism is directional growth related to stimulus direction, whereas some plant movements respond without the same directional growth mechanism. Photoreceptors distinguish light qualities as well as intensity, helping coordinate germination, shade responses and flowering timing. Gravity sensing can redistribute growth signals so opposite sides of an organ expand differently. Water stress changes stomatal behavior and growth allocation through several signals. To infer a hormonal mechanism, compare treatment, dose, timing and tissue-specific responses with appropriate controls. External hormone application can produce an effect without proving that the normal plant uses that exact concentration or route.','植物通过信号网络把环境信息与发育状态整合。激素可移动或局部作用，效应依受体分布、浓度、组织身份和其他路径。生长素影响扩张、器官格局与向性，但根茎及不同浓度效应不同。其他激素类参与分裂、休眠、萌发、衰老和胁迫，没有一种只有独占万能任务。向性是与刺激方向相关的定向生长，某些植物运动并非同样机制。光受体区分光质和强度，协调萌发、避阴及开花时间。重力感知可重分布生长信号，使器官两侧扩张不同。缺水通过多信号改变气孔和生长分配。推断激素机制需比较处理、剂量、时间及组织响应并设对照；外源激素有效不证明天然植物使用完全相同浓度路径。');
expand('B05.06','A plant experiment must distinguish inherited differences from environmental responses and measurement artifacts. A common-garden comparison grows different genotypes under shared conditions, while reciprocal transplants can test how each performs in contrasting environments. Neither design eliminates every confound automatically: maternal effects, initial size, soil microbes and microclimate may still matter. Randomize positions and replicate independent plants or plots rather than treating many leaves on one plant as fully independent organisms. Define the response precisely, such as dry biomass, leaf area, survival or carbon-assimilation rate, because these can respond differently. A limiting-factor experiment changes one resource while controlling others sufficiently to interpret the result. If growth plateaus after fertilizer addition, another factor may have become limiting, but toxicity or experimental saturation are alternatives. An adaptation is an inherited feature shaped by selection, whereas acclimation is an individual’s response within its lifetime. A trait that improves performance in one test is not automatically an evolutionary adaptation. Link proposed adaptive function with heritable variation, relevant environmental pressures and fitness consequences, and report tradeoffs such as water conservation reducing carbon uptake.','植物实验须区分遗传差异、环境响应和测量假象。共同园让不同基因型同条件生长，交互移栽检验各自在对比环境的表现；母体效应、初始大小、土微生物和微气候仍可能混杂。随机位置并重复独立植株或样方，不能把同株许多叶都当独立个体。明确干重、叶面积、存活或碳同化等响应，因为它们可能不同。限制因子实验改变一资源，同时足够控制其他。施肥后平台可能因另一资源限制，也可能毒性或实验饱和。适应是经选择塑造的遗传特征，驯化响应是个体一生变化。一次测试提高表现不自动证明进化适应；需联系遗传变异、相关选择压力和适合度，并报告节水可能降低碳摄取等权衡。');

units('B04',['module.B02.05'],[
['进化机制','Selection|Drift|Gene flow','自然选择|遗传漂变|基因流','Evolution changes inherited population variation across generations. Selection reflects differential reproductive success, drift reflects random sampling, and gene flow transfers variants among populations. Mutation introduces new sequence variants.','进化改变种群跨世代遗传变异。选择源于繁殖成功差异，漂变源于随机抽样，基因流在种群间转移变异，突变引入新序列。','A population has 40 A copies among 100 total copies at a locus. Find A frequency.','某位点共 100 份等位基因，其中 A 为 40 份，A 频率是多少？',0.4,'pA = 40/100 = 0.4.','Evolution occurs in populations across generations.','进化发生于跨世代种群。','An individual evolves a needed inherited trait merely by trying harder.','个体只要努力就会进化出所需遗传性状。'],
['系统发育与比较证据','Common ancestry|Clades|Homology','共同祖先|单系群|同源性','A phylogeny is a hypothesis about ancestry. A clade contains an ancestor and all descendants. Shared derived traits support relationships, while convergence can make unrelated lineages resemble one another.','系统树是祖先关系假说，单系群含祖先及其全部后代。共有衍征支持关系，趋同可使不近缘谱系相似。','A rooted binary tree begins with one lineage and undergoes three splitting events with no extinction. How many terminal lineages result?','有根二叉树初始一谱系，发生三次分支且无灭绝，终端谱系有几个？',4,'Each split adds one terminal lineage: 1 + 3 = 4.','Rotating branches around a node does not change the represented relationships.','绕节点旋转分支不改变所表示亲缘关系。','Left-to-right tip order alone measures evolutionary relatedness.','末端左右顺序本身衡量亲缘远近。'],
['种群动态','Exponential growth|Density dependence|Demographic rates','指数增长|密度制约|种群统计率','Population size changes through births, deaths, immigration and emigration. Exponential growth assumes a constant per-capita rate; density-dependent models allow resource limits or interactions to change growth as population size changes.','种群大小由出生、死亡、迁入和迁出改变。指数增长假定人均增长率恒定，密度制约模型允许资源或作用随种群大小改变增长。','A population starts at 100, with 20 births, 5 deaths, 3 immigrants and 8 emigrants. Find final size.','初始 100，出生 20、死亡 5、迁入 3、迁出 8，末数量是多少？',110,'Nfinal = 100 + 20 − 5 + 3 − 8 = 110.','Carrying capacity can change with environmental conditions.','环境容纳量可随条件改变。','Carrying capacity is a permanent species-wide constant.','容纳量是一个物种永远固定的常数。'],
['群落与生态系统','Species interactions|Energy flow|Nutrient cycling','种间作用|能量流动|营养循环','Communities combine interacting populations; ecosystems include abiotic conditions and material flows. Energy enters, transfers and dissipates, while elements cycle through organisms and environmental reservoirs. Interaction effects depend on context.','群落由相互作用种群构成，生态系统还含非生物条件与物质流。能量输入、转移并耗散，元素在生物和环境库间循环，相互作用效应依情境。','A trophic transfer retains 10% of 500 energy units. How many units reach the next level in this model?','某营养级转移保留 500 能量单位的 10%，模型中下一级得到多少？',50,'Transferred energy = 0.10 × 500 = 50.','Energy transfer efficiency is variable; ten percent is an illustrative approximation.','能量传递效率可变，百分之十只是示例近似。','Every ecosystem recycles energy with no loss of usable energy.','所有生态系统都无可用能损失地循环能量。'],
['行为生态学','Proximate causes|Fitness consequences|Tradeoffs','近因|适合度后果|权衡','Behavior can be explained by immediate mechanisms and by evolutionary consequences. Costs and benefits depend on environment, relatives and competitors; an adaptive explanation requires evidence rather than a convenient story.','行为可用即时机制和进化后果解释。成本收益依环境、亲属和竞争者而变，适应解释需要证据而非方便故事。','An illustrative foraging choice gives 30 energy units but costs 12. Find net gain.','觅食获得 30 能量单位，成本 12，净收益是多少？',18,'Net gain = 30 − 12 = 18.','A behavior can involve tradeoffs rather than maximizing every benefit simultaneously.','行为可涉及权衡，而非同时最大化一切收益。','Every observed behavior is necessarily the optimal adaptation in all environments.','所有观察到的行为都在任何环境中最优适应。'],
['生物多样性与保护推理','Diversity measures|Habitat fragmentation|Evidence-based interventions','多样性指标|生境破碎化|证据支持干预','Biodiversity includes genetic, species and ecosystem variation. Conservation compares threats, ecological connections and intervention outcomes. Species counts alone omit abundance, distinctness and genetic diversity, so several measures may be needed.','生物多样性包括遗传、物种及生态系统差异。保护需比较威胁、生态连接与干预后果。单看物种数忽略丰度、独特性和遗传多样性，常需多指标。','A survey records 4, 3 and 3 individuals of three species. Find the relative abundance of the first species.','调查三种物种个体数为 4、3、3，第一种相对丰度是多少？',0.4,'p1 = 4/(4+3+3) = 0.4.','Conservation evidence should compare outcomes with appropriate baselines.','保护证据应以合适基线比较结果。','An increasing raw count always proves conservation success regardless of effort and detectability.','不论调查努力与可检出性，原始计数上升总证明保护成功。']]);
expand('B04.01','Evolution is a change in inherited characteristics or allele frequencies of populations across generations. Mutation generates new sequence variants without anticipating whether they will be useful. Recombination reshuffles existing variants, and gene flow introduces variants from other populations. Natural selection occurs when heritable differences affect survival or reproduction in a particular environment, causing some variants to contribute disproportionately to later generations. Fitness is relative reproductive contribution, not strength, moral worth or a universal ranking of organisms. Genetic drift changes frequencies through random sampling, especially strongly in small populations; founder events and bottlenecks can magnify its effects. Selection and drift operate together rather than being mutually exclusive explanations. A trait can become common through linkage with another selected variant, and a useful present-day feature need not have originated for its current role. Individuals develop, learn and acclimate during life, but those changes are not automatically inherited evolutionary changes. To test an evolutionary explanation, connect variation, inheritance and differential reproduction with evidence, while comparing alternatives such as environmental induction or historical constraint. Evolution has no predetermined goal of producing greater complexity or perfection.','进化是种群跨世代遗传特征或等位频率改变。突变不预知是否有用地生成变异，重组重排已有变异，基因流从其他种群带入变异。可遗传差异若影响特定环境下存活繁殖，某些变异对后代贡献增加，就发生自然选择。适合度是相对繁殖贡献，不是力量、道德价值或普遍排名。漂变通过随机抽样改变频率，小种群尤其强，奠基与瓶颈可放大。选择漂变共同作用，并非互斥。性状可因与受选择变异连锁而增多，目前有用特征也不一定为现用途起源。个体一生发育、学习、适应环境不自动等于可遗传进化。检验解释需把变异、遗传和繁殖差异连到证据，并比较环境诱导或历史限制。进化没有朝复杂或完美前进的预定目标。');
expand('B04.02','A phylogenetic tree represents branching relationships inferred from evidence, not a ladder from primitive to advanced organisms. A node usually represents a common ancestor, and sister groups share a more recent common ancestor with each other than with another sampled group. Rotating branches around a node changes the drawing but not its topology. A clade includes an ancestor and all of its descendants, whereas excluding some descendants creates a different grouping. Homologous features derive from common ancestry, while analogous similarities can evolve independently through convergence. Shared derived characters are especially informative for resolving relationships, but whether a character is ancestral or derived depends on the comparison and outgroup. Molecular sequences provide many characters, yet alignment errors, different evolutionary rates and gene duplication can complicate inference. A gene tree need not exactly match the species history because processes such as incomplete lineage sorting or horizontal transfer intervene. Branch lengths mean time or change only when the diagram explicitly defines that scale. Evaluate support and uncertainty for branching claims instead of treating one rendered tree as direct observation of the past.','系统树是由证据推断的分支关系，不是从原始到高级的阶梯。节点通常代表共同祖先，姐妹群彼此共享较近祖先；绕节点转枝只改图形不改拓扑。单系群包含祖先及全部后代，排除部分后代是不同分组。同源来自共同祖先，类似相似可由趋同独立产生。共有衍征尤其有信息，但祖征衍征依比较和外群而定。分子序列提供许多性状，然而比对错误、速率差和基因复制使推断复杂。不完全谱系排序或水平转移等可使基因树不同于物种史。只有图明示尺度时，枝长才代表时间或变化。应评估分支支持和不确定度，不能把渲染树当过去的直接观察。');
expand('B04.03','A population is a set of individuals of the same species defined within a relevant place and time. Its abundance changes through births and immigration minus deaths and emigration. Per-capita rates divide events by population size and distinguish a large total birth count from high reproductive output per individual. Exponential growth assumes a constant per-capita net rate and unrestricted conditions over the modeled interval. Logistic growth adds a density-dependent reduction, often summarized by a carrying-capacity parameter, but real resources and conditions can change that parameter. Age structure matters because juveniles, reproductive adults and older individuals contribute differently to future growth. Density dependence may arise from competition, infection or predation, while weather disturbances can affect populations without a simple density relation. Time delays can produce overshoot or oscillation rather than smooth approach to equilibrium. Population estimates also depend on sampling and detectability, so observed counts are not automatically true abundance. Compare model predictions with time-series data, distinguish process variation from observation error and avoid extrapolating a short exponential phase indefinitely. A useful model states its boundary, interval and mechanisms instead of treating every population as one universal growth curve.','种群是在相关时空内定义的同种个体集合，数量由出生迁入减死亡迁出改变。人均率把事件数除以种群大小，区分出生总数大与每个体繁殖高。指数增长假定所模拟区间人均净率恒定且限制忽略；逻辑斯蒂增长加入密度制约，常用容纳量概括，但真实资源条件可改变它。年龄结构影响未来增长，因为幼体、繁殖成体和老体贡献不同。竞争、感染、捕食可产生密度制约，天气扰动未必简单依密度。时间延迟可导致超调或振荡，而非平滑趋稳。估计还依取样与可检出性，观测数不自动等于真实丰度。应与时间数据比较，区分过程变异和观察误差，不可把短期指数无限外推。模型须说明边界、区间与机制，而非一条万能曲线。');
expand('B04.04','A community contains interacting populations, while an ecosystem includes their physical environment and exchanges of matter and energy. Competition occurs when organisms reduce one another’s access to a limiting resource; predation and herbivory transfer biomass through consumption; mutualisms can benefit both partners under particular conditions. The sign and strength of an interaction may change with context rather than being a permanent label. Food webs represent multiple feeding connections and are more realistic than a single straight chain. Primary producers capture energy, consumers obtain it through other organisms, and decomposers process dead material and wastes. Energy is transformed and dispersed as heat, so usable energy generally declines across trophic transfers; nutrients instead cycle among organic and inorganic reservoirs. Carbon, nitrogen and phosphorus cycles involve distinct chemical transformations and limiting steps. A keystone effect means a species has an influence disproportionate to its abundance, but it must be established experimentally or comparatively. Disturbance, succession and feedback alter community composition over time. Predict an intervention by considering indirect effects and resource changes, not simply removing one arrow from a static food-web picture.','群落含相互作用种群，生态系统还含物理环境及物质能量交换。竞争减少彼此对限制资源的获取，捕食和植食通过消费转移生物量，互利在特定条件下双方受益。作用正负强弱可随情境变化，不是永久标签。食物网含多条取食连接，比直链更真实。生产者捕获能量，消费者由他者获取，分解者处理遗体与废物。能量转换并以热分散，因此营养传递中的可用能通常下降；营养元素则在有机无机库间循环。碳氮磷循环有不同化学转化和限制步骤。关键种影响与其丰度不成比例，但需实验或比较证明。扰动、演替和反馈使群落随时间改变。预测干预须考虑间接效应和资源变化，不能只从静态食物网删一箭头。');
expand('B04.05','Behavioral ecology asks how behavior interacts with ecological conditions and evolutionary consequences. Proximate explanations concern immediate mechanisms such as sensory input, hormones, neural circuits and learning. Evolutionary explanations concern how a behavior’s consequences affect reproduction across generations; these levels can be complementary rather than competing. A foraging strategy may trade energy gain against predation risk, travel time or competition, so maximizing food intake alone is not always favored. Social behavior can affect both an individual’s direct reproduction and the reproduction of relatives, but relatedness is a population-genetic comparison rather than a feeling of familiarity. Signals can convey information, while their reliability depends on costs, constraints and shared interests. Sexual selection concerns differential mating or fertilization success and may oppose other survival advantages. An adaptive story must make testable predictions and consider alternatives such as developmental constraint, learning or incidental byproducts. Observing a behavior in one environment does not prove it is optimal everywhere. Compare individuals, environments or experimental manipulations while respecting ethical limits, and distinguish measured behavior from inferred motivation or subjective experience.','行为生态研究行为与环境及进化后果的关系。近因解释包括感觉、激素、神经与学习等即时机制，进化解释关注行为后果如何跨代影响繁殖，两层互补而非竞争。觅食可能在能量、捕食风险、旅行时间和竞争间权衡，因此不总最大化食物。社会行为可影响自身繁殖及亲属繁殖，亲缘度是群体遗传比较，不是熟悉感。信号传信息，其可靠性依成本、约束和利益一致。性选择关注交配受精差异，可能与存活优势冲突。适应故事须给可检验预测并考虑发育限制、学习或副产物。一个环境观察到行为不证明处处最优。应在伦理范围比较个体、环境或操纵，区分测得行为与推断动机、主观体验。');
expand('B04.06','Biodiversity has several dimensions: variation within species, differences among species and the diversity of ecological systems and functions. Species richness counts how many species occur, while evenness describes how abundance is distributed among them. Two sites can have equal richness but very different dominance patterns or evolutionary distinctness. Habitat loss reduces available area, and fragmentation can additionally isolate populations, increase edge effects and change movement among patches. Small isolated populations may lose genetic variation through drift and face demographic or environmental fluctuations. Conservation actions such as habitat protection, restoration, corridors or targeted management should be evaluated against explicit objectives and plausible unintended effects. An apparent increase in observed animals can reflect greater survey effort or improved detectability rather than real population growth. Before-and-after comparisons benefit from appropriate untreated references and sufficiently long monitoring. Prioritization involves ecological evidence and explicit social values, not a single universally correct biodiversity score. Avoid treating one charismatic species as a complete proxy for ecosystem health. A defensible recommendation states the threat mechanism, evidence for expected benefit, uncertainty and how outcomes will be measured and revised.','生物多样性有物种内变异、物种间差异及生态系统功能多样等维度。丰富度数物种，均匀度描述丰度分布；两地丰富度相同仍可优势度和进化独特性不同。生境损失减少面积，破碎化还隔离种群、增加边缘效应并改变迁移。小隔离种群可因漂变丢失遗传变异，并受人口或环境波动威胁。保护、恢复、廊道和定向管理应按明确目标及潜在副作用评估。观察动物变多可能只是调查努力或检出率提高。前后比较宜有未处理参照和足够长期监测。优先序涉及生态证据与明示社会价值，不是一种万能分数。不能把单一魅力物种当完整生态健康代理。合理建议应说明威胁机制、收益证据、不确定度及如何测量修正。');

units('B03',['module.B02.06','module.C09.01'],[
['DNA 结构与复制','Antiparallel strands|Semiconservative copying|Polymerase direction','反向平行链|半保留复制|聚合方向','DNA strands have complementary bases and opposite chemical directions. Replication uses each parental strand as a template, producing daughter duplexes with one old and one new strand. Polymerases extend a growing strand at its 3′ end.','DNA 双链碱基互补、化学方向相反。复制以各亲代链作模板，子双链各含一旧一新链。聚合酶在生长链 3′ 端延伸。','One double-stranded DNA molecule undergoes three ideal replication rounds. How many double-stranded molecules result?','一个 DNA 双链分子理想复制三轮，得到几个双链分子？',8,'N = 1 × 2³ = 8 molecules.','Both daughter DNA molecules retain parental template material after one round.','一轮复制后两个子 DNA 都保留亲代模板材料。','Replication puts both old strands together in one daughter molecule.','复制后两条旧链仍一起放在同一个子分子中。'],
['转录与 RNA 加工','RNA synthesis|Promoters|Splicing','RNA 合成|启动子|剪接','Transcription makes RNA from a DNA template. In eukaryotes many primary transcripts are capped, spliced and polyadenylated before translation or other functions. Alternative processing can produce different RNA products from one locus.','转录以 DNA 为模板合成 RNA。真核许多初级转录本经加帽、剪接和加尾后用于翻译或其他功能。可变加工可使同一位点产生不同 RNA。','A precursor RNA is 1000 nucleotides and removed introns total 300. Ignoring added ends, find mature length.','前体 RNA 长 1000 核苷酸，去除内含子共 300；忽略末端添加，成熟长度是多少？',700,'Length = 1000 − 300 = 700 nucleotides.','Not all transcribed RNAs encode proteins.','并非所有转录 RNA 都编码蛋白。','Every RNA molecule is translated into a protein.','每个 RNA 分子都会翻译成蛋白。'],
['翻译与遗传密码','Codons|tRNA|Ribosome','密码子|转运 RNA|核糖体','Ribosomes read mRNA in a defined frame, using tRNAs to connect codons with amino acids. Start and stop signals define an open reading frame. The genetic code is redundant but not arbitrary.','核糖体按确定阅读框读 mRNA，由 tRNA 联系密码子与氨基酸。起始和终止信号定义开放阅读框，遗传密码有简并但并非任意。','A coding segment contains 30 nucleotides for amino acids, excluding a stop codon. How many amino acids does it specify?','编码氨基酸的片段含 30 核苷酸，不含终止密码子，编码几个氨基酸？',10,'30 nucleotides / 3 per codon = 10 amino acids.','A stop codon signals termination rather than an ordinary amino acid.','终止密码子表示终止，而非普通氨基酸。','Every triplet in every reading frame is translated simultaneously.','所有阅读框中的每个三联体都同时被翻译。'],
['基因调控','Transcription factors|Chromatin|Post-transcriptional control','转录因子|染色质|转录后调控','Gene expression is controlled at transcription, RNA processing and stability, translation and protein turnover. Regulatory DNA and interacting factors determine context-dependent expression; chromatin accessibility affects which sites can be used.','基因表达可在转录、RNA 加工与稳定、翻译及蛋白周转层面调控。调控 DNA 与作用因子决定情境相关表达，染色质可及性影响位点能否使用。','A transcript synthesis rate doubles while its first-order decay constant is unchanged. By what factor does its ideal steady-state amount change?','转录本合成速率加倍，一级降解常数不变，理想稳态量变为几倍？',2,'At steady state RNA = synthesis/decay constant; factor = 2.','Different cell types can express different genes despite sharing most DNA sequence.','不同细胞类型虽共享大部分 DNA，仍可表达不同基因。','Every gene is expressed equally in every cell at all times.','每个基因在所有细胞和所有时间都等量表达。'],
['突变、修复与重组','Sequence change|Repair pathways|Homologous exchange','序列变化|修复途径|同源交换','Mutations alter sequence and may be neutral, harmful or beneficial depending on context. Repair pathways recognize particular damage patterns, while recombination can exchange homologous information or repair breaks. Neither process is perfectly error-free.','突变改变序列，效应可中性、有害或有利，依情境而定。修复识别特定损伤，重组可交换同源信息或修复断裂，两者并非绝对无误。','A coding sequence loses 3 consecutive nucleotides without disrupting splice sites. How many full codons are removed in the simplest in-frame case?','编码序列删除连续三个核苷酸，不影响剪接，最简单同框情形少几个密码子？',1,'3 nucleotides = 1 codon; frame is retained.','A mutation’s effect depends on location and biological context.','突变效应依位置与生物情境。','Every DNA change necessarily destroys gene function.','每次 DNA 改变都必破坏基因功能。'],
['分子方法与实验解释','PCR|Sequencing|Perturbation controls','聚合酶链式反应|测序|扰动对照','PCR amplifies a primer-defined DNA region, sequencing reads base information, and perturbations test functional hypotheses. Each method has distinct controls and detection limits; a molecular signal alone does not establish biological causation.','PCR 扩增引物限定 DNA，测序读取碱基信息，扰动检验功能假设。各方法具有不同对照与检出限，分子信号本身不证明生物因果。','Starting from 2 copies, ideal doubling for 4 PCR cycles gives how many copies?','初始两份，PCR 理想倍增四周期，得到几份？',32,'N = 2 × 2^4 = 32.','A negative PCR result can reflect failed amplification rather than absence of template.','PCR 阴性可由扩增失败造成，而非模板不存在。','Any visible PCR band proves the intended sequence without additional checks.','任何可见 PCR 条带都无需核查即可证明目标序列。']]);
expand('B03.01','DNA is a polymer of nucleotides linked through a sugar–phosphate backbone. Each strand has chemical polarity, conventionally described from 5′ to 3′, and complementary strands run antiparallel. Adenine pairs with thymine and guanine with cytosine in the common double-helical structure; stacking interactions and the surrounding solution also contribute to stability. Semiconservative replication separates parental strands and uses each as a template. DNA polymerases require a suitable primer end and add nucleotides to the 3′ hydroxyl, so synthesis proceeds 5′ to 3′. Because the templates are antiparallel, one new strand can be synthesized continuously near a moving fork while the other is made in short fragments that are later joined. Helicases separate strands, primases provide primers, and other proteins manage tension, stabilize exposed DNA and seal backbone interruptions. Proofreading and repair lower error rates but do not make copying infallible. Eukaryotic chromosomes use many replication origins, and chromosome ends require special handling. A diagram showing one fork is therefore a local model, not the entire replication program. Distinguish nucleotide count, strand count and double-stranded molecule count when interpreting replication experiments.','DNA 由核苷酸经糖磷酸骨架连接，每链有 5′ 到 3′ 化学方向，互补链反向平行。常见双螺旋中 A 配 T、G 配 C，碱基堆积与溶液环境也贡献稳定。半保留复制分开旧链，各自作模板。DNA 聚合酶需要合适引物端，在 3′ 羟基加核苷酸，因此合成方向为 5′→3′。模板反向使一条新链可随复制叉连续合成，另一条以短片段合成后连接。解旋酶分链，引物酶供引物，其他蛋白处理张力、稳定单链及封闭骨架缺口。校对修复降低错误但并非绝对无误。真核染色体有多个起点，末端需特殊处理，一张复制叉图只是局部模型。解释实验时应区分核苷酸数、链数和双链分子数。');
expand('B03.02','Transcription transfers sequence information from a DNA template into an RNA strand. RNA polymerase selects complementary ribonucleotides and synthesizes RNA in the 5′ to 3′ direction while reading the template in the opposite direction. The RNA resembles the coding DNA strand except that uracil replaces thymine, but which strand is coding depends on the gene’s orientation. Promoter sequences and associated proteins help determine where transcription begins and how often it occurs. In many eukaryotic protein-coding genes, the initial transcript contains exons interrupted by introns. Splicing removes introns and joins selected exons, while a 5′ cap and a processed 3′ end contribute to stability, export and translation. Alternative splicing can generate several RNA forms from the same locus, but not every possible splice pattern is functional. Many RNAs instead function directly, including ribosomal, transfer and regulatory RNAs. RNA abundance depends on both synthesis and degradation, so more transcript can reflect slower decay rather than increased transcription. Distinguish the DNA template, primary RNA, mature RNA and final protein when following an experiment through the expression pathway.','转录把 DNA 模板信息转为 RNA。RNA 聚合酶选互补核糖核苷酸，按 5′→3′ 合成、反向读模板。RNA 与编码链相似但 U 代 T，哪链编码取决于基因朝向。启动子及相关蛋白影响起始位置与频率。许多真核蛋白编码基因的初转录本含外显子和内含子，剪接去内含子并连接所选外显子，5′ 帽和加工 3′ 端影响稳定、输出及翻译。可变剪接使同位点产生多种 RNA，但不是每种可能拼法都有功能。许多 RNA 直接工作，如核糖体、转运及调控 RNA。RNA 丰度同时取决于合成和降解，增多可能是衰减变慢而非转录增强。追踪表达实验时，应区分模板 DNA、初级 RNA、成熟 RNA 和最终蛋白。');
expand('B03.03','Translation decodes an mRNA sequence into a polypeptide using an existing molecular apparatus. A codon is a three-nucleotide unit read in a particular frame, so choosing the start site determines how later triplets are grouped. Transfer RNAs carry amino acids and pair their anticodons with suitable codons. Aminoacyl-tRNA synthetases attach the appropriate amino acid to each tRNA type, providing an essential layer of accuracy before the ribosome reads the message. The ribosome coordinates initiation, elongation and termination; peptide-bond formation extends the chain from its amino end toward its carboxyl end. Stop codons recruit termination machinery rather than a conventional aminoacyl-tRNA. The code is degenerate because several codons can specify one amino acid, but a given codon generally has a defined meaning within the organism’s translation system. Mitochondria and some organisms use variant code assignments, so the familiar table is widespread rather than exceptionless. A frameshift can alter every downstream codon until a new stop appears, whereas a multiple-of-three insertion may preserve the frame. After translation, folding, targeting and chemical modification further determine the protein’s mature function.','翻译用已有分子机器把 mRNA 解码成多肽。密码子是在特定框中读取的三个核苷酸，起始位点决定后续分组。tRNA 携氨基酸，以反密码子配密码子；氨酰 tRNA 合成酶先给各 tRNA 装正确氨基酸，提供关键准确性层。核糖体协调起始、延伸、终止，肽链由氨端向羧端延长。终止密码子招募终止机器，而非普通氨酰 tRNA。多种密码子可指同氨基酸，称简并，但在给定翻译系统内某密码子通常意义明确。线粒体和部分生物用变异密码表，因此常用表广泛而非无例外。移码可改所有下游密码直至新终止，三的倍数插入则可能保持阅读框。翻译后折叠、定位及化学修饰继续决定成熟蛋白功能。');
expand('B03.04','Gene regulation determines when, where and how much a genetic product is made. At transcriptional initiation, DNA-binding proteins and other factors influence polymerase recruitment or activity. Regulatory sites can integrate several inputs, so a gene may respond only when a particular combination of signals is present. In eukaryotes, DNA packaging into chromatin affects accessibility, and modifications to chromatin-associated proteins can help maintain or change expression states. Regulation also acts after transcription through splicing, RNA localization, RNA degradation, translation efficiency and protein degradation. A promoter reporter measures the behavior of the tested construct and may omit distant regulatory elements or native chromatin context. RNA amount does not automatically equal protein amount because translation and turnover intervene. Some regulatory changes are rapid and reversible, while developmental programs can stabilize long-lived cell identities. Feedback loops connect gene products back to their own regulators and can create thresholds, adaptation or persistent states. Avoid the claim that a single gene is simply on or off in all cells: expression often varies continuously and heterogeneously. A convincing regulatory model links a defined perturbation to timing, molecular intermediates and a functional response with appropriate controls.','基因调控决定产物何时、何地和多少生成。转录起始时，DNA 结合蛋白等影响聚合酶招募或活性，调控位点可整合多输入，使基因只对特定信号组合响应。真核染色质包装影响可及性，相关蛋白修饰帮助维持或改变表达状态。转录后还可调剪接、RNA 定位降解、翻译效率及蛋白降解。启动子报告测的是该构建体行为，可能缺远端元件或天然染色质背景。RNA 量不自动等于蛋白量，因为中间有翻译和周转。有些调控迅速可逆，发育程序则可稳定长期细胞身份。反馈把产物连回其调节者，可形成阈值、适应和持续状态。不能把单基因说成所有细胞中简单开关，表达常连续且异质。可信模型需用对照连接扰动、时间、分子中间环节和功能响应。');
expand('B03.05','DNA damage and mutation are related but distinct. Damage is a chemical or structural lesion, while a mutation is a heritable sequence change that remains after copying or repair. Substitutions, insertions and deletions can affect coding sequence, regulatory regions or apparently noncoding regions with important functions. A synonymous coding substitution preserves the encoded amino acid in the simple code interpretation but can still influence splicing, RNA structure or translation. A missense change alters an amino acid, and a nonsense change introduces a premature stop; their consequences depend on position and protein context. Repair pathways recognize different lesions, such as mismatches or damaged bases, and use templates or local chemistry to restore information. Homologous recombination can repair breaks using related sequence information and also generates meiotic variation. Nonhomologous repair can join ends with different error patterns. Mutation does not occur because an organism knows which change it needs; selection subsequently changes the frequencies of variants according to their consequences in an environment. Distinguish mutation rate, observed variant frequency and fitness effect, because each describes a different stage of the evolutionary and molecular process.','DNA 损伤与突变相关但不同：损伤是化学结构病变，突变是复制或修复后保留下的可遗传序列改变。替换、插入和缺失可影响编码、调控或有功能的非编码区。同义编码替换在简单密码解释下不改氨基酸，但仍可能影响剪接、RNA 结构或翻译；错义改氨基酸，无义产生提前终止，后果依位置和蛋白情境。修复路径识别错配、损坏碱基等不同病变，用模板或局部化学恢复信息。同源重组可用相关序列修断裂，也产生减数变异；非同源连接的错误模式不同。突变不是生物知道需要什么才发生，随后选择按环境中的后果改变变异频率。应区分突变率、观测变异频率与适合度效应，三者属于分子与进化过程不同环节。');
expand('B03.06','Molecular methods answer different questions and require controls tailored to their failure modes. PCR amplifies DNA between compatible primer sites through repeated copying cycles, but efficiency is not perfectly constant indefinitely and contamination can also be amplified. A no-template control checks contamination, while an appropriate positive control checks whether amplification conditions can work. Reverse-transcription assays add a conversion from RNA to DNA and need controls for residual genomic DNA. Sequencing provides base calls with quality limits; an apparent variant can arise from sampling, mapping or read errors unless supported appropriately. Protein detection depends on reagent specificity, so a band at an expected size is suggestive rather than automatically definitive. Gene disruption or knockdown can test function, but off-target changes and compensatory responses complicate interpretation. A rescue with a suitably controlled restored gene strengthens a causal argument. Quantitative comparisons need normalization justified by stable reference behavior, not an arbitrary convenient denominator. Combine molecular identity, abundance, localization and perturbation evidence, and keep the conclusion no broader than the method’s validated sensitivity and specificity. A negative result should be interpreted alongside controls before being called absence.','分子方法回答不同问题，需匹配失误模式的对照。PCR 在相容引物位点间反复复制，但效率不会无限恒定，污染也会扩增；无模板对照查污染，阳性对照查条件能否工作。逆转录多了 RNA 到 DNA 转换，需控制残留基因组 DNA。测序碱基判读有质量限制，表观变异可能来自抽样、比对或读错。蛋白检测依赖试剂特异性，预期大小一条带只是提示，不自动确证。敲除或敲低可检验功能，但脱靶和补偿响应干扰解释；受控恢复基因的挽救能加强因果。定量比较应以稳定参照行为支持归一化，而非随意选分母。应综合身份、丰度、定位和扰动，结论不超出验证灵敏度与特异性；阴性必须结合对照再解释为缺失。');

units('B02',['module.B01.05','math.probability'],[
['孟德尔遗传','Alleles|Segregation|Genotype and phenotype','等位基因|分离|基因型与表型','Alleles are alternative versions at a locus. Diploid individuals carry two copies, which segregate into gametes during meiosis. Dominance describes a heterozygote’s phenotype under specified conditions, not an allele’s frequency or superiority.','等位基因是同一位点的不同版本。二倍体携带两份，减数分裂时分离到配子。显隐性描述指定条件下杂合子的表型，不代表频率或优劣。','For Aa × Aa with equal segregation, find probability of aa.','Aa × Aa 且等概率分离，aa 概率是多少？',0.25,'P(aa) = P(a from each parent) = 1/2 × 1/2 = 1/4.','A dominant allele can be rare in a population.','显性等位基因在种群中仍可罕见。','Dominant means the allele must be most common.','显性意味着该等位基因必最常见。'],
['概率桥梁与系谱推理','Conditional probability|Pedigrees|Penetrance','条件概率|系谱|外显率','Pedigrees constrain inheritance models through related individuals. Use conditional probabilities when observed phenotype excludes genotypes. Incomplete penetrance, new mutation and small family size can make a simple inheritance pattern ambiguous.','系谱通过亲属限制遗传模型。观察表型排除基因型后应使用条件概率。不完全外显、新突变和小家庭可使简单遗传模式难以唯一判断。','Among unaffected offspring of Aa × Aa for a fully penetrant recessive trait, find carrier probability.','完全外显隐性性状中，Aa × Aa 的未患后代为携带者概率是多少？',2/3,'Unaffected genotypes: AA, Aa, aA; 2 of 3 are carriers.','Conditioning on an observed phenotype changes the relevant sample space.','以观察表型为条件会改变样本空间。','Carrier probability remains one half regardless of pedigree evidence.','无论系谱证据如何，携带者概率总为二分之一。'],
['连锁、重组与遗传图谱','Linked loci|Crossing over|Map distance','连锁位点|交换|遗传图距','Nearby loci on one chromosome often travel together. Crossing over can create recombinant gametes. For short intervals recombination percentage approximates map distance, while multiple crossovers can hide the true number of exchanges.','同染色体相近位点常共同传递，交换可产生重组配子。短区间重组百分比近似图距，多次交换可能隐藏实际交换数。','There are 20 recombinant offspring among 200 informative offspring. Find recombination percentage.','200 个信息性后代中有 20 个重组型，重组率百分之几？',10,'r = 20/200 × 100% = 10%.','Observed recombination fraction does not exceed one half in the simple two-locus linkage model.','简单两位点模型中，观测重组率不超过二分之一。','A recombination fraction of one half proves the loci lie on different chromosomes.','重组率二分之一证明位点必在不同染色体。'],
['染色体变异','Aneuploidy|Structural rearrangement|Dosage','非整倍性|结构重排|剂量','Nondisjunction can alter chromosome number. Deletions, duplications, inversions and translocations alter structure, potentially changing dosage, gene disruption or meiotic pairing. A rearrangement can be balanced in amount yet still affect function.','不分离可改变染色体数。缺失、重复、倒位与易位改变结构，影响剂量、基因完整或减数配对。重排即使总量平衡，也可能影响功能。','A normally diploid cell has 2n = 10. How many chromosomes does a trisomic cell contain?','正常二倍体 2n = 10，某染色体三体细胞有几条染色体？',11,'Trisomy adds one chromosome: 2n + 1 = 11.','A balanced rearrangement can still disrupt a gene at a breakpoint.','平衡重排仍可在断点破坏基因。','Balanced chromosome rearrangements are always biologically irrelevant.','平衡染色体重排总无生物影响。'],
['数量与群体遗传','Polygenic traits|Allele frequencies|Hardy–Weinberg model','多基因性状|等位基因频率|哈代—温伯格模型','Many traits reflect multiple loci and environment. Population genetics tracks allele frequencies; under random mating and ideal assumptions, two-allele genotype frequencies are p², 2pq and q². This is a testable reference model.','许多性状由多位点和环境共同影响。群体遗传追踪等位基因频率；随机交配及理想假设下，两等位基因型频率为 p²、2pq、q²，这是可检验参照模型。','If p = 0.7 and q = 0.3, find expected heterozygote frequency.','p = 0.7、q = 0.3，预期杂合子频率是多少？',0.42,'2pq = 2 × 0.7 × 0.3 = 0.42.','Heritability describes variation in a population under specified conditions.','遗传力描述指定条件下种群中的变异。','A heritability value gives the genetically determined fraction of one person’s trait.','遗传力给出一个人性状由基因决定的百分比。'],
['遗传实验与推断','Cross design|Complementation|Causal interpretation','杂交设计|互补检验|因果解释','Genetic experiments compare controlled crosses or perturbations with explicit predictions. Complementation can test whether recessive defects affect different functional units, but dominance, dosage and complex interactions can complicate interpretation.','遗传实验用明确预测比较受控杂交或扰动。互补检验可判断隐性缺陷是否影响不同功能单位，但显性、剂量与复杂相互作用会干扰解释。','A predicted 3:1 phenotype ratio is tested in 80 offspring. Find expected count in the smaller class.','80 个后代检验 3:1 表型比，较小类预期多少个？',20,'Expected smaller class = 80 × 1/4 = 20.','Observed counts fluctuate around probabilistic predictions.','观测数会围绕概率预测波动。','A Mendelian ratio must appear exactly in every finite family.','每个有限家庭都必须精确呈孟德尔比例。']]);
expand('B02.01','A gene is a functional genetic unit, while a locus identifies a genomic position and an allele is a version at that locus. In a diploid organism, homologous chromosomes usually provide two copies of each autosomal locus. Meiosis separates homologues and then sister chromatids, producing gametes with one copy per locus in the simple model. Fertilization combines two gametes and restores the diploid state. Genotype describes the allele combination; phenotype is an observed characteristic influenced by genotype and conditions. Complete dominance means a heterozygote resembles one homozygote for the specified phenotype. In incomplete dominance it is intermediate, and in codominance both allele-associated features can be detected. These terms do not rank evolutionary fitness or population frequency. A Punnett square enumerates possible gamete combinations and their probabilities; it does not guarantee exact counts in a small family. Independent assortment applies to suitably unlinked loci, whereas linked loci can violate the simple product-ratio prediction. Always state the inheritance assumptions, including equal segregation, viability and penetrance, before translating a cross into a predicted phenotypic ratio.','基因是功能遗传单位，位点指基因组位置，等位基因是该位点版本。二倍体同源染色体通常给常染色体位点两份。减数分裂先分同源染色体再分姐妹单体，简单模型下每配子每位点一份；受精合并配子恢复二倍体。基因型是等位组合，表型是受基因型及条件影响的观察特征。完全显性指杂合子在指定表型上像某纯合子；不完全显性居中，共显性可检测两种等位相关特征。这些术语不排名适合度或频率。棋盘列配子组合与概率，不保证小家庭精确计数。独立分配适用于合适非连锁位点，连锁可违反简单乘积比例。预测表型比前须明确等分离、存活与外显等假设。');
expand('B02.02','A pedigree records relationships and observed traits, allowing candidate inheritance models to make different predictions. Begin by identifying affected and unaffected individuals, sexes, mating relationships and generation structure without assuming a model from one striking pair. Autosomal dominant, autosomal recessive and sex-linked models imply different possible genotypes, but small pedigrees often fit more than one explanation. An unaffected child of two heterozygous parents for a fully penetrant recessive trait is not sampled from all four Punnett outcomes; the affected outcome has been excluded, leaving three equally weighted possibilities, two of which are carriers. This is conditional probability. Penetrance is the probability that a genotype produces the defined phenotype under specified conditions; expressivity concerns the degree or form of that phenotype. Incomplete penetrance, age of onset, new mutations and environmental effects can obscure simple patterns. Related events are not automatically independent, so use shared parental genotype uncertainty consistently. A pedigree supports probabilities and model comparisons rather than certainty about every unobserved genotype. Distinguish educational inheritance calculations from clinical diagnosis, which requires additional evidence and professional interpretation.','系谱记录亲缘与表型，使候选遗传模型产生不同预测。先识别患与未患、性别、配偶及世代，不要凭显眼的一对就定模型。常显、常隐、性连锁允许不同基因型，但小系谱常兼容多个解释。完全外显隐性性状中，两杂合亲本的未患孩子不再从四种结果取样，因为患病结果已排除；剩三种等权可能，两种为携带者，这是条件概率。外显率是指定条件下某基因型产生定义表型的概率，表现度则指程度或形式。不完全外显、起病年龄、新突变及环境会遮蔽简单模式。亲属事件不自动独立，应一致处理共同亲本基因型的不确定性。系谱支持概率和模型比较，而非所有未测基因型的确定结论。教学计算也不同于需更多证据的临床诊断。');
expand('B02.03','Genes on the same chromosome are physically linked, but crossing over during meiosis can exchange segments between homologues. A heterozygote’s phase specifies which alleles share a chromosome, such as AB/ab versus Ab/aB, and changes which offspring classes count as parental or recombinant. A testcross can reveal gamete types when the other parent contributes a known recessive combination. Recombination fraction is recombinant offspring divided by informative total, subject to assumptions about viability and scoring. For short intervals, one percent recombination corresponds approximately to one centimorgan. Over longer intervals, multiple crossovers can restore the original endpoint combination, making observed recombination underestimate the number of exchanges. The two-locus fraction approaches one half, so a value near one half can describe unlinked loci or widely separated loci on one chromosome. Three-point crosses add information about gene order and double crossovers. Genetic distance measures recombination behavior and is not a fixed conversion to physical base-pair distance because recombination rates vary along chromosomes and across biological contexts. Count classes carefully and state the mapping model rather than treating percentages as a literal ruler.','同染色体基因物理连锁，但减数交换可在同源间交换片段。杂合体相位说明哪些等位在同一染色体，如 AB/ab 与 Ab/aB，决定哪些后代算亲本型或重组型。测交另一亲本提供已知隐性组合，可显露配子类型。重组率是重组后代除以信息性总数，需假定存活和判分无偏。短区间百分之一重组近似一厘摩，长区间多次交换可恢复端点组合，使观测低估交换次数。两位点率趋近二分之一，因此近二分之一既可不连锁，也可同染色体相距很远。三点测交增加基因顺序与双交换信息。遗传距离描述重组行为，因位置和生物背景不同，不能固定换算碱基对。应仔细计类并说明模型，不能把百分比当实体尺。');
expand('B02.04','Chromosomal variation changes the number or arrangement of large DNA segments. Aneuploidy adds or removes particular chromosomes, whereas polyploidy changes whole chromosome sets. Nondisjunction during a division can produce cells or gametes with unequal chromosome numbers; the consequences depend on which division and chromosome are involved. Structural variants include deletions, duplications, inversions and translocations. A deletion can remove genes, a duplication can alter dosage, and a breakpoint can interrupt a gene or separate it from regulatory sequences. An inversion preserves total DNA amount in its simplest form but can affect pairing and recombination. A balanced translocation may preserve material overall while creating reproductive risks or disrupting function at breakpoints. Mosaicism means different cells in one organism carry different genetic states, often because a change occurred after fertilization. Detecting a variant requires a method suited to its scale: a conventional chromosome image does not reveal every small sequence change. Phenotypic effects depend on dosage sensitivity, genomic location, cell distribution and environment, so neither “balanced” nor “large” alone determines the biological outcome.','染色体变异改变大片 DNA 数量或排列。非整倍性增减特定染色体，多倍性改变整套染色体。某次分裂不分离可使细胞或配子染色体数不等，后果依发生阶段和染色体。结构变异含缺失、重复、倒位和易位：缺失移去基因，重复改剂量，断点可打断基因或使其脱离调控。简单倒位总 DNA 量不变，却可影响配对与重组；平衡易位可总量守恒而仍带来繁殖风险或断点功能破坏。嵌合指个体不同细胞具有不同遗传状态，常来自受精后变化。检测方法须匹配尺度，普通染色体图不能发现所有小序列改变。表型依剂量敏感性、位置、细胞分布和环境，不能单凭“平衡”或“很大”判断后果。');
expand('B02.05','Many traits vary continuously because multiple genetic effects combine with environmental influences and measurement variation. A quantitative trait can still have particular large-effect loci, but its distribution is not necessarily explained by one dominant–recessive pair. Population genetics shifts attention from a single family to allele and genotype frequencies. Count alleles carefully: each diploid homozygote contributes two copies of one allele and each heterozygote contributes one of each. Under the Hardy–Weinberg reference conditions, random union of gametes produces genotype frequencies p², 2pq and q² for two alleles whose frequencies sum to one. The model assumes an appropriate mating structure and excludes evolutionary changes such as selection, migration, mutation and drift in its idealized long-term form. Deviations can suggest violated assumptions but do not identify one unique cause. Heritability partitions observed variation statistically within a specified population and environment. It is not the fraction of one individual caused by genes, nor does a high value mean that environmental intervention is ineffective. Gene–environment interaction means the effect of a genotype can change across environments, further limiting simplistic genetic determinism.','许多性状连续变化，因多基因效应叠加环境与测量变异；数量性状仍可能有大效应位点，但不一定由一对显隐基因解释。群体遗传关注等位和基因型频率。二倍体纯合贡献某等位两份，杂合各一份。哈代—温伯格参照中，两等位频率 p、q 和为一，随机配子结合给 p²、2pq、q²。模型要求合适交配结构，理想长期形式排除选择、迁移、突变和漂变等变化。偏离提示假设可能失效，却不能唯一识别原因。遗传力在指定种群环境内统计分解变异，不是一个人由基因造成的比例，高值也不表示环境干预无效。基因—环境互作意味着同一基因型效应随环境改变，进一步限制简单遗传决定论。');
expand('B02.06','A genetic experiment becomes informative when competing explanations predict different outcomes. Choose a cross, perturbation or rescue that distinguishes those explanations rather than merely reproducing the original phenotype. A testcross can expose gamete types, while reciprocal crosses can reveal maternal, cytoplasmic or sex-linked effects under suitable designs. Complementation tests bring two recessive mutations together; restoration of function often suggests defects in different genes, but intragenic complementation, dominant effects and dosage interactions create exceptions. A rescue experiment asks whether restoring a normal component reverses a defect, strengthening causal interpretation when appropriate controls exclude nonspecific effects. Expected Mendelian ratios are probabilities, so finite samples fluctuate; compare observed counts with an appropriate sampling model instead of declaring every deviation a new mechanism. Environmental conditions, genetic background and viability can alter the observed classes. Distinguish correlation with a marker from proof that the marker itself causes the phenotype. Strong conclusions combine inheritance, molecular identity, perturbation and rescue evidence. Report which hypotheses the experiment excludes and which remain compatible, because one successful cross rarely proves an entire causal pathway on its own.','遗传实验在竞争解释预测不同结果时最有信息。应选能区分解释的杂交、扰动或挽救，而非仅重复原表型。测交显示配子类型，正反交在合适设计下可揭示母体、胞质或性连锁效应。互补把两个隐性突变放一起，功能恢复常提示不同基因缺陷，但基因内互补、显性及剂量作用有例外。挽救检验恢复正常组分是否逆转缺陷，适当对照排除非特异效应后加强因果。孟德尔比是概率，有限样本有波动，应比较采样模型而非每次偏离都宣称新机制。环境、遗传背景与存活可改变观察分类。须区分与标记相关和标记本身致因，强结论结合遗传、分子身份、扰动和挽救证据。说明排除与仍相容假设，一次成功杂交通常不能证明整条因果路径。');

units('B01',['biology.life','chemistry.bonding'],[
['细胞学说与生物组织','Cell theory|Prokaryotes and eukaryotes|Scale','细胞学说|原核与真核|尺度','Cells are fundamental units of organisms and arise from pre-existing cells. Prokaryotic cells lack a membrane-bounded nucleus; eukaryotic cells organize genetic material and many reactions into membrane-bounded compartments.','细胞是生物基本单位，来自已有细胞。原核细胞没有膜包围的细胞核，真核细胞将遗传物质及许多反应组织到膜区室。','A cell measures 0.02 mm. Express its length in micrometres.','细胞长 0.02 mm，换算为微米是多少？',20,'0.02 mm × 1000 μm/mm = 20 μm.','Organism-level functions can emerge from interactions among specialized cells.','个体功能可由特化细胞相互作用产生。','Every living cell has a membrane-bounded nucleus.','所有活细胞都有膜包围细胞核。'],
['膜与物质运输','Selective permeability|Osmosis|Active transport','选择透过性|渗透|主动运输','A lipid bilayer separates aqueous regions while proteins mediate selective exchange. Passive transport follows an electrochemical driving force; active transport couples movement to an energy source. Osmosis is water movement across a selectively permeable boundary.','脂双层分开水环境，蛋白介导选择性交换。被动运输顺电化学驱动力，主动运输将移动与能量来源耦合。渗透是水跨选择透过边界的移动。','A transporter moves 3 ions per cycle and completes 4 cycles. How many ions are transported?','转运蛋白每周期搬三个离子，完成四周期，共搬几个离子？',12,'3 ions/cycle × 4 cycles = 12 ions.','Water movement depends on solute permeability as well as concentrations.','水移动不仅依赖浓度，还依赖溶质透过性。','Every solute crosses a lipid bilayer equally easily.','所有溶质都同样容易穿过脂双层。'],
['细胞器与区室','Nucleus|Endomembrane traffic|Energy organelles','细胞核|内膜运输|能量细胞器','Compartments separate reactions and maintain different environments. The nucleus houses most eukaryotic DNA, the endomembrane system processes and sorts many proteins, and mitochondria or chloroplasts carry out specialized energy conversions.','区室分离反应并维持不同环境。细胞核容纳大部分真核 DNA，内膜系统加工分选许多蛋白，线粒体或叶绿体执行特定能量转换。','A vesicle transfers 5 cargo molecules per trip. How many molecules transfer in 6 trips?','囊泡每次运输五个货物分子，六次共运输多少个？',30,'5 × 6 = 30 molecules.','Protein targeting signals influence destination.','蛋白定位信号影响去向。','Every newly synthesized protein is sent to the nucleus.','所有新合成蛋白都被送进细胞核。'],
['酶与细胞能量','Catalysis|ATP coupling|Redox carriers','催化|ATP 耦合|氧化还原载体','Enzymes make reactions kinetically accessible while cells couple free-energy transfers through ATP, reducing cofactors and ion gradients. Energy conversion conserves total energy but dissipates part of its capacity to do useful work.','酶使反应动力学上可及，细胞通过 ATP、还原辅因子和离子梯度耦合自由能转移。能量转换保持总能守恒，却耗散部分做有用功的能力。','A coupled process has energy changes +7 and −12 units. Find the sum.','耦合过程能变分别为 +7 与 −12 单位，总和是多少？',-5,'ΔGtotal = 7 − 12 = −5.','Enzymes do not change the overall equilibrium of a reaction.','酶不改变反应总平衡。','Enzymes create energy from nothing.','酶能凭空创造能量。'],
['细胞周期与分裂','DNA replication|Mitosis|Cell-cycle control','DNA 复制|有丝分裂|细胞周期控制','The cell cycle coordinates growth, DNA replication and division. Mitosis separates replicated sister chromatids, while cytokinesis divides the cell. Checkpoints and regulatory proteins help prevent division with incomplete or damaged genetic material.','细胞周期协调生长、DNA 复制与分裂。有丝分裂分离复制后的姐妹染色单体，胞质分裂分开细胞。检查点与调控蛋白帮助防止未完成或受损遗传物质进入分裂。','A cell has 4 chromosomes before DNA replication. Immediately after replication, how many sister chromatids are present?','细胞复制前有四条染色体，复制完成后共有几条姐妹染色单体？',8,'4 replicated chromosomes × 2 sister chromatids = 8.','DNA amount doubles before mitosis without immediately doubling chromosome count by centromeres.','有丝分裂前 DNA 量加倍，但按着丝粒计数的染色体数不立即加倍。','DNA replication and cell division are the same event.','DNA 复制与细胞分裂是同一事件。'],
['信号、显微与证据','Receptors|Signal transduction|Imaging limits','受体|信号转导|成像限制','Cells detect selected signals through receptors and convert them into intracellular responses. Microscopy reveals structures only within its resolution and labeling limits; observing colocalization alone does not establish a direct molecular interaction.','细胞通过受体检测特定信号并转为胞内响应。显微镜只能在分辨率和标记限制内揭示结构，共定位本身不能证明直接分子相互作用。','A 5 μm structure appears 500 μm long in an image. Find linear magnification.','5 μm 结构在图上长 500 μm，线性放大倍数是多少？',100,'Magnification = image length/actual length = 500/5 = 100.','Magnification and resolution are different properties.','放大倍数与分辨率是不同性质。','Increasing image size always reveals new molecular detail.','把图放大总能揭示新分子细节。']]);
expand('B01.01','Cell theory connects observations from many organisms: living organisms consist of cells, the cell is a basic organizational unit, and new cells arise from existing cells. This does not imply that every biological entity, such as a virus, is itself a cell. All cells have a boundary membrane, an internal aqueous environment, genetic information and machinery for using that information, though specialized mature cells can lose some components. Prokaryotic cells include bacteria and archaea and lack a membrane-bounded nucleus. Eukaryotic cells contain a nucleus and other membrane-bounded compartments, although their sizes and structures vary widely. A tissue is an organized collection of interacting cells, organs combine tissues, and organ systems coordinate functions. These levels are related but not interchangeable explanations. Small cells have relatively more surface area per volume, which affects exchange with the environment. A large organism therefore commonly consists of many cells rather than one proportionally enlarged cell. Microscopes and stains reveal only selected features, so drawings are simplified models. Learn to connect each structure with a function and the evidence supporting it rather than treating a labeled diagram as a complete inventory of every cell.','细胞学说综合多种生物观察：生物由细胞构成，细胞是基本组织单位，新细胞来自已有细胞；这不意味着病毒等每种生物实体本身都是细胞。细胞具有膜边界、内部水环境、遗传信息及利用信息的机器，但特化成熟细胞可失去部分成分。细菌和古菌属于原核细胞，没有膜包围细胞核。真核有细胞核及其他膜区室，大小结构仍广泛变化。组织是相互作用的细胞集合，器官组合组织，系统协调功能；这些解释层次相关却不能互换。小细胞表面积相对体积更大，影响环境交换，因此大型个体通常由更多细胞组成，而非一个同比放大细胞。显微与染色仅显示部分特征，课图是简化模型。应把结构、功能和证据联系起来，而非把标注图当每种细胞的完整库存。');
expand('B01.02','The membrane’s amphipathic lipids arrange with hydrophilic regions facing water and hydrophobic regions inward. Small nonpolar molecules can cross the lipid region more readily than ions or many polar solutes. Channels provide selective pathways, while carriers bind and change conformation; their transport can saturate when binding sites are occupied. Diffusion produces net movement down a chemical-potential gradient even though individual molecules move in both directions. For ions, electrical and concentration effects combine into an electrochemical gradient. Primary active transport directly couples to an energy-releasing process such as ATP hydrolysis, while secondary active transport uses a gradient established elsewhere. Osmosis concerns water movement driven by water’s chemical potential across a boundary with unequal permeabilities. Tonicity predicts sustained cell-volume effects and depends on effectively nonpenetrating solutes, so it is not identical to total osmolarity in every case. Animal cells may swell or shrink when external conditions change; cell walls alter the mechanical outcome in plants. Predict transport by identifying the species, permeability, both sides’ conditions and the available energy coupling, not by assuming all movement follows one concentration arrow.','膜脂两亲性使亲水区朝水、疏水区向内。小非极性分子比离子和许多极性溶质更易穿脂区。通道提供选择通路，载体结合并变构，位点占满时可饱和。扩散虽每个分子双向运动，却沿化学势梯度产生净流；离子还需合并电势形成电化学梯度。初级主动运输直接耦合 ATP 水解等放能过程，次级主动运输利用其他过程建立的梯度。渗透是不同透过边界两侧水化学势驱动的移动。张性预测持续体积影响，依赖有效不透过溶质，并非所有情形下等同总渗透浓度。动物细胞可涨缩，植物细胞壁改变力学结局。预测应明确物种、透过性、两侧条件及能量耦合，不能把一切归为一个浓度箭头。');
expand('B01.03','Compartmentation allows a cell to maintain chemically different spaces while controlling traffic between them. The nuclear envelope separates most eukaryotic DNA from the cytoplasm, and nuclear pores regulate exchange of selected molecules. Ribosomes translate RNA into proteins; free and membrane-associated ribosomes use the same basic machinery, but targeting signals direct some growing proteins to the endoplasmic reticulum. The ER participates in protein processing and lipid synthesis, while the Golgi modifies and sorts cargo for different destinations. Vesicles carry selected cargo rather than randomly blending all compartments. Lysosomes or related degradative compartments maintain conditions suited to breaking down material, and peroxisomes perform particular oxidative reactions. Mitochondria convert energy through respiratory processes, while chloroplasts in photosynthetic eukaryotes capture light energy; both retain distinctive membranes and genetic systems consistent with endosymbiotic origins. The cytoskeleton organizes shape, movement and intracellular transport. These structures are dynamic, not fixed isolated bags. A protein’s location depends on targeting information, transport machinery and cell state, so disrupting localization can impair function even when the protein’s chemical sequence is unchanged.','区室化使细胞维持不同化学空间并控制运输。核膜把大部分真核 DNA 与胞质隔开，核孔调节选择性交换。核糖体把 RNA 翻译成蛋白；游离和膜结合核糖体基本机器相同，但定位信号把部分新生蛋白导向内质网。内质网参与蛋白加工和脂质合成，高尔基体修饰分选货物。囊泡选择性载货，并非随机混匀区室。溶酶体等降解区室维持适于分解的条件，过氧化物酶体执行特定氧化反应。线粒体通过呼吸转能，光合真核的叶绿体捕获光能，两者特殊膜与遗传系统符合内共生起源。细胞骨架组织形状、运动及胞内运输。细胞器动态而非孤立固定袋子。蛋白位置依定位信息、运输机器和细胞状态，即使序列不变，定位受损仍可破坏功能。');
expand('B01.04','Cells need both materials for construction and usable free energy to maintain organization. Catabolic reactions break down or oxidize molecules, while anabolic reactions assemble cellular components; the two are linked through intermediates and energy carriers. Enzymes accelerate selected transformations by stabilizing a favorable reaction pathway, but they do not alter the overall thermodynamic equilibrium. Active sites bind substrates in environments suited to catalysis, and activity can depend on pH, temperature, cofactors and regulatory molecules. ATP is continually formed and consumed in coupled processes. Its hydrolysis is useful only when an actual molecular mechanism connects it to transport, synthesis or movement. Electron carriers transfer reducing equivalents between reactions, and membranes can maintain ion gradients that store electrochemical free energy. Cellular respiration and photosynthesis use different sources and pathways but both involve controlled electron transfer and membrane organization. Matter and energy must be tracked separately: carbon atoms cycle through molecules, whereas usable energy is progressively dispersed. A cell can maintain stable concentrations while molecules turn over rapidly, so a steady snapshot does not indicate that biochemical reactions have stopped.','细胞既需构建材料，也需可用自由能维持组织。分解代谢分解或氧化分子，合成代谢构建成分，两者经中间体和能量载体连接。酶稳定合适路径以加速特定转化，但不改变总热力学平衡。活性位点提供适合催化的环境，活性依赖 pH、温度、辅因子和调节分子。ATP 持续生成消耗，只有存在实际分子机制将水解与运输、合成或运动连接时，水解才有用。电子载体转移还原当量，膜可维持储存电化学自由能的离子梯度。呼吸与光合来源路径不同，但都涉及受控电子转移和膜组织。物质与能量须分别追踪：碳原子在分子间循环，可用能量逐渐分散。细胞浓度稳定仍可快速周转，因此静态快照不表示生化反应停止。');
expand('B01.05','The eukaryotic cell cycle separates growth, DNA replication and chromosome segregation into coordinated phases. During G1 a cell grows and responds to conditions; S phase duplicates DNA; G2 prepares for division; mitosis partitions replicated chromosomes. A replicated chromosome contains two sister chromatids joined until their separation. Chromosome count is conventionally based on centromeres, so doubling DNA in S phase does not immediately double that count. During mitosis, condensed chromosomes attach to spindle microtubules, align and separate so each daughter nucleus receives an appropriate set. Cytokinesis divides the cytoplasm and differs mechanically between animal and plant cells. Checkpoints monitor events such as DNA integrity and spindle attachment, while cyclins and associated kinases coordinate transitions. A checkpoint is a regulatory process rather than a conscious inspection, and failures can permit abnormal proliferation or chromosome imbalance. Some differentiated cells exit the active cycle, while others divide frequently. Meiosis is a distinct specialized program that reduces chromosome sets and generates variation for sexual reproduction; it must not be confused with ordinary mitotic production of genetically similar daughter cells.','真核细胞周期协调分开生长、DNA 复制和染色体分离。G1 生长并响应条件，S 复制 DNA，G2 准备分裂，有丝分裂分配染色体。复制染色体含两条姐妹染色单体，分离前相连。按着丝粒计数时，S 期 DNA 加倍不立即使染色体数加倍。有丝分裂中染色体凝缩、连接纺锤微管、排列并分离，使子核获得适当集合。胞质分裂分开胞质，动物与植物机制不同。检查点监测 DNA 完整性和纺锤连接，周期蛋白及相关激酶协调转变。检查点是调控过程而非有意识检查，失效可导致异常增殖或染色体失衡。一些分化细胞退出活跃周期，另一些频繁分裂。减数分裂是减半染色体组并产生变异的特殊程序，不能与普通有丝分裂混淆。');
expand('B01.06','Cell signaling begins when a stimulus changes a receptor or another sensing molecule. A receptor’s location and binding specificity determine which signals a cell can detect, and the same signal can produce different responses in different cell types because their internal networks differ. Transduction relays the information through protein interactions, phosphorylation, second messengers or changes in gene expression. Cascades can amplify a small input, while feedback and signal termination prevent indefinite activation. A pathway diagram indicates proposed causal connections, but experiments are needed to establish which connections operate in a particular context. Microscopy can visualize cell structures or labeled molecules, yet magnification merely enlarges an image while resolution determines whether nearby features can be distinguished. Fluorescent labels report the distribution of the label under the preparation conditions; fixation, overexpression or tagging can alter the system. Colocalization means signals occupy overlapping resolved regions, not necessarily that two molecules touch directly. Combine imaging with perturbations, controls and quantitative timing to test a signaling explanation. A change after treatment can reflect direct signaling, toxicity or an indirect cell-state shift, so alternatives must remain visible in the reasoning.','细胞信号始于刺激改变受体或其他感知分子。受体位置与结合特异性决定能检测何信号；不同细胞网络不同，同一信号可引起不同响应。转导通过蛋白作用、磷酸化、第二信使或基因表达传递信息，级联可放大小输入，反馈和终止防止无限活化。路径图表示拟议因果连接，需实验确认特定情境中哪些实际运作。显微可显示结构或标记分子，但放大仅增图尺寸，分辨率决定能否区分相邻特征。荧光报告制备条件下标签分布，固定、过表达或加标签可能扰动系统。共定位只说明信号在可分辨区域重叠，不一定直接接触。应结合扰动、对照和定量时间检验信号解释；处理后变化也可能源于毒性或间接状态改变。');

units('C10',['module.C07.06','module.C08.06','module.C09.06'],[
['多重平衡定量题','Speciation|Conservation equations|Validity checks','物种分布|守恒方程|有效性检查','Integrated equilibrium problems combine acid–base, precipitation or complexation with shared material balances. Select independent unknowns, identify a dominant-species approximation, and verify it against the resulting concentrations.','综合平衡题把酸碱、沉淀或配位与共享物料守恒结合。应选独立未知量、提出优势物种近似，并用求得浓度检验。','Total metal is 0.10 mol/L and complexed metal is 0.08 mol/L, with no other forms. Find free-metal concentration.','总金属为 0.10 mol/L，配合态为 0.08 mol/L，无其他形态，游离金属浓度是多少？',0.02,'[M]free = [M]total − [ML] = 0.10 − 0.08 = 0.02 mol/L.','A total analytical concentration is not automatically the free-ion concentration.','分析总浓度不自动等于游离离子浓度。','Every equilibrium expression should use total concentrations regardless of speciation.','无论物种分布如何，平衡式都应使用总浓度。'],
['结构与光谱推断题','Formula constraints|Signal equivalence|Candidate testing','分子式约束|信号等价|候选检验','A structure puzzle combines atom inventory, unsaturation, symmetry and multiple spectra. Equivalent nuclei can share signals, while integration constrains relative counts. Build candidates and test every reliable datum rather than guessing from one peak.','结构题综合原子库存、不饱和度、对称性与多种光谱。等价核可共享信号，积分约束相对数量。应建候选并逐项检验，而非凭单峰猜。','A proton NMR integral ratio is 3:2:1 and the molecule has 12 observed hydrogens. How many correspond to the largest signal?','氢谱积分比 3:2:1，总可观测氢数 12，最大信号对应几个氢？',6,'Scale = 12/(3+2+1) = 2; largest = 3 × 2 = 6 H.','Signal count reflects chemical environments, not simply atom count.','信号数反映化学环境，并非简单原子数。','Every hydrogen atom necessarily gives its own separate NMR peak.','每个氢原子必产生独立核磁峰。'],
['机理与合成推理','Electron bookkeeping|Selectivity|Route comparison','电子记账|选择性|路线比较','Mechanism problems track atoms, charges and stereochemistry through plausible steps. Synthesis problems additionally compare step compatibility and cumulative yield. A shorter route is useful only if its proposed chemistry is selective and feasible.','机理题追踪合理步骤中的原子、电荷与立体化学。合成题还比较步骤相容性与总产率。更短路线只有化学选择性与可行性成立时才有意义。','Three steps each yield 50%. Find overall percentage yield.','三步各产率 50%，总百分产率是多少？',12.5,'Overall yield = 0.5³ × 100% = 12.5%.','A valid mechanism must preserve total atoms and charge.','有效机理必须保持原子与总电荷守恒。','Drawing curved arrows alone establishes experimental proof.','画出弯箭头本身就构成实验证明。'],
['热力学与动力学综合','Driving force|Activation barrier|Temperature effects','驱动力|活化势垒|温度效应','Equilibrium and rate answer different questions. Combine Gibbs-energy or cell-potential information with a kinetic law to predict both direction and timescale. Temperature can change both the equilibrium constant and the rate constants.','平衡与速率回答不同问题。吉布斯能或电势需与速率律结合，才可预测方向与时间尺度。温度可同时改变平衡常数与速率常数。','A first-order process has a half-life of 10 min. What fraction remains after 20 min?','一级过程半衰期 10 min，20 min 后剩余比例是多少？',0.25,'20 min = 2 half-lives; remaining = (1/2)² = 0.25.','A strongly favorable reaction can still be slow.','强烈有利的反应仍可很慢。','A large equilibrium constant always implies a large rate constant.','平衡常数大总意味着速率常数大。'],
['实验数据与操作分析','Procedure purpose|Error direction|Evidence comparison','操作目的|误差方向|证据比较','Practical reasoning links each operation to a chemical or measurement purpose. Predict whether contamination, incomplete transfer or endpoint bias raises or lowers the reported result, and separate systematic effects from random variation.','实验推理把每个操作联系到化学或测量目的。预测污染、转移不全或终点偏差使结果升高或降低，并区分系统效应与随机变异。','True dry precipitate is 1.00 g but retained water adds 0.10 g. Find percentage mass overestimate.','真实干沉淀 1.00 g，残水增加 0.10 g，质量高估百分之几？',10,'Overestimate = 0.10/1.00 × 100% = 10%.','A known error direction can be inferred from the calculation chain.','可由计算链推断已知误差方向。','Every experimental error necessarily lowers the reported result.','所有实验误差都必使结果偏低。'],
['限时综合题组','Information triage|Linked subproblems|Independent checks','信息筛选|关联子题|独立检查','Integrated sets often supply unfamiliar data that can be solved with familiar conservation and equilibrium ideas. Separate given facts from assumptions, retain units and carry earlier results with explicit conditions so later reasoning remains reviewable.','综合题常提供陌生数据，却可用熟悉守恒和平衡思想求解。应区分已知与假设，保留单位，并连同条件传递前题结果，使后续推理可检查。','A 120-minute set reserves 20 minutes for checking; four equal sections share the rest. Find time per section in minutes.','120 分钟题组预留 20 分钟检查，其余均分四部分，每部分多少分钟？',25,'(120 − 20)/4 = 25 min.','An unfamiliar context can still obey familiar conservation laws.','陌生情境仍可遵循熟悉的守恒规律。','Every unfamiliar compound requires memorizing its full chemistry before any reasoning is possible.','任何陌生化合物都必须先背完全部化学性质才能推理。']]);
expand('C10.01','Start a multi-equilibrium problem by identifying what was actually added, because analytical totals remain fixed even while species redistribute. A metal salt and a ligand can produce free metal, several complexes and possibly a precipitate; an acid–base ligand also changes form with pH. Write separate balances for total metal and total ligand, counting the number of ligand units in each complex. Add charge balance when the problem does not otherwise determine the hydrogen-ion concentration. Equilibrium constants connect free species, so substituting total metal directly into a formation constant generally gives an incorrect result. Choose a provisional dominant species only when the constants and available amounts support it. Solve the reduced equations, then calculate neglected fractions and compare with the required precision. Check whether precipitation is allowed by the resulting ion product, not merely by remembering that a salt is called insoluble. A physically acceptable solution has nonnegative concentrations, satisfies every conserved total and agrees with the assumed phase inventory. If two different approximations produce incompatible answers, the conflict is evidence to revisit assumptions rather than average the answers.','多重平衡先识别实际加入了什么：物种会重分布，分析总量仍守恒。金属盐与配体可产生游离金属、多种配合物甚至沉淀；酸碱配体还随 pH 改形态。分别写总金属和总配体守恒，注意每配合物所含配体数；若其他条件不能确定氢离子，补电荷守恒。平衡常数连接游离物种，把总金属直接代入生成常数通常错误。只有常数和库存支持时才能假设优势物种，解简化方程后计算被忽略比例并对照精度要求。沉淀是否允许应看最终离子积，而不是只背“难溶”。物理解须浓度非负、符合所有总量与相态假设。不同近似若矛盾，应重查假设，不能把答案平均。');
expand('C10.02','A molecular-structure puzzle is best treated as a constraint-satisfaction problem. Begin with the formula and charge, calculate an appropriate unsaturation count and list plausible functional-group combinations. An exact mass can distinguish formulas that have similar nominal masses, while isotope patterns can reveal characteristic elemental composition. Infrared evidence helps identify or exclude bond types, but overlapping bands and weak absorptions limit certainty. In proton NMR, integration gives relative proton counts and splitting reflects couplings under a stated model; chemically equivalent protons need not correspond one to one with peaks in a complex spectrum. Carbon NMR signal count can reveal symmetry or distinct carbon environments. Use the combined information to draw several candidate structures rather than committing immediately to the first familiar pattern. Test each candidate against every observation, including missing signals that should have been strong and detectable. Stereochemical information may require additional experiments beyond a simple one-dimensional spectrum. A good final explanation says how each major feature supports the proposed structure and why alternatives fail. If the supplied evidence cannot distinguish two candidates, identifying that underdetermination is stronger reasoning than inventing a unique answer.','结构题适合作为约束满足问题。先从分子式、电荷和不饱和度列可能官能团组合。准确质量可区分名义质量相近的式子，同位素模式可提示元素组成。红外帮助识别或排除键，但重叠与弱吸收限制确定性。氢谱积分给相对氢数，裂分在给定模型下反映耦合；复杂谱中化学等价氢不必与峰一一对应。碳谱信号数可揭示对称性与碳环境。综合数据画多个候选，不要见熟悉模式就立即定案。逐一检验全部观察，包括本应强且可检出却缺失的信号。立体信息可能需超出简单一维谱的实验。好的解释说明各主要特征如何支持候选、为何排除其他；若证据不足区分两候选，指出欠定比编造唯一答案更严谨。');
expand('C10.03','An Olympiad mechanism should account for the origin and destination of every atom that changes its bonding. Mark nucleophilic and electrophilic sites, identify plausible leaving groups and track proton transfers explicitly when they affect charge or reactivity. A carbocation, radical or anion intermediate must be justified by the proposed conditions rather than inserted simply because it is familiar. Check whether rearrangement or stereochemical constraints would produce additional products. In synthesis, work backward to useful disconnections, then verify the route forward with the actual functional groups present. A reagent that performs the desired transformation on an isolated model compound may attack another group in the target precursor. Compare routes by compatibility, selectivity, availability and cumulative yield rather than step count alone. Catalytic, stoichiometric and work-up reagents have different roles and should not be conflated. A formal arrow from starting material to product is not a complete route unless the intermediate states and reaction conditions are chemically plausible. When evidence is supplied, use product ratios, labeling, rate dependence or stereochemistry to discriminate mechanisms instead of presenting the most elaborate possible story.','竞赛机理应交代每个改变连接原子的来源去向。标亲核亲电位点、合理离去基，并在影响电荷或活性时明确质子转移。碳正离子、自由基或负离子中间体须由条件支持，不能因熟悉而随意插入。检查重排和立体约束是否产生额外产物。合成先逆推有效断键，再按实际官能团正向验证；某试剂在简单模型能完成目标转化，不代表不会攻击前体其他基团。路线比较应看相容、选择性、可得性与总产率，而非只数步。催化、计量和后处理试剂作用不同。起始到产物的一根箭头不是完整路线，中间状态与条件必须合理。若题给证据，应通过产物比、标记、速率或立体结果区分机理，而非编最复杂故事。');
expand('C10.04','A synthesis of thermodynamics and kinetics begins by separating the question of direction from the question of timescale. The sign of actual reaction Gibbs energy predicts whether a small forward change lowers the relevant potential under the stated conditions. The equilibrium constant describes the composition reached after sufficient equilibration, whereas rate constants determine how rapidly the system approaches that state. A catalyst can shorten the approach without changing the final equilibrium ratio. Temperature complicates the comparison because it changes both equilibrium preferences and kinetic barriers; an increased rate does not by itself imply increased equilibrium yield. In electrochemistry, a favorable reversible potential may coexist with slow electrode kinetics or large resistive losses. In competing reaction networks, the initially dominant product can differ from the more stable long-time product, motivating the distinction between kinetic and thermodynamic control under specified reversible conditions. Build an energy or free-energy diagram that distinguishes reactants, intermediates, transition states and products. The vertical difference between endpoints controls thermodynamic driving force, while the barrier measured from the relevant populated state influences the rate. Never substitute one of these differences for the other.','热力学与动力学综合首先区分方向和时间尺度。实际反应吉布斯能符号判断规定条件下小幅正向变化是否降低相应势。平衡常数描述充分平衡后的组成，速率常数决定接近平衡快慢。催化剂可缩短过程而不改变最终平衡比例。温度同时改变平衡偏好与势垒，因此速率增加不代表平衡产率增加。电化学中，有利可逆电势可与慢电极动力学或大电阻损失并存。竞争网络的初期主产物可不同于长期更稳定产物，在指定可逆条件下形成动力学与热力学控制区别。能量图应区分反应物、中间体、过渡态与产物；端点高度差控制热力学驱动力，从实际布居态量起的势垒影响速率，不能互相替代。');
expand('C10.05','A practical-data problem asks why a procedure produces a trustworthy number, not merely which apparatus appears in a picture. For each operation, identify whether it establishes composition, removes an interference, preserves a sample or improves a measurement. Rinsing a transfer vessel can improve quantitative transfer, while rinsing a prepared precipitate has a different purpose and may cause dissolution loss if the solvent is unsuitable. Trace an error through the calculation equation to determine its direction: retained water increases a gravimetric mass, whereas incomplete recovery usually decreases it. The effect of a volume error depends on whether that volume is in a numerator, denominator or calibration step, so memorized “high” and “low” labels are unreliable. Distinguish a single blunder, a systematic method bias and random reading variation. Replicates characterize spread but do not automatically expose a shared bias. Compare controls, blanks and reference results to locate the likely failure stage. Report the supported conclusion and uncertainty without deleting inconvenient observations. Good analysis can explain why an apparently precise set of measurements is nevertheless not accurate.','实验数据题问操作为何产生可信数值，而不只是识图认仪器。每步应判断是在确定组成、去干扰、保存样品还是改善测量。冲洗转移容器改善定量转移，洗沉淀目的不同，溶剂不当还会造成溶失。沿计算式追踪误差方向：残水抬高重量结果，不完全回收通常降低。体积误差效果取决于它在分子、分母还是校准步骤，死记“偏高偏低”不可靠。区分单次粗差、系统偏倚与随机读数变异；重复反映分散，却不自动揭示共同偏差。结合对照、空白与标准结果定位失误阶段。如实报告结论和不确定度，不删不方便的观察。良好分析能解释看似精密的一组测量为何仍不准确。');
expand('C10.06','An integrated chemistry set often introduces an unfamiliar compound, technique or historical experiment, but supplies enough information to reason from conservation and models already learned. First mark what is given, what is requested and which quantities connect the subparts. Translate prose into atom counts, charge balances, amount ratios or energy relations before attempting elaborate algebra. A later subproblem may remain solvable symbolically even if an earlier numerical answer is uncertain; preserve the dependency explicitly rather than inventing a value. Units provide a fast independent check, especially when moving among mass, moles, concentration, pressure and electrical charge. Estimate the expected sign and order of magnitude before accepting a calculator result. Separate a stated idealization from an experimentally demonstrated fact, and avoid adding unsupported chemical assumptions simply to force a neat answer. During review, check limiting reagents, equilibrium approximation validity, charge conservation and whether a structure satisfies every constraint. A clear derivation lets valid reasoning survive an arithmetic slip. After a timed set, classify mistakes by missing concept, misread condition, algebra, units or time allocation so the next practice session addresses their actual causes.','综合化学题常介绍陌生化合物、技术或历史实验，但通常给足信息，可用已学守恒和模型推理。先标已知、目标及子题间连接量，把文字转为原子数、电荷守恒、物质的量比或能量关系，再复杂运算。前题数值不确定时，后题常仍可符号求解，应保留依赖而非捏造数值。质量、摩尔、浓度、压强、电荷间转换时，单位提供快速独立检查；接受计算器结果前先估符号与数量级。区分题设理想化与已证实事实，不为凑整齐答案添加无依据化学假设。复查限量试剂、近似有效性、电荷与结构约束。清晰推导能让有效思路不被算术失误掩盖。限时后按概念缺失、误读、代数、单位或分配时间分类错误，使下次训练针对真实原因。');

units('C09',['module.C06.06','biology.cells','module.C03.04'],[
['蛋白质、糖类、脂质与核酸','Biopolymer structure|Functional groups|Noncovalent assembly','生物聚合物结构|官能团|非共价组装','Proteins join amino acids, nucleic acids join nucleotides, and many carbohydrates join sugars. Lipids are a chemically varied class rather than one repeating polymer. Sequence, stereochemistry and environment determine folding and assembly.','蛋白质连接氨基酸，核酸连接核苷酸，许多糖类连接单糖。脂质化学多样，并非一种重复聚合物。序列、立体化学与环境决定折叠和组装。','A linear peptide contains 6 amino-acid residues. How many peptide bonds connect them?','线性肽含六个氨基酸残基，共有几个连接肽键？',5,'A linear chain of n residues has n − 1 links: 6 − 1 = 5.','Noncovalent interactions are essential to biomolecular structure.','非共价相互作用对生物分子结构至关重要。','Protein folding changes every peptide bond into a new covalent linkage.','蛋白质折叠会把每条肽键都变成新的共价连接。'],
['酶与动力学模型','Catalysis|Saturation|Michaelis–Menten parameters','催化|饱和|米氏参数','Enzymes accelerate reactions by lowering an effective activation barrier without changing equilibrium. A simple single-substrate steady-state model gives v = Vmax[S]/(Km+[S]); its assumptions and inhibition pattern must be checked.','酶通过降低有效活化势垒加速反应，不改变平衡。简单单底物稳态模型给 v = Vmax[S]/(Km+[S])，应检查其假设和抑制模式。','Vmax = 10 and [S] = Km. Find v.','Vmax = 10，且 [S] = Km，v 为多少？',5,'v = Vmax/2 = 5.','Enzyme saturation can make rate insensitive to further substrate increase.','酶饱和后，继续增加底物对速率影响可很小。','Every enzyme rate stays proportional to substrate at arbitrarily high concentration.','任意高底物浓度下酶速率都保持正比于底物。'],
['生物能量与耦合','Gibbs-energy coupling|ATP turnover|Electrochemical gradients','吉布斯能耦合|ATP 周转|电化学梯度','An unfavorable biochemical step can proceed when mechanistically coupled to a sufficiently favorable process. ATP and ion gradients mediate energy transfer; their useful free energy depends on actual cellular concentrations and conditions.','不利生化步骤若通过机理与足够有利过程耦合即可进行。ATP 和离子梯度介导能量转移，其可用自由能取决于实际细胞浓度与条件。','Two coupled steps have ΔG values +12 and −20 kJ/mol. Find combined ΔG.','两个耦合步骤 ΔG 分别为 +12 与 −20 kJ/mol，总 ΔG 是多少？',-8,'ΔGtotal = 12 − 20 = −8 kJ/mol.','Coupling requires a shared mechanism, not merely simultaneous reactions nearby.','耦合需要共同机理，不是附近同时发生即可。','Any favorable reaction automatically drives every nearby unfavorable reaction.','任意有利反应都会自动驱动附近全部不利反应。'],
['中心代谢','Glycolysis|Citric-acid cycle|Oxidative phosphorylation','糖酵解|柠檬酸循环|氧化磷酸化','Central metabolism redistributes carbon and reducing equivalents. Glycolysis converts glucose to pyruvate, the citric-acid cycle oxidizes acetyl groups, and electron transport can establish the proton gradient used for ATP synthesis.','中心代谢重新分配碳与还原当量。糖酵解把葡萄糖转为丙酮酸，柠檬酸循环氧化乙酰基，电子传递可建立用于合成 ATP 的质子梯度。','One glucose forms two three-carbon pyruvate molecules. How many pyruvate molecules arise from 4 glucose molecules?','一个葡萄糖产生两个三碳丙酮酸，四个葡萄糖产生几个丙酮酸？',8,'4 × 2 = 8 pyruvate molecules.','Carbon flow and electron flow must both be accounted for.','须同时核算碳流与电子流。','The citric-acid cycle directly uses all released energy to make ATP in one step.','柠檬酸循环一步直接把全部能量变成 ATP。'],
['生物合成与调控','Anabolism|Feedback control|Compartmentation','合成代谢|反馈调控|区室化','Biosynthesis builds molecules using precursors, reducing power and energy. Feedback inhibition, covalent modification and gene expression regulate flux. Compartmentation separates incompatible processes and changes local substrate access.','生物合成利用前体、还原力与能量构建分子。反馈抑制、共价修饰和基因表达调节通量。区室化分离不相容过程并改变局部底物可及性。','A feedback inhibitor reduces pathway flux from 20 to 5 units. Find the percentage reduction.','反馈抑制使通量从 20 降至 5 单位，降低百分之几？',75,'Reduction = (20 − 5)/20 × 100% = 75%.','A pathway can be regulated at several steps and timescales.','同一路径可在多个步骤和时间尺度受到调控。','Every metabolic pathway is controlled by one permanently fixed rate-limiting enzyme.','每条代谢路径都由一个永久固定限速酶控制。'],
['生化方法与整合路径','Purification|Tracer analysis|Flux inference','纯化|示踪分析|通量推断','Purification separates components for testing, while labeled tracers follow atom movement through pathways. Metabolite concentrations are pool sizes; flux describes turnover, so concentration alone does not determine pathway speed.','纯化分离组分以供测试，标记示踪追踪原子在路径中的流动。代谢物浓度是池大小，通量是周转，单看浓度不能确定路径速度。','A pool contains 10 units and outflow is 2 units per minute at steady state. Find simple turnover time in minutes.','稳态池含 10 单位，流出每分钟 2 单位，简单周转时间为多少分钟？',5,'Turnover time = pool/flux = 10/2 = 5 min.','Equal metabolite concentrations can accompany different fluxes.','相同代谢物浓度可对应不同通量。','A larger metabolite pool always proves a faster reaction.','代谢池越大总证明反应越快。']], [{title:'MIT OpenCourseWare · General Biochemistry',url:'https://ocw.mit.edu/courses/7-05-general-biochemistry-spring-2020/'}]);
expand('C09.01','Biomolecules use a limited set of chemical groups to generate diverse structures and functions. Amino acids contain an amino group and carboxyl group attached to a side-chain-bearing carbon; their protonation states depend on pH. Peptide bonds join residues into a sequence with distinct amino and carboxyl ends. The sequence constrains folding, while hydrogen bonding, electrostatics, hydrophobic effects and dispersion help stabilize secondary and tertiary organization. Carbohydrates include simple sugars and linked polymers with different bond orientations, making starch and cellulose chemically similar in composition but functionally different. Lipids include fats, phospholipids and steroids; many are amphipathic, containing both water-compatible and hydrophobic regions. This property supports membrane assembly. Nucleotides combine a base, sugar and phosphate; nucleic-acid chains have directional sugar–phosphate backbones, with base sequences carrying information. Hydrolysis and condensation connect the construction and breakdown of these structures, but cells use specific activated intermediates and enzymes rather than relying on an abstract reverse reaction. A biomolecule’s function depends on shape, chemical environment and interactions, so knowing its monomer list alone is insufficient to explain its behavior.','生物分子用有限化学基团产生多样结构功能。氨基酸含氨基、羧基及带侧链的中心碳，质子化状态依赖 pH；肽键连接成具有不同氨端和羧端的序列。序列约束折叠，氢键、静电、疏水效应及色散稳定二三级结构。糖包括单糖和不同连接方向的聚合物，使淀粉与纤维素虽组成相近而功能不同。脂质包括脂肪、磷脂和类固醇，许多兼具亲水与疏水区，因此能支持膜组装。核苷酸含碱基、糖与磷酸，核酸具有有方向的糖磷酸骨架，碱基序列承载信息。水解与缩合连接构建和分解，但细胞使用具体活化中间体和酶，而非抽象逆反应。分子功能依赖形状、环境及相互作用，仅知道单体清单不足以解释行为。');
expand('C09.02','An enzyme binds reactants in an active-site environment that can orient them, transfer protons, stabilize charge or form temporary covalent intermediates. Catalysis lowers the effective barrier along an available pathway; it does not supply a different overall equilibrium. Enzyme specificity is selective recognition, not necessarily absolute exclusivity for one molecule. In the simplest Michaelis–Menten scheme, substrate binds enzyme, the complex forms product and enzyme is regenerated. Under appropriate initial-rate and steady-state assumptions, the rate follows a saturating curve. Vmax scales with total active enzyme concentration, and kcat describes turnover per active enzyme at saturation. Km equals the substrate concentration at half Vmax within that model, but it is not always a direct dissociation constant or a universal measure of binding affinity. Inhibitors can alter apparent parameters differently depending on their binding mechanism. Irreversible loss of activity and allosteric regulation require additional descriptions. Temperature and pH affect both catalytic chemistry and protein structure, so an observed optimum reflects competing effects. Fit rate data with uncertainty and inspect whether the simple model actually captures the curve before assigning mechanistic meaning to its parameters.','酶的活性位点可定位反应物、转移质子、稳定电荷或形成暂时共价中间体。催化降低路径上的有效势垒，不改变总平衡。特异性是选择性识别，不一定绝对只接受一种分子。简单米氏方案中，底物结合酶，复合物生成产物并再生酶；在适当初速和稳态假设下，速率呈饱和曲线。Vmax 随活性酶总量变化，kcat 描述饱和下每个活性酶周转。Km 在该模型内等于半最大速率的底物浓度，但不总是解离常数或通用亲和尺度。抑制剂依结合机制改变表观参数，不可逆失活及变构调控需更多描述。温度与 pH 同时影响催化化学及蛋白结构，观测最适值反映竞争效应。应带不确定度拟合并检查模型是否真实描述曲线，再赋予参数机理意义。');
expand('C09.03','Cells maintain organized, nonequilibrium states by exchanging matter and energy with their surroundings. A reaction’s actual Gibbs-energy change depends on cellular concentrations as well as its standard transformed value. ATP hydrolysis is useful because suitable enzymes can couple it to otherwise unfavorable processes through shared intermediates or conformational cycles. It is misleading to say that energy is released simply by breaking a high-energy bond: bond breaking costs energy, and the favorable overall change arises from the complete reactant-to-product transformation, including solvation and stabilization. ATP is therefore an energy-transfer currency that is continually regenerated, not a permanent one-way fuel store. Reducing cofactors such as NADH carry transferable electron equivalents, while ion gradients store electrochemical free energy across membranes. A gradient includes both a concentration contribution and an electrical contribution for charged species. ATP synthase couples ion movement to chemical synthesis through a molecular mechanism. Adding two favorable and unfavorable equations is only physically meaningful when an actual coupling pathway exists. Distinguish total energy conservation from the free-energy decrease that limits how much useful work a cell can extract.','细胞通过与环境交换物质能量维持有组织的非平衡态。实际反应吉布斯能不仅依赖标准转化值，也依赖细胞浓度。ATP 水解之所以有用，是酶能通过共同中间体或构象循环把它与不利过程耦合。“断高能键放能”容易误导，因为断键需要能量；有利总变化来自完整反应物到产物转化，包括溶剂化和稳定化。ATP 是持续再生的能量转移货币，不是永久单向燃料仓。NADH 等辅因子携带可转移还原当量，离子梯度跨膜储存电化学自由能；带电物种梯度兼有浓度和电势贡献。ATP 合酶以分子机理把离子流与合成耦合。只有存在真实耦合路径时，才能有物理意义地把有利和不利方程相加。能量总守恒与限制可提取有用功的自由能降低是不同概念。');
expand('C09.04','Central metabolism is a connected network rather than one linear energy-production chain. Glycolysis converts a six-carbon glucose into two three-carbon pyruvate molecules while transferring electrons to a cofactor and producing a net ATP gain under the standard pathway bookkeeping. When oxidative metabolism is available, pyruvate can be converted to acetyl-CoA with carbon dioxide release and additional reducing-equivalent production. The citric-acid cycle oxidizes acetyl-derived carbon while regenerating its starting acceptor and supplying intermediates for biosynthesis. Electron carriers feed an electron-transport system whose favorable electron transfers can pump protons across a membrane. ATP synthesis then uses the resulting electrochemical gradient. Oxygen serves as the terminal acceptor in aerobic respiration, but glycolysis itself does not directly consume oxygen. Fermentation regenerates oxidized cofactor so glycolysis can continue without that respiratory route. Exact ATP yield per glucose depends on organism, transport costs, coupling efficiency and alternative pathways, so a single universal integer can mislead. Track carbon atoms, electron equivalents and energy transfers separately; their balances reveal different aspects of the same network and help detect inconsistent pathway summaries.','中心代谢是网络，不是单一产能直线。标准糖酵解把六碳葡萄糖变成两个三碳丙酮酸，同时向辅因子转移电子并净生成 ATP。有氧化代谢条件时，丙酮酸可转为乙酰辅酶 A，释放 CO2 并生成更多还原当量。柠檬酸循环氧化乙酰来源碳、再生起始受体，并提供合成前体。电子载体把电子送入传递系统，有利电子转移可跨膜泵质子，ATP 合成再利用电化学梯度。氧是有氧呼吸末端受体，但糖酵解本身不直接消耗氧。发酵再生氧化辅因子，使糖酵解无需该呼吸路径仍可继续。每葡萄糖 ATP 实际收益依生物、转运成本、耦合效率及替代路径变化，万能固定整数会误导。碳、还原当量和能量应分别核算，反映同一网络的不同方面。');
expand('C09.05','Anabolic pathways assemble complex molecules from smaller precursors and usually consume energy and reducing power. They are not necessarily simple reversals of catabolic pathways: strongly favorable breakdown steps may require different enzymes and coupled reactions in the synthetic direction. Shared intermediates connect amino-acid, nucleotide, carbohydrate and lipid synthesis, so changing one branch can alter precursor availability elsewhere. Feedback inhibition allows an end product to reduce activity at an earlier pathway step, limiting unnecessary production. Covalent modification can switch enzyme activity on a short timescale, while changes in gene expression alter enzyme abundance more slowly. Substrate supply, cofactor ratios, transport and product removal can all control flux, so there need not be one permanently dominant rate-limiting enzyme. Compartmentation separates reactions into organelles or local environments with different concentrations and conditions. Reciprocal regulation helps avoid wasteful cycles in which synthesis and breakdown consume energy without useful net change, though some cycles can serve regulatory or heat-producing roles. Interpret a metabolic change by distinguishing altered enzyme amount, altered enzyme activity and changed metabolite availability rather than attributing every effect to one gene.','合成代谢用小前体组装复杂分子，通常消耗能量和还原力。它并不一定是分解途径简单反向，强有利分解步骤在合成方向可能需不同酶与耦合反应。共享中间体连接氨基酸、核苷酸、糖与脂质合成，一个分支变化可影响其他前体供应。反馈抑制使终产物降低前端步骤活性，限制无用生产；共价修饰可快速切换酶活，基因表达则较慢改变酶量。底物、辅因子比例、转运和产物移除都控制通量，不必存在永久主导限速酶。区室化把反应放入浓度与条件不同的细胞器或局部环境。互反调控避免合成分解徒耗能而无净结果，但某些循环也有调控或产热功能。解释代谢变化时，应区分酶量、酶活与代谢物供应，而非把一切归给一个基因。');
expand('C09.06','Biochemical methods turn a complex cellular mixture into testable measurements. Fractionation and chromatography can enrich a molecule, but enrichment must be checked for identity, activity and contamination rather than assumed from one band. An enzyme assay measures a defined chemical conversion under controlled conditions; it is not automatically a direct measurement of flux in a living cell. Electrophoresis separates molecules by charge and size-dependent mobility, with interpretation depending on denaturing or native conditions. Isotopic tracers follow labeled atoms through transformations and can reveal pathway connectivity or turnover when the labeling design and sampling times are appropriate. A metabolite concentration is the size of a pool, while flux is the amount crossing a pathway step per time. A pool can stay constant because equal large inflow and outflow balance, or because both flows are small. Thus steady concentration does not mean metabolic inactivity. Perturbations, time courses and multiple labels provide stronger constraints than one endpoint. Integrate biochemical data with compartmentation, conservation balances and alternative routes, and distinguish a pathway diagram’s possible connections from measured use of those connections under a particular condition.','生化方法把复杂细胞混合物转成可检验测量。分级和色谱可富集分子，但需检验身份、活性和污染，不能看到一条带就默认纯。酶测定在受控条件下测指定转化，不自动等于活细胞通量。电泳按电荷和大小相关迁移率分离，解释依赖变性或天然条件。同位素示踪在合适标记与取样时间下追踪原子，揭示连接和周转。代谢物浓度是池大小，通量是每时间通过步骤的量；池恒定既可能是大流入大流出相等，也可能两者都小，因此浓度稳定不意味代谢停止。扰动、时间序列和多种标记比单终点约束更强。应结合区室、守恒和替代路径，区分路径图的可能连接与某条件下实测使用的连接。');

units('C08',['module.C04.06','math.derivatives','math.integrals','module.P10.03'],[
['热力学势与化学势','Thermodynamic constraints|Chemical potential|Composition derivatives','热力学约束|化学势|组成导数','Different thermodynamic potentials suit different controlled variables. Chemical potential is the partial change of Gibbs energy when adding a component at fixed temperature, pressure and other amounts. It drives material transfer and reaction equilibria.','不同热力学势适用于不同控制变量。化学势是在温度、压强和其他组分量固定时，加某组分引起的吉布斯能偏变化，决定物质转移与反应平衡。','At fixed conditions, adding 0.2 mol changes G by approximately 6 kJ. Find local chemical potential in kJ/mol.','固定条件下加入 0.2 mol 使 G 近似增加 6 kJ，局部化学势为多少 kJ/mol？',30,'μ ≈ ΔG/Δn = 6/0.2 = 30 kJ/mol.','Chemical potential can depend on composition.','化学势可以依赖组成。','Chemical potential is simply the total mass of a component.','化学势就是组分总质量。'],
['相平衡与反应平衡','Phase coexistence|Activity|Reaction Gibbs energy','相共存|活度|反应吉布斯能','Coexisting phases have equal chemical potential for transferable components. Reaction equilibrium requires the stoichiometric sum of chemical potentials to vanish. Activities encode departures from an ideal concentration model.','共存相中可交换组分的化学势相等。反应平衡要求各化学势按计量数加权之和为零，活度编码相对理想浓度模型的偏离。','For A ⇌ B with μA = 5 and μB = 8 kJ/mol, find forward reaction ΔrG in kJ/mol.','A ⇌ B 中 μA = 5、μB = 8 kJ/mol，正向 ΔrG 是多少 kJ/mol？',3,'ΔrG = μB − μA = 8 − 5 = 3 kJ/mol.','Equal chemical potential, rather than equal concentration, defines phase-transfer equilibrium.','相转移平衡要求化学势相等，而非浓度相等。','Two equilibrium phases must contain every component at identical concentration.','平衡两相各组分浓度必须完全相同。'],
['动理论与输运','Diffusion|Viscosity|Thermal conduction','扩散|黏性|热传导','Transport laws relate fluxes to gradients near local equilibrium. Fick’s law gives particle flux opposite a concentration gradient. Momentum and energy transport appear as viscosity and thermal conductivity; coefficients depend on microscopic collisions.','局部近平衡下，输运定律联系通量与梯度。菲克定律使粒子通量与浓度梯度相反；动量和能量输运表现为黏性与热导，系数依赖微观碰撞。','With D = 2 and concentration gradient −3 in consistent units, find J = −D dc/dx.','一致单位下 D = 2，浓度梯度 −3，J = −D dc/dx 是多少？',6,'J = −2 × (−3) = 6.','Zero net diffusive flux does not mean molecules stop moving.','净扩散通量为零不意味着分子停止运动。','Diffusion stops all microscopic motion at uniform concentration.','浓度均匀时扩散会使全部微观运动停止。'],
['量子化学模型','Electronic Hamiltonian|Approximation|Molecular orbitals','电子哈密顿量|近似|分子轨道','Quantum chemistry solves or approximates molecular electronic states. Separating fast electronic and slower nuclear motion motivates the Born–Oppenheimer approximation. Basis choice and correlation treatment influence accuracy and computational cost.','量子化学求解或近似分子电子态。快电子与慢核运动分离形成玻恩—奥本海默近似的动机。基组和电子关联处理影响精度与计算成本。','A normalized two-state expansion has squared first coefficient 0.3. Find the squared second coefficient.','归一化两态展开第一系数模平方为 0.3，第二系数模平方是多少？',0.7,'|c1|² + |c2|² = 1; |c2|² = 0.7.','An approximation requires convergence and comparison checks.','近似需要收敛与对照检查。','A larger basis automatically removes every physical approximation.','更大基组自动消除所有物理近似。'],
['分子光谱','Rotational levels|Vibrational levels|Selection rules','转动能级|振动能级|选择定则','Spectra measure energy differences between states, with transition strengths constrained by symmetry and coupling to radiation. Rotational, vibrational and electronic transitions probe different molecular scales; selection rules determine which transitions are allowed.','光谱测量态间能量差，跃迁强度受对称性及与辐射耦合限制。转动、振动和电子跃迁探测不同分子尺度，选择定则决定允许跃迁。','Two energy levels are 3 and 11 units. Find absorbed photon energy for the upward transition.','能级为 3 与 11 单位，向上跃迁吸收光子能量是多少？',8,'Ephoton = Eupper − Elower = 11 − 3 = 8.','An energy difference can exist even when a transition is symmetry-forbidden.','即使跃迁被对称性禁阻，能级差仍可存在。','Every pair of energy levels produces an equally intense spectral line.','任意两能级都产生同强度谱线。'],
['统计热力学与反应动力学','Partition functions|Transition-state model|Energy distributions','配分函数|过渡态模型|能量分布','Statistical thermodynamics builds macroscopic averages from state energies and probabilities. Reaction dynamics asks how collisions and motion cross reactive regions; transition-state theory approximates rate using populations near an activated dividing surface.','统计热力学从态能量与概率建立宏观平均。反应动力学研究碰撞和运动如何通过反应区，过渡态理论以活化分界面附近的布居近似速率。','Two equal-energy states and one state with Boltzmann weight 0.5 give what partition sum if each low state has weight 1?','两个等能低态各权重 1，一个高态权重 0.5，配分和是多少？',2.5,'Z = 1 + 1 + 0.5 = 2.5.','State degeneracy contributes to the partition sum.','态简并度对配分和有贡献。','Only the lowest-energy state ever contributes at nonzero temperature.','非零温度下永远只有最低态有贡献。']], [{title:'MIT OpenCourseWare · Physical Chemistry',url:'https://ocw.mit.edu/courses/5-61-physical-chemistry-fall-2017/'}]);
expand('C08.01','Thermodynamic potentials reorganize energy accounting around the variables controlled by an experiment. Internal energy is natural for entropy, volume and composition; enthalpy replaces volume control with pressure; Helmholtz energy is useful at fixed temperature and volume; Gibbs energy is useful at fixed temperature and pressure. These choices are related by Legendre transforms, which exchange a variable for its conjugate quantity rather than introducing a new source of energy. For a mixture, adding material changes energy and entropy even when temperature and pressure remain constant. The chemical potential of component i is its partial molar Gibbs energy, the derivative with respect to its amount while other specified variables are held fixed. “Partial molar” means the incremental contribution in the actual mixture, not the pure substance’s total molar property. Composition-dependent interactions can make those quantities differ. Matter tends to transfer in a direction that lowers the appropriate total potential under the constraints. At equilibrium, transferable species have matching chemical potentials across accessible regions. For ions, electrical potential contributes to the electrochemical potential, so concentration differences can be balanced by voltage rather than disappearing entirely.','热力学势围绕实验控制变量重组能量核算。内能自然对应熵、体积与组成；焓用压强替代体积控制；亥姆霍兹能适用于恒温恒容，吉布斯能适用于恒温恒压。勒让德变换交换变量与共轭量，并不创造新的能量来源。混合物中，即使温压不变，加物质也改变能量和熵。组分化学势为偏摩尔吉布斯能，即固定其他指定变量时对其物质的量的偏导。“偏摩尔”指实际混合物中的增量贡献，不等于纯物质摩尔性质；组成相互作用可使二者不同。物质转移趋于在约束下降低相应总势，平衡时可转移物种在可达区域化学势匹配。离子还须计电势形成电化学势，因此浓度差可被电压平衡，而不必完全消失。');
expand('C08.02','Phase equilibrium concerns the stable distribution of matter among solid, liquid and gas phases or among multiple condensed phases. A component that can move between two phases is at equilibrium when its chemical potential is equal in both; equal concentration is neither necessary nor generally expected. A phase diagram summarizes which phases are stable at specified pressure, temperature and composition. Lines or surfaces of coexistence mark equality conditions, while triple and critical points have distinct meanings. A critical point ends the liquid–gas distinction; a triple point permits three phases to coexist under specified conditions. Reaction equilibrium similarly requires the stoichiometric sum of chemical potentials to vanish. Writing chemical potential as a standard term plus RT ln activity leads to the familiar reaction quotient and equilibrium constant. Ideal-solution laws are approximations to activity behavior, and strong interactions can require activity coefficients. When phase change and chemical reaction are coupled, one must satisfy both sets of equilibrium conditions together with material balances. A stable equilibrium minimizes the appropriate potential under constraints; merely finding an algebraic stationary point does not guarantee global stability against phase separation.','相平衡研究物质在固液气或多个凝聚相中的稳定分布。组分能在两相转移时，平衡要求其化学势相等，并不要求浓度相等。相图总结指定压强、温度和组成下的稳定相，共存线面标志相等条件。临界点终结液气区别，三相点则允许指定条件下三相共存。反应平衡要求化学势按计量数加权之和为零。把化学势写为标准项加 RT ln 活度，可导出反应商和平衡常数。理想溶液规律是活度近似，强相互作用需活度系数。相变与反应耦合时，须同时满足两类平衡与物料守恒。稳定平衡在约束下使相应势最小；求得代数驻点并不保证对相分离具有全局稳定性。');
expand('C08.03','Molecular motion transports matter, momentum and energy even when there is no bulk flow. A concentration gradient produces diffusion because more particles initially cross from the high-concentration side than in the reverse direction. The microscopic motion remains random; the net flux is directional. In a simple one-dimensional dilute model, Fick’s first law is J = −D dc/dx, and the minus sign indicates movement down the concentration gradient. Combining this law with conservation gives the time-dependent diffusion equation when D is constant. Viscosity describes momentum transport between layers moving at different velocities, while thermal conductivity describes energy transport down a temperature gradient. Their coefficients reflect collision rates, interaction strengths and molecular structure. Near local equilibrium, fluxes can often be approximated as linear in gradients; large gradients, rarefied gases or coupled electric and chemical driving forces may require more elaborate descriptions. Diffusion time over a distance scales approximately with distance squared divided by diffusivity, explaining why microscopic transport can be fast while macroscopic diffusion is slow. Convection, stirring and membrane transport must be distinguished from diffusion rather than absorbed into an unexplained effective rate.','即使没有整体流动，分子运动也输运物质、动量和能量。浓度梯度使高浓侧跨向低浓侧的粒子多于反向，微观运动仍随机，净通量却有方向。简单一维稀薄模型中 J = −D dc/dx，负号表示沿浓度降低方向。结合守恒且 D 恒定可得时间相关扩散方程。黏性描述不同速度层之间的动量输运，热导描述沿温度降低方向的能量输运，其系数反映碰撞、相互作用和分子结构。局部近平衡下通量常近似正比梯度；大梯度、稀薄气体或电化学驱动耦合需更复杂模型。跨距离的扩散时间约按距离平方除以扩散系数缩放，因此微观扩散快、宏观扩散慢。对流、搅拌和膜输运须与扩散区分，不能全塞入未解释的有效速率。');
expand('C08.04','A molecular quantum calculation starts with a Hamiltonian specifying kinetic energies and interactions among nuclei and electrons. Solving the exact many-particle equation is generally difficult, so physical and numerical approximations are made explicitly. The Born–Oppenheimer approximation exploits the mass difference between nuclei and electrons to solve electronic states at approximately fixed nuclear positions, producing a potential-energy surface for nuclear motion. It can fail near strongly coupled electronic states. Molecular orbitals are expanded in a finite basis; increasing the basis improves representational flexibility but does not automatically correct an inadequate treatment of electron correlation. Mean-field methods approximate each electron’s interaction with the others, while more advanced methods recover additional correlated behavior at increased cost. Geometry optimization searches for a stationary point on an approximate energy surface; a frequency analysis helps distinguish a minimum from a saddle point. Computed energies are method-dependent estimates, so compare relative quantities consistently and test convergence. A visually attractive orbital plot does not establish chemical accuracy. Validate predictions against known limits, alternative calculations or experimental observables, and distinguish a model’s electronic energy from the full temperature-dependent free energy.','分子量子计算先用哈密顿量指定核与电子动能及相互作用。精确多粒子方程通常难解，因此应明示物理与数值近似。玻恩—奥本海默近似利用核电子质量差，近似固定核位置求电子态，形成核运动势能面；电子态强耦合附近可能失效。分子轨道用有限基组展开，增加基组提高表示能力，却不能自动补足电子关联处理不足。平均场近似每个电子与其余电子作用，更高级方法以较大计算代价恢复关联。几何优化寻找近似势能面的驻点，频率分析帮助区分极小与鞍点。计算能量依赖方法，应一致比较相对量并检验收敛。漂亮轨道图不证明化学精度，应与已知极限、其他计算或实验量对照，区分电子能与完整温度相关自由能。');
expand('C08.05','A molecular spectrum is a set of transition frequencies and intensities, not a direct drawing of the molecule. Photon energy must match the difference between initial and final states, while the coupling matrix element and state populations determine whether the transition is observable and how strong it is. Rotational energies depend on moments of inertia and therefore reveal information about mass distribution and bond lengths. Vibrational frequencies depend on force constants and masses; isotopic substitution can shift them without changing the main electronic bonding pattern. Electronic transitions usually involve larger energies and can overlap with vibrational structure. Selection rules arise from symmetry and the interaction with radiation, so an existing energy gap need not produce a strong allowed line. Finite lifetimes, collisions, thermal motion and instrument response broaden spectral features. The harmonic oscillator and rigid rotor are useful first models, but anharmonicity and centrifugal distortion produce corrections. Interpret a spectrum by combining positions, intensities, isotope changes and temperature dependence. A single frequency match is weak evidence compared with a consistent assignment across multiple independent features and known selection constraints.','分子光谱是一组跃迁频率与强度，不是分子直接图像。光子能量须匹配始末态差，耦合矩阵元及态布居决定能否观测和强度。转动能取决于转动惯量，可揭示质量分布与键长；振动频率依赖力常数与质量，同位素替换可在基本电子成键不变时移频。电子跃迁能量通常较大，可伴振动结构。选择定则来自对称性与辐射作用，所以有能隙未必有强允许谱线。有限寿命、碰撞、热运动及仪器响应使峰展宽。谐振子和刚性转子是初模型，非谐与离心畸变给出修正。解释应结合位置、强度、同位素变化及温度依赖。单频匹配证据弱，多个独立谱征与选择约束一致更有说服力。');
expand('C08.06','Statistical thermodynamics connects a list of microscopic states with measurable averages. At fixed temperature in the canonical description, a state’s weight decreases exponentially with energy, while degeneracy multiplies the number of states contributing at that energy. The partition function sums those weights and normalizes probabilities. Translational, rotational, vibrational and electronic contributions can sometimes be factored approximately when their motions are sufficiently separable. Derivatives and weighted averages then yield energy, heat capacity and other thermodynamic quantities. Reaction dynamics adds the question of how trajectories or quantum amplitudes move between reactant and product regions. Transition-state theory estimates flux through a dividing surface near a free-energy bottleneck, assuming an appropriate equilibrium-like population and limited recrossing. A barrier’s height alone is not always enough: orientation, solvent reorganization, tunneling and competing channels can affect rate. Thermodynamic populations and kinetic pathways therefore play complementary roles. Two reactions can have similar equilibrium constants but radically different speeds. When using a rate model, identify which degrees of freedom are equilibrated, what defines the dividing surface and which dynamical corrections have been neglected rather than treating an exponential factor as a universal complete explanation.','统计热力学把微观态列表连接到可测平均。恒温正则描述中，态权重随能量指数降低，简并度增加该能量贡献的态数，配分函数求和并归一概率。运动足够可分离时，平动、转动、振动和电子贡献可近似因子化，通过导数及加权平均得到能量、热容等量。反应动力学进一步问轨迹或量子振幅如何在反应物与产物区域之间运动。过渡态理论估计自由能瓶颈附近分界面的通量，假定合适类平衡布居及有限回穿。仅势垒高度不总够，取向、溶剂重组、隧穿与竞争通道都可影响速率。热力学布居与动力学路径互补，平衡常数相近的反应速度可迥异。使用速率模型时，应明确哪些自由度平衡、分界面如何定义、忽略何种动力学修正，不能把指数因子视为普适完整解释。');

units('C07',['module.C04.06','physics.units'],[
['取样、精密度与校准','Representative sampling|Precision|Calibration curve','代表性取样|精密度|校准曲线','Analytical results depend first on whether the sample represents the material of interest. Precision describes repeated agreement, while calibration relates signal to reference amounts and can reveal bias.','分析结果首先依赖样品是否代表目标材料。精密度描述重复一致性，校准把信号与参考量联系并可发现偏差。','A calibration is signal = 2c + 1. For signal 9, find c.','校准关系为信号 = 2c + 1，信号为 9 时 c 是多少？',4,'c = (9 − 1)/2 = 4.','Repeated analysis cannot repair a systematically unrepresentative sample.','重复分析不能修复系统性不代表总体的取样。','Many repeated measurements always eliminate sampling bias.','大量重复测量总能消除取样偏差。'],
['滴定与重量分析','Equivalence point|Endpoint|Precipitate mass','等当点|终点|沉淀质量','Titration infers amount from a known reacting quantity; the observed endpoint approximates a stoichiometric equivalence point. Gravimetry converts an isolated compound’s mass to analyte amount through a known composition.','滴定由已知反应量推断待测量，观察终点近似计量等当点。重量分析通过已知组成把分离化合物质量换算为待测物量。','A 1:1 titration uses 20 mL of 0.10 mol/L titrant. Find analyte amount in mmol.','1:1 滴定消耗 20 mL、0.10 mol/L 滴定剂，待测物量为多少 mmol？',2,'n = cV = 0.10 × 0.020 mol = 2 mmol.','An indicator endpoint can differ slightly from exact equivalence.','指示终点可略偏离精确等当点。','Every endpoint is exactly pH seven.','每个滴定终点都恰为 pH 七。'],
['分离与色谱','Partitioning|Retention|Resolution','分配|保留|分离度','Chromatography separates components through different interactions with stationary and mobile phases. Retention identifies behavior under specified conditions; resolution also depends on peak widths, so unequal retention times alone may not separate mixtures adequately.','色谱利用组分对固定相和流动相作用不同来分离。保留时间描述指定条件下行为；分离度还依赖峰宽，因此保留时间不同不一定足够分离。','Retention times differ by 4 min and two baseline peak widths sum to 4 min. Find Rs = 2Δt/(w1+w2).','两保留时间差 4 min，两基线峰宽之和 4 min，Rs = 2Δt/(w1+w2) 为多少？',2,'Rs = 2 × 4/4 = 2.','Retention time is condition-dependent evidence rather than unique identity proof.','保留时间依条件而变，并非唯一身份证明。','One retention-time match proves identity in every sample.','一次保留时间匹配能证明所有样品中的身份。'],
['光谱与定量分析','Absorbance|Beer–Lambert law|Selectivity','吸光度|比尔—朗伯定律|选择性','Absorbance is −log10 transmitted intensity fraction. In a suitable dilute range, A = εlc. Overlap, scattering, chemical changes and instrument limits can invalidate a simple one-species linear calibration.','吸光度为透射强度比例的负常用对数。合适稀溶范围内 A = εlc。重叠、散射、化学变化与仪器限制可使简单单物种线性校准失效。','If absorbance doubles at fixed path length and absorptivity, by what factor does concentration change?','光程与吸光系数固定，吸光度加倍，浓度变为几倍？',2,'A = εlc; cnew/cold = Anew/Aold = 2.','A blank corrects contributions unrelated to the target analyte under matched conditions.','匹配条件的空白可校正与目标分析物无关的贡献。','Beer–Lambert linearity is exact at every concentration and wavelength.','比尔—朗伯线性在所有浓度和波长下都精确成立。'],
['实验计划与质量控制','Blanks|Recovery|Reference materials','空白|回收率|标准物质','A quality-control plan distinguishes contamination, loss, drift and random variability. Blanks, spikes, duplicates and reference materials test different failure modes; no single control replaces all the others.','质量控制计划区分污染、损失、漂移和随机变异。空白、加标、平行样与标准物质检验不同失误，任何单一对照不能代替其余。','A 10-unit spike produces an 8-unit increase in measured analyte. Find percent recovery.','加标 10 单位后测得分析物增加 8 单位，回收率为百分之几？',80,'Recovery = 8/10 × 100% = 80%.','A spike-recovery test probes matrix and processing effects.','加标回收检验基体与处理效应。','A clean blank alone guarantees accurate recovery of analyte.','空白干净就能保证分析物准确回收。'],
['未知物综合鉴定','Orthogonal evidence|Candidate elimination|Detection limits','互补证据|候选排除|检出限','Unknown identification combines composition, separation, reaction and spectral evidence. Each observation constrains candidates; contradictory reliable evidence rejects a candidate. A missing signal only constrains abundance relative to method sensitivity.','未知物鉴定综合组成、分离、反应与光谱证据。每项观察约束候选，可靠矛盾可排除候选。未见信号只相对于方法灵敏度限制含量。','There are 8 candidates; one independent test excludes 3, and another excludes 2 different remaining candidates. How many remain?','八个候选，一项检验排除三个，另一项排除剩余中另外两个，还剩几个？',3,'8 − 3 − 2 = 3 candidates.','Failure to detect is not proof of absolute absence.','未检出不等于绝对不存在。','A missing peak proves zero concentration without considering sensitivity.','不考虑灵敏度，缺峰就证明浓度为零。']]);
expand('C07.01','An analytical measurement begins before the instrument is switched on. Define the target population or batch and the property to be reported, then choose a sampling scheme capable of representing its variation. A soil surface scoop, for example, may not represent deeper material even if its laboratory assay is exceptionally precise. Homogenization, storage, contamination and chemical changes during transport can all alter the sample. Precision concerns the spread of repeated measurements under stated conditions; accuracy concerns agreement with an appropriate reference, and bias is a systematic offset. A calibration curve relates known standard amounts to instrument response and may include a nonzero blank signal. Use standards spanning the relevant range and inspect residuals rather than automatically forcing a line through zero. Interpolation within a validated range is generally better supported than extrapolation. Matrix components can change the response relative to a simple standard solution, motivating matrix matching or standard additions when appropriate. Propagate uncertainty from sampling, preparation, calibration and measurement instead of reporting only the instrument’s final display digits. A precise result from a biased sample answers the wrong question precisely.','分析测量在开机前已经开始。先定义目标总体或批次及报告性质，再选能代表其变异的取样方案。比如表层土一勺，即使检测极精密，也可能不代表深层。均化、保存、污染和运输中的化学变化均可改变样品。精密度关注重复分散，准确性关注与合适参考的一致，偏倚是系统偏移。校准曲线联系已知标准量与信号，可有非零空白。标准应覆盖相关范围，检查残差，不应自动强迫过原点。验证范围内插值通常比外推更有依据。基体可使响应不同于简单标准液，因此可能需基体匹配或标准加入。应传播取样、制备、校准及测量不确定度，而非只报显示位数。偏倚样品的精密结果，是精确回答了错误问题。');
expand('C07.02','A titration uses a reaction with known stoichiometry to convert a measured titrant amount into an analyte amount. The reaction must be sufficiently complete, selective and fast under the chosen conditions. The equivalence point is the theoretical composition where the stoichiometric amount has been added; the endpoint is an observed signal change used to stop the experiment. Their difference is a method-dependent error that can be minimized by a suitable indicator or instrumental criterion. Standardize the titrant when its concentration cannot be established reliably from preparation alone. Account for aliquot volume, dilution factors and the actual reaction coefficient ratio rather than assuming every reaction is one to one. Gravimetric analysis instead isolates a compound of known composition, converts it to a stable weighable form and uses its mass to infer the analyte. Incomplete precipitation lowers recovery, while coprecipitated impurities or retained water can raise apparent mass. Washing must remove contaminants without dissolving excessive product, and drying to a stable mass helps establish a reproducible composition. Both methods rely on chemical selectivity and careful material accounting, not only accurate balance or burette readings.','滴定用已知计量反应把滴定剂量换算为分析物量，要求反应在所选条件下足够完全、选择性好且快。等当点是理论计量加入量，终点是实际用于停止实验的信号变化，两者差是方法误差，可选适当指示剂或仪器判据减小。若配制不能可靠确定浓度，应标定滴定剂。须计入分取体积、稀释倍数和真实计量比，不能默认所有反应 1:1。重量分析则分离已知组成化合物，转为稳定称量形式，再由质量推分析物。不完全沉淀降低回收，共沉淀杂质或残水可抬高表观质量。洗涤须除污染又不过量溶失产物，干燥至恒重有助建立可重复组成。两种方法都依赖选择性与物料核算，而非仅靠天平或滴定管精确。');
expand('C07.03','A separation succeeds when components move differently enough to distinguish their signals or collect them separately. Chromatography repeatedly partitions species between a moving phase and a stationary environment. Stronger retention in the stationary phase generally delays arrival, while flow rate and column geometry also affect retention time. Different separation modes exploit adsorption, partitioning, size, charge or affinity, so a method suitable for one mixture may fail for another. Resolution depends both on the distance between peak centres and on peak broadening. Broadening can arise from multiple flow paths, longitudinal diffusion and slow mass transfer between phases. Increasing column length may improve separation but also increases time and pressure requirements. Peak area can support quantitative analysis only with a suitable response calibration; equal areas do not necessarily imply equal masses for different compounds. A retention-time match is supportive but not unique identification because unrelated species can coelute. Couple separation with an independent detector or compare under altered conditions to strengthen identification. Also distinguish analytical separation, which measures composition, from preparative separation, which prioritizes collecting adequate purity and yield.','分离要求组分移动差异足以区分信号或分别收集。色谱让物种在流动相与固定环境之间反复分配，固定相保留越强通常越晚到达，流速与柱几何也影响保留时间。不同模式利用吸附、分配、大小、电荷或亲和，一种混合物适用的方法可能对另一种失效。分离度同时取决于峰中心距离和峰展宽，展宽可来自多路径、纵向扩散及相间传质慢。加长色谱柱可能提高分离，但增加时间和压力。峰面积只有经过适当响应校准才可定量，不同物质等面积未必等质量。保留时间相同只是支持证据，无关物种可共洗脱；结合独立检测或改变条件比较可增强鉴定。分析分离主要测组成，制备分离更关注收集纯度和产率，二者目标不同。');
expand('C07.04','Spectroscopy measures how matter interacts with electromagnetic radiation as a function of wavelength or frequency. Absorption can probe electronic, vibrational or other allowed transitions, and the selected region determines which structural information is accessible. Transmittance is the fraction of incident intensity emerging from the sample; absorbance is its negative base-ten logarithm. Beer–Lambert behavior predicts absorbance proportional to concentration and path length when the absorbing species is unchanged, the light is sufficiently monochromatic and scattering or instrumental limitations are negligible. A solvent and reagent blank estimates background contributions under matched conditions. Choose a wavelength with useful sensitivity and limited interference, then calibrate using standards in the valid range. At high absorbance, stray light and detector limits can distort linearity; at changing concentration, association or acid–base equilibria can change the absorbing species itself. For mixtures, absorbances can add under suitable independent-species assumptions, requiring multiple wavelengths or other constraints to separate contributions. A spectral feature can support identity while a calibrated signal supports amount; these are related but distinct claims that should not be conflated.','光谱测量物质与电磁辐射的作用如何随波长或频率变化。吸收可探测电子、振动等允许跃迁，所选波段决定可得结构信息。透射率是出射与入射强度之比，吸光度是其负常用对数。当吸收物种不变、光足够单色、散射和仪器限制可忽略时，比尔—朗伯关系预测吸光度正比于浓度与光程。溶剂和试剂空白估计匹配背景。应选灵敏且干扰少的波长，并用有效范围内标准校准。高吸光度时杂散光和探测器限制可破坏线性；浓度改变时缔合或酸碱平衡也可能改变吸收物种。合适独立物种假设下，混合物吸光度可相加，需多波长或其他约束分离贡献。谱征支持身份，校准信号支持含量，两者相关但不是同一结论。');
expand('C07.05','Quality control is a set of targeted checks on an entire analytical process. A reagent blank follows the procedure without intentional analyte and can reveal contamination or background signal. A field blank may also test collection and transport contamination. A duplicate tests combined sampling or measurement variability depending on where the duplication begins. A spike adds a known amount of analyte to a sample; recovery compares the measured increment with the added amount and can expose losses or matrix effects. A certified reference material provides an independent composition benchmark when its matrix and concentration range are relevant. Calibration checks interspersed through a run detect drift that a single initial calibration would miss. Define acceptance criteria and a response to failed controls before examining the sample results, rather than adjusting criteria to make a run appear successful. Randomize or balance run order where time trends could confound treatment comparisons. Preserve traceable sample identifiers, preparation records and raw measurements. A method can be precise but inaccurate, or accurate on standards but biased in real samples, so several complementary controls are necessary.','质量控制针对完整分析流程设置不同检查。试剂空白不故意加分析物但走全流程，揭示污染或背景；现场空白还能检验采集运输污染。平行样检验取样或测量变异，取决于从哪一步重复。加标向样品加入已知分析物，比较测得增量与加入量，可揭示损失或基体效应。基体和浓度范围合适的标准物质提供独立组成基准。穿插校准核查可发现初始校准遗漏的漂移。应在看样品结果前定义接受标准及控制失败后的处置，而不是事后改标准让实验显得成功。若时间趋势可能混杂处理比较，应随机或平衡运行顺序。保留可追溯编号、制备记录与原始读数。方法可精密但不准确，也可在标准液准确而在真实样品偏倚，因此需要互补控制。');
expand('C07.06','Unknown identification is an exercise in constraint combination. Begin with broad observations that do not prematurely assume a structure: phase, solubility, elemental composition or accurate mass can narrow the candidate class. Then use selective reactions, chromatographic behavior and spectra to test more specific possibilities. Each result has a sensitivity, specificity and uncertainty; a negative test means only that the target response was not detected under those conditions. A positive result can also have false alternatives if several species respond similarly. Orthogonal evidence is valuable because it constrains different features, such as elemental formula, functional groups and connectivity, rather than repeating the same assumption in several forms. Track which observations each candidate explains and which it contradicts. Do not rescue a favored candidate by silently ignoring a reliable inconsistent feature. If multiple structures remain compatible, report that ambiguity and propose the next measurement that would discriminate them. Quantitative purity and qualitative identity are separate: correctly identifying the principal component does not establish that no impurity is present. A defensible conclusion states the supported identity, relevant limits and the evidence chain connecting measurements to inference.','未知物鉴定是组合约束。先观察不预设结构的广泛性质，如相态、溶解度、元素组成或准确质量，再用选择性反应、色谱和光谱检验更具体候选。每项结果都有灵敏度、特异性和不确定度；阴性只表示该条件下未检出目标响应，阳性也可能有其他会产生类似响应的物种。互补证据约束不同特征，如分子式、官能团与连接，而不是多次重复同一假设。应记录各候选解释哪些观察、与哪些矛盾，不能为保留偏爱候选而忽略可靠冲突。若多个结构仍相容，应报告歧义并提出最能区分的下一测量。主成分身份正确不等于没有杂质，定性身份与定量纯度不同。可辩护结论应说明支持的身份、相关限制，以及从测量到推断的证据链。');

units('C06',['module.C02.06','module.C03.04'],[
['结构、命名与官能团','Connectivity|Functional groups|Skeletal notation','连接关系|官能团|键线式','Organic structures specify atom connectivity before three-dimensional shape. Functional groups organize recurring reactions. In skeletal notation, unlabeled line ends and vertices represent carbon, with enough implicit hydrogens to satisfy normal valence.','有机结构先确定原子连接，再确定三维形状。官能团组织重复出现的反应规律。键线式中未标注端点与顶点表示碳，并补足正常价态所需氢。','An acyclic saturated hydrocarbon has 5 carbons. Using CnH2n+2, find hydrogen count.','无环饱和烃有五个碳，按 CnH2n+2 求氢原子数。',12,'H = 2n + 2 = 2 × 5 + 2 = 12.','Identical molecular formulas can describe different connectivities.','相同分子式可对应不同连接结构。','A molecular formula uniquely specifies every organic structure.','分子式唯一确定所有有机结构。'],
['立体化学与构象','Chirality|Configuration|Conformation','手性|构型|构象','Stereoisomers share connectivity but differ spatially. Conformations interconvert by bond rotation, while changing configuration requires a different structural operation. Enantiomers are nonsuperimposable mirror images; diastereomers are other stereoisomers.','立体异构体连接相同而空间不同。构象可由键旋转互变，改变构型需要其他结构操作。对映体互为不可重合镜像，非对映体是其他立体异构体。','A molecule has two independent stereocentres and no internal symmetry. What is the maximum stereoisomer count?','分子有两个独立手性中心且无内部对称，最多有几个立体异构体？',4,'Maximum = 2^2 = 4.','Internal symmetry can reduce the 2^n stereoisomer maximum.','内部对称可使异构体数少于 2^n 上限。','Every molecule with two stereocentres has exactly four stereoisomers.','任何含两个手性中心的分子都恰有四个立体异构体。'],
['酸碱行为与电子流','Nucleophile|Electrophile|Curved arrows','亲核体|亲电体|弯箭头','A nucleophile donates an electron pair and an electrophile accepts one. Curved two-electron arrows begin at an electron pair or bond and end at the site receiving it. Acid–base preferences follow relative conjugate-acid strengths.','亲核体供电子对，亲电体接受电子对。双电子弯箭头从电子对或化学键起，指向接收位置。酸碱偏好取决于相对共轭酸强度。','For HA + B− ⇌ A− + HB, pKa(HB) − pKa(HA) = 3. Estimate equilibrium constant.','HA + B− ⇌ A− + HB 中，pKa(HB) − pKa(HA) = 3，估计平衡常数。',1000,'K ≈ 10^[pKa(HB) − pKa(HA)] = 10^3 = 1000.','Arrow tails identify where electrons start.','箭尾标明电子从何处出发。','An electron-pair arrow should always start at a positive charge symbol.','电子对箭头总应从正电荷符号出发。'],
['取代与消除','SN1 and SN2|E1 and E2|Competing pathways','SN1 与 SN2|E1 与 E2|竞争路径','Substitution replaces a leaving group; elimination forms a multiple bond by removing groups from neighboring atoms. Substrate crowding, nucleophile or base strength, solvent and temperature influence competing mechanisms.','取代更换离去基，消除从邻近原子移去基团形成多重键。底物拥挤、亲核体或碱强度、溶剂与温度影响竞争机制。','An SN2 rate is k[substrate][nucleophile]. Both concentrations double. By what factor does rate rise?','SN2 速率为 k[底物][亲核体]，两浓度都加倍，速率增为几倍？',4,'Rate factor = 2 × 2 = 4.','An SN2 elementary step is concerted.','SN2 基元步骤协同完成。','Every substitution necessarily forms a free carbocation intermediate.','所有取代都必经自由碳正离子中间体。'],
['加成、芳香与羰基化学','Pi-bond addition|Aromatic substitution|Carbonyl polarity','π 键加成|芳香取代|羰基极性','Addition converts a pi bond into new sigma-bond connections. Aromatic substitution can preserve an aromatic ring after temporary disruption. Carbonyl polarization makes its carbon electrophilic, enabling nucleophilic addition or acyl substitution depending on attached groups.','加成把 π 键转为新的 σ 键连接。芳香取代在短暂破坏后可恢复芳香环。羰基极化使碳呈亲电性，依附着基团不同可发生亲核加成或酰基取代。','Hydrogenation of one isolated C=C consumes how many H2 molecules per molecule of alkene?','氢化一个孤立 C=C，每个烯烃分子消耗几个 H2？',1,'One H atom adds to each carbon; total 2 H = 1 H2.','A carbonyl carbon is generally electrophilic because the C–O bond is polarized.','C—O 键极化使羰基碳通常具有亲电性。','All carbonyl compounds react by exactly the same mechanism.','所有羰基化合物都以完全相同机理反应。'],
['合成与光谱鉴定','Retrosynthesis|Chemoselectivity|Spectral constraints','逆合成|化学选择性|光谱约束','Retrosynthesis reasons backward from target bonds to plausible precursors. Forward synthesis must respect functional-group compatibility. Infrared, NMR and mass data constrain different structural features and should be combined rather than read as isolated labels.','逆合成从目标键向后推合理前体，正向合成须尊重官能团相容性。红外、核磁与质谱约束不同结构特征，应综合判断而非逐峰贴标签。','Two synthesis steps each give 80% isolated yield. Find overall percentage yield.','两步合成各有 80% 分离产率，总百分产率是多少？',64,'Overall fraction = 0.8 × 0.8 = 0.64; yield = 64%.','A proposed structure should satisfy all independent spectral constraints.','候选结构应同时满足所有独立光谱约束。','One matching spectral peak uniquely proves a molecular structure.','一个匹配谱峰即可唯一证明分子结构。']], [{title:'OpenStax · Organic Chemistry',url:'https://openstax.org/details/books/organic-chemistry'}]);
expand('C06.01','Carbon commonly forms four bonds, allowing chains, branches and rings with many different connectivities. A molecular formula counts atoms but does not show which atoms are joined, so structural isomers can share a formula. Condensed formulas group atoms into recognizable units, while skeletal drawings suppress most carbon and attached hydrogen labels. Read each unlabeled vertex and line end as carbon, count bond orders, then add the implied hydrogens needed for ordinary neutral carbon valence. Heteroatoms and hydrogens attached to them are usually shown explicitly. Functional groups identify recurring local structures such as alcohols, carbonyls, carboxylic acids, amines and alkenes; a molecule can contain several and their interactions matter. Systematic naming selects an appropriate parent skeleton, numbers it to locate substituents and principal groups, and records unsaturation and suffixes. The name is a compact structural instruction, not a substitute for drawing. A degree-of-unsaturation count compares hydrogen content with an acyclic saturated reference and can reveal rings or multiple bonds, but cannot locate them. Always verify that the final structure matches both the atom inventory and chemically plausible valences.','碳通常成四键，可形成链、支链与环等多种连接。分子式只计数原子，不说明连接，因此结构异构体可同式。简式把原子合成易识别单元，键线式省去大部分碳和相连氢。每个未标顶点与端点读作碳，数清键级，再补足普通中性碳价态所需氢；杂原子及与其相连的氢通常明写。官能团是重复局部结构，如醇、羰基、羧酸、胺和烯烃；一个分子可有多个官能团且彼此影响。系统命名选择合适母体，编号定位取代基与主官能团，并记录不饱和与后缀。名称是压缩结构指令，不能代替画图。不饱和度把氢含量与无环饱和参照比较，可提示环和多重键，但不能确定位置。最终结构应同时符合原子库存与合理价态。');
expand('C06.02','Three-dimensional structure matters because molecules interact with other structured molecules. A tetrahedral atom attached to four distinguishable substituents is a common stereogenic centre, but chirality can also arise without this motif. Chirality means that an object and its mirror image cannot be superimposed by rotation and translation. Enantiomers have identical properties in an ideal achiral environment except for opposite optical rotation, yet can behave differently with enzymes or other chiral partners. Diastereomers are stereoisomers that are not mirror-image partners and can differ in ordinary physical properties. R and S labels encode a priority-based configuration; they do not directly predict the sign of optical rotation. Conformations arise through rotations about suitable single bonds, such as staggered and eclipsed ethane or chair cyclohexane arrangements. Steric and torsional energies make some conformations more populated than others. Configuration is retained under those ordinary rotations. For n independent stereocentres, 2^n is an upper bound, not a guarantee: internal symmetry can produce meso forms and reduce the count. Draw and compare structures explicitly rather than relying on a flat left-versus-right impression.','三维结构重要，因为分子与其他有结构分子相互作用。四面体原子连接四种不同取代基是常见立体中心，但手性也可不依赖该结构。手性指物体与镜像无法经旋转平移重合。理想非手性环境中，对映体除旋光方向相反外性质相同，但与酶或手性伙伴可有不同作用。非对映体不是镜像对，普通物理性质可不同。R/S 按优先序编码构型，并不直接预测旋光正负。构象来自合适单键旋转，例如乙烷交错/重叠、环己烷椅式；位阻与扭转能影响各构象占比，普通旋转不改变构型。n 个独立立体中心的 2^n 只是上界，内部对称可产生内消旋形式并减少数量。应实际画图比较，不能凭平面左右印象判断。');
expand('C06.03','Organic mechanisms are electron-accounting models. A full curved arrow represents movement of an electron pair; its tail must begin at a lone pair or an existing bond, and its head identifies the atom or bond receiving that pair. After drawing arrows, redraw the product and check every atom’s bond count and formal charge. Nucleophiles are electron-pair donors and electrophiles are acceptors, but nucleophilicity is a kinetic property and should not be equated automatically with basicity, which is an equilibrium property. Steric hindrance and solvent can make a strong base a poor nucleophile for a particular substitution. Proton transfer compares the relative stability of acid–base partners. Resonance delocalization, electronegativity, inductive effects, hybridization and solvation can stabilize a conjugate base and increase acidity. Resonance contributors are alternative descriptions of one electronic structure, not rapidly interconverting molecules. Arrows used to relate contributors redistribute electrons without moving nuclei. Every proposed mechanism must preserve total atoms and charge, and arrows alone do not establish that the indicated path is experimentally correct; rate and product evidence must also support it.','有机机理是电子记账模型。完整弯箭头表示一对电子移动，尾部须从孤电子对或已有键出发，头部指向接收电子对的原子或键。画箭头后应重画产物并检查每个原子键数与形式电荷。亲核体供电子对，亲电体受电子对，但亲核性属于动力学性质，碱性属于平衡性质，不能自动等同。位阻与溶剂可使强碱在某取代中成为弱亲核体。质子转移比较酸碱伙伴的相对稳定；共振离域、电负性、诱导、杂化及溶剂化可稳定共轭碱并增强酸性。共振贡献式是同一电子结构的替代描述，不是快速互变分子；贡献式之间只移动电子，不移动原子核。机制须守恒原子和电荷，但画出箭头不能证明实验确实沿该路径，还需速率与产物证据。');
expand('C06.04','Substitution and elimination often compete because the same substrate and reagent can support more than one pathway. In an SN2 step, a nucleophile attacks while the leaving group departs in one concerted event. Backside approach produces inversion at an appropriate stereogenic reaction centre, and crowding around that centre slows the pathway. An SN1 mechanism begins with ionization to a carbocation-like intermediate; its rate-limiting formation can make the initial rate independent of nucleophile concentration. Such intermediates may rearrange, and product stereochemistry can reflect solvent cages rather than perfect unrestricted randomization. E2 elimination is concerted and usually requires a suitable antiperiplanar arrangement of the removed hydrogen and leaving group. E1 proceeds through an ionization intermediate shared with possible SN1 chemistry. Base strength, nucleophile character, substrate structure, leaving-group ability, solvent and temperature must be considered together. A highly substituted substrate does not mechanically select one pathway under every condition. Compare the predicted rate dependence, rearrangements and stereochemical outcomes with evidence. Product ratios reflect competing activation barriers and may change when one experimental condition is changed.','取代与消除常竞争，因为同一底物和试剂可支持多条路径。SN2 中亲核进攻与离去同步完成，背面进攻在合适反应立体中心产生构型反转，中心拥挤会减慢。SN1 先离解形成碳正离子型中间体，其形成若控速，初速可与亲核体浓度无关。中间体可能重排，产物立体化学也可能受溶剂笼影响，并非完美随机化。E2 协同消除通常需要被移除氢与离去基适当反式共平面；E1 经离解中间体，可与 SN1 共用。应同时考虑碱强度、亲核性、底物、离去能力、溶剂和温度，不能认为高取代底物在任何条件下都必选某一路。比较速率依赖、重排与立体结果来检验机理，产物比反映竞争活化势垒，改变条件可改变比例。');
expand('C06.05','An alkene’s pi bond contains accessible electron density and can react with an electrophile. Addition consumes that pi bond and creates new sigma bonds, with regioselectivity and stereoselectivity depending on the mechanism rather than a universal slogan. Aromatic systems gain stabilization from cyclic delocalization under appropriate orbital conditions. Electrophilic aromatic substitution temporarily disrupts that delocalization and then restores it by losing a proton, which helps explain why substitution can be favored over simple addition. Existing substituents affect both reaction rate and preferred position through electronic effects. A carbonyl group is polarized toward oxygen, leaving carbon susceptible to nucleophilic attack. Aldehydes and ketones commonly undergo addition, whereas carboxylic-acid derivatives bearing a suitable leaving group can undergo nucleophilic acyl substitution through a tetrahedral intermediate. Acid or base conditions alter both electrophile activation and nucleophile availability. An addition product and a substitution product are therefore not interchangeable predictions. Identify the functional group, leaving-group ability, reaction medium and proton transfers, then track atoms through each step rather than memorizing an isolated final formula.','烯烃 π 键具有易参与反应的电子密度，可与亲电体反应。加成消耗 π 键并形成新 σ 键，区域和立体选择性取决于机理，而非万能口号。芳香系统在适当轨道条件下由环状离域获得稳定。亲电芳香取代暂时破坏离域，再失质子恢复，因此常比简单加成有利；原有取代基通过电子效应改变速率与定位。羰基向氧极化，使碳易受亲核进攻。醛酮常发生加成，而带合适离去基的羧酸衍生物可经四面体中间体发生亲核酰基取代。酸碱条件同时改变亲电活化和亲核体可用性。因此加成与取代不能随意互换预测，应识别官能团、离去能力、介质和质子转移，再逐步追踪原子，而不是只背最终式。');
expand('C06.06','A synthesis plan connects a target structure to available starting materials through chemically plausible transformations. Retrosynthetic analysis disconnects a target bond conceptually and asks which precursor functional groups could form it. Those backward suggestions must then be checked forward for reagent compatibility, selectivity and the order of operations. Chemoselectivity distinguishes which functional group reacts; regioselectivity distinguishes positions; stereoselectivity distinguishes spatial products. Protecting groups can temporarily suppress one reactive site but add steps and losses, so they are a strategic tradeoff rather than an automatic requirement. Overall isolated yield multiplies step yields, making unnecessary steps costly even when each step looks efficient. Structure identification works in the opposite direction by combining constraints. Mass spectrometry constrains mass and fragmentation; infrared absorption suggests bond types; NMR chemical shifts, integrals and couplings constrain distinct environments and neighboring relationships. No single peak normally proves a whole structure. Build candidates consistent with formula and unsaturation, then reject those contradicting any reliable spectral feature. Report uncertainty when multiple candidates remain rather than treating a plausible sketch as a uniquely established molecule.','合成计划通过合理转化把可得原料连接到目标结构。逆合成在概念上切断目标键，寻找可形成该键的前体官能团；反推后须正向检查试剂相容、选择性与顺序。化学选择性区分反应官能团，区域选择性区分位置，立体选择性区分空间产物。保护基可暂时抑制位点，但增加步骤和损失，是策略权衡而非自动要求。总分离产率为各步产率乘积，即使单步高效，多余步骤仍代价明显。结构鉴定则综合约束反推结构：质谱约束质量与碎片，红外提示键类型，核磁位移、积分与耦合约束环境及邻接。单峰通常不能证明完整结构。先依据分子式与不饱和度建立候选，再排除与可靠谱征矛盾者；若仍多解，应报告不确定性，而不是把合理草图说成唯一已证分子。');

units('C05',['module.C02.06','module.C03.06'],[
['周期规律与主族化学','Valence patterns|Oxidation states|Acid–base character','价电子模式|氧化态|酸碱性质','Main-group chemistry reflects valence configurations, size and electronegativity. Oxides may be acidic, basic or amphoteric; oxidation states describe accessible electron-bookkeeping patterns but do not uniquely specify structure or reactivity.','主族化学受价电子排布、大小与电负性影响。氧化物可呈酸性、碱性或两性；氧化态描述电子记账模式，却不能唯一确定结构与反应性。','In neutral SO3 with oxygen assigned −2, find sulfur oxidation number.','中性 SO3 中氧取 −2，硫氧化数是多少？',6,'x + 3(−2) = 0; x = +6.','Members of a group resemble each other without being chemically identical.','同族元素性质相似，但并非完全相同。','Every element in a group has identical reaction rates and products.','同族每个元素的反应速率与产物完全相同。'],
['配位化合物与异构','Ligands|Coordination number|Stereoisomerism','配体|配位数|立体异构','A ligand donates electron density through donor atoms to a metal centre. Coordination number counts donor atoms, not necessarily ligand molecules. Identical formulas can have different connectivity or spatial arrangements.','配体通过给体原子向金属中心提供电子密度。配位数计数给体原子，并不一定等于配体分子数。同一组成可具有不同连接或空间排列。','Three bidentate ligands bind through two atoms each. Find coordination number.','三个双齿配体各通过两个原子配位，配位数是多少？',6,'CN = 3 × 2 = 6.','Geometric isomers can have the same formula but different spatial arrangements.','几何异构体可同式而空间排列不同。','Coordination number always equals the number of ligand molecules.','配位数总等于配体分子数。'],
['晶体场与配位场模型','Orbital splitting|Spin state|Ligand effects','轨道分裂|自旋态|配体效应','Ligands split metal d-orbital energies according to geometry. Electron pairing competes with occupying higher orbitals, producing different spin states. Ligand-field theory extends electrostatic crystal-field ideas with covalent orbital mixing.','配体按几何使金属 d 轨道能量分裂。电子配对与占据高轨道竞争，形成不同自旋态。配位场理论在静电晶体场基础上加入共价轨道混合。','An octahedral d3 configuration places three electrons singly in lower t2g orbitals. How many unpaired electrons result?','八面体 d3 的三个电子分别占据低能 t2g 轨道，未成对电子有几个？',3,'Three singly occupied t2g orbitals give 3 unpaired electrons.','Spin state depends on splitting compared with pairing cost.','自旋态取决于分裂能与配对代价的比较。','Every metal ion has the same spin state with every ligand.','同一金属离子遇任何配体自旋态都相同。'],
['过渡金属化学','Variable oxidation states|Redox|Ligand substitution','可变氧化态|氧化还原|配体取代','Closely spaced valence orbitals allow several accessible oxidation states and ligand-dependent properties. Redox changes electron count, while substitution changes ligands; either can alter geometry, magnetism and reaction rate.','接近的价轨道能量使多种氧化态可及，性质依赖配体。氧化还原改变电子数，取代改变配体，两者都可改变几何、磁性与速率。','Fe2+ is oxidized to Fe3+. How many electrons are lost per ion?','Fe2+ 氧化为 Fe3+，每个离子失去几个电子？',1,'Fe2+ → Fe3+ + e−: one electron.','Thermodynamic stability and substitution inertness are different properties.','热力学稳定与取代惰性是不同性质。','A thermodynamically stable complex must exchange ligands slowly.','热力学稳定配合物必定缓慢交换配体。'],
['固态结构与材料','Unit cells|Coordination|Defects','晶胞|配位|缺陷','A unit cell repeats a crystal’s structure by translation. Shared boundary atoms contribute fractional counts. Defects and nonstoichiometry influence conductivity and strength, so a perfect-lattice drawing is only a starting model.','晶胞通过平移重复晶体结构，边界共享原子按分数计数。缺陷与非化学计量影响导电和强度，完美晶格图只是起始模型。','A simple cubic unit cell has eight corner atoms, each shared by eight cells. How many atoms belong to one cell?','简单立方晶胞有八个角原子，各被八晶胞共享，每晶胞含几个原子？',1,'8 × 1/8 = 1 atom.','Real crystal defects can strongly affect bulk properties.','真实晶体缺陷可显著影响宏观性质。','All samples with the same ideal lattice have identical properties.','理想晶格相同的样品性质必完全相同。'],
['无机反应途径','Substitution pathways|Redox pathways|Speciation','取代途径|氧化还原途径|物种分布','Inorganic reactions may exchange ligands, transfer electrons or transfer atoms. Speciation depends on ligands, pH and oxidation conditions. A plausible pathway must conserve atoms and charge and agree with kinetic evidence.','无机反应可能交换配体、转移电子或转移原子。物种分布依赖配体、pH 与氧化条件。合理路径须守恒原子和电荷，并符合动力学证据。','A substitution replaces two water ligands with two monodentate ligands. How many leaving water molecules are released?','取代反应用两个单齿配体替换两个配位水，释放几个水分子？',2,'One-for-one replacement of two sites releases 2 H2O.','The observed product does not uniquely determine the reaction pathway.','观察到的产物不能唯一决定反应途径。','A balanced net equation fully proves one molecular mechanism.','配平净方程就完全证明一种分子机理。']]);
expand('C05.01','Main-group chemistry uses the periodic table as an explanatory framework rather than a list of isolated facts. Valence-electron configuration constrains common bonding patterns, but orbital size, effective nuclear attraction and polarizability alter those patterns down a group. Small second-period atoms often form strong multiple bonds, while heavier congeners can favor different structures or coordination numbers. Oxidation state tracks formal electron assignment; its stability depends on both the element and its chemical partners. In heavier p-block elements, lower oxidation states can become comparatively important, an observation often discussed through the inert-pair effect. Acidic oxides react with bases and basic oxides with acids; amphoteric oxides can participate in both types of reaction under suitable conditions. This classification concerns reaction behavior, not simply whether oxygen is present. Hydrides range from ionic to covalent, so their reactions with water or acids cannot be predicted from the formula label alone. Compare representative compounds by identifying bond polarity, structure, accessible oxidation changes and acid–base roles. A periodic trend generates a hypothesis; actual phase, solvent and reaction conditions decide whether the proposed reaction occurs.','主族化学把周期表作为解释框架，而不是孤立事实列表。价电子排布约束常见成键模式，但轨道大小、有效核吸引与可极化性会沿族改变这些模式。小的第二周期原子常形成强多重键，较重同族元素可偏好不同结构与配位数。氧化态记录形式电子归属，其稳定性取决于元素及化学伙伴；重 p 区元素中，低氧化态可能更重要，常用惰性电子对效应讨论。酸性氧化物与碱反应，碱性氧化物与酸反应，两性氧化物在合适条件下两者皆可。此分类关注反应行为，并非仅看是否含氧。氢化物从离子型到共价型均有，与水酸的反应不能仅凭名称预测。比较代表化合物时，应识别键极性、结构、可及氧化变化及酸碱角色。周期趋势提出假设，相态、溶剂和条件决定实际反应。');
expand('C05.02','A coordination compound contains a central atom or ion associated with ligands through donor atoms. A ligand may bind through one donor atom, several donors on the same molecule, or bridge two metal centres. Denticity counts how many donors from one ligand attach to a given centre, while coordination number counts all attached donor atoms. A chelating ligand uses multiple donor atoms, often changing complex stability through both enthalpic and entropic effects. To assign the metal oxidation state, combine the complex charge with the formal charges of its ligands; neutral ligands contribute zero to that charge calculation. Structural isomers differ in connectivity, such as which donor atom an ambidentate ligand uses. Geometric isomers preserve connectivity but change relative positions, as with cis and trans arrangements in suitable square-planar or octahedral complexes. Optical isomers are nonsuperimposable mirror images and can interact differently with chiral environments. Draw the actual geometry before counting isomers: a flat formula alone hides spatial information. The same coordination number does not guarantee one geometry, and geometry can depend on metal identity, oxidation state and ligand properties.','配位化合物含中心原子或离子及通过给体原子结合的配体。一个配体可单点结合、多点结合，也可桥连两个金属中心。齿数计数同一配体连到给定中心的给体数，配位数计数所有连接给体原子。螯合配体用多个给体结合，常通过焓与熵因素改变稳定性。确定金属氧化态时，将配合物总电荷与配体形式电荷合并，电中性配体在此计算中贡献零。结构异构体连接方式不同，例如两可配体改用另一给体原子。几何异构保持连接却改变相对位置，如合适平面正方或八面体中的顺反。光学异构体互为不可重合镜像，可与手性环境不同作用。计数异构体前应画实际几何，平面化学式隐藏空间信息。同一配位数不保证同一构型，构型还依赖金属、氧化态与配体。');
expand('C05.03','In a free isolated ion, the five d orbitals have the same energy before additional interactions are considered. A surrounding ligand arrangement breaks that equivalence because orbitals point toward or between different ligand directions. In an octahedral crystal-field picture, orbitals directed toward the six ligands are raised relative to the other three. The splitting energy competes with the energetic cost of pairing electrons. When splitting is small, electrons may occupy higher orbitals before pairing; when it is large, pairing in the lower set can be favored. The outcome depends on electron count, metal identity, oxidation state and ligand type. Counting unpaired electrons provides a first magnetic prediction, while transitions between split states can absorb visible light and contribute to colour. Colour alone is not an infallible oxidation-state label, because several transitions and environmental effects may contribute. Tetrahedral and square-planar geometries have different splitting patterns and must not inherit the octahedral diagram unchanged. Crystal-field theory treats ligands electrostatically; ligand-field and molecular-orbital descriptions include covalent mixing and can explain bonding trends that a purely electrostatic model misses.','孤立自由离子的五个 d 轨道在进一步相互作用前等能。周围配体排列破坏等价性，因为轨道分别指向配体或配体间隙。八面体晶体场中，指向六个配体的轨道相对另三个升高。分裂能与电子配对代价竞争：分裂小时可能先占高轨道再配对，分裂大时可能先在低能组配对。结果依赖电子数、金属、氧化态与配体。未成对电子数给出初步磁性预测，分裂态间跃迁可吸收可见光并贡献颜色。颜色不是绝对可靠的氧化态标签，因为多种跃迁及环境效应可同时贡献。四面体和平面正方分裂不同，不能原样套八面体图。晶体场把配体作静电处理，配位场和分子轨道描述加入共价混合，可解释纯静电模型遗漏的趋势。');
expand('C05.04','Transition-metal chemistry is diverse because several valence electronic arrangements can be close enough in energy to participate in bonding and redox chemistry. Removing electrons from a neutral atom does not always follow the simple written filling order in reverse; for common first-row transition-metal cations, outer s electrons are removed before d electrons. A metal’s oxidation state affects charge density and ligand attraction, while ligand identity can stabilize one oxidation state relative to another. Redox potentials are therefore properties of specified chemical couples and conditions, not permanent numbers belonging to an element in every environment. Complex colour and magnetism reflect electronic states and geometry. Ligand substitution changes the coordination sphere without necessarily changing oxidation state; redox changes electron bookkeeping and may occur with or without a simultaneous ligand change. Thermodynamic stability measures an equilibrium preference, whereas kinetic inertness measures how slowly exchange occurs. A complex can be stable yet labile, or metastable yet persist because exchange is slow. Predict a reaction by combining oxidation state, ligand availability, solvent, pH and possible precipitates rather than using metal identity alone.','过渡金属化学多样，因为几种价电子排布可能能量接近，参与成键与氧化还原。从中性原子移电子不总是书写填充顺序的简单倒转，常见第一过渡系阳离子通常先失外层 s 电子再失 d 电子。氧化态影响电荷密度与配体吸引，配体也能相对稳定某种氧化态。因此氧化还原电势属于指定电对和条件，并非元素在所有环境中的永久数值。颜色与磁性反映电子态与几何。配体取代改变配位层而不一定改变氧化态；氧化还原改变电子记账，可伴随或不伴随配体改变。热力学稳定衡量平衡偏好，动力学惰性衡量交换慢快。配合物可稳定但易交换，也可亚稳却因交换慢而长期存在。预测时应结合氧化态、配体、溶剂、pH 和可能沉淀，不能只看金属名称。');
expand('C05.05','A crystal is described by a repeating lattice together with a basis of atoms, ions or molecules placed at each lattice position. A unit cell is a convenient repeating region, and many cell choices can describe the same infinite structure. Count shared particles carefully: a corner contribution is shared among eight neighboring cubic cells, a face among two and an edge among four. The number of particles per cell, their molar mass and the cell volume together predict density. Coordination number describes the local number of nearest neighbors and is different from the number of particles per cell. Packing efficiency compares occupied model-sphere volume with cell volume, but atoms are not literal hard marbles in every material. Vacancies, interstitials and substitutional impurities disrupt the ideal arrangement and can carry charge or alter transport. Dislocations help explain plastic deformation, while grain boundaries separate differently oriented crystallites. A material’s chemical formula and perfect-cell diagram therefore do not determine every mechanical or electronic property. Processing history, defect concentration, temperature and phase composition can be as important as the ideal crystal structure.','晶体可用重复点阵及放在各点阵位置的原子、离子或分子基元描述。晶胞是方便的重复区域，同一无限结构可选不同晶胞。共享粒子要正确计数：立方角点由八胞共享，面由两胞共享，棱由四胞共享。每胞粒子数、摩尔质量与胞体积共同预测密度。配位数是局部最近邻数，不等于每胞粒子数。堆积效率比较模型球体积与胞体积，但真实原子并非处处都是硬弹珠。空位、间隙与替位杂质扰动理想排列，可带电或改变输运。位错帮助解释塑性形变，晶界隔开取向不同的晶粒。因此化学式与完美晶胞图不能确定所有力学或电子性质，加工历史、缺陷浓度、温度和相组成可能同样重要。');
expand('C05.06','Organize an inorganic transformation by asking which structural features change. Ligand substitution replaces one coordinated donor with another; electron transfer changes oxidation state; atom transfer changes connectivity while possibly coupling to redox. In an associative substitution picture, the entering ligand participates before the leaving ligand fully departs, whereas a dissociative picture begins with ligand loss. These labels describe limiting mechanisms, and actual pathways can lie between them. Rate dependence on entering-ligand concentration can help distinguish alternatives but should be combined with other evidence. Electron transfer may occur between species without a shared ligand bridge or through a bridging group; geometry and reorganization influence its rate. The dominant dissolved species can change with pH, ligand concentration or oxidation conditions, so the substance named on a reagent bottle may not be the reacting species. Write material and charge balances, then consider equilibrium speciation before proposing an elementary step. A plausible product is not proof of a mechanism: transient intermediates, isotope tracing, rate laws and activation trends provide stronger discrimination among pathways.','分析无机变化先问哪些结构特征改变：配体取代更换给体，电子转移改变氧化态，原子转移改变连接并可能耦合氧化还原。缔合型取代中，进入配体先参与而离去配体尚未完全离开；解离型则先失配体。二者是极限机制，真实途径可介于其间。速率对进入配体浓度的依赖可帮助区分，但应结合其他证据。电子转移可通过共同桥联配体，也可无桥进行，几何与重组影响速率。优势溶解物种随 pH、配体浓度和氧化条件变化，试剂瓶标签上的物质未必就是实际反应物种。提出基元步骤前，应列物料与电荷守恒并考虑平衡分布。得到合理产物不能证明机理，短寿命中间体、同位素追踪、速率律和活化趋势更能区分竞争途径。');

units('C04',['module.C03.06','math.derivatives','math.integrals'],[
['速率、速率律与实验测定','Reaction rate|Reaction order|Initial-rate comparison','反应速率|反应级数|初速率比较','Rate measures concentration change per time, with stoichiometric normalization when comparing species. An empirical rate law specifies how rate depends on concentrations; orders must be measured unless a justified elementary-step model applies.','速率描述单位时间浓度变化，比较不同物种时应按计量系数归一。经验速率律说明速率如何依赖浓度；除非有合理基元步骤模型，否则级数应由实验确定。','Doubling A concentration quadruples rate with other conditions fixed. Find the order in A.','其他条件不变，A 浓度加倍使速率变四倍，对 A 的级数是多少？',2,'2^n = 4, so n = 2.','Overall reaction coefficients do not generally determine the rate law.','总反应系数通常不能决定速率律。','Every rate-law exponent equals its balanced-equation coefficient.','所有速率指数都等于配平方程系数。'],
['积分速率律与半衰期','First-order decay|Integrated law|Half-life','一级衰减|积分速率律|半衰期','For first-order disappearance, d[A]/dt = −k[A], giving [A] = [A]0exp(−kt). Half-life ln2/k is concentration-independent only for this first-order model.','一级消耗满足 d[A]/dt = −k[A]，故 [A] = [A]0exp(−kt)。只有该一级模型的半衰期 ln2/k 与浓度无关。','After three first-order half-lives, what fraction remains?','经过三个一级反应半衰期，还剩初始量的多少？',0.125,'Remaining fraction = (1/2)^3 = 1/8 = 0.125.','Different reaction orders have different integrated laws.','不同反应级数具有不同积分规律。','Every reaction has a concentration-independent half-life.','所有反应的半衰期都与浓度无关。'],
['反应机理与催化','Elementary step|Intermediate|Activation barrier','基元步骤|中间体|活化势垒','A mechanism proposes elementary steps whose sum gives the overall reaction. Intermediates are formed and consumed. A catalyst provides an alternative pathway and is regenerated; it changes kinetics without changing the equilibrium constant.','机理由相加后得到总反应的基元步骤组成。中间体先生成后消耗。催化剂提供替代路径并再生，改变动力学但不改变平衡常数。','A catalyst increases both forward and reverse equilibrium rates from 2 to 10 units. By what factor are they increased?','催化剂使平衡时正逆速率都从 2 增至 10 单位，增大几倍？',5,'Rate factor = 10/2 = 5.','Catalysis does not change the reaction’s overall Gibbs-energy difference.','催化不改变反应总吉布斯能差。','A catalyst makes an unfavorable equilibrium automatically favorable.','催化剂会自动把不利平衡变为有利。'],
['氧化还原配平','Oxidation state|Half-reactions|Electron balance','氧化数|半反应|电子守恒','Oxidation loses electrons and reduction gains them. Split a redox equation into half-reactions, balance atoms and charge in the stated acidic or basic medium, then cancel equal transferred-electron counts.','氧化失电子，还原得电子。把反应拆成半反应，在指定酸性或碱性介质中平衡原子与电荷，再使转移电子数相等并约去。','An oxidation releases 2 electrons per event; a reduction consumes 3. What smallest total electron count balances both?','一次氧化放出 2 电子，一次还原消耗 3 电子，最小匹配总电子数是多少？',6,'LCM(2,3) = 6 electrons.','Oxidation and reduction occur together in a complete redox reaction.','完整氧化还原反应中，氧化与还原同时发生。','An oxidation-state change always equals a measured full ionic charge transfer.','氧化数变化总等于实测完整离子电荷转移。'],
['原电池与电解池','Anode and cathode|Cell potential|Charge transport','阳极与阴极|电池电势|电荷输运','Oxidation occurs at the anode and reduction at the cathode in both cell types. A galvanic cell supplies electrical work; an electrolytic cell uses external work to drive a chosen reaction.','两种电池中都是阳极氧化、阴极还原。原电池输出电功，电解池使用外部功驱动选定反应。','Cathode reduction potential is 0.8 V and anode reduction potential is −0.2 V. Find cell potential in V.','阴极还原电势为 0.8 V，阳极还原电势为 −0.2 V，电池电势为多少 V？',1,'Ecell = Ecathode − Eanode = 0.8 − (−0.2) = 1.0 V.','Electrode names follow reaction type, not a fixed polarity across every cell.','电极名称由反应类型决定，不是所有电池中固定正负性。','The anode is always negative in every electrochemical cell.','所有电化学池的阳极总是负极。'],
['能斯特方程与动力学区别','Concentration dependence|Reaction quotient|Overpotential','浓度依赖|反应商|过电位','The Nernst relation E = E° − RT lnQ/(nF) connects reversible potential with composition. Actual operating voltage also reflects resistance and kinetic overpotentials, so thermodynamic voltage alone does not determine current.','能斯特关系 E = E° − RT lnQ/(nF) 联系可逆电势与组成。实际工作电压还受电阻和动力学过电位影响，因此热力学电压不能单独决定电流。','At Q = 1, the logarithmic correction is zero. If E° = 1.2 V, find reversible E in V.','Q = 1 时对数修正为零，若 E° = 1.2 V，可逆 E 为多少 V？',1.2,'ln1 = 0, so E = E° = 1.2 V.','Favorable cell potential does not guarantee rapid electrode kinetics.','有利电池电势不保证电极反应迅速。','Nernst voltage alone fixes the current through any real cell.','能斯特电压单独决定任意实际电池的电流。']]);
expand('C04.01','A reaction rate describes how quickly composition changes, and the sign depends on whether a species is consumed or produced. For aA → bB, the normalized rate is −(1/a)d[A]/dt = (1/b)d[B]/dt when volume is fixed. An average rate uses a finite time interval; an instantaneous rate is the tangent slope of a concentration–time curve. A rate law such as r = k[A]^m[B]^n is an experimentally testable model over stated conditions. The exponents m and n are orders and need not be integers; their sum is the overall order. To infer one exponent by initial rates, compare experiments where only that reactant concentration changes while temperature and other relevant variables remain fixed. The ratio of rates then equals the concentration ratio raised to the unknown exponent. The rate constant’s units depend on overall order, so dimensional analysis can catch an inconsistent proposed law. Temperature usually changes k, while catalysts, surface area and transport limitations can change the observed behavior. A concentration correlation alone does not establish a unique molecular mechanism, because several mechanisms can produce the same empirical law.','反应速率描述组成变化快慢，符号取决于物种被消耗还是生成。恒体积 aA → bB 中，归一速率为 −(1/a)d[A]/dt = (1/b)d[B]/dt。平均速率使用有限时间区间，瞬时速率是浓度—时间曲线切线斜率。r = k[A]^m[B]^n 是规定条件下可实验检验的模型。m、n 为级数，不必为整数，和为总级数。初速法求某指数时，应比较只有该反应物浓度变化、温度及其他变量固定的实验，速率比等于浓度比的相应幂。k 的单位依赖总级数，量纲检查可发现错误速率律。温度通常改变 k，催化、表面积和输运限制也可改变观测行为。浓度关系不能唯一确定分子机理，因为不同机理可产生相同经验速率律。');
expand('C04.02','An integrated rate law relates concentration directly to elapsed time by solving a differential rate equation. For zero-order disappearance, concentration decreases linearly until the model ceases to apply near depletion. For first order, the fraction lost per short interval is proportional to the fraction present, producing exponential decay. Taking the natural logarithm gives ln[A] = ln[A]0 − kt, so an appropriate straight-line plot has slope −k. For a simple second-order single-reactant law, 1/[A] increases linearly instead. These plots provide diagnostics, but fitting transformed data can alter error weighting; residuals and the original measurement uncertainties still matter. Half-life means the time required for the current amount to fall by one half. It is constant through successive intervals for a first-order process, but generally changes with concentration for other orders. A pseudo-first-order experiment keeps another reactant in large excess so its concentration changes negligibly; the observed constant then includes that reactant’s approximately fixed contribution. Do not infer a mechanism solely because one transformed plot looks straight over a narrow range.','积分速率律通过解微分速率方程，把浓度直接与时间联系起来。零级消耗浓度线性下降，直到接近耗尽时模型可能失效。一级反应短时间损失比例与现有比例相关，产生指数衰减；取自然对数得 ln[A] = ln[A]0 − kt，直线斜率为 −k。简单单反应物二级反应则是 1/[A] 随时间线性增加。这些图可诊断模型，但变换数据会改变误差权重，仍应检查残差与原测量不确定度。半衰期是当前量降至一半所需时间，一级过程连续半衰期相同，其他级数通常随浓度变化。准一级实验使另一反应物大量过量，其浓度近似不变，观测常数因此包含该固定浓度的贡献。狭窄范围内某变换图看似直线，不能单独证明机理。');
expand('C04.03','A balanced overall equation reports net chemical change but hides the molecular sequence. A mechanism proposes elementary events, each with a limited number of directly participating particles. Adding its steps must cancel intermediates and recover the observed overall equation. Intermediates are produced in one step and consumed in another; a catalyst is consumed and subsequently regenerated, so it does not appear in the net equation. A transition state is different from an intermediate: it is a high-energy configuration along a reaction path, not a stable species that accumulates. Activation energy or activation free energy controls the sensitivity of rate to temperature and pathway. A catalyst offers an alternative sequence with more accessible barriers; it does not change the starting and ending thermodynamic states. A proposed slow step can help derive a rate expression, but if it contains an unmeasured intermediate, additional equilibrium or steady-state reasoning is needed. The steady-state approximation says an intermediate’s production and consumption nearly balance after an initial transient; it does not mean the whole reaction is at equilibrium. Mechanisms must be tested against rates, isotope effects, detected intermediates and other independent observations.','总方程只报告净变化，隐藏分子过程。机理提出直接参与粒子数有限的基元步骤，相加后应约去中间体并恢复总方程。中间体在一步生成、另一步消耗；催化剂先消耗后再生，因此不出现在净方程中。过渡态不同于中间体，它是路径上的高能构型，不是能积累的稳定物种。活化能或活化自由能控制速率对温度及路径的敏感性。催化剂提供势垒更易跨越的替代序列，却不改变始末热力学状态。慢步骤可帮助推导速率式，但若含未测中间体，还需平衡或稳态推理。稳态近似指初始暂态后，中间体生成和消耗近似平衡，并不意味着整个反应处于化学平衡。应以速率、同位素效应、检出的中间体及其他独立观察检验机理。');
expand('C04.04','Oxidation numbers are a systematic bookkeeping convention for electron assignment. In a neutral species their sum is zero, and in an ion the sum equals the ionic charge. Rules such as oxygen usually being −2 and hydrogen usually +1 have exceptions, so inspect peroxides, hydrides and unusual bonding rather than applying rules blindly. An increase in oxidation number identifies oxidation; a decrease identifies reduction. For half-reaction balancing in acidic aqueous solution, balance non-hydrogen and non-oxygen atoms first, oxygen using water, hydrogen using H+, and finally charge using electrons. Multiply the half-reactions so electrons cancel before adding them. For a basic medium, neutralize any introduced H+ by adding equal OH− to both sides and simplify water. Finally recount every element and the total charge. Electrons must not remain in the summed closed redox equation. Oxygen transfer is a useful historical example of oxidation but is not the definition: metal-ion electron transfer can be redox without any oxygen. Oxidation-number changes describe electron bookkeeping and need not imply that each covalent atom carries an integer measured physical charge.','氧化数是系统化电子归属记账规则。中性物种总和为零，离子总和等于离子电荷。氧通常为 −2、氢通常为 +1，但过氧化物、氢化物及特殊成键有例外，不能机械套用。氧化数升高表示氧化，降低表示还原。酸性水溶液半反应配平时，先配除氢氧外元素，再用水配氧、H+ 配氢、电子配电荷。倍乘使电子数相等后相加。碱性介质中，用两侧等加 OH− 中和引入的 H+ 并化简水。最后复核所有元素和总电荷，完整闭合氧化还原式中不能残留电子。氧转移是历史上的典型氧化，但不是定义；金属离子电子转移无需氧也可为氧化还原。氧化数变化属于电子记账，不意味着共价原子实际带整数电荷。');
expand('C04.05','An electrochemical cell separates coupled oxidation and reduction so electron transfer can pass through an external circuit. Oxidation always occurs at the anode and reduction always at the cathode; these definitions survive when switching between galvanic and electrolytic operation. In a galvanic cell, spontaneous chemical change supplies electrical work. In electrolysis, an external source drives a reaction against its spontaneous tendency. The polarity of an electrode therefore cannot be memorized independently of operating mode. Ionic movement in an electrolyte or salt bridge maintains bulk charge balance; electrons do not simply travel through the salt bridge as they do through a metal wire. Tabulated standard electrode potentials are commonly reduction potentials. Calculate the standard cell potential by subtracting the anode reduction potential from the cathode reduction potential, without multiplying potentials when balancing electron counts. Potential is intensive; Gibbs-energy change scales with reaction amount through ΔG = −nFE. A real cell under load also experiences internal resistance, concentration changes and electrode polarization. Material compatibility, products and competing electrode reactions determine practical behavior beyond the ideal voltage calculation.','电化学池分开相互耦合的氧化与还原，使电子经外电路传递。阳极始终氧化、阴极始终还原，这一定义在原电池与电解池间保持不变。原电池由自发化学变化输出电功，电解则由外电源驱动逆自发趋势的反应，因此不能脱离运行方式死记电极正负。电解液或盐桥中的离子运动维持宏观电荷平衡，电子不会像在金属导线中那样穿过盐桥。表列标准电势通常为还原电势，电池标准电势等于阴极还原电势减阳极还原电势；配平电子时不能倍乘电势。电势是强度量，吉布斯能通过 ΔG = −nFE 随反应量缩放。负载下真实电池还受内阻、浓度变化与极化影响，材料兼容、产物及竞争电极反应决定理想电压之外的实际表现。');
expand('C04.06','The Nernst equation follows from combining composition-dependent reaction Gibbs energy with electrical work. For a reaction transferring n electrons, E = E° − (RT/nF)lnQ, using the same reaction direction and quotient convention as the tabulated standard potential. Pure solid and liquid activities often cancel, while dissolved-ion activities or gas pressures remain. At equilibrium the reversible full-cell voltage is zero for the specified reaction, linking the standard voltage to the equilibrium constant. The electron count n scales the Gibbs-energy conversion, but multiplying a reaction does not multiply its potential because the quotient and electron count change consistently. A measured open-circuit voltage approximates a reversible potential only under suitable equilibration and negligible leakage. Drawing current drives the system away from that limit. Ohmic resistance produces a voltage drop, while finite reaction rates require activation overpotential; concentration gradients create additional polarization. Thus thermodynamic favorability predicts a possible direction and maximum reversible work, not an operating current. Interpreting a battery, corrosion process or electrolysis experiment requires combining Nernst thermodynamics with transport and electrode kinetics rather than treating voltage as a complete performance model.','能斯特方程由组成相关的反应吉布斯能与电功关系结合得到。转移 n 电子的反应满足 E = E° − (RT/nF)lnQ，方向与反应商约定须与标准电势一致。纯固液活度常约去，溶解离子活度或气体压强保留。指定总反应平衡时，可逆全电池电压为零，从而联系标准电压与平衡常数。n 使吉布斯能转换缩放，但倍乘反应不倍乘电势，因为 Q 与 n 同步改变。开路实测电压只有在充分平衡、泄漏可忽略等条件下才近似可逆电势。输出电流使系统偏离该极限：电阻造成压降，有限反应速率需活化过电位，浓度梯度另生极化。因此热力学只预测可能方向与最大可逆功，而非工作电流。分析电池、腐蚀或电解，必须结合能斯特热力学、输运与电极动力学。');

units('C03',['chemistry.concentration','chemistry.reactions','math.powers-roots'],[
['焓与赫斯定律','Enthalpy|Calorimetry|Hess law','焓|量热|赫斯定律','Enthalpy H = U + pV is a state function. At constant pressure with only pressure–volume work, heat equals enthalpy change. Hess’s law adds reaction enthalpies because state-function differences depend only on endpoints.','焓 H = U + pV 是状态函数。恒压且仅有体积功时，热等于焓变。赫斯定律可将反应焓相加，因为状态函数差只取决于始末态。','Two consecutive reaction steps have enthalpies −40 and +15 kJ. Find total in kJ.','连续两步反应焓为 −40 和 +15 kJ，总焓变为多少 kJ？',-25,'ΔHtotal = −40 + 15 = −25 kJ.','Reversing a reaction reverses its enthalpy-change sign.','反转反应会反转焓变符号。','Enthalpy change is unchanged when the reaction is reversed.','反应反转时焓变不变。'],
['熵与吉布斯能','Entropy|Gibbs energy|Spontaneity conditions','熵|吉布斯能|自发条件','At constant temperature and pressure, a negative reaction Gibbs-energy change favors forward change under the stated composition. ΔG = ΔH − TΔS combines energetic and entropic contributions. Favorability does not specify reaction speed.','恒温恒压下，给定组成的反应吉布斯能变为负时，正向变化有利。ΔG = ΔH − TΔS 综合能量与熵贡献，但有利性不决定速率。','ΔH = 10 kJ, T = 300 K and ΔS = 0.05 kJ/K. Find ΔG in kJ.','ΔH = 10 kJ，T = 300 K，ΔS = 0.05 kJ/K，ΔG 为多少 kJ？',-5,'ΔG = 10 − 300 × 0.05 = −5 kJ.','Temperature and entropy units must be consistent.','温度与熵的单位必须一致。','A negative ΔG guarantees an instantly fast reaction.','ΔG 为负保证反应瞬间完成。'],
['平衡常数与反应商','Dynamic equilibrium|Reaction quotient|Mass action','动态平衡|反应商|质量作用','The reaction quotient Q uses current activities with stoichiometric exponents. At equilibrium Q = K. If Q < K, forward change is favored until equilibrium is approached; pure solid activities are normally one.','反应商 Q 用当前活度及计量指数计算，平衡时 Q = K。Q < K 时正向变化有利；通常纯固体活度为一。','For A ⇌ B with K = 4, equilibrium activity of A is 0.2. Find activity of B.','A ⇌ B 的 K = 4，平衡时 A 活度为 0.2，B 活度是多少？',0.8,'K = aB/aA; aB = 4 × 0.2 = 0.8.','Equilibrium has equal forward and reverse rates.','平衡时正逆反应速率相等。','Equilibrium means all molecular reactions stop.','平衡意味着所有分子反应停止。'],
['酸、碱与缓冲液','Proton transfer|Dissociation constants|Buffer action','质子转移|解离常数|缓冲作用','A Brønsted acid donates a proton and a base accepts one. Conjugate partners differ by one proton. A weak-acid/conjugate-base mixture can resist small pH changes, within its finite buffer capacity.','布朗斯特酸供出质子，碱接受质子。共轭伙伴相差一个质子。弱酸与共轭碱混合物可在有限容量内抵抗小幅 pH 变化。','For ideal dilute solution with [H+] = 10^-3 mol/L, find pH.','理想稀溶液 [H+] = 10^-3 mol/L，pH 是多少？',3,'pH ≈ −log10[H+] = 3.','Strong acid describes dissociation tendency, not simply high concentration.','强酸描述解离倾向，并非只是浓度高。','Every concentrated acid is a strong acid.','所有浓酸都是强酸。'],
['溶解度与配位平衡','Solubility product|Ion product|Complex formation','溶度积|离子积|配合物形成','A solubility product describes ion activities at equilibrium with a solid. Precipitation is favored when the ion product exceeds Ksp. Complexation can lower free-metal activity and thereby increase total dissolved metal.','溶度积描述与固体平衡的离子活度。离子积超过 Ksp 时沉淀有利。配位可降低游离金属活度，从而提高总溶解金属量。','For ideal AB(s) ⇌ A+ + B− with Ksp = 4×10^-6, find molar solubility in pure water.','理想 AB(s) ⇌ A+ + B−，Ksp = 4×10^-6，纯水中摩尔溶解度是多少 mol/L？',0.002,'Ksp = s²; s = √(4×10^-6) = 0.002 mol/L.','Total dissolved metal and free metal ion are different quantities.','总溶解金属与游离金属离子是不同量。','Complexation can never influence solubility.','配位永远不会影响溶解度。'],
['耦合平衡与近似检查','Mass balance|Charge balance|Approximation validity','物料守恒|电荷守恒|近似有效性','Multiple equilibria share species and must satisfy equilibrium relations together with total-material and charge balances. A neglected term is justified only after the solution shows it is sufficiently small for the desired accuracy.','多个平衡共享物种，必须同时满足平衡关系、总物料守恒与电荷守恒。只有求解后确认被忽略项足够小，近似才达到所需精度。','An approximation neglects x = 0.002 in an initial amount 0.10. Find the neglected percentage.','近似在初始量 0.10 中忽略 x = 0.002，忽略比例为百分之几？',2,'100x/C = 100 × 0.002/0.10 = 2%.','Approximation checks follow the provisional solution.','近似应在得到试算解后检验。','A small equilibrium constant always permits every concentration change to be ignored.','平衡常数小就总能忽略全部浓度变化。']]);
expand('C03.01','Separate the system from its surroundings before assigning a heat sign. Heat entering the system is positive; an exothermic reaction transfers heat outward and has negative enthalpy change under the usual constant-pressure conditions. Internal energy includes microscopic energy storage, whereas enthalpy adds the pressure–volume term needed for convenient constant-pressure accounting. A calorimeter infers transferred heat from a measured temperature change using heat capacity. For a solution, q = mcΔT is an approximation requiring an appropriate specific heat and allowance for the container’s own heat capacity. The reacting system’s heat is opposite to the surroundings’ heat when other losses are negligible. Hess’s law allows equations to be reversed, multiplied and added: reverse the enthalpy sign when reversing an equation and multiply the enthalpy when scaling its coefficients. Standard formation enthalpies describe forming one mole of a substance from elements in their specified reference states. Sum product coefficients times formation enthalpies and subtract the corresponding reactant sum. Always retain phase labels: liquid water and water vapour have different enthalpies, so silently changing the phase changes the problem.','指定热量符号前先区分系统与环境。进入系统的热为正；通常恒压条件下，放热反应向外传热，焓变为负。内能描述微观储能，焓增加 pV 项，便于恒压核算。量热计由温度变化与热容推断热量。溶液 q = mcΔT 是近似，需选合适比热并考虑容器热容；若其他损失可忽略，反应系统的热与环境的热互为相反数。赫斯定律允许方程反向、倍乘、相加：反向时焓变变号，倍乘系数时焓变也倍乘。标准生成焓对应元素从指定参考态生成一摩尔物质。按系数求产物生成焓总和，再减反应物总和。相态标签必须保留，液态水与水蒸气焓不同，暗中换相态就是改变问题。');
expand('C03.02','Entropy measures how energy and matter can be distributed among compatible microscopic states; calling it disorder is at best an incomplete analogy. Melting, mixing and gas expansion often increase entropy because more configurations become accessible, but a complete calculation must consider the specific process. The second law constrains total entropy of system plus surroundings. At constant temperature and pressure, Gibbs energy packages that total-entropy criterion into a system property. In ΔG = ΔH − TΔS, use kelvin and matching energy units. A reaction with positive enthalpy can still be favorable if the entropy term is sufficiently large. Standard reaction Gibbs energy refers to specified standard activities, while actual reaction Gibbs energy depends on current composition through ΔG = ΔG° + RT ln Q. Equilibrium is reached when the reaction Gibbs-energy change becomes zero, not when the system’s total Gibbs energy is literally zero. Thermodynamic favorability gives a direction under stated constraints; activation barriers can make a favorable transformation extremely slow. Diamonds and combustible fuels illustrate why a driving force and a kinetic pathway must be considered separately.','熵衡量能量和物质在相容微观态间分配的可能性，“混乱度”最多是不完整类比。熔化、混合和气体膨胀常使可及构型增加，但完整计算须针对具体过程。第二定律约束系统加环境的总熵。恒温恒压下，吉布斯能把总熵判据转化为系统性质。ΔG = ΔH − TΔS 中须用开尔文及匹配的能量单位。焓变为正的反应，若熵项足够大，仍可有利。标准反应吉布斯能对应标准活度，实际值则通过 ΔG = ΔG° + RT ln Q 依赖组成。平衡意味着反应吉布斯能变为零，不是系统总吉布斯能数值为零。热力学给出指定约束下的方向，但活化势垒可使有利变化极慢，因此驱动力与动力学途径必须分别考虑。');
expand('C03.03','A reversible reaction can proceed in both directions while its macroscopic composition remains constant. At equilibrium the two rates match; individual molecules continue to react. For a reaction aA + bB ⇌ cC + dD, the reaction quotient uses product activities raised to c and d divided by reactant activities raised to a and b. Activities are dimensionless effective concentrations relative to standard states. Concentrations or partial pressures can approximate them in suitable dilute or ideal conditions. Pure condensed phases usually have unit activity while present, which is why their amounts do not appear explicitly in the simplest equilibrium expression. Changing a reaction’s direction inverts K; multiplying all coefficients by a factor raises K to that factor. At a fixed temperature K is a property of the specified reaction, while Q changes as composition changes. Adding a reactant can therefore change Q without changing K. A catalyst accelerates approach in both directions but does not alter the equilibrium constant. Temperature changes can change K, and pressure changes influence gas equilibria through composition and volume rather than a universal rule that every reaction shifts the same way.','可逆反应可持续双向进行，而宏观组成保持恒定。平衡时正逆速率相等，分子仍在反应。对 aA + bB ⇌ cC + dD，反应商为产物活度按系数乘方之积，除以反应物对应之积。活度是相对标准态的无量纲有效浓度；合适稀溶液或理想条件下可用浓度或分压近似。纯凝聚相存在时通常取单位活度，因此其量不显式出现。反向反应使 K 取倒数，全部系数乘某因子则 K 乘相应幂。温度固定时，K 属于指定反应，而 Q 随组成改变；加反应物可改变 Q 而不改变 K。催化剂加速两个方向接近平衡，不改变 K。温度可改变 K，压强通过气体组成与体积影响平衡，不能机械认为所有反应都朝同一方向移动。');
expand('C03.04','Acid and base labels describe a reaction role. A Brønsted acid donates H+ to a base, producing its conjugate base and the base’s conjugate acid. Water can play either role. For a weak acid HA, Ka describes HA + H2O ⇌ H3O+ + A− with water activity absorbed into the convention. A smaller pKa means a larger Ka and a stronger acid under comparable conditions. Strong and weak refer to dissociation tendency; concentrated and dilute refer to amount per volume. The pH definition uses hydrogen-ion activity, so the familiar negative logarithm of concentration is an ideal dilute approximation. A buffer contains appreciable amounts of a weak acid and its conjugate base. Added acid is consumed mainly by the base component, while added base consumes the acid component. The Henderson–Hasselbalch relation connects pH to pKa and the conjugate-pair activity ratio, but it presumes the relevant equilibrium description is valid. Buffer capacity is finite: near exhaustion of one component, a small addition can cause a large pH change. A titration equivalence point concerns stoichiometric consumption and is not automatically pH seven.','酸碱标签描述反应角色。布朗斯特酸向碱供出 H+，生成其共轭碱与原碱的共轭酸；水可扮演任一角色。弱酸 HA 的 Ka 描述 HA + H2O ⇌ H3O+ + A−，水活度吸收到约定中。可比条件下，pKa 越小、Ka 越大、酸越强。强弱描述解离倾向，浓稀描述单位体积含量。pH 严格使用氢离子活度，浓度负对数是理想稀溶液近似。缓冲液含显著量弱酸及其共轭碱；加酸主要被碱组分消耗，加碱主要消耗酸组分。亨德森—哈塞尔巴尔赫关系联系 pH、pKa 与共轭对活度比，但需相关平衡模型成立。缓冲容量有限，一种组分接近耗尽时，少量加入就可导致大幅 pH 改变。滴定等当点表示计量消耗完成，并不自动等于 pH 七。');
expand('C03.05','Solubility is a total dissolved amount under specified conditions, whereas a solubility product is an equilibrium constant written in terms of particular free-ion activities. For a salt producing unequal numbers of ions, the stoichiometric powers matter: AB2 gives a product involving one A activity and the square of B activity. In pure water with no other reactions, those activities can sometimes be related directly to a single molar-solubility variable. A common ion changes the starting composition and usually suppresses dissolution in the simple model, so the pure-water square-root shortcut is no longer valid. Compare the current ion product with Ksp to predict whether a solution is undersaturated, saturated or thermodynamically supersaturated. Nucleation barriers can delay visible precipitation even when it is favorable. Ligands form complexes with metal ions and reduce the free-ion activity at a given total metal concentration. This can drive additional solid dissolution. Acid–base reactions may similarly remove a dissolved ion, coupling pH and solubility. Distinguish free metal, complexed metal and total dissolved metal, and use material balances to connect them.','溶解度是在指定条件下的总溶解量，溶度积则是用特定游离离子活度写成的平衡常数。若盐释放不等数目的离子，计量指数重要，例如 AB2 的离子积包含 A 活度一次方及 B 活度平方。纯水且无其他反应时，可把活度与单一溶解度变量联系。加入共同离子改变初组成，在简单模型中通常抑制溶解，因此纯水平方根捷径不再适用。比较当前离子积与 Ksp，可判断未饱和、饱和或热力学过饱和；即使沉淀有利，成核势垒仍可延迟可见沉淀。配体络合金属会在给定总金属浓度下降低游离活度，驱动更多固体溶解。酸碱反应也可移除某溶解离子，将 pH 与溶解度耦合。必须区分游离、配合及总溶解金属，并通过物料守恒连接。');
expand('C03.06','A coupled-equilibrium problem cannot usually be solved by treating every reaction as if the others did not exist. List the chemically distinct species first, then write independent equilibrium relations and analytical totals. A material balance counts each conserved element or component across all its species; a charge balance sums positive and negative ionic charge in the bulk solution. Water autoionization may need inclusion when acid or base concentrations are very small. Choose unknowns that reduce redundancy, such as free hydrogen-ion concentration and free ligand concentration, and express other species through equilibrium ratios. Approximations are hypotheses: neglecting a dissociated amount against the starting concentration must be checked after obtaining the tentative result. The common five-percent criterion is a rough classroom tolerance, not a universal scientific law. When it fails, retain the term and solve the resulting quadratic or numerical system. Also check positivity, conservation totals and whether the assumed dominant species actually dominates. A mathematically real root can be physically impossible if it implies negative concentration or consumes more material than was available.','耦合平衡不能通常把每个反应当作其他反应不存在来解。先列不同物种，再写独立平衡关系与分析总量。物料守恒在所有物种中计数每个保守元素或组分，电荷守恒则平衡溶液正负离子电荷。酸碱极稀时，须计入水自解离。可选择游离氢离子或配体浓度为未知量，通过平衡比表达其他物种，以减少冗余。近似是待检验假设：忽略解离量相对于初浓度，必须求出试算值后检查。常见百分之五规则只是课堂粗略容差，不是普适科学定律。若不满足，应保留该项并解二次或数值方程。还须检查浓度非负、总量守恒以及假定优势物种是否真占优。数学实根若给出负浓度或消耗量超过库存，便不具物理意义。');

units('C01',['chemistry.matter','math.ratios'],[
['粒子、物质与混合物','Elements and compounds|Mixtures|Physical separation','元素与化合物|混合物|物理分离','An element contains one atomic-number type; a compound has chemically bonded elements in a characteristic composition. A mixture combines substances without requiring a fixed ratio. Homogeneity concerns the scale of observation.','元素由同一原子序数类型构成，化合物由元素按特定组成化学结合而成。混合物不要求固定比例，均匀性还取决于观察尺度。','A mixture contains 8 g salt and 32 g water. Find salt mass fraction.','混合物含 8 g 盐和 32 g 水，盐的质量分数是多少？',0.2,'wsalt = 8/(8 + 32) = 0.20.','A compound and a mixture differ in chemical identity, not simply appearance.','化合物与混合物的区别在于化学组成，并非仅看外观。','Every homogeneous sample is a pure substance.','所有均匀样品都是纯物质。'],
['原子质量、摩尔与组成','Relative atomic mass|Molar mass|Composition','相对原子质量|摩尔质量|组成','A mole contains exactly 6.02214076×10^23 specified entities. Molar mass converts mass to amount through n = m/M. Average atomic masses reflect isotope abundances rather than requiring every atom to have that mass.','一摩尔包含恰好 6.02214076×10^23 个指定微粒。摩尔质量通过 n = m/M 把质量换算为物质的量。平均原子质量反映同位素丰度，不意味着每个原子都有该质量。','A sample has mass 18 g and molar mass 18 g/mol. Find amount in mol.','样品质量 18 g，摩尔质量 18 g/mol，物质的量为多少 mol？',1,'n = m/M = 18/18 = 1 mol.','The counted entity must be specified when reporting moles.','报告摩尔数时必须指明所计数的实体。','One mole always weighs one gram.','一摩尔总是重一克。'],
['反应方程与守恒','Atom balance|Stoichiometric coefficients|Charge balance','原子守恒|计量系数|电荷守恒','Balance equations by changing coefficients, never the formulas of participating species. Coefficients give amount ratios for the stated reaction. Ionic equations must conserve total electric charge as well as every element.','配平时改变系数，不能改变参与物种的化学式。系数表示该反应的物质的量比例，离子方程还必须同时守恒总电荷和每种元素。','For 2H2 + O2 → 2H2O, how many mol H2O form from 3 mol O2 with excess H2?','反应 2H2 + O2 → 2H2O 中，氢气过量，3 mol O2 可生成多少 mol H2O？',6,'n(H2O) = 2 × n(O2) = 6 mol.','Coefficients change the number of formula units, not each unit’s composition.','系数改变化学式单元数，不改变各单元组成。','Balancing allows changing H2O into H2O2.','配平允许把 H2O 改为 H2O2。'],
['限量试剂与产率','Reaction extent|Limiting reagent|Percent yield','反应进度|限量试剂|产率','Compare initial amounts divided by stoichiometric coefficients to identify the limiting reagent. The smallest ratio sets maximum reaction extent. Actual isolated product divided by theoretical product defines fractional yield.','把初始物质的量除以计量系数并比较，最小比值确定限量试剂及最大反应进度。实际分离产物量除以理论产物量得到产率。','Theoretical product is 20 g; isolated product is 15 g. Find percentage yield.','理论产物为 20 g，实际分离 15 g，百分产率是多少？',75,'Yield = 15/20 × 100% = 75%.','The reagent with the smallest mass need not be limiting.','质量最小的试剂不一定限量。','The largest stoichiometric coefficient always identifies the limiting reagent.','系数最大者总是限量试剂。'],
['溶液与浓度','Molarity|Dilution|Solution volume','物质的量浓度|稀释|溶液体积','Molarity is dissolved amount per solution volume, usually mol/L. Dilution conserves solute amount when none reacts or is lost, so c1V1 = c2V2. Final solution volume is not always the sum of component volumes.','物质的量浓度为溶质物质的量除以溶液体积，常用 mol/L。无反应且无损失时，稀释保持溶质量不变，因此 c1V1 = c2V2。最终溶液体积不一定等于组分体积之和。','Dilute 100 mL of 2 mol/L solution to 400 mL. Find final concentration in mol/L.','100 mL、2 mol/L 溶液稀释至 400 mL，终浓度为多少 mol/L？',0.5,'c2 = c1V1/V2 = 2 × 100/400 = 0.5 mol/L.','Molarity uses total solution volume.','物质的量浓度使用溶液总体积。','Molarity always uses the starting solvent volume alone.','物质的量浓度总只用初始溶剂体积。'],
['气体与定量化学模型','Ideal gas equation|Partial pressure|Model range','理想气体方程|分压|模型范围','For dilute gases, pV = nRT links amount with pressure, volume and absolute temperature. Ideal-mixture partial pressures add; each equals mole fraction times total pressure. High pressure and condensation can invalidate the ideal model.','稀薄气体中 pV = nRT 联系物质的量、压强、体积与绝对温度。理想混合气体分压相加，各分压等于摩尔分数乘总压。高压与冷凝可能使理想模型失效。','A gas has mole fraction 0.25 in a 200 kPa ideal mixture. Find its partial pressure in kPa.','理想混合气总压为 200 kPa，某气体摩尔分数 0.25，分压为多少 kPa？',50,'pi = xi ptotal = 0.25 × 200 = 50 kPa.','Gas-law temperature must be absolute.','气体定律温度必须采用绝对温标。','Real gases remain exactly ideal at any pressure.','真实气体在任意压强下都严格理想。']]);
expand('C01.01','A substance has a reproducible chemical identity; its physical state may still change. Ice, liquid water and water vapour all contain H2O, whereas hydrogen peroxide contains different molecules and is a different substance. An element is defined by proton number, not by whether it appears as single atoms: oxygen gas commonly contains O2 molecules but is still an element. A compound has constituent atoms chemically combined, so separating it into elements requires chemical change. Mixtures can have variable composition: salty water can be dilute or concentrated without creating a new compound. A homogeneous mixture looks uniform at the chosen scale; a suspension contains distinguishable dispersed material. Physical separation exploits a property difference. Filtration retains particles too large for pores but does not remove dissolved ions. Distillation uses volatility differences, and chromatography uses different affinities for moving and stationary phases. Select the method from particle size, solubility or volatility, rather than from the colour of the sample. A separation can fail when the relevant properties are too similar or when heating changes the substances chemically.','物质具有可重复的化学身份，但物态可以变化。冰、液态水和水蒸气都含 H2O；过氧化氢具有不同分子，是另一种物质。元素由质子数定义，不取决于是否以单原子存在；氧气通常含 O2 分子，仍是元素单质。化合物中原子发生化学结合，拆成元素需要化学变化。混合物组成可变，盐水变浓或变稀不意味着产生新化合物。均相混合物在选定尺度上均匀，悬浊液则有可区分的分散物。物理分离利用性质差异：过滤截留大于孔径的颗粒，却不能去除溶解离子；蒸馏利用挥发性差异，色谱利用对流动相与固定相的亲和差异。应根据粒径、溶解度或挥发性选择方法，而非只凭颜色。当性质过于相似，或加热引发化学变化时，分离方法可能失败。');
expand('C01.02','Chemical amounts require three distinct levels: the mass of one microscopic entity, a count of entities, and the mass of a macroscopic sample. Relative atomic mass compares an atom with one twelfth of the carbon-12 atomic mass; it is dimensionless. Molar mass instead has units such as grams per mole. Isotopes share proton number but differ in neutron number, so a natural sample can contain atoms with different masses. A tabulated average is the abundance-weighted mean, not the mass of a special average isotope. The mole is a counting unit like a dozen but vastly larger. Always specify atoms, molecules, ions or formula units. The molar mass of H2O is obtained by adding two hydrogen contributions and one oxygen contribution. To find elemental mass percentage, divide the element’s total mass contribution in one formula amount by the compound’s molar mass. Conversely, empirical formulas follow by converting each elemental mass to moles, dividing by the smallest amount and seeking a simple whole-number ratio. An empirical formula gives a ratio; a molecular formula additionally needs molecular molar mass.','化学计量应区分单个微观实体质量、实体个数和宏观样品质量。相对原子质量以碳-12 原子质量的十二分之一为基准，是无量纲比值；摩尔质量则有 g/mol 等单位。同位素质子数相同、中子数不同，自然样品可能混有不同质量原子。表列平均值是丰度加权平均，不代表一种特殊“平均同位素”。摩尔像打一样是计数单位，但数量巨大，必须指定原子、分子、离子或化学式单元。H2O 摩尔质量由两个氢和一个氧的贡献相加得到。元素质量百分比等于一个化学式量中该元素的质量贡献除以化合物摩尔质量。反求实验式时，先把各元素质量换成摩尔数，再除以最小值，寻找简单整数比。实验式只给比例，分子式还需要分子摩尔质量。');
expand('C01.03','A chemical equation states which species disappear and appear, along with their relative amounts. The formula of each species records its identity; changing a subscript changes that identity. Balancing therefore changes only the multipliers placed before formulas. Start by listing the number of atoms of each element on both sides. Choose coefficients so each inventory agrees, then reduce to the smallest convenient whole-number set. For ions, perform a separate charge count: conserving atoms alone is insufficient. State symbols such as solid, liquid, gas and aqueous distinguish phases and help determine whether a net ionic reaction occurs. In a net ionic equation, spectator ions that remain unchanged on both sides are removed. Coefficients describe amount ratios, not mass ratios; equal coefficients can correspond to very different masses because molar masses differ. They also do not generally give a rate law: a reaction may occur through several hidden steps. In stoichiometric calculations, convert the supplied mass or concentration into amount first, apply the coefficient ratio, and only then convert to the requested final quantity.','化学方程说明哪些物种消失、哪些出现，以及相对数量。化学式记录物种身份，改变下标就改变物质，因此配平只改化学式前的系数。先列两侧各元素原子数，再选择系数使每项库存一致，最后化为方便的最简整数比。离子反应还需独立计算总电荷，仅原子守恒不够。固、液、气、水溶液等状态符号区分相态，并帮助判断净离子反应。净离子方程中可约去两侧不变的旁观离子。计量系数给物质的量比而非质量比，因为摩尔质量不同。系数通常也不能直接给速率定律，反应可能经历多个隐藏步骤。计算时先把给定质量或浓度转换为物质的量，使用系数比，再转为目标量。');
expand('C01.04','A balanced reaction can be imagined as a recipe applied repeatedly. If a recipe consumes two units of A for every one unit of B, three units of A cannot consume three units of B completely. Define a trial reaction extent by dividing each available reactant amount by the number of units it consumes per recipe. The smallest value limits how many complete recipe units can occur. Multiply that extent by each product coefficient to obtain the theoretical amount, assuming the stated reaction goes to completion with no competing reaction. Remaining excess reactant equals its initial amount minus the coefficient times the extent. Actual product may be lower because of incomplete reaction, side reactions, transfer losses or purification losses. Percentage yield compares an actual isolated amount with the theoretical amount on the same mass or mole basis. A value above one hundred percent often indicates wet or impure product, an incorrect assumed composition, or measurement error. It is a reason to investigate the calculation and sample, not evidence that atom conservation failed.','配平方程可以看作反复使用的配方。若每份反应消耗两份 A 和一份 B，三份 A 不可能完全消耗三份 B。将各反应物初始物质的量除以其计量系数，最小值限制可进行的反应份数，即反应进度。用该值乘产物系数得到理论产量，前提是所述反应完成且无竞争反应。过量试剂剩余量为初始量减去系数乘反应进度。实际产量可因未完全反应、副反应、转移或纯化损失而降低。百分产率应在相同质量或摩尔基准上比较实际分离量与理论量。超过百分之百通常提示产物潮湿、不纯、组成假设错误或测量误差，应检查样品与计算，而不是认为原子守恒失效。');
expand('C01.05','A solution is a single phase containing a solvent and one or more dissolved solutes. Dissolution distributes particles through the solvent; it does not mean the particles have disappeared. Molarity is an amount concentration and depends on total solution volume, so temperature-driven expansion can change molarity even when solute amount remains fixed. Mass fraction uses masses and is less directly sensitive to such volume changes. Molality uses moles per kilogram of solvent and must not be confused with molarity. To prepare a specified solution, determine the required solute amount, convert to mass if appropriate, dissolve it in less than the final volume, and then adjust the final solution volume. The equation c1V1 = c2V2 is an amount balance, not an independent law of liquids. It requires the same conserved solute and no reaction or loss. Mixing different reacting solutions requires stoichiometric accounting before a final concentration is reported. Keep volume units consistent within a ratio and convert to litres when multiplying a concentration expressed per litre to obtain moles.','溶液是溶剂与一种或多种溶质构成的单一相。溶解使粒子分散在溶剂中，并不是粒子消失。物质的量浓度使用溶液总体积，温度引起体积膨胀时，即使溶质量不变，浓度也会改变。质量分数用质量，较少直接受体积变化影响。质量摩尔浓度用每千克溶剂中的摩尔数，不能与物质的量浓度混淆。配液时先确定所需溶质量，必要时换算为质量，先溶于少于终体积的溶剂，再定容。c1V1 = c2V2 是物质的量守恒关系，要求同一溶质不反应也不损失。混合能反应的溶液时，应先做计量核算，再报告终浓度。比值中的体积单位要一致；若浓度单位为每升，乘体积求摩尔数时需使用升。');
expand('C01.06','Gas pressure results from particle momentum transfer to container walls. Increasing particle amount at fixed temperature and volume increases collision frequency and hence pressure in the ideal model. Increasing absolute temperature raises the typical particle kinetic energy, while increasing volume reduces the collision rate per area. The ideal equation combines these trends with a proportionality constant R whose numerical value depends on the chosen pressure and volume units. Never mix a value of R in litre atmospheres with pressures in pascals without conversion. An ideal mixture treats each component as if it occupied the full container independently at the same temperature. Its partial pressure is therefore proportional to its mole fraction, and summing all partial pressures returns the total. Gas collected over water includes water vapour; subtract the appropriate vapour pressure before attributing all pressure to the desired gas. At high density, finite molecular volume and intermolecular attractions become important. Near condensation, the ideal approximation can fail dramatically, so always identify temperature, pressure and phase before using a simple gas calculation.','气体压强源于粒子向容器壁传递动量。理想模型中，温度与体积不变时粒子数增加，碰撞频率和压强增加；绝对温度升高增加典型粒子动能，体积增大则减少单位面积碰撞率。理想气体方程把这些趋势结合，R 的数值取决于压强与体积单位。不能把以 L·atm 为单位的 R 与 Pa 压强未经换算混用。理想混合物中，每种组分都视为在同温下独立占满容器，因此分压与摩尔分数成正比，分压之和为总压。排水集气含水蒸气，应先减去对应蒸气压，不能把总压都归给目标气体。高密度下，分子有限体积和吸引力变得重要；接近冷凝时理想近似可严重失效，列式前应识别温度、压强和相态。');

units('C02',['module.C01.06'],[
['原子证据与电子结构','Nucleus|Electron shells|Spectral evidence','原子核|电子层|光谱证据','Scattering supports a compact positive nucleus; line spectra support discrete electronic energies. Orbitals describe quantum probability distributions, not tiny planetary paths. Electron configurations fill allowed states subject to exclusion and energy ordering.','散射支持紧凑正电原子核，线光谱支持离散电子能级。轨道描述量子概率分布，而非微型行星路径。电子排布按不相容与能量顺序填充允许态。','A neutral atom has 8 protons. How many electrons does it have?','中性原子有 8 个质子，电子数是多少？',8,'Neutrality: electrons = protons = 8.','An ion differs from its neutral atom in electron count.','离子与对应中性原子的电子数不同。','Ion formation changes the element’s proton number.','形成离子会改变元素质子数。'],
['周期性与变化趋势','Effective nuclear charge|Atomic size|Ionization energy','有效核电荷|原子大小|电离能','Shielding reduces the attraction felt by an outer electron. Across a period effective nuclear attraction generally increases, reducing atomic size and raising ionization energy, with subshell and pairing exceptions.','屏蔽减弱外层电子感受到的吸引。沿周期有效核吸引通常增加，原子变小、电离能升高，但存在亚层与配对引起的例外。','An atom has 11 protons and 10 electrons. Find its net charge in elementary-charge units.','原子有 11 个质子、10 个电子，净电荷为几个元电荷？',1,'Charge/e = 11 − 10 = +1.','Periodic trends have mechanistic exceptions.','周期趋势存在有机制原因的例外。','Every periodic trend is strictly monotonic without exception.','所有周期趋势都严格单调且无例外。'],
['离子键、共价键与金属键','Electrostatic bonding|Electron sharing|Delocalized electrons','静电成键|电子共享|离域电子','Ionic solids are extended electrostatic structures, covalent bonds share electron density, and metallic bonding involves delocalized electrons. These models describe limiting patterns; actual bonding can have mixed character.','离子晶体是扩展静电结构，共价键共享电子密度，金属键涉及离域电子。这些是极限模型，实际成键可以兼具多种特征。','A neutral salt contains Ca2+ and Cl−. How many chloride ions balance one calcium ion?','中性盐含 Ca2+ 与 Cl−，一个钙离子需要几个氯离子配平电荷？',2,'(+2) + 2(−1) = 0.','Bond character lies on a continuum rather than three perfectly separate boxes.','键性质呈连续变化，并非三个完全隔离类别。','All ionic compounds consist of discrete neutral molecules.','所有离子化合物都由独立中性分子组成。'],
['分子几何与极性','Electron domains|Molecular shape|Dipole cancellation','电子域|分子构型|偶极抵消','Electron-domain repulsion provides a first geometry model. Lone pairs count as domains but are omitted when naming atom positions. Molecular polarity depends on vector addition of bond dipoles and geometry.','电子域排斥提供初步几何模型。孤电子对算电子域，但命名原子构型时不列作原子。分子极性取决于键偶极矢量叠加及几何。','A tetrahedral electron-domain arrangement contains three bonds and one lone pair. How many total domains are present?','四面体电子域排列含三个键和一对孤电子对，共有几个电子域？',4,'3 bonding domains + 1 lone-pair domain = 4.','Polar bonds can cancel in a symmetric molecule.','极性键可在对称分子中相互抵消。','Any molecule with a polar bond must be polar.','只要有极性键，分子就必为极性分子。'],
['分子间作用力与材料','Dispersion|Dipole interactions|Hydrogen bonding','色散力|偶极相互作用|氢键','All atoms and molecules exhibit dispersion interactions from correlated charge fluctuations. Permanent dipoles add orientation-dependent attraction. Hydrogen bonding requires suitable donors and acceptors; collective interactions influence phase and material properties.','所有原子分子都有由关联电荷涨落产生的色散作用。永久偶极增加与取向有关的吸引。氢键需要适当供体与受体，集体相互作用影响相态和材料性质。','A phase change absorbs 200 J for a 5 g sample. Find latent heat per gram in J/g.','5 g 样品相变吸热 200 J，每克潜热为多少 J/g？',40,'L = Q/m = 200/5 = 40 J/g.','Boiling separates molecules without usually breaking their internal covalent bonds.','沸腾通常分开分子，而不打断分子内部共价键。','Boiling water converts every H2O molecule into hydrogen and oxygen atoms.','水沸腾会把每个 H2O 分子拆成氢氧原子。'],
['原子轨道与分子轨道入门','Orbital overlap|Bonding and antibonding|Bond order','轨道重叠|成键与反键|键级','Atomic orbitals combine into molecular orbitals with different energies and spatial distributions. Electrons in bonding orbitals stabilize relative to separated atoms; antibonding occupation counteracts this. A simple bond order is (Nb − Na)/2.','原子轨道组合为能量与空间分布不同的分子轨道。成键轨道电子相对分离原子使体系稳定，反键占据抵消此作用。简单键级为 (Nb − Na)/2。','A molecule has 6 bonding and 2 antibonding electrons. Find bond order.','分子有 6 个成键电子和 2 个反键电子，键级是多少？',2,'Bond order = (6 − 2)/2 = 2.','Antibonding electrons reduce the net bond order.','反键电子降低净键级。','Every occupied molecular orbital strengthens the bond equally.','每个被占据分子轨道都等量加强化学键。']]);
expand('C02.01','Rutherford-type scattering showed that most atomic volume does not contain concentrated positive mass: most fast projectiles pass through, while a small fraction undergo large deflections near a compact nucleus. Nuclear proton number identifies the element, and neutron number distinguishes isotopes. Electron number determines ionic charge together with proton number. The classical picture of an orbiting charge cannot account for stable atomic spectra. In the quantum description, an orbital is a state with a spatial probability distribution and allowed energy. Principal shells contain subshells with different angular structure; each spatial orbital permits two electrons with opposite spin labels. The Pauli principle forbids two identical electrons from occupying the same complete state. Hund’s rule favors separate occupation of equal-energy orbitals before pairing in the introductory ground-state model. Aufbau ordering is a useful construction rule, but closely spaced levels cause exceptions, especially for transition elements and ions. An emitted photon carries the difference between two levels, so separate spectral lines provide evidence of energy differences. A line does not reveal an electron’s classical circular path.','卢瑟福式散射表明，原子大部分体积中没有集中正电质量：多数高速粒子直接穿过，少数靠近紧凑原子核时发生大角偏转。质子数识别元素，中子数区分同位素，电子数与质子数共同决定离子电荷。经典绕核运动不能解释稳定原子光谱。量子描述中，轨道是具有空间概率分布和允许能量的态。主电子层包含角结构不同的亚层，每个空间轨道可容纳两个自旋标签相反的电子。泡利原理禁止电子占据同一完整状态，洪特规则在入门基态模型中使等能轨道先单独占据再配对。构造原理是实用规则，但能级接近会造成例外，尤其在过渡元素与离子中。发射光子的能量等于两个能级差，离散谱线由此提供能量差证据，并不揭示电子经典圆轨道。');
expand('C02.02','Periodic organization follows the repeating pattern of valence-electron configurations. Elements in a group often show related chemistry because their outer-electron patterns resemble one another, although extra shells change size and shielding. Moving down a group generally adds a shell, placing outer electrons farther from the nucleus. Moving across a period adds protons while electrons enter the same principal shell, so the effective attraction commonly rises. Atomic radius is not a uniquely sharp boundary; covalent, metallic and van der Waals radii are operational definitions obtained in different contexts. Ionization energy is the energy required to remove an electron from a gaseous species. Successive ionizations become harder, and a large jump can reveal removal from a filled inner shell. Electron affinity concerns adding an electron and has sign conventions that must be checked. Electronegativity describes attraction to shared electron density within a bond, not an isolated-atom radius or charge. Subshell energies, electron pairing and imperfect shielding create important exceptions to simple trends, so explain a comparison mechanistically instead of memorizing arrows alone.','周期组织来自价电子排布的重复。同族元素外层模式相似，常有相近化学性质，但新增电子层会改变大小与屏蔽。沿族向下通常增加电子层，外层电子离核更远；沿周期增加质子而电子仍进入相同主层，有效吸引通常加强。原子半径并非唯一锐利边界，共价、金属和范德华半径是在不同情境中定义的操作量。电离能是从气态物种移去电子所需能量。连续电离越来越困难，大跃升可提示开始移除内层电子。电子亲和能涉及加入电子，应检查符号约定；电负性描述成键时对共享电子密度的吸引，不等同孤立原子半径或电荷。亚层能量、电子配对与不完全屏蔽造成趋势例外，因此应解释机理，而非只背箭头。');
expand('C02.03','Chemical bonding reflects a lower total energy for some arrangements of nuclei and electrons than for the corresponding separated species. Attraction alone is insufficient: at very short separations, repulsion raises the energy and establishes an equilibrium bond distance. In an ionic lattice, each ion interacts with many surrounding ions, so one should not picture sodium chloride as isolated NaCl pairs. Charge magnitude and ionic separation influence electrostatic lattice stabilization. A covalent description emphasizes shared electron density between nuclei, with single, double and triple bonds representing different idealized shared-electron patterns. A coordinate bond denotes a bookkeeping origin for the shared pair; after formation it is not a fundamentally different force. Metallic bonding describes electrons distributed through a lattice, helping explain electrical conduction and the ability of layers to slide without destroying every bond. Electronegativity differences shift electron density continuously, so ionic and covalent labels are useful limits rather than rigid categories. Lewis structures track valence electrons and formal charges; formal charge is a bookkeeping assignment and should not automatically be interpreted as a measured atomic charge.','化学键反映某些核与电子排列的总能量低于相应分离物种。仅有吸引不足以解释稳定距离；过近时排斥抬高能量，形成平衡键长。离子晶格中，每个离子与许多周围离子作用，不能把氯化钠想成独立 NaCl 对。电荷大小与离子间距影响晶格静电稳定。共价描述强调核间共享电子密度，单、双、三键表示不同理想共享模式。配位键只说明共享电子对的记账来源，形成后不是另一种基本力。金属键中电子遍布晶格，可帮助解释导电及晶层滑移时不至于破坏所有键。电负性差连续改变电子密度，离子和共价是有用极限而非硬类别。路易斯结构记录价电子与形式电荷，形式电荷是记账量，不应自动视为测得的原子真实电荷。');
expand('C02.04','Molecular shape begins with connectivity: identify which atoms are joined before counting electron domains around a chosen central atom. In the basic VSEPR model, each single, double or triple bond counts as one directional domain, while each lone pair counts as another. Two domains favor a linear arrangement, three a trigonal planar arrangement and four a tetrahedral arrangement. Molecular geometry names the positions of atoms rather than all electron domains, so four domains with one lone pair give a trigonal pyramidal molecule, not a tetrahedral molecular shape. Lone pairs and multiple bonds can shift angles away from ideal values because their electron distributions differ. A bond dipole combines magnitude and direction; determine molecular polarity by adding these dipoles as vectors in the actual geometry. Linear carbon dioxide can have polar bonds whose dipoles cancel, whereas bent water does not have that cancellation. Symmetry is therefore as important as electronegativity. VSEPR is an introductory predictive model, not a universal quantitative theory: delocalization, transition-metal coordination and electronic-state changes may require orbital-based explanations or experimental structure data.','分子构型先从连接关系开始：先确定哪些原子相连，再数中心原子周围电子域。基础 VSEPR 模型中，单、双、三键各算一个方向性电子域，每对孤电子对另算一个。两个域倾向直线，三个域倾向平面三角形，四个域倾向四面体。分子构型命名只看原子位置，所以四个域中含一对孤电子对时为三角锥形，而非四面体分子构型。孤电子对与多重键的电子分布不同，会使键角偏离理想值。键偶极有大小和方向，应按实际构型作矢量叠加判断分子极性。直线 CO2 的极性键偶极可抵消，弯曲水分子则不能；对称性与电负性同样重要。VSEPR 是入门预测模型，不是普遍定量理论，离域、过渡金属配位与电子态变化可能需要轨道解释或实验结构。');
expand('C02.05','Intermolecular forces act between molecules and must be distinguished from the bonds that hold each molecule together. London dispersion arises because instantaneous charge fluctuations in one species correlate with fluctuations in another. Greater polarizability and favorable contact area often strengthen dispersion, which exists even in nonpolar substances. Permanent molecular dipoles add interactions whose strengths depend on orientation and separation. Hydrogen bonding is a directional interaction involving a hydrogen attached to an appropriate electronegative donor and an available acceptor; merely containing hydrogen is insufficient. These interactions collectively influence boiling point, viscosity, surface tension, solubility and crystal packing. A higher boiling point can indicate stronger effective cohesion, but molecular size, shape and phase structure must also be considered. Dissolution involves replacing solute–solute and solvent–solvent interactions with solute–solvent interactions, together with entropy changes, so “like dissolves like” is only a heuristic. A solid’s properties may instead be dominated by a covalent network, ionic lattice or metallic electrons. Always identify the structural level before using the phrase weak intermolecular force to explain a material.','分子间作用与分子内部化学键必须区分。伦敦色散源于不同物种瞬时电荷涨落的关联；可极化性更大、接触面积更有利时，作用常更强，非极性物质也有色散力。永久偶极增加依赖取向与距离的相互作用。氢键是有方向性的作用，需要氢连接适当电负性供体，并有可用受体，仅含氢并不足够。这些作用共同影响沸点、黏度、表面张力、溶解度和晶体堆积。较高沸点可提示更强内聚，但还须考虑大小、形状和相结构。溶解把溶质—溶质、溶剂—溶剂作用替换为溶质—溶剂作用，同时涉及熵变，因此“相似相溶”只是经验指导。有些固体性质主要由共价网络、离子晶格或金属电子决定。解释材料时应先明确结构层次，不能一律归于弱分子间作用。');
expand('C02.06','An atomic orbital describes an allowed one-electron spatial state associated with an atom. When atoms approach, compatible orbital combinations extend over more than one nucleus. Constructive combination can increase electron density between nuclei and lower energy, producing a bonding molecular orbital; destructive combination introduces a node and often raises energy, producing an antibonding orbital. The number of molecular orbitals formed equals the number of atomic orbitals combined in the chosen basis. Fill the resulting states according to their energies, Pauli exclusion and the applicable spin rules. The introductory bond-order expression counts bonding electrons minus antibonding electrons, divided by two. It summarizes net stabilization in simple cases but does not replace a complete energy calculation. Unpaired electrons imply paramagnetic behavior, which can distinguish molecular-orbital predictions from overly simple Lewis pictures, as in oxygen. Sigma orbitals have symmetry around the bond axis, while pi orbitals have a nodal plane containing that axis. Orbital diagrams are model representations rather than photographs, and their ordering can depend on the atoms involved; copying one ordering indiscriminately across all molecules can give incorrect conclusions.','原子轨道描述与原子相关的允许单电子空间态。原子接近时，相容轨道组合可延伸到多个核。相长组合能增加核间电子密度并降低能量，形成成键轨道；相消组合引入节点，常抬高能量，形成反键轨道。在选定基组中，形成的分子轨道数等于参与组合的原子轨道数。按能量、泡利原理与适用自旋规则填充。入门键级公式为成键电子数减反键电子数再除二，它概括简单情形的净稳定，但不能代替完整能量计算。未成对电子意味着顺磁性，可区分分子轨道预测与过度简化路易斯图，如氧气。σ 轨道绕键轴对称，π 轨道有包含键轴的节点平面。轨道图是模型而非照片，其能量顺序依原子种类变化，不能把一张排序无差别套给所有分子。');

units('P08',['math.derivatives','math.integrals','math.vectors','module.P02.06'],[
['广义坐标与约束','Degrees of freedom|Holonomic constraints|Generalized coordinates','自由度|完整约束|广义坐标','Generalized coordinates independently specify a configuration. A holonomic constraint restricts positions through an equation; choosing coordinates on that constraint can eliminate unknown reaction forces.','广义坐标独立确定构型。完整约束通过位置方程限制运动；沿约束选择坐标可消去未知约束反力。','A particle in three-dimensional space is constrained to a fixed sphere surface. How many positional degrees of freedom remain?','三维空间质点被限制在固定球面上，还剩几个位置自由度？',2,'3 coordinates − 1 independent constraint = 2.','An angle can be a generalized coordinate.','角度可以作为广义坐标。','Every generalized coordinate must have length units.','所有广义坐标都必须具有长度单位。'],
['变分原理','Action|Stationary path|Endpoint conditions','作用量|驻值路径|端点条件','The action is the time integral of the Lagrangian. Hamilton’s principle makes its first variation vanish for nearby paths with fixed endpoints; stationary does not necessarily mean a minimum.','作用量是拉格朗日量对时间的积分。哈密顿原理要求固定端点的邻近路径使作用量一阶变分为零；驻值不一定是最小值。','A constant Lagrangian is 3 J for 4 s. Find action in J·s.','拉格朗日量恒为 3 J，持续 4 s，作用量为多少 J·s？',12,'S = ∫Ldt = 3 × 4 = 12 J·s.','Stationary action means zero first variation.','驻定作用量意味着一阶变分为零。','Every physical path is the absolute shortest geometric path.','每条物理路径都是绝对最短的几何路径。'],
['拉格朗日方程','Lagrangian|Euler–Lagrange equation|Generalized force','拉格朗日量|欧拉—拉格朗日方程|广义力','For conservative systems L = T − V. Each coordinate obeys d/dt(∂L/∂q̇) − ∂L/∂q = 0; additional nonconservative generalized forces belong on the right.','保守系统中 L = T − V。各坐标满足 d/dt(∂L/∂q̇) − ∂L/∂q = 0；非保守广义力放在右侧。','For L = mẋ²/2 − kx²/2, m = 2 and k = 8, find ω² = k/m.','L = mẋ²/2 − kx²/2，m = 2、k = 8，ω² = k/m 为多少？',4,'ω² = k/m = 8/2 = 4.','The Euler–Lagrange equation reproduces Newtonian spring motion.','欧拉—拉格朗日方程可还原牛顿弹簧运动。','The Lagrangian is always kinetic plus potential energy.','拉格朗日量总等于动能加势能。'],
['中心力运动','Angular momentum|Effective potential|Radial motion','角动量|有效势能|径向运动','A central force points along the separation, giving zero torque about the centre. Conserved angular momentum confines motion to a plane and adds L²/(2mr²) to the radial effective potential.','中心力沿连线方向，对中心力矩为零。角动量守恒使运动限制在平面内，并在径向有效势中增加 L²/(2mr²)。','With L = 4, m = 2 and r = 2 in consistent units, find centrifugal effective-potential term L²/(2mr²).','使用一致单位，L = 4、m = 2、r = 2，求有效势中的 L²/(2mr²)。',1,'16/(2 × 2 × 4) = 1.','A central force conserves angular momentum about its centre.','中心力保持关于力心的角动量。','A central force necessarily keeps speed constant.','中心力必然使速率恒定。'],
['哈密顿力学','Canonical momentum|Hamiltonian|Phase space','正则动量|哈密顿量|相空间','Canonical momentum is ∂L/∂q̇. The Legendre transform H = Σpq̇ − L gives Hamilton’s equations q̇ = ∂H/∂p and ṗ = −∂H/∂q when the transformation is regular.','正则动量为 ∂L/∂q̇。勒让德变换 H = Σpq̇ − L 在正则条件下导出 q̇ = ∂H/∂p、ṗ = −∂H/∂q。','A free particle has H = p²/(2m), p = 6 and m = 3. Find q̇ = p/m.','自由粒子 H = p²/(2m)，p = 6、m = 3，q̇ = p/m 为多少？',2,'q̇ = p/m = 6/3 = 2.','Phase space specifies coordinates and their conjugate momenta.','相空间同时指定坐标及其共轭动量。','A point in position space always determines the future motion uniquely.','仅知道位置空间的一点总能唯一确定未来运动。'],
['小振动与非线性动力学','Linearization|Normal frequencies|Nonlinear sensitivity','线性化|简正频率|非线性敏感性','Near a stable equilibrium, expand potential to quadratic order and solve the coupled linear modes. Larger excursions retain nonlinear terms; some driven systems become sensitive to initial conditions.','稳定平衡附近，把势能展开至二次项并求耦合线性模式。较大偏离必须保留非线性项；一些受迫系统会对初始条件敏感。','For a mode with effective stiffness 25 and mass 1, find angular frequency √(k/m).','某模式有效刚度 25、质量 1，角频率 √(k/m) 为多少？',5,'ω = √(25/1) = 5.','Linearization is a local approximation near equilibrium.','线性化是平衡附近的局部近似。','Small-oscillation predictions are exact at every amplitude.','小振动预测在所有振幅下都精确。']], [{title:'MIT OpenCourseWare · Classical Mechanics III',url:'https://ocw.mit.edu/courses/8-09-classical-mechanics-iii-fall-2014/'}]);

units('P09',['module.P06.06','math.derivatives','math.integrals','math.vectors'],[
['静电边值问题','Poisson equation|Boundary conditions|Uniqueness','泊松方程|边界条件|唯一性','Electrostatic potential obeys ∇²V = −ρ/ε0; charge-free regions obey Laplace’s equation. Boundary potentials or normal derivatives constrain the solution, and suitable boundary data make it unique.','静电势满足 ∇²V = −ρ/ε0，无电荷区域满足拉普拉斯方程。边界电势或法向导数约束解，适当边值可保证唯一性。','A uniform one-dimensional potential falls from 12 V to 4 V across 2 m. Find field magnitude in V/m.','一维均匀电势在 2 m 内由 12 V 降至 4 V，场强大小为多少 V/m？',4,'|E| = |ΔV|/Δx = 8/2 = 4 V/m.','Boundary conditions are part of the physical problem.','边界条件是物理问题的一部分。','A differential equation alone always fixes a unique potential.','仅有微分方程总能确定唯一电势。'],
['多极展开与物质中的场','Dipole moment|Far-field expansion|Polarization','偶极矩|远场展开|极化','For localized charges far away, potential can be expanded into monopole, dipole and higher terms. A neutral distribution has no monopole term. Polarization describes electric dipole moment per volume in matter.','远离局域电荷分布时，电势可展开为单极、偶极及高阶项。中性分布没有单极项。极化强度表示物质单位体积的电偶极矩。','Charges ±2 C are separated by 0.3 m. Find dipole moment magnitude in C·m.','±2 C 电荷相距 0.3 m，偶极矩大小为多少 C·m？',0.6,'p = qd = 2 × 0.3 = 0.6 C·m.','A neutral object can have a nonzero dipole field.','中性物体可以具有非零偶极场。','Zero net charge means zero field everywhere.','净电荷为零意味着处处电场为零。'],
['静磁场与矢势','Vector potential|Gauge freedom|Magnetic field','矢势|规范自由度|磁场','Writing B = ∇×A automatically enforces zero magnetic divergence. Different vector potentials related by adding a gradient describe the same B; this is gauge freedom, not different measured magnetism.','写成 B = ∇×A 自动满足磁场散度为零。相差一个梯度的矢势给出同一 B，这是规范自由度，而非不同的实测磁场。','For A = (0, bx, 0), Bz = b. If b = 3 T, find Bz in T.','A = (0, bx, 0) 时 Bz = b；b = 3 T，则 Bz 为多少 T？',3,'Bz = ∂Ay/∂x − ∂Ax/∂y = b = 3 T.','Gauge-related vector potentials can represent the same field.','规范相关的矢势可以表示同一磁场。','Every different vector potential implies a different magnetic field.','每个不同矢势都对应不同磁场。'],
['麦克斯韦方程','Gauss laws|Faraday law|Ampere–Maxwell law','高斯定律|法拉第定律|安培—麦克斯韦定律','Electric flux measures enclosed charge; magnetic flux through a closed surface is zero. Changing magnetic fields induce electric circulation, while current and changing electric fields induce magnetic circulation.','电通量联系包围电荷，闭合曲面的磁通为零。时变磁场产生电场环量，电流与时变电场产生磁场环量。','If enclosed charge doubles with geometry unchanged, electric flux doubles by Gauss’s law. A starting flux of 7 becomes what?','由高斯定律，包围电荷加倍时电通量加倍；初通量为 7，末通量是多少？',14,'Φnew = 2Φold = 14.','A changing electric field contributes to magnetic circulation.','时变电场对磁场环量有贡献。','Only conduction current can produce magnetic circulation.','只有传导电流能产生磁场环量。'],
['电磁能量与动量','Field energy|Poynting vector|Radiation pressure','场能量|坡印廷矢量|辐射压强','Electric and magnetic fields store energy. The Poynting vector E×B/μ0 gives energy flux in vacuum. Electromagnetic waves carry momentum and can exert pressure on absorbing or reflecting surfaces.','电场与磁场储存能量。真空坡印廷矢量 E×B/μ0 表示能流。电磁波携带动量，可对吸收或反射表面施加压力。','A steady energy flux of 30 W/m² crosses a perpendicular area of 2 m². Find transmitted power in W.','30 W/m² 稳定能流垂直穿过 2 m² 面积，功率为多少 W？',60,'P = SA = 30 × 2 = 60 W.','Field momentum allows light to exert force.','场动量使光能够施加力。','Light cannot exert force because photons have zero rest mass.','光子静质量为零，因此光不能施加力。'],
['辐射与波导入门','Accelerating charge|Retarded propagation|Waveguide cutoff','加速电荷|推迟传播|波导截止','Accelerating charges can radiate; field changes propagate at finite speed. Conducting waveguide boundaries allow discrete transverse patterns, with propagation only above the mode’s cutoff frequency.','加速电荷可以辐射，场变化以有限速度传播。导体波导边界允许离散横向模式，只有高于相应截止频率才能传播。','A signal travels 600 m in vacuum at 3×10^8 m/s. Find delay in microseconds.','信号以 3×10^8 m/s 在真空传播 600 m，延迟为多少微秒？',2,'t = 600/(3×10^8) s = 2 μs.','Waveguide boundary conditions select propagation modes.','波导边界条件选择传播模式。','Every frequency propagates in every hollow waveguide mode.','任何频率都能在每个空心波导模式中传播。']], [{title:'MIT OpenCourseWare · Electromagnetism II',url:'https://ocw.mit.edu/courses/8-07-electromagnetism-ii-fall-2012/'}]);

units('P10',['module.P07.06','math.integrals','math.derivatives','math.linear-independence'],[
['量子实验起源与波粒模型','Photon energy|Matter waves|Quantization','光子能量|物质波|量子化','Photoelectric thresholds require quantized energy hf, while electron diffraction supports wavelength h/p. Wave and particle descriptions refer to different measured features, not a tiny classical object switching identities.','光电阈值需要量子化能量 hf，电子衍射支持波长 h/p。波粒描述对应不同可测性质，并非微小经典物体在身份间切换。','Photon frequency doubles at fixed Planck constant. By what factor does energy change?','普朗克常数固定，光子频率加倍，能量变为几倍？',2,'E = hf; Enew/Eold = 2.','Increasing photon frequency increases energy per photon.','提高光子频率会增加每个光子的能量。','Increasing intensity always increases each photon’s energy.','提高光强总会提高每个光子的能量。'],
['量子态、算符与测量','State amplitudes|Observables|Born probabilities','态振幅|可观测量|玻恩概率','A normalized state assigns complex amplitudes. Observables correspond to Hermitian operators; possible measurement values are eigenvalues. The squared magnitude of an outcome amplitude gives its probability.','归一化量子态给出复振幅。可观测量对应厄米算符，可能测量值为本征值。某结果振幅的模平方给出其概率。','An outcome amplitude has magnitude 0.6. What is its probability?','某结果振幅的模为 0.6，其概率是多少？',0.36,'P = |a|² = 0.6² = 0.36.','Probabilities sum to one for a normalized complete set of outcomes.','归一化态的完备结果概率之和为一。','An amplitude is always identical to its probability.','振幅总等于概率。'],
['一维薛定谔方程','Wavefunction|Boundary conditions|Energy eigenstates','波函数|边界条件|能量本征态','The Schrödinger equation evolves a wavefunction. For a time-independent potential, stationary states solve an energy eigenvalue equation. Normalization and boundary conditions select physically admissible solutions.','薛定谔方程决定波函数演化。势不随时间变化时，定态满足能量本征方程。归一化与边界条件选择物理允许的解。','An infinite well has energies En = n²E1. If E1 = 2 units, find E3.','无限深势阱能级 En = n²E1；E1 = 2 单位时，E3 是多少？',18,'E3 = 3² × 2 = 18.','Boundary conditions help quantize bound-state energies.','边界条件有助于确定束缚态离散能级。','Every arbitrary energy is a bound-state energy in an infinite well.','无限深势阱的任意能量都是束缚态能级。'],
['量子谐振子与隧穿','Zero-point energy|Barrier penetration|Transmission','零点能|势垒穿透|透射','A quantum oscillator has energies (n + 1/2)ℏω, including nonzero ground energy. A finite barrier can admit transmission below its classical height because the wavefunction extends through the classically forbidden region.','量子谐振子能级为 (n + 1/2)ℏω，基态能量非零。有限势垒中，波函数可延伸进经典禁区，因此粒子能在低于势垒高度时透射。','If ℏω = 4 energy units, find oscillator ground energy.','若 ℏω = 4 能量单位，谐振子基态能量是多少？',2,'E0 = (1/2)ℏω = 2.','Tunneling probability depends strongly on barrier width.','隧穿概率强烈依赖势垒宽度。','Tunneling means energy conservation is violated.','隧穿意味着违反能量守恒。'],
['角动量与氢原子','Angular quantum numbers|Hydrogen spectrum|Orbital probability','角量子数|氢光谱|轨道概率','Orbital angular momentum has squared magnitude ℏ²l(l+1) and one-component values mℏ. Hydrogen’s central Coulomb potential produces bound energy levels and spatial probability distributions called orbitals.','轨道角动量平方为 ℏ²l(l+1)，一个分量取 mℏ。氢原子的中心库仑势产生束缚能级和称为轨道的空间概率分布。','For l = 2, how many allowed magnetic quantum numbers m exist?','l = 2 时，允许的磁量子数 m 有几个？',5,'m = −2, −1, 0, 1, 2; count = 2l + 1 = 5.','An orbital is a quantum probability structure, not a classical planet-like path.','原子轨道是量子概率结构，不是行星式经典路径。','An electron orbital specifies one exact classical trajectory.','电子轨道指定一条精确经典轨迹。'],
['自旋、近似与多粒子概览','Intrinsic spin|Perturbation|Exchange symmetry','内禀自旋|微扰|交换对称性','Spin is intrinsic angular momentum. Weak additional interactions may be treated perturbatively. Identical fermions have antisymmetric states and obey Pauli exclusion; bosons have symmetric states and may share a quantum state.','自旋是内禀角动量。弱附加相互作用可用微扰近似处理。相同费米子态反对称并遵守泡利不相容原理；玻色子态对称，可共享同一量子态。','A single spatial orbital accommodates electrons in how many distinct spin states?','一个空间轨道可对应电子的几个不同自旋态？',2,'ms = +1/2 or −1/2: two spin states.','Pauli exclusion applies to identical fermions in the same complete one-particle state.','泡利原理禁止相同费米子占据同一完整单粒子态。','Pauli exclusion forbids all particles from sharing any spatial region.','泡利原理禁止所有粒子共享任何空间区域。']], [{title:'MIT OpenCourseWare · Quantum Physics I',url:'https://ocw.mit.edu/courses/8-04-quantum-physics-i-spring-2016/'}]);

units('P11',['module.P02.06','math.powers-roots'],[
['狭义相对论公设','Relativity principle|Invariant light speed|Simultaneity','相对性原理|光速不变|同时性','Inertial observers share the same physical laws and vacuum light speed. Consequently, simultaneity at separated locations depends on frame, and space and time coordinates mix under transformations.','惯性观察者遵循相同物理定律，并测得相同真空光速。因此，异地同时性依赖参考系，空间与时间坐标在变换中混合。','A light signal travels 3×10^8 m in vacuum at 3×10^8 m/s. Find time in seconds.','光以 3×10^8 m/s 在真空传播 3×10^8 m，时间为多少秒？',1,'t = d/c = 1 s.','The same vacuum light speed is measured by inertial observers.','惯性观察者测得相同真空光速。','A source moving toward an observer necessarily makes vacuum light travel faster than c.','光源朝观察者移动必使真空光速超过 c。'],
['洛伦兹变换','Lorentz factor|Time dilation|Length contraction','洛伦兹因子|时间膨胀|长度收缩','The Lorentz factor is γ = 1/√(1 − v²/c²). A clock’s proper time belongs to events on its own worldline; other inertial frames may assign a longer interval.','洛伦兹因子为 γ = 1/√(1 − v²/c²)。时钟的固有时对应其自身世界线上的事件，其他惯性系可能测得更长间隔。','At v = 0.6c, find γ.','v = 0.6c 时，γ 为多少？',1.25,'γ = 1/√(1 − 0.36) = 1/0.8 = 1.25.','Length contraction compares simultaneous endpoint positions in the measuring frame.','长度收缩要求在测量系中同时确定两端位置。','Time dilation means a moving clock mechanically malfunctions.','时间膨胀意味着运动时钟机械故障。'],
['相对论能量与动量','Rest energy|Relativistic momentum|Invariant relation','静能|相对论动量|不变量关系','Total energy is γmc² and momentum is γmv. Their invariant relation is E² = p²c² + m²c⁴. Massless particles have E = pc, while massive particles cannot reach c with finite energy.','总能量为 γmc²，动量为 γmv，满足 E² = p²c² + m²c⁴。无质量粒子有 E = pc；有质量粒子不能通过有限能量达到 c。','Using units c = 1, a particle has mass 3 and momentum 4. Find total energy.','取 c = 1，粒子质量为 3、动量为 4，总能量是多少？',5,'E = √(p² + m²) = √(16 + 9) = 5.','Rest energy is included in total relativistic energy.','总相对论能量包含静能。','Relativistic total energy equals kinetic energy alone.','相对论总能量只有动能。'],
['引力与广义相对论概览','Equivalence principle|Spacetime curvature|Gravitational redshift','等效原理|时空曲率|引力红移','Locally, free fall removes the uniform-gravity effect in a small region. General relativity describes gravity through spacetime geometry; tidal differences reveal curvature. Clocks at different gravitational potentials can tick at different rates.','在足够小区域内，自由落体系可局部消除均匀引力效应。广义相对论用时空几何描述引力，潮汐差异揭示曲率。不同引力势处时钟速率可以不同。','In a weak-field estimate fractional clock shift is ΔΦ/c². If ΔΦ = 9 and c² = 9×10^16 in SI, find the fraction.','弱场钟速相对差近似 ΔΦ/c²；ΔΦ = 9、c² = 9×10^16，求比例。',1e-16,'ΔΦ/c² = 9/(9×10^16) = 10^-16.','Local equivalence does not eliminate tidal effects over an extended region.','局部等效不能消除大范围内的潮汐效应。','Gravity can always be transformed away everywhere at once.','引力总能在全部空间同时通过换系消除。'],
['恒星结构与演化','Hydrostatic balance|Fusion|Stellar lifetime','流体静力平衡|核聚变|恒星寿命','Pressure gradients support stars against gravity while energy is generated and transported outward. Main-sequence fusion consumes core hydrogen. Mass strongly influences luminosity, lifetime and the eventual remnant.','压强梯度支撑恒星对抗引力，内部产生能量并向外输运。主序聚变消耗核心氢。质量强烈影响光度、寿命及最终遗迹。','A toy fuel-lifetime estimate is available energy divided by luminosity. For energy 100 units and luminosity 5 units per year, find years.','简化燃料寿命等于可用能量除以光度；能量 100 单位，光度每年 5 单位，寿命为多少年？',20,'t ≈ E/L = 100/5 = 20 years.','Higher luminosity consumes a fixed energy reserve faster.','对固定能量储备，光度越大消耗越快。','All stars have the same lifespan independent of mass.','所有恒星寿命相同且与质量无关。'],
['宇宙学与观测证据','Expansion|Redshift|Cosmic background','膨胀|红移|宇宙背景辐射','Cosmological redshift records stretching of wavelengths as the universe expands. Nearby recession approximately follows Hubble’s law. Background radiation, element abundances and structure observations constrain cosmological models jointly.','宇宙学红移记录宇宙膨胀造成的波长伸长。近距离退行速度近似满足哈勃定律。背景辐射、元素丰度和结构观测共同约束宇宙模型。','A spectral wavelength changes from 400 to 600 nm. Find redshift z = (λobs − λemit)/λemit.','谱线波长从 400 nm 变为 600 nm，红移 z 是多少？',0.5,'z = (600 − 400)/400 = 0.5.','Several independent observations test an expansion model.','多种独立观测共同检验宇宙膨胀模型。','One redshift measurement alone determines every cosmological parameter.','一次红移测量就能确定全部宇宙学参数。']]);

units('P12',['physics.units','module.P01.06'],[
['仪器分辨率与校准','Resolution|Calibration|Zero offset','分辨率|校准|零点偏差','Resolution is the smallest distinguishable indication. Calibration compares an instrument with references to estimate a response relation; it can reveal offsets and scale errors but does not remove every uncertainty.','分辨率是能区分的最小示值变化。校准用参考标准估计仪器响应，可发现零点与比例偏差，但不能消除全部不确定度。','A sensor reads 2 units high. Its reading is 17; find corrected value.','传感器读数偏高 2 单位，读得 17，修正值是多少？',15,'xcorrected = 17 − 2 = 15.','A precise display can still have calibration bias.','显示精细的仪器仍可存在校准偏差。','More display digits guarantee greater accuracy.','显示位数越多就一定越准确。'],
['不确定度与重复测量','Repeatability|Mean|Uncertainty sources','重复性|平均值|不确定度来源','Repeated readings characterize random variation. The mean estimates a central value, while uncertainty must also include calibration, resolution and procedural effects. Repetition alone cannot remove a constant bias.','重复读数刻画随机变化。平均值估计中心值，但不确定度还应包括校准、分辨率与操作影响。重复测量不能单独消除恒定偏差。','Readings are 9, 10 and 11. Find their arithmetic mean.','读数为 9、10、11，算术平均值是多少？',10,'mean = (9 + 10 + 11)/3 = 10.','Repeatability and accuracy describe different properties.','重复性与准确性描述不同性质。','A stable repeated result must equal the true value.','稳定的重复结果必然等于真值。'],
['力学实验','Controlled variables|Pendulum model|Timing multiple cycles','控制变量|单摆模型|多周期计时','A small-angle pendulum predicts T² proportional to length. Measuring several cycles reduces relative start–stop timing effects. Keep amplitude small, measure pivot-to-centre length and test the predicted proportionality.','小角度单摆预测 T² 与摆长成正比。测多个周期可降低启停计时的相对影响。保持小振幅，测支点到质心距离，并检验比例关系。','Ten oscillations take 18 s. Find period in s.','十次完整振动耗时 18 s，周期为多少秒？',1.8,'T = 18/10 = 1.8 s.','A longer timing interval can reduce relative reaction-time error.','更长计时区间可减小反应时间误差的相对影响。','Timing one partial swing always gives the full period.','测一个不完整摆动总能得到完整周期。'],
['电学与光学实验','Instrument connection|Loading|Optical alignment','仪表连接|负载效应|光路对准','A voltmeter measures potential difference across a component; an ammeter is inserted in series. Optical measurements require aligned axes and a stated image criterion. Instrument influence belongs in the circuit or ray model.','电压表跨接元件测电势差，电流表串联接入。光学测量需要对准轴线并说明成像判据。仪器影响应计入电路或光路模型。','A 2 V reading across a 500 Ω resistor implies what current in mA for the ideal circuit?','理想电路中，500 Ω 电阻两端为 2 V，电流为多少 mA？',4,'I = V/R = 2/500 A = 4 mA.','Finite meter input resistance can alter the measured circuit.','电表有限输入电阻可改变被测电路。','Every measurement leaves the system completely unchanged.','所有测量都完全不影响系统。'],
['拟合、残差与系统误差','Regression|Residual structure|Model checking','回归|残差结构|模型检验','A fit estimates parameters from data. Residuals are observed minus predicted values; systematic curvature or trends suggest missing physics, drift or an unsuitable error model. Small residuals alone do not establish causation.','拟合从数据估计参数。残差为观测值减预测值；系统弯曲或趋势可能提示遗漏物理、漂移或误差模型不当。残差小本身不能证明因果。','Observed value is 12 and fitted prediction is 9. Find residual.','观测值为 12，拟合预测为 9，残差是多少？',3,'residual = observed − predicted = 12 − 9 = 3.','Residual patterns can reveal a model’s inadequacy.','残差模式可以揭示模型不足。','A straight-line fit is valid for every data shape.','直线拟合适用于任何数据形状。'],
['实验设计与报告答辩','Testable hypothesis|Control design|Transparent reporting','可检验假设|对照设计|透明报告','A useful experiment separates competing predictions. Specify variables, controls, repeats, analysis rules and uncertainty before interpreting outcomes. A report distinguishes raw observations, calculations, model assumptions and conclusions.','有用的实验区分竞争预测。解释结果前，明确变量、对照、重复、分析规则和不确定度。报告应区分原始观察、计算、模型假设与结论。','Three treatment settings each require four repeats. How many measurements are planned?','三个处理水平各重复四次，共计划多少次测量？',12,'3 settings × 4 repeats = 12 measurements.','Unexpected results should be reported with the procedure and uncertainty.','异常结果应连同方法和不确定度如实报告。','Deleting inconvenient results automatically improves an experiment.','删除不方便的结果就能自动改善实验。']]);

units('P13',['module.P07.06','module.P12.06'],[
['尺度、估算与极限','Dimensional scaling|Order of magnitude|Limiting checks','量纲缩放|数量级|极限检查','A scaling argument predicts how output changes when a characteristic size changes. Distinguish linear, area and volume factors. Test zero, very large and symmetric limits before trusting a complicated expression.','尺度分析预测特征尺寸变化时输出如何改变。必须区分长度、面积与体积因子。相信复杂式子前，检查零值、极大值与对称极限。','A similar solid’s linear size doubles at unchanged density. By what factor does mass increase?','密度不变的相似实心物体线度加倍，质量变为几倍？',8,'Mass ∝ volume ∝ length³; factor = 2³ = 8.','Geometric scaling changes area and volume differently.','几何缩放对面积与体积的影响不同。','Doubling length always doubles every physical quantity.','长度加倍总使每个物理量加倍。'],
['耦合力学问题','Constraint equations|System selection|Consistency','约束方程|系统选择|一致性','Coupled-body problems need force equations and geometric constraints together. A massless inextensible rope can link accelerations, but moving pulleys change that ratio. Check forces and acceleration directions against the constraint.','耦合物体问题需要同时使用受力方程与几何约束。无质量不可伸长绳联系加速度，但动滑轮可改变比例。应检查力与加速度方向是否符合约束。','In a stated pulley constraint x + 2y = constant, x increases 6 cm. Find the magnitude of y’s change in cm.','滑轮约束为 x + 2y = 常数，x 增加 6 cm，y 变化量绝对值为多少 cm？',3,'Δx + 2Δy = 0; Δy = −3 cm; magnitude = 3 cm.','Acceleration ratios follow geometry, not a universal equal-acceleration rule.','加速度比来自几何，而非普遍的相等加速度规则。','All rope-connected bodies always have identical acceleration.','所有绳连物体的加速度总相同。'],
['场、电路与热学综合','Electrical heating|Thermal balance|Feedback','电热效应|热平衡|反馈','A resistor’s electrical power enters a thermal energy balance. Temperature-dependent resistance couples the equations, and heat loss can establish a steady temperature. State whether voltage or current is controlled.','电阻电功率进入热能平衡。电阻随温度变化会耦合方程，散热可建立稳态温度。必须说明控制的是电压还是电流。','A resistor dissipates 12 W for 5 s with negligible loss. Find deposited energy in J.','电阻以 12 W 发热 5 s，忽略损失，产生能量为多少 J？',60,'Q = Pt = 12 × 5 = 60 J.','Constant-voltage and constant-current heating can respond differently to resistance changes.','恒压与恒流加热对电阻变化可能有不同响应。','Heating always remains unchanged when resistance changes.','电阻改变时发热总不变。'],
['光学与现代物理连接','Photon counting|Wave optics|Energy balance','光子计数|波动光学|能量平衡','Use wave optics to determine propagation and interference, then quantized photon energy to relate energy flow to detection counts. A detector’s efficiency and background affect recorded counts.','用波动光学确定传播与干涉，再用光子能量量子化联系能流与探测计数。探测效率与背景会影响实际计数。','A pulse contains energy 20 units and each photon has energy 4 units. Find photon count.','脉冲总能量为 20 单位，每个光子能量为 4 单位，共多少光子？',5,'N = Epulse/Ephoton = 20/4 = 5.','Wave propagation and discrete detection can be parts of one consistent model.','波动传播与离散探测可以属于同一一致模型。','Observing discrete counts disproves all interference effects.','看到离散计数就否定所有干涉现象。'],
['实验数据挑战','Uncertainty comparison|Competing models|Evidence strength','不确定度比较|竞争模型|证据强度','A data challenge requires estimating parameters and comparing residuals with expected errors. Look for systematic deviations and ask whether a rival mechanism predicts the same trend before claiming a unique explanation.','数据题需要估计参数，并把残差与预期误差比较。寻找系统偏离，确认竞争机制是否也能预测同一趋势，然后才能判断解释是否唯一。','A prediction is 10 and a measurement is 12 with stated standard uncertainty 1. Find the difference in uncertainty units.','预测 10，测量 12，给定标准不确定度 1，差值是不确定度的几倍？',2,'|12 − 10|/1 = 2.','Agreement within uncertainty supports but does not uniquely prove a model.','不确定度内一致支持模型，但不能唯一证明模型。','One matching point proves every assumption in a model.','一个吻合点即可证明模型所有假设。'],
['限时理论与实验分析','Problem decomposition|Verification|Partial reasoning','问题分解|验证|局部推理','Under time limits, identify governing laws before algebra, separate independent subproblems and reserve time for dimensions and limits. State intermediate reasoning so a mistake in one calculation does not obscure valid conclusions.','限时解题先确定规律再计算，分离独立子问题，并预留量纲与极限检查时间。写出中间推理，避免一次运算错误掩盖其他有效结论。','A 90-minute set reserves 15 minutes for checks and divides the rest equally among 3 problems. Find minutes per problem.','90 分钟题组预留 15 分钟检查，其余均分三题，每题多少分钟？',25,'(90 − 15)/3 = 25 minutes.','A clearly stated approximation can justify a tractable first model.','明确说明的近似可以支持可求解的初步模型。','A long unexplained equation is stronger evidence than a checked derivation.','长而不解释的方程比检查过的推导更有说服力。']]);

units('P14',['module.P04.06','module.P10.06','math.probability'],[
['微观态、简并度与熵','Microstates|Multiplicity|Boltzmann entropy','微观态|简并度|玻尔兹曼熵','A macrostate groups compatible microscopic configurations. Multiplicity counts them; for equally likely microstates Boltzmann entropy is kB ln Ω. More multiplicity means greater entropy under those conditions.','宏观态集合了相容的微观构型。简并度计数这些构型；等可能微观态下，玻尔兹曼熵为 kB ln Ω。在此条件下，简并度越大，熵越大。','Two distinguishable independent two-state objects have how many joint microstates?','两个可区分且独立的二态对象，共有多少联合微观态？',4,'Ω = 2 × 2 = 4.','Multiplicity counts configurations compatible with the macrostate.','简并度计数与宏观态相容的构型。','Entropy is simply the number of particles.','熵就是粒子数。'],
['系综与配分函数','Statistical ensembles|Boltzmann weights|Partition function','统计系综|玻尔兹曼权重|配分函数','An ensemble specifies constraints and probabilities. At fixed temperature, canonical state weights are exp(−E/kBT); their sum Z normalizes probabilities. Thermodynamic averages follow weighted sums, not equal weighting in general.','系综指定约束与概率。恒温正则态权重为 exp(−E/kBT)，其和 Z 使概率归一化。热力学平均由加权求和得到，通常不是等权平均。','Two states have Boltzmann weights 1 and 3. Find probability of the second.','两态玻尔兹曼权重为 1 和 3，第二态概率是多少？',0.75,'P2 = 3/(1 + 3) = 0.75.','The partition function normalizes statistical weights.','配分函数使统计权重归一化。','Every canonical state must have equal probability.','正则系综各态概率必相等。'],
['经典气体与分布','Maxwell distribution|Equipartition|Mean free path','麦克斯韦分布|能量均分|平均自由程','Classical equilibrium gas speeds have a distribution, not one common speed. Each quadratic energy degree contributes kBT/2 on average when equipartition applies. Collisions define transport scales such as mean free path.','经典平衡气体速率形成分布，并非人人相同。能量均分适用时，每个二次能量自由度平均贡献 kBT/2。碰撞决定平均自由程等输运尺度。','In units kBT = 2, three translational quadratic degrees contribute what mean energy?','取 kBT = 2，三个平动二次自由度的平均能量是多少？',3,'Eaverage = 3(kBT/2) = 3.','Mean speed and root-mean-square speed are different statistics.','平均速率与方均根速率是不同统计量。','Every gas molecule has exactly the average speed.','每个气体分子都恰好具有平均速率。'],
['量子统计','Fermi–Dirac statistics|Bose–Einstein statistics|Classical limit','费米—狄拉克统计|玻色—爱因斯坦统计|经典极限','Fermions obey exclusion while bosons can accumulate in one state. Quantum occupation statistics matter when wavefunctions overlap significantly; low occupation per state leads toward the classical dilute limit.','费米子遵守不相容原理，玻色子可聚集于同一态。波函数显著重叠时，量子占据统计重要；每态占据很低时趋近经典稀薄极限。','For three distinct one-particle states, how many identical spinless fermions can occupy them at most?','三个不同单粒子态最多能容纳几个相同无自旋费米子？',3,'At most one fermion per complete state: 3.','Bosons and fermions have different exchange symmetry.','玻色子与费米子的交换对称性不同。','All quantum particles obey Pauli exclusion.','所有量子粒子都遵守泡利不相容原理。'],
['固体、声子与能带','Lattice vibrations|Phonons|Electronic bands','晶格振动|声子|电子能带','Collective lattice vibrations are quantized as phonons. Electrons in a periodic potential form allowed bands separated by possible gaps. Occupancy and gap structure help distinguish metals, semiconductors and insulators.','晶格集体振动量子化为声子。周期势中的电子形成允许能带及可能的带隙。占据情况与带隙结构帮助区分金属、半导体和绝缘体。','A phonon has energy ℏω = 2 units. What energy is added by creating 3 such phonons?','一个声子能量 ℏω = 2 单位，产生三个这种声子增加多少能量？',6,'ΔE = 3ℏω = 6.','A band gap restricts available electronic energies.','带隙限制电子可取能量。','Electrons in a crystal always have every possible energy.','晶体中电子总能具有任意能量。'],
['相变与集体行为','Order parameter|Critical behavior|Correlations','序参量|临界行为|关联','A phase transition changes macroscopic organization. An order parameter distinguishes phases, and correlations measure how local fluctuations are related. Near some continuous transitions, correlation lengths grow and simple independent-particle pictures fail.','相变改变宏观组织。序参量区分相，关联描述局部涨落之间的联系。在一些连续相变附近，关联长度增长，简单独立粒子图像失效。','Four Ising spins have values +1, +1, +1, −1. Find mean spin.','四个伊辛自旋为 +1、+1、+1、−1，平均自旋是多少？',0.5,'m = (1 + 1 + 1 − 1)/4 = 0.5.','Collective correlations can produce behavior absent in an isolated particle.','集体关联可产生单个孤立粒子所无的行为。','Every phase transition is just an individual particle changing identity.','每种相变都只是单个粒子改变身份。']], [{title:'MIT OpenCourseWare · Statistical Physics I',url:'https://ocw.mit.edu/courses/8-044-statistical-physics-i-spring-2013/'}]);

survey('P04',['module.P03.06'],[
['温度与热平衡','Temperature|Zeroth law|Thermal expansion','温度|热力学第零定律|热膨胀','Temperature orders thermal equilibrium: bodies at the same temperature exchange no net heat when thermally connected. Thermal expansion is a material response, not the definition of temperature.','温度表征热平衡：同温物体热接触时没有净热传递。热膨胀是材料响应，而不是温度本身的定义。','Kelvin temperature is Celsius temperature plus 273.15. Thus 0 °C is 273.15 K.','开尔文温度等于摄氏温度加 273.15，因此 0 °C 为 273.15 K。','Convert 20 °C to kelvin.','把 20 °C 换算为 K。',293.15,'T = 20 + 273.15 = 293.15 K.','Equal temperature does not require equal internal energy.','同温不要求内能相等。','Equal temperature means equal internal energy.','同温意味着内能相等。'],
['理想气体与微观模型','Ideal gas law|Molecular motion|Absolute temperature','理想气体定律|分子运动|绝对温度','The dilute ideal-gas model neglects particle volume and intermolecular potential energy. It gives pV = nRT; temperature measures mean translational kinetic energy in the classical model.','稀薄理想气体忽略粒子体积和分子间势能，满足 pV = nRT；经典模型中温度联系平均平动动能。','At fixed amount and temperature, halving volume doubles pressure.','物质的量与温度不变时，体积减半使压强加倍。','At constant temperature, pressure is 100 kPa at 4 L. Find pressure at 2 L in kPa.','恒温下 4 L 时压强为 100 kPa，2 L 时压强为多少 kPa？',200,'p2 = p1V1/V2 = 100 × 4/2 = 200 kPa.','Absolute temperature must be used in the gas law.','气体定律必须使用绝对温度。','Celsius temperature may replace kelvin in pV = nRT.','pV = nRT 中可直接使用摄氏温度。'],
['热、功与第一定律','Heat transfer|Work|Internal energy','热传递|功|内能','Heat is energy transferred because of a temperature difference. With W defined as work done by the system, the first law is ΔU = Q − W.','热是由温差引起的能量传递。若 W 定义为系统对外做功，第一定律为 ΔU = Q − W。','A gas receives 80 J of heat and does 30 J of work; its internal energy rises by 50 J.','气体吸热 80 J、对外做功 30 J，内能增加 50 J。','A system receives 120 J and does 45 J of work. Find ΔU in J.','系统吸热 120 J，对外做功 45 J，内能变化为多少 J？',75,'ΔU = Q − W = 120 − 45 = 75 J.','Heat and work depend on the process.','热与功取决于过程。','Heat is a substance stored inside a body.','热是储存在物体内的一种物质。'],
['热力学过程','Isothermal process|Adiabatic process|Pressure–volume work','等温过程|绝热过程|压强体积功','Isothermal means constant temperature; adiabatic means no heat transfer. Quasistatic expansion work is the area under the pressure–volume curve. Different paths between identical states can transfer different heat and work.','等温表示温度不变，绝热表示无热传递。准静态膨胀功等于压强—体积曲线下的面积。同一始末态可以通过不同路径传递不同热与功。','At constant 200 Pa, expansion through 0.03 m³ does 6 J of work.','在恒定 200 Pa 下膨胀 0.03 m³，对外做功 6 J。','At constant 1000 Pa, volume increases by 0.02 m³. Find work in J.','压强恒为 1000 Pa，体积增大 0.02 m³，做功为多少 J？',20,'W = pΔV = 1000 × 0.02 = 20 J.','An adiabatic expansion can lower temperature.','绝热膨胀可以使温度下降。','Adiabatic means constant temperature.','绝热就是温度不变。'],
['熵与第二定律','Entropy|Reversibility|Total entropy change','熵|可逆性|总熵变化','For a reversible heat transfer, dS = δQrev/T. An isolated system’s total entropy cannot decrease. Local entropy can decrease if entropy exported to the surroundings more than compensates.','可逆热传递满足 dS = δQ可逆/T。孤立系统总熵不能减少。局部熵可以下降，只要向环境输出的熵充分补偿。','Reversibly adding 600 J at constant 300 K increases entropy by 2 J/K.','在 300 K 下可逆吸热 600 J，熵增加 2 J/K。','Reversible heat input is 900 J at 300 K. Find ΔS in J/K.','在 300 K 下可逆吸热 900 J，熵变为多少 J/K？',3,'ΔS = Qrev/T = 900/300 = 3 J/K.','The second law concerns system plus surroundings for a nonisolated system.','非孤立系统应用第二定律时应考虑系统与环境。','Entropy of every individual object must always increase.','每个物体的熵都必须一直增加。'],
['热机、制冷机与相变','Heat-engine efficiency|Refrigeration|Latent heat','热机效率|制冷|潜热','A cyclic heat engine converts part of heat input into work and rejects the rest. A refrigerator uses work to move heat from cold to hot. During an equilibrium phase change, heat can change phase fraction without changing temperature.','循环热机把部分输入热转为功，其余排出。制冷机消耗功把热从低温处搬到高温处。平衡相变时，热可以改变相比例而不改变温度。','Receiving 100 J and rejecting 60 J gives 40 J of work and efficiency 0.40.','吸热 100 J、放热 60 J，做功 40 J，效率为 0.40。','An engine receives 200 J and produces 50 J work. Find efficiency as a decimal.','热机吸热 200 J，做功 50 J，效率的小数值是多少？',0.25,'η = W/Qhot = 50/200 = 0.25.','A cyclic engine must reject heat when operating between finite-temperature reservoirs.','在有限温度热库间工作的循环热机必须向外放热。','Every heat engine can convert all heat input into work.','所有热机都能把全部输入热转化为功。']]);

survey('P05',['module.P01.06','chemistry.atoms'],[
['电荷与库仑力','Charge conservation|Coulomb law|Superposition','电荷守恒|库仑定律|叠加','Charge comes in positive and negative forms and is conserved. Point charges exert a force k|q1q2|/r² along their separation; vector forces from several charges add.','电荷有正负两种并满足守恒。点电荷间力大小为 k|q1q2|/r²，沿连线方向；多个电荷的力按矢量叠加。','Doubling one charge doubles force, whereas doubling distance reduces force to one quarter.','一个电荷加倍使力加倍，距离加倍则使力降为四分之一。','Force is 20 N at distance r. Find force at 2r in N.','距离 r 时力为 20 N，距离 2r 时为多少 N？',5,'Fnew = 20/2² = 5 N.','Opposite charges attract and like charges repel.','异种电荷相吸，同种电荷相斥。','The Coulomb force always attracts.','库仑力总是吸引力。'],
['电场与电势','Electric field|Potential difference|Force and energy','电场|电势差|力与能量','Electric field is force per positive test charge: E = F/q. Potential difference is potential-energy change per charge: ΔV = ΔU/q. Field direction is toward decreasing potential.','电场为正试探电荷所受力除以电荷量：E = F/q。电势差为单位电荷势能变化：ΔV = ΔU/q。电场指向电势降低的方向。','A 2 C charge moving through a potential rise of 3 V gains 6 J potential energy.','2 C 电荷经过 3 V 的电势升高，势能增加 6 J。','A charge of 3 C moves through a 4 V potential rise. Find ΔU in J.','3 C 电荷经过 4 V 电势升高，势能增加多少 J？',12,'ΔU = qΔV = 3 × 4 = 12 J.','Field is a vector; potential is a scalar.','电场是矢量，电势是标量。','Zero potential at a point guarantees zero electric field there.','一点电势为零就保证该点电场为零。'],
['导体、电容器与电介质','Electrostatic conductor|Capacitance|Dielectric polarization','静电导体|电容|介质极化','In electrostatic equilibrium a conductor has zero internal field and an equipotential surface. Capacitance C = Q/V measures charge storage per voltage. Dielectrics polarize and can increase capacitance for fixed geometry.','静电平衡导体内部电场为零，表面等势。电容 C = Q/V 表示单位电压储存的电荷。电介质发生极化，在固定几何下可增大电容。','A 2 μF capacitor at 5 V stores 10 μC charge.','2 μF 电容器加 5 V 电压，储存 10 μC 电荷。','A 3 μF capacitor is at 4 V. Find charge in μC.','3 μF 电容器电压为 4 V，电荷量为多少 μC？',12,'Q = CV = 3 × 4 = 12 μC.','Capacitance depends on geometry and material.','电容取决于几何与材料。','The capacitance of an ideal capacitor changes whenever its voltage changes.','理想电容器的电容总随电压变化。'],
['电流、电阻与功率','Current|Ohmic resistance|Electrical power','电流|欧姆电阻|电功率','Current is charge crossing a section per time. An ohmic element obeys V = IR over its stated conditions. Power transferred is VI; for a resistor this becomes I²R.','电流为单位时间穿过截面的电荷。欧姆元件在规定条件下满足 V = IR。传递功率为 VI，电阻中可写为 I²R。','A 6 V source across 3 Ω drives 2 A and supplies 12 W.','6 V 电源接 3 Ω 电阻，电流为 2 A，功率为 12 W。','Find current through 4 Ω at 12 V in A.','4 Ω 电阻两端为 12 V，电流为多少 A？',3,'I = V/R = 12/4 = 3 A.','Resistance can depend on temperature.','电阻可以依赖温度。','Every electrical component obeys a constant-resistance Ohm law.','所有电学元件都满足恒定电阻的欧姆定律。'],
['基尔霍夫定律与电路模型','Junction rule|Loop rule|Equivalent resistance','节点定律|回路定律|等效电阻','Charge conservation makes incoming and outgoing steady currents balance at a junction. Energy accounting makes signed voltage changes sum to zero around a lumped circuit loop without unaccounted changing magnetic flux.','电荷守恒要求稳态节点流入与流出电流平衡。无未计入时变磁通的集中参数电路中，绕闭合回路的带符号电压变化总和为零。','Series resistors 2 Ω and 5 Ω carry the same current and have equivalent resistance 7 Ω.','2 Ω 与 5 Ω 电阻串联，电流相同，等效电阻为 7 Ω。','At a junction 5 A enters; one branch carries 2 A out. Find the other outgoing current in A.','节点流入 5 A，一支路流出 2 A，另一支路流出多少 A？',3,'Iother = 5 − 2 = 3 A.','Parallel branches share voltage, not necessarily current.','并联支路电压相同，电流不一定相同。','All currents in a parallel network are equal.','并联电路中各电流总相等。'],
['RC 暂态与测量','Time constant|Exponential charging|Instrument loading','时间常数|指数充电|仪器负载','An ideal RC circuit has time constant τ = RC. During charging from zero, capacitor voltage is Vs(1 − exp(−t/τ)). A meter with finite input resistance can change the circuit it measures.','理想 RC 电路时间常数为 τ = RC。从零开始充电时，电容电压为 Vs(1 − exp(−t/τ))。输入电阻有限的电表可能改变被测电路。','A 1000 Ω resistor and 0.001 F capacitor give τ = 1 s.','1000 Ω 电阻与 0.001 F 电容的时间常数为 1 s。','R = 2000 Ω and C = 0.003 F. Find τ in seconds.','R = 2000 Ω，C = 0.003 F，时间常数为多少秒？',6,'τ = RC = 2000 × 0.003 = 6 s.','The ideal capacitor voltage approaches its final value asymptotically.','理想电容电压渐近接近最终值。','Charging is complete exactly after one time constant.','经过一个时间常数就完全充电。']]);

survey('P06',['module.P05.06','math.vectors'],[
['磁力与带电粒子运动','Lorentz force|Circular orbit|Magnetic work','洛伦兹力|圆轨道|磁力做功','Magnetic force qv × B is perpendicular to velocity. It changes direction but does no work on a point charge. Perpendicular motion in uniform B follows a circle of radius mv/(|q|B).','磁力 qv × B 垂直于速度，改变方向但不对点电荷做功。速度垂直均匀磁场时，圆轨道半径为 mv/(|q|B)。','For perpendicular motion with q = 2 C, v = 3 m/s and B = 4 T, force magnitude is 24 N.','q = 2 C、v = 3 m/s、B = 4 T 且彼此垂直时，磁力为 24 N。','For q = 1 C, v = 5 m/s and perpendicular B = 2 T, find force in N.','q = 1 C，v = 5 m/s，垂直磁场 B = 2 T，磁力为多少 N？',10,'F = |q|vB = 1 × 5 × 2 = 10 N.','A parallel velocity component feels no magnetic force.','平行于磁场的速度分量不受磁力。','A stationary charge always feels a magnetic force.','静止电荷总受磁力。'],
['电流产生的磁场','Biot–Savart law|Ampere law|Symmetry','毕奥—萨伐尔定律|安培定律|对称性','Steady currents produce magnetic fields. A long straight wire gives B = μ0I/(2πr). Ampere’s integral law is especially useful when symmetry makes field magnitude constant along a suitable loop.','稳恒电流产生磁场。长直导线产生 B = μ0I/(2πr)。当对称性使适当回路上的场强大小恒定时，安培环路定律特别有用。','At fixed distance from a long wire, tripling current triples magnetic field.','到长直导线距离不变时，电流增为三倍，磁场也增为三倍。','A wire produces 8 μT at r. Find field at 2r in μT.','导线在 r 处产生 8 μT 磁场，2r 处为多少 μT？',4,'Bnew = 8/2 = 4 μT.','Magnetic field around a straight current is circular.','直电流周围的磁场线呈圆周形。','The field points directly radially away from every straight wire.','直导线磁场总沿径向远离导线。'],
['磁通与电磁感应','Magnetic flux|Faraday law|Induced emf','磁通|法拉第定律|感应电动势','Magnetic flux through a flat surface in uniform field is BA cos θ, with θ measured from the normal. Faraday’s law gives emf equal to the negative rate of flux linkage change.','均匀磁场穿过平面的磁通为 BA cos θ，其中 θ 从法线量起。法拉第定律给出电动势等于磁通链变化率的负值。','A single loop’s flux changes by 0.6 Wb in 0.2 s; average emf magnitude is 3 V.','单匝线圈磁通在 0.2 s 内改变 0.6 Wb，平均感应电动势大小为 3 V。','Flux changes by 0.8 Wb over 0.4 s in one turn. Find average emf magnitude in V.','单匝磁通在 0.4 s 内改变 0.8 Wb，平均电动势大小为多少 V？',2,'|emf| = |ΔΦ/Δt| = 0.8/0.4 = 2 V.','Changing area or orientation can induce emf even when B is constant.','B 不变时，改变面积或朝向仍可产生感应电动势。','Induction requires the field magnitude itself to change.','感应必须要求磁场大小改变。'],
['楞次定律与能量守恒','Opposition to flux change|Mechanical work|Induced current','反抗磁通变化|机械功|感应电流','Lenz’s law selects an induced-current direction whose magnetic effect opposes the change that caused it. The opposition accounts for mechanical work becoming electrical energy and heat.','楞次定律确定感应电流方向：其磁效应反抗引发感应的磁通变化。这种反抗解释机械功如何转为电能与热。','If increasing upward flux induces downward field, the induced current opposes the increase, not necessarily the existing total field.','向上磁通增大时，感应场向下，反抗的是增加过程，而不是必然抵消已有总场。','An induced 6 V emf drives a 3 Ω loop. Find current magnitude in A.','6 V 感应电动势作用于 3 Ω 回路，电流大小为多少 A？',2,'I = |emf|/R = 6/3 = 2 A.','The induced response opposes flux change.','感应响应反抗磁通的变化。','The induced field always opposes the external field regardless of whether it grows or shrinks.','无论外磁场增强还是减弱，感应场总与外场反向。'],
['电感与交流电路','Self-inductance|Reactance|Phase','自感|电抗|相位','An inductor opposes current change with emf −L dI/dt and stores LI²/2 magnetic energy. In sinusoidal circuits reactance depends on frequency; current and voltage need not peak simultaneously.','电感以电动势 −L dI/dt 反抗电流变化，储存 LI²/2 磁能。正弦交流中电抗依赖频率，电流与电压峰值不一定同时出现。','An inductance of 2 H with current 3 A stores 9 J.','2 H 电感通过 3 A 电流时储能 9 J。','L = 4 H and I = 2 A. Find stored energy in J.','L = 4 H，I = 2 A，储能为多少 J？',8,'U = LI²/2 = 4 × 2²/2 = 8 J.','An ideal inductor’s voltage depends on current change.','理想电感的电压取决于电流变化。','Inductor voltage always equals L times current.','电感电压总等于 L 乘电流。'],
['电磁波与麦克斯韦概览','Displacement current|Coupled fields|Wave speed','位移电流|耦合场|波速','Maxwell’s equations connect charges and currents with electric and magnetic fields. Time-varying fields sustain electromagnetic waves; in vacuum their speed is 1/√(μ0ε0). Displacement current completes charge conservation in changing fields.','麦克斯韦方程把电荷、电流与电磁场联系起来。时变场可维持电磁波，真空波速为 1/√(μ0ε0)。位移电流使时变场中的电荷守恒完整成立。','For any periodic wave, speed equals frequency times wavelength.','任何周期波都满足波速等于频率乘波长。','Using c = 3×10^8 m/s and f = 10^8 Hz, find vacuum wavelength in metres.','取 c = 3×10^8 m/s，f = 10^8 Hz，真空波长为多少米？',3,'λ = c/f = 3×10^8 / 10^8 = 3 m.','Electromagnetic waves can propagate through vacuum.','电磁波能在真空中传播。','Every wave requires a material medium.','所有波都需要物质介质。']]);

survey('P07',['module.P03.06'],[
['波的传播与叠加','Wave speed|Phase|Superposition','波速|相位|叠加','A travelling disturbance transfers energy without transporting the medium as a whole. Frequency counts cycles; wavelength separates equal phases. In a linear medium, overlapping displacements add.','传播的扰动传递能量，却不使介质整体随波迁移。频率计数周期，波长连接同相位点。线性介质中，重叠位移相加。','A wave of frequency 5 Hz and wavelength 2 m moves at 10 m/s.','频率 5 Hz、波长 2 m 的波，波速为 10 m/s。','For f = 4 Hz and λ = 3 m, find speed in m/s.','f = 4 Hz，λ = 3 m，波速为多少 m/s？',12,'v = fλ = 4 × 3 = 12 m/s.','Wave speed and particle speed describe different motions.','波速与介质质点速度描述不同运动。','Every particle travels with the wavefront indefinitely.','所有质点都会一直跟随波前前进。'],
['驻波与声音','Nodes|Resonant modes|Sound intensity','波节|共振模式|声强','Oppositely travelling coherent waves can form stationary nodes and antinodes. A string fixed at both ends permits wavelengths 2L/n. Sound is a pressure disturbance, and intensity measures transmitted power per area.','相反方向的相干波可以形成固定波节与波腹。两端固定弦允许波长 2L/n。声音是压强扰动，声强表示单位面积传递的功率。','A 1 m string with speed 100 m/s has fundamental frequency 50 Hz.','1 m 长弦的波速为 100 m/s，基频为 50 Hz。','A fixed-end string has L = 2 m and v = 80 m/s. Find fundamental frequency in Hz.','两端固定弦 L = 2 m，v = 80 m/s，基频为多少 Hz？',20,'f1 = v/(2L) = 80/4 = 20 Hz.','Standing-wave nodes have zero displacement amplitude.','驻波波节的位移振幅为零。','Every point of a standing wave has equal amplitude.','驻波每一点的振幅都相同。'],
['反射与折射','Reflection angle|Snell law|Total internal reflection','反射角|斯涅尔定律|全反射','Angles are measured from the surface normal. Reflection preserves that angle; refraction obeys n1 sin θ1 = n2 sin θ2. Total internal reflection requires incidence from higher to lower refractive index above the critical angle.','角度从界面法线量起。反射角等于入射角，折射满足 n1 sin θ1 = n2 sin θ2。全反射要求从高折射率进入低折射率介质且超过临界角。','At normal incidence the ray direction does not bend even though speed changes.','垂直入射时，传播速度虽然改变，光线方向却不偏折。','A ray has incidence angle 35°. Find reflection angle in degrees.','入射角为 35°，反射角为多少度？',35,'θreflection = θincidence = 35°.','Refraction changes wavelength while frequency stays continuous at a stationary boundary.','静止界面折射会改变波长，而频率保持连续。','Frequency must change whenever light enters glass.','光进入玻璃时频率必然改变。'],
['透镜与光学仪器','Thin-lens equation|Magnification|Real and virtual images','薄透镜公式|放大率|实像与虚像','A consistent sign convention gives 1/f = 1/u + 1/v and transverse magnification −v/u for a thin lens. Real images involve converging rays; virtual images locate apparent ray origins.','在一致的符号约定下，薄透镜满足 1/f = 1/u + 1/v，横向放大率为 −v/u。实像由光线实际会聚形成，虚像对应光线看似发出的地点。','An object at twice the focal length forms a same-size inverted real image at twice the focal length.','物体位于二倍焦距时，在另一侧二倍焦距形成等大倒立实像。','For f = 10 cm and u = 20 cm, find positive image distance v in cm.','f = 10 cm，u = 20 cm，正像距 v 为多少 cm？',20,'1/v = 1/10 − 1/20 = 1/20; v = 20 cm.','A converging lens can form a virtual image when the object is inside its focal distance.','物体在焦距以内时，会聚透镜可以形成虚像。','A converging lens always makes a real image.','会聚透镜总成实像。'],
['干涉与衍射','Path difference|Coherence|Diffraction scale','光程差|相干性|衍射尺度','Coherent waves interfere according to phase difference. Equal-phase sources reinforce at path differences mλ. Finite apertures spread waves by diffraction; narrow openings produce wider angular spreading.','相干波按相位差发生干涉。同相源在程差 mλ 处相长。有限孔径通过衍射使波扩散，开口越窄，角向扩展越大。','Two equal in-phase amplitudes A sum to 2A; intensity scales with amplitude squared, giving four times one-wave intensity.','两个同相等振幅 A 相加得到 2A；强度与振幅平方成正比，因此为单波强度四倍。','Two equal in-phase amplitudes are each 3 units. Find resulting amplitude.','两个同相振幅各为 3 单位，合振幅是多少？',6,'Aresult = 3 + 3 = 6.','Interference requires stable relative phase for a stable pattern.','稳定干涉图样需要稳定的相对相位。','Independent random-phase sources always produce stable bright and dark fringes.','独立随机相位光源总产生稳定明暗条纹。'],
['偏振与波模型边界','Transverse polarization|Malus law|Photon evidence','横波偏振|马吕斯定律|光子证据','Polarization describes the direction of transverse field oscillation. An ideal analyzer transmits I = I0 cos²θ for linearly polarized input. Wave optics explains interference, while quantized energy exchange requires a photon description.','偏振描述横向场振动方向。线偏振光经过理想检偏器时，I = I0 cos²θ。波动光学解释干涉，而量子化能量交换需要光子描述。','A 60° analyzer transmits one quarter of incident polarized intensity.','检偏器夹角为 60° 时，透过入射线偏振光强度的四分之一。','At 60° an ideal analyzer receives intensity 80 units. Find transmitted intensity.','理想检偏器夹角为 60°，入射线偏振强度 80 单位，透射强度是多少？',20,'I = 80 cos²60° = 80/4 = 20.','Polarization is evidence of transverse wave structure.','偏振体现横波结构。','Longitudinal sound in air is polarized in the same way as light.','空气中的纵向声波与光具有相同方式的偏振。']]);

compact('P02',['功与动能','势能与能量守恒','冲量、动量与碰撞','质心与多粒子系统','力矩、转动与角动量','滚动与刚体平衡'],
'Energy and momentum provide complementary descriptions of motion. Kinetic energy is a scalar, mv²/2 for a nonrelativistic particle, while momentum is the vector mv. External work changes kinetic energy; external impulse changes total momentum. Choose a system before deciding which interactions are internal. Internal forces may redistribute energy or momentum without changing an isolated system’s total momentum. Mechanical energy is conserved only when nonconservative transfers are absent or explicitly included. Keep rotational and translational motion distinct, and always specify the axis for angular quantities.',
'能量与动量提供互补的运动描述。非相对论质点的动能为标量 mv²/2，动量则为矢量 mv。外力做功改变动能，外力冲量改变总动量。判断内外相互作用前先选系统。内力可以重新分配能量或动量，但不会改变孤立系统总动量。只有不存在非保守能量转移，或已将其计入时，才能正确使用能量守恒。要区分平动和转动，并明确角量所对应的轴。',['module.P01.06'],[
['Force–displacement work|Kinetic energy|Work–energy theorem','力与位移的功|动能|动能定理','For a constant force, work is Fs cos θ. Summing the work of all forces gives the change in kinetic energy. A perpendicular force does zero work even while changing direction.','恒力做功为 Fs cos θ。所有力做功之和等于动能变化。垂直于位移的力不做功，却仍能改变运动方向。','A 5 N force parallel to a 3 m displacement does 15 J of work.','5 N 力与 3 m 位移同向，做功 15 J。','A 4 N parallel force acts through 6 m. Find work in J.','4 N 力沿位移作用 6 m，做功为多少 J？',24,'W = Fs = 4 × 6 = 24 J.','Work can be negative when force opposes displacement.','力与位移相反时，功可为负。','Every force does positive work.','所有力都做正功。'],
['Conservative force|Potential energy|Energy accounting','保守力|势能|能量账目','A conservative force permits a potential energy U with work W = −ΔU. Near Earth, gravitational U = mgh relative to a chosen zero. With only conservative forces, K + U is constant.','保守力允许定义势能 U，满足 W = −ΔU。近地面重力势能为相对选定零点的 mgh。只有保守力做功时，K + U 保持不变。','Dropping 2 kg through 5 m with g = 10 m/s² releases 100 J of gravitational potential energy.','2 kg 物体下降 5 m，取 g = 10 m/s²，重力势能减少 100 J。','For m = 3 kg, g = 10 m/s² and height gain 2 m, find ΔU in J.','m = 3 kg，g = 10 m/s²，上升 2 m，势能增加多少 J？',60,'ΔU = mgΔh = 3 × 10 × 2 = 60 J.','Potential-energy differences are independent of the chosen zero.','势能差与所选零点无关。','Absolute gravitational potential energy has one compulsory zero.','重力势能只有一个强制零点。'],
['Impulse|Momentum conservation|Elasticity','冲量|动量守恒|弹性程度','Impulse is force integrated over time, or average force times duration. In an isolated collision total momentum is conserved; kinetic energy is also conserved only for an elastic collision. Sticking collisions are perfectly inelastic.','冲量是力对时间的积分，也可用平均力乘作用时间。孤立碰撞中总动量守恒；只有弹性碰撞还保持总动能不变。碰后粘在一起的碰撞称完全非弹性碰撞。','A 2 kg cart at 3 m/s sticks to a stationary 1 kg cart. The common speed is 6/3 = 2 m/s.','2 kg 小车以 3 m/s 撞上静止的 1 kg 小车并粘合，共同速度为 6/3 = 2 m/s。','A 10 N average force acts for 0.4 s. Find impulse in N·s.','10 N 平均力作用 0.4 s，冲量为多少 N·s？',4,'J = Faverage Δt = 10 × 0.4 = 4 N·s.','Momentum can be conserved while kinetic energy decreases.','动量守恒时，动能仍可减少。','Every collision conserves kinetic energy.','所有碰撞都保持动能不变。'],
['Mass-weighted position|External force|Internal interactions','质量加权位置|外力|内部相互作用','The centre of mass has position Σmixi/Σmi. Its acceleration equals total external force divided by total mass. Internal forces can change relative motion while the centre follows the external-force equation.','质心位置为 Σmixi/Σmi。质心加速度等于合外力除以总质量。内力可以改变相对运动，而质心仍满足由外力决定的运动方程。','Masses 1 kg at x = 0 and 3 kg at x = 4 m have centre x = 3 m.','1 kg 质量在 x = 0，3 kg 质量在 x = 4 m，质心位于 x = 3 m。','Equal masses lie at x = 2 m and x = 8 m. Find centre-of-mass x in m.','相等质量分别位于 x = 2 m 与 8 m，质心 x 为多少米？',5,'xCM = (2 + 8)/2 = 5 m.','The centre of mass may lie outside the material of a hollow body.','空心物体的质心可以位于没有材料的空间。','The centre of mass must always contain matter.','质心位置必须有物质。'],
['Torque|Moment of inertia|Angular momentum','力矩|转动惯量|角动量','Torque is the vector r × F; its magnitude is force times perpendicular lever arm. About a fixed axis, τnet = Iα when I is constant. Angular momentum changes under external torque and is conserved when that torque vanishes.','力矩为矢量 r × F，大小等于力乘垂直力臂。绕固定轴且 I 不变时，τ合 = Iα。外力矩改变角动量；合外力矩为零时角动量守恒。','A 6 N perpendicular force applied 0.5 m from a pivot produces 3 N·m of torque.','在离支点 0.5 m 处施加垂直的 6 N 力，力矩为 3 N·m。','A torque of 12 N·m acts on I = 3 kg·m². Find α in rad/s².','12 N·m 力矩作用于 I = 3 kg·m² 的物体，角加速度为多少 rad/s²？',4,'α = τ/I = 12/3 = 4 rad/s².','Moment of inertia depends on the chosen rotation axis.','转动惯量取决于所选转轴。','Mass alone determines moment of inertia.','只知道质量就能确定转动惯量。'],
['No-slip rolling|Static equilibrium|Translational and rotational energy','无滑动滚动|静力平衡|平动与转动能','Pure rolling satisfies vCM = ωR at a stationary surface. Its kinetic energy is MvCM²/2 + ICMω²/2. Static rigid-body equilibrium requires both zero net force and zero net torque.','在静止表面纯滚动时，v质心 = ωR。总动能为 Mv质心²/2 + I质心ω²/2。刚体静力平衡既要求合力为零，也要求合力矩为零。','A wheel of radius 0.2 m rotating at 10 rad/s rolls at 2 m/s. The instantaneous contact point is at rest relative to the ground.','半径 0.2 m 的轮以 10 rad/s 转动，纯滚动速率为 2 m/s；接触点瞬时相对地面静止。','A wheel rolls without slipping with R = 0.3 m and ω = 20 rad/s. Find vCM in m/s.','半径 0.3 m 的轮以 20 rad/s 纯滚动，质心速率为多少 m/s？',6,'vCM = ωR = 20 × 0.3 = 6 m/s.','Zero net force alone does not guarantee rotational equilibrium.','合力为零并不保证转动平衡。','A force couple has no rotational effect because its net force is zero.','力偶合力为零，所以没有转动效应。']]);

compact('P03',['万有引力与轨道','静止流体与浮力','流动、连续性与伯努利模型','简谐运动','阻尼与共振','耦合振动入门'],
'A force law together with an equation of motion predicts a system’s evolution. In gravity the inverse-square dependence concerns distance from the attracting mass centre. In fluids, pressure is normal force per unit area and depends on depth at rest. For oscillations, displacement is measured from equilibrium and a restoring effect points back toward that equilibrium. Density is mass divided by volume, while frequency counts cycles per second. Distinguish equilibrium, steady flow and periodic motion: each has different simplifying assumptions and different conserved quantities.',
'力的规律与运动方程共同决定系统演化。引力的平方反比关系使用到吸引质量中心的距离。流体中的压强是单位面积法向力，静止时随深度改变。振动位移从平衡位置量起，回复作用指向平衡位置。密度是质量除以体积，频率是每秒周期数。要区分平衡、稳定流动与周期运动，因为它们的简化假设和守恒量不同。',['module.P02.06'],[
['Inverse-square gravity|Circular orbit|Orbital energy','平方反比引力|圆轨道|轨道能量','Newtonian gravity has magnitude GMm/r². For a circular orbit it supplies mv²/r, giving v² = GM/r. Gravitational potential energy referenced to infinity is −GMm/r.','牛顿引力大小为 GMm/r²。圆轨道中它提供 mv²/r，因此 v² = GM/r。以无穷远为零点时，引力势能为 −GMm/r。','Doubling orbital radius reduces gravitational force to one quarter, not one half.','轨道半径加倍时，引力减至四分之一，而不是一半。','At radius r the force is 36 N. What is the force at 3r in N?','距离 r 处引力为 36 N，距离 3r 处为多少 N？',4,'Fnew = 36/3² = 4 N.','An orbit is continuous free fall with sufficient sideways motion.','轨道运动是具有足够侧向运动的持续自由落体。','Orbiting bodies experience no gravity.','轨道上的物体不受引力。'],
['Hydrostatic pressure|Buoyant force|Displaced volume','静水压强|浮力|排开体积','In a constant-density fluid, pressure rises by ρgh with depth. A submerged body experiences buoyancy equal to the weight of displaced fluid. Floating equilibrium therefore equates displaced fluid weight and body weight.','恒定密度流体中，压强随深度增加 ρgh。浸入物体的浮力等于所排开流体的重量。漂浮平衡时，排开流体的重量等于物体重量。','A displaced volume of 0.002 m³ of water has mass 2 kg and buoyancy 20 N if g = 10 m/s².','排开 0.002 m³ 水，相应质量为 2 kg；取 g = 10 m/s²，浮力为 20 N。','For ρ = 1000 kg/m³, g = 10 m/s² and depth 3 m, find gauge pressure in Pa.','ρ = 1000 kg/m³，g = 10 m/s²，深度 3 m，表压为多少 Pa？',30000,'Δp = ρgh = 1000 × 10 × 3 = 30000 Pa.','Buoyancy depends on displaced fluid volume and density.','浮力取决于排开流体的体积和密度。','Buoyancy always equals the object’s weight.','浮力总等于物体重力。'],
['Continuity|Bernoulli relation|Model limitations','连续性|伯努利关系|模型限制','Steady incompressible flow satisfies Av = constant along a tube. For inviscid flow along a streamline, p + ρv²/2 + ρgh is constant. Pumps, viscous losses and changing density require additional terms or different models.','稳定不可压缩管流满足 Av 不变。沿无黏性流体流线，p + ρv²/2 + ρgh 为常数。泵、黏性损失或密度变化需要额外项或不同模型。','Halving a pipe’s area doubles the mean flow speed when volume flow stays fixed.','体积流量不变时，管道截面积减半，平均流速加倍。','Water moves at 2 m/s through area 6 cm². Find speed through area 3 cm² in m/s.','水以 2 m/s 流经 6 cm² 截面，流经 3 cm² 截面时速率为多少 m/s？',4,'v2 = A1v1/A2 = 6 × 2/3 = 4 m/s.','Bernoulli’s simple form assumes negligible dissipative losses.','简单伯努利方程假定耗散损失可忽略。','Bernoulli’s equation applies unchanged across every pump.','任何泵两端都能直接使用不变的伯努利方程。'],
['Linear restoring force|Period|Energy exchange','线性回复力|周期|能量交换','For a spring, F = −kx gives simple harmonic motion with angular frequency √(k/m). Position varies sinusoidally and period is 2π√(m/k). Kinetic and elastic potential energy exchange while their sum remains constant without damping.','弹簧回复力 F = −kx 产生角频率 √(k/m) 的简谐运动。位移按正弦变化，周期为 2π√(m/k)。无阻尼时，动能与弹性势能相互转换，总和不变。','With m = 1 kg and k = 4 N/m, angular frequency is 2 rad/s.','m = 1 kg、k = 4 N/m 时，角频率为 2 rad/s。','For m = 2 kg and k = 18 N/m, find angular frequency in rad/s.','m = 2 kg、k = 18 N/m，角频率为多少 rad/s？',3,'ω = √(k/m) = √(18/2) = 3 rad/s.','In the ideal linear spring model, period is independent of amplitude.','理想线性弹簧模型中，周期与振幅无关。','Every oscillation is exactly sinusoidal at any amplitude.','所有振动在任何振幅下都是严格正弦运动。'],
['Dissipation|Driven oscillation|Resonance width','耗散|受迫振动|共振宽度','Damping transfers oscillation energy into other forms. A periodic driving force can replace that loss. The steady response depends on driving frequency; a lightly damped system has a large response near its natural frequency. Stronger damping usually broadens and reduces the resonance peak.','阻尼把振动能转移为其他形式。周期驱动力可补充损失。稳态响应依赖驱动频率；弱阻尼系统在固有频率附近响应较大。阻尼增大通常使共振峰降低并变宽。','If amplitude decays by a factor of one half each second, an initial 8 mm becomes 2 mm after two seconds.','若振幅每秒减半，初始 8 mm 振幅两秒后变为 2 mm。','Amplitude is multiplied by 0.5 each cycle. Starting at 16 mm, what is it after three cycles?','振幅每周期乘 0.5，初始 16 mm，三个周期后为多少 mm？',2,'A = 16 × (0.5)³ = 2 mm.','A driven damped steady state can have constant amplitude despite ongoing energy loss.','受迫阻尼稳态可在持续损耗能量时保持振幅不变。','Constant amplitude proves there is no energy dissipation.','振幅恒定就证明没有能量耗散。'],
['Coupling|Normal modes|Superposition','耦合|简正模|叠加','Coupled oscillators exchange energy through their interaction. A normal mode is a collective pattern in which all coordinates oscillate at one frequency with fixed amplitude ratios. Linear systems permit a general motion to be decomposed into such modes.','耦合振子通过相互作用交换能量。简正模是一种集体运动模式：各坐标以同一频率振动，振幅比固定。线性系统的一般运动可以分解为这些模式的叠加。','Two identical masses connected symmetrically can move together or oppositely. The coupling spring stretches differently in the two patterns, so their frequencies differ.','对称连接的两个相同质量可以同相或反相运动。两种模式使耦合弹簧伸长不同，因此频率不同。','Two mode frequencies are 10 and 12 Hz. What is their frequency difference in Hz?','两个模式频率为 10 与 12 Hz，频率差为多少 Hz？',2,'Δf = 12 − 10 = 2 Hz.','Normal-mode decomposition relies on linearized equations.','简正模分解依赖线性化方程。','Every coupled nonlinear system is an exact sum of independent fixed modes.','所有耦合非线性系统都能精确写成独立固定模式的和。']]);

course('P01',
'Mechanics describes how positions change and why changes of velocity occur. Choose a system, an origin, a positive direction and a clock before writing equations. A particle model ignores size and rotation when these do not affect the question. A vector carries direction as well as magnitude; its components are signed numbers along chosen axes. Mass measures inertia in kilograms. Force is an interaction measured in newtons, where one newton equals one kilogram metre per second squared. Equations describe these quantities, not merely numbers.',
'力学研究位置怎样改变，以及速度为何改变。列式前先选定系统、原点、正方向和时钟。当大小和转动不影响问题时，可以使用质点模型。矢量同时具有大小与方向；分量是沿选定坐标轴的带符号数。质量用千克表示，衡量惯性。力描述相互作用，单位牛顿；一牛顿等于一千克米每二次方秒。方程描述的是这些物理量，而不只是数字。',
'The same motion can be represented by words, a diagram, a graph and equations. Agreement between these representations is a useful independent check. Calculus later replaces interval averages with instantaneous rates.',
'同一运动可以用语言、图示、图像和方程表示。各表示之间相互一致，是有效的独立检查。微积分以后将用瞬时变化率代替区间平均量。',
['physics.motion','math.vectors'],[
['一维运动学','Position and displacement|Velocity and acceleration|Constant-acceleration conditions','位置与位移|速度与加速度|匀加速条件','Displacement is final position minus initial position. Average velocity divides displacement by elapsed time; average speed instead uses total path length. Acceleration is velocity change per time. When acceleration is constant, v = u + at and displacement s = ut + at²/2. The signs must refer to the same axis throughout.','位移等于末位置减初位置。平均速度用位移除以时间；平均速率则使用总路程。加速度是速度随时间的变化。加速度恒定时，v = u + at，位移 s = ut + at²/2。所有正负号必须始终对应同一坐标轴。','Starting from rest with a = 2 m/s² for 3 s gives v = 6 m/s and s = 9 m. The velocity–time graph is a straight line; its triangular area is also 9 m.','从静止开始，以 2 m/s² 加速 3 s，末速度为 6 m/s，位移为 9 m。速度—时间图像是一条直线，其下三角形面积同样为 9 m。','From rest, constant acceleration is 3 m/s² for 4 s. Find displacement in metres.','从静止开始，以 3 m/s² 匀加速 4 s，位移为多少米？',24,'s = 0 × 4 + 3 × 4² / 2 = 24 m.','Negative acceleration need not mean slowing down: negative velocity becoming more negative increases speed. The constant-acceleration equations fail when acceleration varies.','负加速度不一定表示减速：负速度变得更负时，速率反而增加。加速度变化时不能直接套用匀加速公式。','Displacement can be zero after a nonzero journey.','经过非零路程后，位移仍可为零。','Distance and displacement are always identical.','路程与位移总是相同。'],
['二维与三维运动','Vector components|Projectile motion|Independent axes','矢量分量|抛体运动|各轴独立','Resolve position, velocity and acceleration along perpendicular axes. Without air resistance near Earth, a projectile has constant horizontal velocity and downward acceleration g. Horizontal and vertical motions share the same time, which links their equations. In three dimensions a third independent component is added; vector magnitude uses the square root of the sum of squared components.','把位置、速度和加速度分解到互相垂直的坐标轴。近地面忽略空气阻力时，抛体水平速度恒定，竖直加速度为向下的 g。两个方向共用同一个时间，由此联系方程。三维情形增加第三个分量；矢量大小等于各分量平方和的平方根。','A horizontal launch at 8 m/s falls for 2 s, travelling 16 m horizontally. With g = 10 m/s² it drops 20 m. Combining displacements gives a diagonal displacement, not the curved path length.','水平以 8 m/s 抛出，飞行 2 s 后水平前进 16 m。取 g = 10 m/s²，下降 20 m。分位移合成得到斜向总位移，而不是弯曲轨迹的路程。','A vector has perpendicular components 6 and 8. What is its magnitude?','一个矢量的两个垂直分量为 6 和 8，其大小是多少？',10,'√(6² + 8²) = √100 = 10.','Horizontal and vertical positions are independent equations, but the elapsed time is shared. Air resistance would couple motion through the velocity-dependent force.','水平与竖直位置分别列式，但时间相同。若考虑空气阻力，依赖速度的阻力会使运动分量发生耦合。','Perpendicular components combine using the Pythagorean relation.','垂直分量通过勾股关系合成大小。','The magnitude is always the sum of component magnitudes.','矢量大小总是各分量绝对值之和。'],
['牛顿定律与受力图','Inertia|Net force|Action–reaction pairs','惯性|合力|作用力与反作用力','In an inertial frame, zero net force means constant velocity. Newton’s second law is the vector equation ΣF = ma for constant mass. Draw only forces acting on the chosen body. Newton’s third law pairs equal opposite forces on different bodies; these do not cancel within a single body’s force diagram.','在惯性系中，合力为零意味着速度恒定。质量恒定时，牛顿第二定律为矢量方程 ΣF = ma。受力图只画作用在所选物体上的力。第三定律的一对等大反向力作用在不同物体上，不会在单个物体的受力图中互相抵消。','A 2 kg cart pulled right with 7 N and left with 3 N has net force 4 N right, hence acceleration 2 m/s² right. Its current velocity may nevertheless point left.','2 kg 小车受到向右 7 N、向左 3 N 的力，合力为向右 4 N，因此加速度向右，为 2 m/s²；此时速度仍可能向左。','A 3 kg body experiences a net force of 12 N. Find acceleration in m/s².','3 kg 物体受到 12 N 合力，加速度为多少 m/s²？',4,'a = F / m = 12 / 3 = 4 m/s².','A force changes velocity, not necessarily position in its own direction immediately. Weight and normal force are not a third-law pair because both act on one body.','力改变速度，并不保证物体立即沿力的方向运动。重力与支持力都作用在同一物体上，因此不是第三定律力对。','Third-law partners act on different bodies.','第三定律的一对力作用在不同物体上。','A moving body always needs a forward net force.','运动物体总需要向前的合力。'],
['接触力与摩擦','Normal force|Static friction|Kinetic friction','支持力|静摩擦|滑动摩擦','A normal force is perpendicular to a contact surface. Static friction adjusts to prevent relative slipping up to |f| ≤ μsN; it is not always at that limit. In a simple dry-contact model, sliding friction has magnitude μkN and opposes relative sliding. Surface geometry and other forces determine N.','支持力垂直于接触面。静摩擦力会调整大小以阻止相对滑动，但满足 |f| ≤ μsN，并非总等于最大值。简单干摩擦模型中，滑动摩擦力大小为 μkN，方向与相对滑动相反。支持力 N 由表面几何和其他力共同决定。','A horizontal 10 N push on a stationary box is balanced by 10 N static friction if the maximum is 15 N. A 20 N push exceeds that limit and slipping begins in this idealized model.','若最大静摩擦力为 15 N，水平推力 10 N 会被 10 N 静摩擦力平衡。若推力增为 20 N，则超过极限，在此理想模型中开始滑动。','A sliding object has N = 40 N and μk = 0.25. Find friction magnitude in N.','滑动物体受到 40 N 支持力，μk = 0.25，摩擦力大小为多少 N？',10,'f = μkN = 0.25 × 40 = 10 N.','Friction opposes relative slipping or its tendency, not necessarily the centre-of-mass velocity. A driven wheel can receive forward static friction.','摩擦力阻碍相对滑动或滑动趋势，不一定与质心速度相反。主动轮可以受到向前的静摩擦力。','Static friction can be smaller than μsN.','静摩擦力可以小于 μsN。','Normal force always equals weight.','支持力总等于重力。'],
['圆周运动与约束','Centripetal acceleration|Radial force balance|Constraint forces','向心加速度|径向受力平衡|约束力','Uniform circular motion changes direction even when speed is constant. The inward acceleration is v²/r. “Centripetal force” names the inward resultant, not an additional interaction: tension, gravity or contact forces can supply it. A rope constrains length only while taut, and a track can push only where contact persists.','匀速圆周运动虽速率恒定，方向却持续变化，向内加速度为 v²/r。“向心力”是径向合力的名称，不是额外的一种相互作用；绳力、重力或接触力都可以提供它。绳只有绷紧时才能约束长度，轨道只有保持接触时才能施加推力。','For a 1 kg object moving at 4 m/s around a radius of 2 m, the inward resultant is 8 N. If speed doubles at fixed radius, the required force becomes four times larger.','1 kg 物体以 4 m/s 绕半径 2 m 的圆运动，向内合力为 8 N。半径不变而速率加倍时，所需向心力增为四倍。','Find centripetal acceleration for v = 6 m/s and r = 3 m.','v = 6 m/s、r = 3 m 时，向心加速度为多少 m/s²？',12,'a = v² / r = 36 / 3 = 12 m/s².','Do not add an extra centripetal force to the real forces. Check positive tension or normal force; a negative result means the assumed constraint has failed.','不要在真实作用力之外再添加一个向心力。必须检查张力或支持力非负；算得负值说明原先假定的约束无法维持。','Constant speed around a circle still requires acceleration.','绕圆运动速率恒定，仍然需要加速度。','Constant speed always means zero acceleration.','速率恒定总意味着加速度为零。'],
['参考系与模型检查','Relative velocity|Inertial frames|Limiting cases','相对速度|惯性参考系|极限情形','At ordinary speeds, velocities transform by vector subtraction: vrelative = vobject − vframe. Frames moving uniformly relative to an inertial frame remain inertial. An accelerating frame requires inertial-force terms if Newton’s law is kept in its familiar form. A model must also pass checks of units, signs and simple limits.','普通低速下，相对速度通过矢量相减得到：v相对 = v物体 − v参考系。相对惯性系做匀速直线运动的参考系仍是惯性系。若在加速参考系中保持牛顿方程的常见形式，需要引入惯性力项。模型还应通过单位、符号和简单极限的检查。','A train moves east at 20 m/s and a passenger walks east at 2 m/s relative to it. Ground velocity is 22 m/s. Walking west instead gives 18 m/s east, not 22 m/s west.','火车向东 20 m/s，乘客相对车厢向东走 2 m/s，对地速度为向东 22 m/s。若向西走，对地速度则为向东 18 m/s，而不是向西 22 m/s。','Two cars move east at 25 and 17 m/s. Find the faster car’s velocity relative to the slower car in m/s.','两车向东速度分别为 25 与 17 m/s，快车相对慢车的速度为多少 m/s？',8,'vrelative = 25 − 17 = 8 m/s east.','An inertial-force description depends on the chosen accelerating frame; it is not an additional physical interaction. Galilean velocity addition fails near light speed.','惯性力描述取决于所选加速参考系，并非额外的物理相互作用。接近光速时，伽利略速度相加不再适用。','Changing a uniformly moving frame can change velocity but not ordinary Newtonian acceleration.','换到匀速运动参考系会改变速度，但不改变牛顿力学中的加速度。','Every frame is inertial.','所有参考系都是惯性系。']]);
